/**
 * Analytics overview queries
 *
 * Dashboard overview and rankings statistics.
 */

import { query } from './_generated/server';
import { calculateHabitStrength, getStreaksForHabit } from './analytics/index';

/**
 * Get overview statistics for the analytics dashboard
 */
export const getOverviewStats = query({
  args: {},
  handler: async (ctx) => {
    const habits = await ctx.db.query('habits').collect();
    const activeHabits = habits.filter((h) => !h.archived && !h.paused);

    if (activeHabits.length === 0) {
      return {
        averageStrength: 0,
        rankedHabits: [],
        strongestHabit: null,
        totalHabits: 0,
        weakestHabit: null,
      };
    }

    // Calculate strengths with streaks
    const habitsWithStrength = await Promise.all(
      activeHabits.map(async (habit) => {
        const streaks = await getStreaksForHabit(ctx, habit._id, 'anonymous');
        const strength = calculateHabitStrength(
          habit,
          streaks.currentStreak / 66
        );
        return {
          ...habit,
          currentStreak: streaks.currentStreak,
          longestStreak: streaks.longestStreak,
          strength,
        };
      })
    );

    habitsWithStrength.sort((a, b) => b.strength - a.strength);

    const totalStrength = habitsWithStrength.reduce(
      (sum, h) => sum + h.strength,
      0
    );
    const averageStrength = totalStrength / habitsWithStrength.length;

    const rankedHabits = habitsWithStrength.map((habit) => ({
      currentStreak: habit.currentStreak,
      emoji: habit.icon || '🎯',
      id: habit._id,
      isAtRisk: habit.currentStreak < 3,
      longestStreak: habit.longestStreak,
      name: habit.name,
      strength: habit.strength,
    }));

    const strongest = habitsWithStrength[0];
    const weakest = habitsWithStrength.at(-1);

    return {
      averageStrength,
      rankedHabits,
      strongestHabit: strongest
        ? {
            emoji: strongest.icon || '🎯',
            id: strongest._id,
            name: strongest.name,
            strength: strongest.strength,
          }
        : null,
      totalHabits: activeHabits.length,
      weakestHabit: weakest
        ? {
            emoji: weakest.icon || '🎯',
            id: weakest._id,
            name: weakest.name,
            strength: weakest.strength,
          }
        : null,
    };
  },
});

/**
 * Analytics weekly insights query
 *
 * Week-over-week comparison and habit change analysis.
 */

import { v } from 'convex/values';
import { query, internalMutation } from './_generated/server';
import { getStreaksForHabit } from './analytics/index';
import {
  calculateHabitChanges,
  categorizeHabitChanges,
  calculateWeekOverWeekChange,
} from './analytics/weeklyHelpers';

/**
 * Get weekly insights
 */
export const getWeeklyInsights = query({
  args: {},
  handler: async (ctx) => {
    const habits = await ctx.db.query('habits').collect();
    const activeHabits = habits.filter((h) => !h.archived && !h.paused);

    const oneWeekAgo = new Date();
    oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);
    const twoWeeksAgo = new Date();
    twoWeeksAgo.setDate(twoWeeksAgo.getDate() - 14);

    // Get all trackings for these habits
    const trackings: any[] = [];
    for (const habit of activeHabits) {
      const habitTrackings = await ctx.db
        .query('tracking')
        .withIndex('by_habit_and_date', (q) => q.eq('habitId', habit._id))
        .collect();
      trackings.push(...habitTrackings);
    }

    // Calculate changes for each habit
    const habitChanges = await Promise.all(
      activeHabits.map(async (habit) => {
        const streaks = await getStreaksForHabit(ctx, habit._id, 'anonymous');
        return calculateHabitChanges(
          habit,
          trackings,
          oneWeekAgo,
          twoWeeksAgo,
          streaks.currentStreak
        );
      })
    );

    const categories = categorizeHabitChanges(habitChanges);
    const totals = calculateWeekOverWeekChange(habitChanges);

    return {
      ...categories,
      ...totals,
      generatedAt: new Date().toISOString(),
    };
  },
});

/**
 * Scheduled function to generate weekly insights (to be called via cron)
 */
export const generateWeeklyInsights = internalMutation({
  args: { userId: v.string() },
  handler: async (_ctx, { userId }) => {
    const insightData = {
      generatedAt: new Date().toISOString(),
      userId,
    };
    return { success: true };
  },
});

