/**
 * Momentum-Based Strength Calculation (v2.0)
 * Forgiving strength formula with streak protection
 */
import {
  BASE_DECAY,
  GROWTH_RATE,
  MS_PER_DAY,
  SHIELD_EFFECTIVENESS,
} from './constants';
import {
  addDays,
  findEarliestTrackingDate,
  formatDateKey,
  parseDateKeyToLocalDate,
  startOfDay,
} from './dateUtils';
import type { HabitTrackingRecord, StrengthLevel } from './types';
import { getStrengthLevel } from './strengthLevel';

/** Calculate new habit strength after a completion or miss */
export function calculateNewStrength(
  currentStrength: number,
  completed: boolean,
  completionsLast7Days: number
): number {
  const strength = Math.max(0, Math.min(100, currentStrength));
  const recentCompletions = Math.max(0, Math.min(7, completionsLast7Days));

  if (completed) {
    const gap = 100 - strength;
    return Math.min(100, strength + gap * GROWTH_RATE);
  }
  const streakShield = recentCompletions / 7;
  const protectedDecay = BASE_DECAY * (1 - streakShield * SHIELD_EFFECTIVENESS);
  return Math.max(0, strength * (1 - protectedDecay));
}

/** Calculate strength snapshot by simulating day-by-day strength changes */
export function calculateMomentumStrengthSnapshot({
  habitCreatedAt,
  throughDate,
  tracking,
}: {
  habitCreatedAt: number;
  throughDate?: string;
  tracking: HabitTrackingRecord[];
}): {
  daysProcessed: number;
  strength: number;
  strength100: number;
  strengthLevel: StrengthLevel;
} {
  const evaluationDateKey =
    throughDate ?? formatDateKey(startOfDay(new Date()));
  const evaluationDate = parseDateKeyToLocalDate(evaluationDateKey);
  const creationDate = startOfDay(new Date(habitCreatedAt));

  const earliestDateKey = findEarliestTrackingDate(tracking);
  const earliestDate = earliestDateKey
    ? parseDateKeyToLocalDate(earliestDateKey)
    : null;

  const startDate =
    earliestDate && earliestDate.getTime() < creationDate.getTime()
      ? earliestDate
      : creationDate;

  if (startDate.getTime() > evaluationDate.getTime()) {
    return {
      daysProcessed: 0,
      strength: 0,
      strength100: 0,
      strengthLevel: getStrengthLevel(0),
    };
  }

  const completionDates = new Set(
    tracking.filter((r) => r.completed).map((r) => r.date)
  );

  const daysProcessed =
    Math.floor((evaluationDate.getTime() - startDate.getTime()) / MS_PER_DAY) +
    1;

  let strength100 = 0;

  for (
    let cursor = new Date(startDate);
    cursor.getTime() <= evaluationDate.getTime();
    cursor = addDays(cursor, 1)
  ) {
    const dateKey = formatDateKey(cursor);
    let completionsLast7Days = 0;
    for (let offset = 1; offset <= 7; offset++) {
      if (completionDates.has(formatDateKey(addDays(cursor, -offset)))) {
        completionsLast7Days++;
      }
    }
    strength100 = calculateNewStrength(
      strength100,
      completionDates.has(dateKey),
      completionsLast7Days
    );
  }

  const strength = strength100 / 100;
  return {
    daysProcessed,
    strength,
    strength100,
    strengthLevel: getStrengthLevel(strength),
  };
}

/**
 * Update Habit Strength Mutation
 * @deprecated Use tracking.toggleCompletion instead
 */
import { v } from 'convex/values';
import { mutation } from '../_generated/server';
import { calculateNewStrength } from './momentum';
import { getStrengthLevel } from './strengthLevel';
import { predictCompletionProbability } from './legacyFormula';

export const updateHabitStrength = mutation({
  args: {
    behaviorPerformed: v.boolean(),
    date: v.string(),
    habitId: v.id('habits'),
  },
  handler: async (ctx, args) => {
    const habit = await ctx.db.get(args.habitId);
    if (!habit) {
      throw new Error('Habit not found');
    }

    if (!/^\d{4}-\d{2}-\d{2}$/.test(args.date)) {
      throw new Error('Invalid date format; expected YYYY-MM-DD');
    }

    const previousStrength = habit.strength ?? 0;

    // Update tracking record
    const trackingForDay = await ctx.db
      .query('tracking')
      .withIndex('by_habit_and_date', (q) =>
        q.eq('habitId', args.habitId).eq('date', args.date)
      )
      .unique();

    if (trackingForDay) {
      if (trackingForDay.completed !== args.behaviorPerformed) {
        await ctx.db.patch(trackingForDay._id, {
          completed: args.behaviorPerformed,
        });
      }
    } else {
      await ctx.db.insert('tracking', {
        completed: args.behaviorPerformed,
        date: args.date,
        habitId: args.habitId,
      });
    }

    // Calculate completionsLast7Days for streak shield
    const toggleDate = new Date(args.date);
    const sevenDaysAgo = new Date(toggleDate);
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

    const allTracking = await ctx.db
      .query('tracking')
      .withIndex('by_habit_and_date', (q) => q.eq('habitId', args.habitId))
      .collect();

    let completionsLast7Days = 0;
    for (const record of allTracking) {
      const recordDate = new Date(record.date);
      if (
        recordDate >= sevenDaysAgo &&
        recordDate < toggleDate &&
        record.completed
      ) {
        completionsLast7Days++;
      }
    }

    const newStrength =
      calculateNewStrength(
        previousStrength * 100,
        args.behaviorPerformed,
        completionsLast7Days
      ) / 100;

    const strengthLevel = getStrengthLevel(newStrength);

    await ctx.db.patch(args.habitId, {
      strength: newStrength,
      strengthLevel,
      strengthUpdatedAt: Date.now(),
    });

    return {
      baseline: 0,
      compliance: 0,
      daysSinceCreation: 0,
      newStrength,
      predictionProbability: predictCompletionProbability(newStrength),
      previousStrength,
      strengthLevel,
    };
  },
  returns: v.object({
    baseline: v.number(),
    compliance: v.number(),
    daysSinceCreation: v.number(),
    newStrength: v.number(),
    predictionProbability: v.number(),
    previousStrength: v.number(),
    strengthLevel: v.string(),
  }),
});

