/**
 * Recalculate strength for ALL habits using the new momentum-based formula
 * This REPLACES old strength values with new calculations
 * Run this to fix habits that were initialized with the old formula
 */
import { mutation } from './_generated/server';
import { v } from 'convex/values';
import { calculateNewStrength, getStrengthLevel } from './habitStrength';

export const recalculateAllHabitsStrength = mutation({
  args: {
    force: v.optional(v.boolean()), // Set to true to recalculate even if strength exists
  },
  handler: async (ctx, args) => {
    const habits = await ctx.db
      .query('habits')
      .filter((q) => q.neq(q.field('archived'), true))
      .collect();

    console.log(`🔄 Recalculating strength for ${habits.length} habits...`);

    let recalculated = 0;
    let skipped = 0;

    for (const habit of habits) {
      // Skip if has strength and not forcing
      if (habit.strength !== undefined && !args.force) {
        console.log(`  ⏭️  Skipping ${habit.name} - already has strength (use force:true to recalculate)`);
        skipped++;
        continue;
      }

      console.log(`  🔧 Recalculating ${habit.name}...`);

      // Get all tracking data
      const tracking = await ctx.db
        .query('tracking')
        .withIndex('by_habit_and_date', (q) => q.eq('habitId', habit._id))
        .collect();

      if (tracking.length === 0) {
        await ctx.db.patch(habit._id, {
          strength: 0,
          strengthLevel: 'starting',
          strengthUpdatedAt: Date.now(),
        });
        console.log(`    ✅ 0% (starting) - no tracking data`);
        recalculated++;
        continue;
      }

      // Sort by date and simulate day-by-day
      const sortedTracking = tracking.sort((a, b) => a.date.localeCompare(b.date));
      let currentStrength = 0;
      const completionsByDate = new Map<string, boolean>();

      for (const record of sortedTracking) {
        completionsByDate.set(record.date, record.completed);
      }

      // Apply new formula chronologically
      for (const record of sortedTracking) {
        const recordDate = new Date(record.date);
        const sevenDaysAgo = new Date(recordDate);
        sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

        let completionsLast7Days = 0;
        for (const [date, completed] of completionsByDate.entries()) {
          const checkDate = new Date(date);
          if (checkDate >= sevenDaysAgo && checkDate < recordDate && completed) {
            completionsLast7Days++;
          }
        }

        currentStrength = calculateNewStrength(
          currentStrength,
          record.completed,
          completionsLast7Days
        );
      }

      const finalStrength = currentStrength / 100;
      const strengthLevel = getStrengthLevel(finalStrength);

      await ctx.db.patch(habit._id, {
        strength: finalStrength,
        strengthLevel,
        strengthUpdatedAt: Date.now(),
      });

      console.log(`    ✅ ${currentStrength.toFixed(1)}% (${strengthLevel})`);
      recalculated++;
    }

    console.log(`\n✨ Complete! Recalculated: ${recalculated}, Skipped: ${skipped}`);

    return {
      recalculated,
      skipped,
      total: habits.length,
    };
  },
  returns: v.object({
    recalculated: v.number(),
    skipped: v.number(),
    total: v.number(),
  }),
});

/**
 * Reflections API
 * Quick Reflection - Post-habit completion feedback (BJ Fogg's Tiny Habits)
 *
 * Scientific Basis:
 * - BJ Fogg (Stanford, "Tiny Habits"): Celebration wires habits
 * - Journaling increases self-awareness and consistency
 * - Daylio (50M+ downloads) validates the reflection pattern
 *
 * Story T6: Quick Reflection
 */

import { v } from 'convex/values';
import { mutation, query } from './_generated/server';

// Emoji type validator - matches schema definition
const emojiValidator = v.union(
  v.literal('frustrated'),
  v.literal('neutral'),
  v.literal('happy'),
  v.literal('fire')
);

// Reflection object validator for return types
const reflectionObjectValidator = v.object({
  _creationTime: v.number(),
  _id: v.id('reflections'),
  habitId: v.id('habits'),
  userId: v.optional(v.string()),
  date: v.string(),
  emoji: emojiValidator,
  note: v.optional(v.string()),
  createdAt: v.number(),
  updatedAt: v.number(),
});

/**
 * Get a reflection for a specific habit and date
 */
export const getByHabitAndDate = query({
  args: {
    habitId: v.id('habits'),
    date: v.string(),
  },
  handler: async (ctx, args) => {
    return await ctx.db
      .query('reflections')
      .withIndex('by_habit_and_date', (q) =>
        q.eq('habitId', args.habitId).eq('date', args.date)
      )
      .first();
  },
  returns: v.union(v.null(), reflectionObjectValidator),
});

/**
 * Get all reflections for a specific habit
 */
export const listByHabit = query({
  args: {
    habitId: v.id('habits'),
    limit: v.optional(v.number()),
  },
  handler: async (ctx, args) => {
    let query = ctx.db
      .query('reflections')
      .withIndex('by_habit', (q) => q.eq('habitId', args.habitId))
      .order('desc');

    if (args.limit) {
      return await query.take(args.limit);
    }

    return await query.collect();
  },
  returns: v.array(reflectionObjectValidator),
});

/**
 * Create or update a reflection for a habit on a specific date
 * Only one reflection per habit per day is allowed
 */
export const upsert = mutation({
  args: {
    habitId: v.id('habits'),
    date: v.string(),
    emoji: emojiValidator,
    note: v.optional(v.string()),
  },
  handler: async (ctx, args) => {
    // Validate date format as YYYY-MM-DD
    const isValidDate = /^\d{4}-\d{2}-\d{2}$/.test(args.date);
    if (!isValidDate) {
      throw new Error('Invalid date format; expected YYYY-MM-DD');
    }

    // Validate note length (max 500 chars)
    if (args.note && args.note.length > 500) {
      throw new Error('Reflection note cannot exceed 500 characters');
    }

    // Check if habit exists
    const habit = await ctx.db.get(args.habitId);
    if (!habit) {
      throw new Error('Habit not found');
    }

    const now = Date.now();

    // Check for existing reflection
    const existingReflection = await ctx.db
      .query('reflections')
      .withIndex('by_habit_and_date', (q) =>
        q.eq('habitId', args.habitId).eq('date', args.date)
      )
      .first();

    if (existingReflection) {
      // Update existing reflection
      await ctx.db.patch(existingReflection._id, {
        emoji: args.emoji,
        note: args.note,
        updatedAt: now,
      });
      return existingReflection._id;
    }

    // Create new reflection
    return await ctx.db.insert('reflections', {
      habitId: args.habitId,
      date: args.date,
      emoji: args.emoji,
      note: args.note,
      createdAt: now,
      updatedAt: now,
    });
  },
  returns: v.id('reflections'),
});

/**
 * Delete a reflection
 */
export const remove = mutation({
  args: {
    reflectionId: v.id('reflections'),
  },
  handler: async (ctx, args) => {
    const reflection = await ctx.db.get(args.reflectionId);
    if (!reflection) {
      throw new Error('Reflection not found');
    }

    await ctx.db.delete(args.reflectionId);
    return null;
  },
  returns: v.null(),
});

/**
