import { v } from 'convex/values';
import { mutation } from './_generated/server';
import { voiceNoteObjectValidator } from './voiceNotes/index';

/**
 * Create a new voice note
 */
export const create = mutation({
  args: {
    audioUrl: v.string(),
    duration: v.number(),
    habitId: v.id('habits'),
    isDay1: v.optional(v.boolean()),
    label: v.optional(v.string()),
  },
  handler: async (ctx, args) => {
    const habit = await ctx.db.get(args.habitId);
    if (!habit) throw new Error('Habit not found');

    if (args.duration <= 0) throw new Error('Duration must be positive');
    if (args.duration > 300)
      throw new Error('Voice note cannot exceed 5 minutes');
    if (args.label && args.label.length > 100)
      throw new Error('Label cannot exceed 100 characters');
    if (!args.audioUrl || args.audioUrl.trim() === '')
      throw new Error('Audio URL is required');

    const now = Date.now();

    if (args.isDay1) {
      const existingNotes = await ctx.db
        .query('voiceNotes')
        .withIndex('by_habit', (q) => q.eq('habitId', args.habitId))
        .collect();

      for (const note of existingNotes) {
        if (note.isDay1) {
          await ctx.db.patch(note._id, { isDay1: false, updatedAt: now });
        }
      }
    }

    return await ctx.db.insert('voiceNotes', {
      audioUrl: args.audioUrl,
      createdAt: now,
      duration: args.duration,
      habitId: args.habitId,
      isDay1: args.isDay1 ?? false,
      label: args.label,
    });
  },
  returns: v.id('voiceNotes'),
});

/**
 * Update a voice note's label or Day 1 flag
 */
export const update = mutation({
  args: {
    isDay1: v.optional(v.boolean()),
    label: v.optional(v.string()),
    voiceNoteId: v.id('voiceNotes'),
  },
  handler: async (ctx, args) => {
    const voiceNote = await ctx.db.get(args.voiceNoteId);
    if (!voiceNote) throw new Error('Voice note not found');

    if (args.label && args.label.length > 100)
      throw new Error('Label cannot exceed 100 characters');

    const now = Date.now();

    if (args.isDay1) {
      const existingNotes = await ctx.db
        .query('voiceNotes')
        .withIndex('by_habit', (q) => q.eq('habitId', voiceNote.habitId))
        .collect();

      for (const note of existingNotes) {
        if (note.isDay1 && note._id !== args.voiceNoteId) {
          await ctx.db.patch(note._id, { isDay1: false, updatedAt: now });
        }
      }
    }

    await ctx.db.patch(args.voiceNoteId, {
      ...(args.label !== undefined && { label: args.label }),
      ...(args.isDay1 !== undefined && { isDay1: args.isDay1 }),
      updatedAt: now,
    });

    return args.voiceNoteId;
  },
  returns: v.id('voiceNotes'),
});

/**
 * Delete a voice note
 */
export const remove = mutation({
  args: { voiceNoteId: v.id('voiceNotes') },
  handler: async (ctx, args) => {
    const voiceNote = await ctx.db.get(args.voiceNoteId);
    if (!voiceNote) throw new Error('Voice note not found');
    await ctx.db.delete(args.voiceNoteId);
    return null;
  },
  returns: v.null(),
});

import '../global.css';

import { ConvexProvider } from 'convex/react';
import { ClerkProvider, useAuth } from '@clerk/clerk-expo';
import { PropsWithChildren, useEffect } from 'react';
import { PaperProvider } from 'react-native-paper';
import { SafeAreaProvider } from 'react-native-safe-area-context';

import { AuthGate } from './components/auth/AuthGate';
import { convexClient } from './lib/appConfig';
import theme from './theme';

const CLERK_PUBLISHABLE_KEY = process.env.EXPO_PUBLIC_CLERK_PUBLISHABLE_KEY || '';

// Component to sync Clerk auth token with Convex
function ConvexClerkProvider({ children }: PropsWithChildren) {
  const { getToken, isSignedIn } = useAuth();

  useEffect(() => {
    // Set auth token fetcher for Convex
    convexClient.setAuth(async () => {
      if (!isSignedIn) {
        return null;
      }

      try {
        // Get the Clerk token with 'convex' JWT template
        // Make sure you've created this template in Clerk Dashboard
        const token = await getToken({ template: 'convex' });
        console.log('Convex auth token fetched:', token ? 'SUCCESS' : 'NULL');
        return token ?? null;
      } catch (error) {
        console.error('Failed to get Clerk token:', error);
        // Fallback to default token if template doesn't exist
        try {
          const defaultToken = await getToken();
          console.log('Fallback to default token:', defaultToken ? 'SUCCESS' : 'NULL');
          return defaultToken ?? null;
        } catch {
          return null;
        }
      }
    });
  }, [getToken, isSignedIn]);

  return <ConvexProvider client={convexClient}>{children}</ConvexProvider>;
}

function Providers({ children }: PropsWithChildren) {
  return (
    <SafeAreaProvider>
      <PaperProvider theme={theme}>
        <ClerkProvider publishableKey={CLERK_PUBLISHABLE_KEY}>
          <ConvexClerkProvider>
            {children}
          </ConvexClerkProvider>
        </ClerkProvider>
      </PaperProvider>
    </SafeAreaProvider>
  );
}

export default function App() {
  return (
    <Providers>
      <AuthGate />
    </Providers>
  );
}

