import { getStrengthInfo, getStrengthGradientColor } from '../utils';
import { HabitCardHeader } from './HabitCardHeader';
import { HabitStatsBadges } from './HabitStatsBadges';
import { ActionButtons } from './ActionButtons';
import { StrengthBackground } from './StrengthBackground';
import type { AnimatedHabitCardProps } from '../types';

const CARD_SHADOW = {
  elevation: 2,
  shadowColor: '#000',
  shadowOffset: { height: 2, width: 0 },
  shadowOpacity: 0.05,
  shadowRadius: 8,
};

export function AnimatedHabitCard({
  habit,
  index,
  reducedMotion,
  onRestore,
  onDelete,
}: AnimatedHabitCardProps) {
  const {
    isRestoring,
    showSuccess,
    animatedStyle,
    successIconStyle,
    handleRestorePress,
  } = useAnimatedHabitCard({
    habitId: habit._id,
    habitName: habit.name,
    index,
    onRestore,
    reducedMotion,
  });

  const strength = (habit.strength ?? 0) * 100;
  const strengthInfo = getStrengthInfo(strength);
  const gradientColor = getStrengthGradientColor(strength);
  const archiveDate = habit.archivedAt || habit._creationTime;

  return (
    <Animated.View style={animatedStyle}>
      <View
        className='overflow-hidden rounded-2xl border border-stone-200 bg-white'
        style={CARD_SHADOW}
      >
        <StrengthBackground gradientColor={gradientColor} strength={strength} />

        <View className='relative p-4'>
          <HabitCardHeader
            archiveDate={archiveDate}
            icon={habit.icon}
            iconColor={habit.iconColor}
            name={habit.name}
          />

          <HabitStatsBadges
            habit={habit}
            strength={strength}
            strengthInfo={strengthInfo}
          />

          <ActionButtons
            habitName={habit.name}
            isRestoring={isRestoring}
            showSuccess={showSuccess}
            successIconStyle={successIconStyle}
            onDeletePress={() => onDelete(habit._id, habit.name)}
            onRestorePress={handleRestorePress}
          />
        </View>
      </View>
    </Animated.View>
  );
}

import { useEffect } from 'react';
import {
  useSharedValue,
  useAnimatedStyle,
  withDelay,
  withSpring,
  withTiming,
  Easing,
  cancelAnimation,
  type SharedValue,
} from 'react-native-reanimated';
import { CARD_ANIMATION_DURATION, CARD_ANIMATION_STAGGER } from '../utils';

interface UseCardAnimatedStylesParams {
  index: number;
  reducedMotion: boolean;
}

interface CardAnimationValues {
  cardOpacity: SharedValue<number>;
  cardTranslateY: SharedValue<number>;
  cardTranslateX: SharedValue<number>;
  cardScale: SharedValue<number>;
  successScale: SharedValue<number>;
}

export const useCardAnimatedStyles = ({
  index,
  reducedMotion,
}: UseCardAnimatedStylesParams) => {
  const cardOpacity = useSharedValue(reducedMotion ? 1 : 0);
  const cardTranslateY = useSharedValue(reducedMotion ? 0 : 20);
  const cardTranslateX = useSharedValue(0);
  const cardScale = useSharedValue(1);
  const successScale = useSharedValue(0);

  useEffect(() => {
    if (reducedMotion) {
      cardOpacity.value = 1;
      cardTranslateY.value = 0;
      return;
    }

    const delay = index * CARD_ANIMATION_STAGGER;

    cardOpacity.value = withDelay(
      delay,
      withTiming(1, {
        duration: CARD_ANIMATION_DURATION,
        easing: Easing.out(Easing.cubic),
      })
    );
    cardTranslateY.value = withDelay(
      delay,
      withSpring(0, { damping: 18, stiffness: 120 })
    );

    return () => {
      cancelAnimation(cardOpacity);
      cancelAnimation(cardTranslateY);
    };
  }, [index, reducedMotion, cardOpacity, cardTranslateY]);

  const animatedStyle = useAnimatedStyle(() => ({
    opacity: cardOpacity.value,
    transform: [
      { translateY: cardTranslateY.value },
      { translateX: cardTranslateX.value },
      { scale: cardScale.value },
    ],
  }));

  const successIconStyle = useAnimatedStyle(() => ({
    transform: [{ scale: successScale.value }],
  }));

  const animationValues: CardAnimationValues = {
    cardOpacity,
    cardScale,
    cardTranslateX,
    cardTranslateY,
    successScale,
  };

  return {
    animatedStyle,
    animationValues,
    successIconStyle,
  };
};

/**
 * BinaryCell Component
 *
 * Individual cell in the GitHub-style binary heatmap.
 */

import React, { memo, useCallback } from 'react';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  FadeIn,
} from 'react-native-reanimated';

import type { BinaryCellProps } from './types';
import { getCellState, getBinaryCellAccessibilityLabel } from './utils';
import { ANIMATION, COLORS } from './constants';
import { useReduceMotion } from '../../hooks/useReduceMotion';
import { styles } from './BinaryCell.styles';
import { getBackgroundColor } from './BinaryCell.helpers';

export const BinaryCell = memo(function BinaryCell({
  day,
  index,
  habitColor,
  onPress,
}: BinaryCellProps) {
  const scale = useSharedValue(1);
  const reduceMotion = useReduceMotion();
  const staggerDelay = reduceMotion ? 0 : index * ANIMATION.CELL_STAGGER_DELAY;
  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
  }));

  const handlePressIn = useCallback(() => {
    if (day && !day.isFuture && !day.isBeforeCreation && !reduceMotion) {
      scale.value = withSpring(ANIMATION.TAP_SCALE, { damping: 15 });
    }
  }, [day, reduceMotion, scale]);

  const handlePressOut = useCallback(() => {
    if (!reduceMotion) scale.value = withSpring(1, { damping: 15 });
  }, [reduceMotion, scale]);

  const handlePress = useCallback(() => {
    if (day && onPress && !day.isFuture && !day.isBeforeCreation)
      onPress(day.date, day.completed);
  }, [day, onPress]);

  const accessibilityLabel = getBinaryCellAccessibilityLabel(day);
  const fadeInAnimation = reduceMotion
    ? undefined
    : FadeIn.delay(staggerDelay).duration(ANIMATION.CELL_FADE_DURATION);

  if (day === null) {
    return (
      <Animated.View
        accessible
        accessibilityLabel={accessibilityLabel}
        accessibilityRole='text'
        entering={fadeInAnimation}
        style={styles.cell}
      />
    );
  }

  const cellState = getCellState(day);
  const bgColor = getBackgroundColor(cellState, day, habitColor);
  const isInteractive = !day.isFuture && !day.isBeforeCreation;

  if (!isInteractive) {
    return (
      <Animated.View
        accessible
        accessibilityLabel={accessibilityLabel}
        accessibilityRole='text'
        entering={fadeInAnimation}
        style={[
          styles.cell,
          styles.cellInner,
          { backgroundColor: bgColor },
          cellState === 'future' && styles.futureCell,
        ]}
      />
    );
  }

  return (
    <Animated.View
      accessible
      accessibilityHint={day.isToday ? 'Today' : 'Tap to toggle completion'}
      accessibilityLabel={accessibilityLabel}
      accessibilityRole='button'
      accessibilityState={{ selected: day.completed }}
      entering={fadeInAnimation}
      style={[
        styles.cell,
        styles.cellInner,
        { backgroundColor: bgColor },
        cellState === 'today' && {
          backgroundColor: day.completed ? bgColor : COLORS.CARD_BACKGROUND,
          borderColor: habitColor,
          borderWidth: COLORS.TODAY_RING_WIDTH,
        },
      ]}
    />
  );
});

export default BinaryCell;

/**
 * BinaryHeatmapGrid Component
 *
 * Renders the main 7-row grid for the GitHub-style binary heatmap.
 */

import React, { memo, useMemo, useCallback } from 'react';
import { View, Text, ScrollView } from 'react-native';

import type { BinaryHeatmapGridProps } from './types';
import { MonthLabelsRow } from './MonthLabelsRow';
import { GridRow } from './GridRow';
import {
  CELL_SIZE,
  CELL_GAP,
  DAY_LABELS,
  GRID,
  DAY_NAMES_FULL,
} from './constants';
import { styles } from './BinaryHeatmapGrid.styles';
import { transformWeeksToRows } from './cellHelpers';

export const BinaryHeatmapGrid = memo(function BinaryHeatmapGrid({
  gridData,
  habitColor,
  onCellPress,
}: BinaryHeatmapGridProps) {
  const { weeks, monthLabels } = gridData;

  const rows = useMemo(() => transformWeeksToRows(weeks, GRID.ROWS), [weeks]);

  const handleCellPress = useCallback(
    (date: string, completed: boolean) => {
      onCellPress?.(date, completed);
    },
    [onCellPress]
  );

  const gridContentWidth = weeks.length * (CELL_SIZE + CELL_GAP);

  return (
    <View style={styles.container}>
      <View style={styles.dayLabelsColumn}>
        <View style={styles.monthLabelSpacer} />
        {DAY_LABELS.map((label, index) => (
          <View key={`label-${index}`} style={styles.dayLabelCell}>
            <Text
              accessible
              accessibilityLabel={`${DAY_NAMES_FULL[index]} row`}
              accessibilityRole='text'
              style={styles.dayLabelText}
            >
              {label}
            </Text>
          </View>
        ))}
      </View>
      <ScrollView
        horizontal
        accessibilityLabel='Habit completion heatmap grid'
        accessibilityRole='grid'
        contentContainerStyle={[
          styles.gridScrollContent,
          { width: gridContentWidth },
        ]}
        showsHorizontalScrollIndicator={false}
      >
        <View style={styles.gridContentContainer}>
          <MonthLabelsRow
            gridWidth={gridContentWidth}
            monthLabels={monthLabels}
          />
          <View style={styles.gridContainer}>
            {rows.map((row, dayIndex) => (
              <GridRow
                key={`row-${dayIndex}`}
                dayIndex={dayIndex}
                habitColor={habitColor}
                row={row}
              />
            ))}
          </View>
        </View>
      </ScrollView>
    </View>
  );
});

export default BinaryHeatmapGrid;

/**
 * BinaryHeatmap Component
 *
 * Main container component for the GitHub-style binary heatmap.
 * Grid rendering is delegated to InlineHeatmapGrid to maintain file size.
 */

import React, { memo, useState, useMemo, useCallback, useRef } from 'react';
import { View, Text } from 'react-native';

import type { BinaryHeatmapProps, TimeRange, BinaryDay } from './types';
import { HeatmapLegend } from './HeatmapLegend';
import { HeatmapTooltip } from './HeatmapTooltip';
import { InlineHeatmapGrid } from './InlineHeatmapGrid';
import { generateBinaryGrid } from './utils';
import { styles } from './BinaryHeatmapNew.styles';
import { createDayLookupMap } from './cellHelpers';

const FIXED_TIME_RANGE: TimeRange = '6m';

export const BinaryHeatmap = memo(function BinaryHeatmap({
  habitId: _habitId,
  completedDates,
  habitCreatedAt,
  habitColor,
  currentStreak: _currentStreak,
  onDayPress,
}: BinaryHeatmapProps) {
  const [tooltipDay, setTooltipDay] = useState<BinaryDay | null>(null);
  const [tooltipPosition, setTooltipPosition] = useState({ x: 0, y: 0 });
  const [tooltipVisible, setTooltipVisible] = useState(false);

  const gridData = useMemo(
    () => generateBinaryGrid(FIXED_TIME_RANGE, completedDates, habitCreatedAt),
    [completedDates, habitCreatedAt]
  );

  const dayLookupMap = useMemo(
    () => createDayLookupMap(gridData.weeks),
    [gridData.weeks]
  );

  const onDayPressRef = useRef(onDayPress);
  onDayPressRef.current = onDayPress;
  const dayLookupMapRef = useRef(dayLookupMap);
  dayLookupMapRef.current = dayLookupMap;

  const handleCellPress = useCallback((date: string, completed: boolean) => {
    const day = dayLookupMapRef.current.get(date);
    if (day) {
      setTooltipDay(day);
      setTooltipPosition({ x: 100, y: 50 });
      setTooltipVisible(true);
    }
    onDayPressRef.current?.(date, completed);
  }, []);

  const handleTooltipClose = useCallback(() => {
    setTooltipVisible(false);
    setTooltipDay(null);
  }, []);

  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <Text style={styles.headerTitle}>Activity</Text>
      </View>
      <View style={styles.gridWrapper}>
        <InlineHeatmapGrid
          habitColor={habitColor}
          monthLabels={gridData.monthLabels}
          weeks={gridData.weeks}
        />
      </View>
      <HeatmapLegend
        completionRate={gridData.stats.completionRate}
        habitColor={habitColor}
      />
      {tooltipDay && (
        <HeatmapTooltip
          day={tooltipDay}
          position={tooltipPosition}
          visible={tooltipVisible}
          onClose={handleTooltipClose}
        />
      )}
    </View>
  );
});

export default BinaryHeatmap;

/**
 * HeatmapLegend Component
 *
 * A simple binary legend for the GitHub-style heatmap.
 * Shows "Missed" (gray) and "Done" (habit color) indicators
 * with a completion percentage.
 *
 * Layout per spec:
 * [○ Missed] [● Done]          86% completion
 */

import React, { memo } from 'react';
import { View, Text, StyleSheet } from 'react-native';

import type { HeatmapLegendProps } from './types';
import { LEGEND_INDICATOR_SIZE, COLORS, CELL_BORDER_RADIUS } from './constants';

/**
 * Format completion rate as a rounded percentage string
 */
const formatCompletionRate = (rate: number): string => {
  return `${Math.round(rate)}%`;
};

/**
 * HeatmapLegend - Displays the binary legend for the heatmap
 *
 * This component shows two indicators:
 * - Missed: gray square indicating days the habit was not completed
 * - Done: colored square (using habit color) indicating completed days
 *
 * Also displays the overall completion percentage for the visible period.
 */
export const HeatmapLegend = memo(function HeatmapLegend({
  habitColor,
  completionRate,
}: HeatmapLegendProps) {
  return (
    <View
      accessible
      accessibilityLabel={`Legend: Gray for missed days, colored for completed days. ${formatCompletionRate(completionRate)} completion rate`}
      accessibilityRole='text'
      style={styles.container}
    >
      {/* Left side: Legend indicators */}
      <View style={styles.indicators}>
        {/* Missed indicator */}
        <View
          accessible
          accessibilityLabel='Missed: gray'
          accessibilityRole='text'
          style={styles.indicator}
        >
          <View
            style={[
              styles.indicatorSquare,
              { backgroundColor: COLORS.CELL_EMPTY },
            ]}
          />
          <Text style={styles.indicatorLabel}>Missed</Text>
        </View>

        {/* Done indicator */}
        <View
          accessible
          accessibilityLabel='Done: colored'
          accessibilityRole='text'
          style={styles.indicator}
        >
          <View
            style={[styles.indicatorSquare, { backgroundColor: habitColor }]}
          />
          <Text style={styles.indicatorLabel}>Done</Text>
        </View>
      </View>

      {/* Right side: Completion percentage */}
      <Text
        accessible
        accessibilityLabel={`${formatCompletionRate(completionRate)} completion`}
        accessibilityRole='text'
        style={[styles.completionText, { color: habitColor }]}
      >
        {formatCompletionRate(completionRate)} compl
      </Text>
    </View>
  );
});

const styles = StyleSheet.create({
  completionText: {
    fontSize: 12,
    fontWeight: '600',
  },
  container: {
    alignItems: 'center',
    flexDirection: 'row',
    justifyContent: 'space-between',
