  },
  indicator: {
    alignItems: 'center',
    flexDirection: 'row',
    marginRight: 12,
  },
  indicatorLabel: {
    color: COLORS.TEXT_SECONDARY,
    fontSize: 11,
    marginLeft: 4,
  },
  indicators: {
    alignItems: 'center',
