/**
 * HeatmapTooltip Component
 *
 * Tooltip that displays date and status information on hover/long-press.
 */

import React, { memo, useEffect } from 'react';
import { View, Text, Modal, Pressable } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withTiming,
  withSpring,
} from 'react-native-reanimated';

import type { HeatmapTooltipProps } from './types';
import { formatTooltipText } from './utils';
import { TOOLTIP } from './constants';
import { useReduceMotion } from '../../hooks/useReduceMotion';
import { styles } from './HeatmapTooltip.styles';

const AnimatedView = Animated.createAnimatedComponent(View);

export const HeatmapTooltip = memo(function HeatmapTooltip({
  day,
  position,
  visible,
  onClose,
}: HeatmapTooltipProps) {
  const opacity = useSharedValue(0);
  const scale = useSharedValue(0.9);
  const reduceMotion = useReduceMotion();
  const animationDuration = reduceMotion ? 0 : 150;

  useEffect(() => {
    if (visible) {
      opacity.value = withTiming(1, { duration: animationDuration });
      scale.value = reduceMotion
        ? withTiming(1, { duration: 0 })
        : withSpring(1, { damping: 20, stiffness: 300 });
    } else {
      opacity.value = withTiming(0, { duration: animationDuration });
      scale.value = withTiming(0.9, { duration: animationDuration });
    }
  }, [visible, opacity, scale, animationDuration, reduceMotion]);

  const animatedStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [{ scale: scale.value }],
  }));
  const tooltipText = formatTooltipText(day);

  if (!visible) return null;

  const tooltipStyle = { left: position.x, top: position.y - TOOLTIP.OFFSET };

  return (
    <Modal
      transparent
      animationType='none'
      visible={visible}
      onRequestClose={onClose}
    >
      <Pressable
        accessibilityHint='Tap anywhere to close tooltip'
        accessibilityLabel='Close tooltip'
        accessibilityRole='button'
        style={styles.backdrop}
        onPress={onClose}
      >
        <AnimatedView
          accessible
          accessibilityLabel={tooltipText}
          accessibilityLiveRegion='polite'
          accessibilityRole='tooltip'
          style={[styles.tooltip, tooltipStyle, animatedStyle]}
        >
          <Text style={styles.tooltipText}>{tooltipText}</Text>
          <View style={styles.arrow} />
        </AnimatedView>
      </Pressable>
    </Modal>
  );
});

export default HeatmapTooltip;

/**
 * InlineHeatmapGrid Component
 *
 * Renders the inline grid rows for the simplified BinaryHeatmap.
 * Used by BinaryHeatmapNew when Metro caching issues require inline rendering.
 */

import React, { memo, useMemo } from 'react';
import { View, Text, ScrollView } from 'react-native';

import type { MonthLabel, BinaryDay } from './types';
import { CELL_SIZE, CELL_GAP, GRID } from './constants';
import { styles } from './BinaryHeatmapNew.styles';
import { getCellBackgroundColor, transformWeeksToRows } from './cellHelpers';

const DAY_LABELS = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];

export interface InlineHeatmapGridProps {
  weeks: (BinaryDay | null)[][];
  monthLabels: MonthLabel[];
  habitColor: string;
}

export const InlineHeatmapGrid = memo(function InlineHeatmapGrid({
  weeks,
  monthLabels,
  habitColor,
}: InlineHeatmapGridProps) {
  const rows = useMemo(() => transformWeeksToRows(weeks, GRID.ROWS), [weeks]);
  const gridContentWidth = weeks.length * (CELL_SIZE + CELL_GAP);

  return (
    <View style={styles.gridContainer}>
      <View style={styles.dayLabelsColumn}>
        <View style={styles.monthLabelSpacer} />
        {DAY_LABELS.map((label, index) => (
          <View key={`label-${index}`} style={styles.dayLabelCell}>
            <Text style={styles.dayLabelText}>{label}</Text>
          </View>
        ))}
      </View>
      <ScrollView
        horizontal
        contentContainerStyle={{ width: gridContentWidth }}
        showsHorizontalScrollIndicator={false}
      >
        <View>
          <View style={styles.monthLabelsRow}>
            {monthLabels.map((ml, i) => (
              <Text
                key={`month-${i}`}
                style={[
                  styles.monthLabel,
                  { left: ml.weekIndex * (CELL_SIZE + CELL_GAP) },
                ]}
              >
                {ml.label}
              </Text>
            ))}
          </View>
          {rows.map((row, dayIndex) => (
            <View key={`row-${dayIndex}`} style={styles.gridRow}>
              {row.map((day, weekIndex) => (
                <View
                  key={day?.date ?? `empty-${dayIndex}-${weekIndex}`}
                  style={[
                    styles.cell,
                    {
                      backgroundColor: getCellBackgroundColor(day, habitColor),
                      borderColor: day?.isToday ? habitColor : 'transparent',
                      borderWidth: day?.isToday ? 2 : 0,
                      opacity: day?.isFuture ? 0.4 : 1,
                    },
                  ]}
                />
              ))}
            </View>
          ))}
        </View>
      </ScrollView>
    </View>
  );
});

/**
 * MonthLabelsRow Component
 *
 * Renders the month labels row above the binary heatmap grid.
 */

import React, { memo } from 'react';
import { View, Text } from 'react-native';

import type { BinaryMonthLabel } from './types';
import { CELL_SIZE, CELL_GAP, MONTH_LABEL } from './constants';
import { styles } from './MonthLabelsRow.styles';
import { getFullMonthName } from './MonthLabelsRow.helpers';

export interface MonthLabelsRowProps {
  monthLabels: BinaryMonthLabel[];
  gridWidth: number;
}

export const MonthLabelsRow = memo(function MonthLabelsRow({
  monthLabels,
  gridWidth,
}: MonthLabelsRowProps) {
  const cellUnit = CELL_SIZE + CELL_GAP;

  if (monthLabels.length === 0) {
    return (
      <View
        accessible
        accessibilityLabel='Month labels row'
        accessibilityRole='header'
        style={[styles.container, { width: gridWidth }]}
      />
    );
  }

  return (
    <View
      accessible
      accessibilityLabel='Month labels row'
      accessibilityRole='header'
      style={[styles.container, { width: gridWidth }]}
    >
      {monthLabels.map((monthLabel, index) => {
        const leftPosition = monthLabel.weekIndex * cellUnit;
        const nextLabelIndex = index + 1;
        const nextLeftPosition =
          nextLabelIndex < monthLabels.length
            ? monthLabels[nextLabelIndex].weekIndex * cellUnit
            : gridWidth;
        const width = Math.max(
          nextLeftPosition - leftPosition,
          MONTH_LABEL.MIN_WIDTH
        );

        return (
          <View
            key={`month-${monthLabel.label}-${monthLabel.weekIndex}`}
            style={[styles.labelContainer, { left: leftPosition, width }]}
          >
            <Text
              accessible
              accessibilityLabel={`${getFullMonthName(monthLabel.label)} column`}
              accessibilityRole='text'
              style={styles.labelText}
            >
              {monthLabel.label}
            </Text>
          </View>
        );
      })}
    </View>
  );
});

export default MonthLabelsRow;

