/**
 * MonthlyCalendarGrid Component
 *
 * Full monthly calendar view with habit-colored completion indicators.
 */

import React, { memo, useState, useCallback } from 'react';
import { View, Text } from 'react-native';
import { addMonths, subMonths } from 'date-fns';
import type { MonthlyCalendarGridProps } from './types';
import { styles } from './styles';
import { useCalendarDays } from './useCalendarDays';
import { CalendarDay } from './CalendarDay';
import { MonthNavigation } from './MonthNavigation';

const DAY_HEADERS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

export const MonthlyCalendarGrid = memo(function MonthlyCalendarGrid({
  habitId: _habitId,
  completedDates,
  habitColor,
  habitCreatedAt,
  onDayPress,
}: MonthlyCalendarGridProps) {
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const { weeks } = useCalendarDays({
    completedDates,
    currentMonth,
    habitCreatedAt,
  });

  const goToPreviousMonth = useCallback(() => {
    setCurrentMonth((prev) => subMonths(prev, 1));
  }, []);

  const goToNextMonth = useCallback(() => {
    setCurrentMonth((prev) => addMonths(prev, 1));
  }, []);

  const handleDayPress = useCallback(
    (dateString: string, isCompleted: boolean) => {
      onDayPress?.(dateString, isCompleted);
    },
    [onDayPress]
  );

  return (
    <View style={styles.container}>
      <View style={styles.row}>
        {DAY_HEADERS.map((day) => (
          <View key={day} style={styles.headerCell}>
            <Text style={styles.headerText}>{day}</Text>
          </View>
        ))}
      </View>

      {weeks.map((week, weekIndex) => (
        <View key={`week-${weekIndex}`} style={styles.row}>
          {week.map((day) => (
            <CalendarDay
              key={day.dateString}
              day={day}
              habitColor={habitColor}
              onPress={handleDayPress}
            />
          ))}
        </View>
      ))}

      <MonthNavigation
        currentMonth={currentMonth}
        onNextMonth={goToNextMonth}
        onPreviousMonth={goToPreviousMonth}
      />
    </View>
  );
});

export default MonthlyCalendarGrid;

/**
 * StatsRow Component
 *
 * Displays habit statistics in a row format below the heatmap.
 */

import React, { memo, useCallback } from 'react';
import { View, Text, Pressable, Platform } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  useReducedMotion,
} from 'react-native-reanimated';
import { Settings } from 'lucide-react-native';

import type { StatsRowProps } from './types';
import { COLORS } from './constants';
import { styles } from './StatsRow.styles';
import { StreakBadge } from './StreakBadge';

const PRESS_SCALE = 0.95;
const SETTINGS_ICON_SIZE = 18;
const SPRING_CONFIG = { damping: 15, stiffness: 400 };
const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

export const StatsRow = memo(function StatsRow({
  frequency,
  currentStreak,
  habitColor,
  onSettingsPress,
}: StatsRowProps) {
  const shouldReduceMotion = useReducedMotion();
  const settingsScale = useSharedValue(1);

  const handleSettingsPressIn = useCallback(() => {
    if (!shouldReduceMotion) {
      settingsScale.value = withSpring(PRESS_SCALE, SPRING_CONFIG);
    }
  }, [settingsScale, shouldReduceMotion]);

  const handleSettingsPressOut = useCallback(() => {
    if (!shouldReduceMotion) {
      settingsScale.value = withSpring(1, SPRING_CONFIG);
    }
  }, [settingsScale, shouldReduceMotion]);

  const settingsAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: settingsScale.value }],
  }));

  return (
    <View
      accessible
      accessibilityLabel='Habit statistics'
      accessibilityRole='none'
      style={styles.container}
    >
      <View style={styles.badgesContainer}>
        <View
          accessible
          accessibilityLabel={`Frequency: ${frequency}`}
          accessibilityRole='text'
          style={styles.frequencyBadge}
        >
          <Text style={styles.frequencyText}>{frequency}</Text>
        </View>
        {currentStreak > 0 && (
          <StreakBadge currentStreak={currentStreak} habitColor={habitColor} />
        )}
      </View>
      {onSettingsPress && (
        <AnimatedPressable
          accessible
          accessibilityHint='Opens habit settings and options'
          accessibilityLabel='Habit settings'
          accessibilityRole='button'
          hitSlop={{ bottom: 8, left: 8, right: 8, top: 8 }}
          style={({ focused }: { focused: boolean }) => [
            styles.settingsButton,
            settingsAnimatedStyle,
            Platform.OS === 'web' && focused && styles.webFocus,
          ]}
          testID='stats-row-settings-button'
          onPress={onSettingsPress}
          onPressIn={handleSettingsPressIn}
          onPressOut={handleSettingsPressOut}
        >
          <Settings
            color={COLORS.TEXT_SECONDARY}
            size={SETTINGS_ICON_SIZE}
            strokeWidth={2}
            testID='settings-icon'
          />
        </AnimatedPressable>
      )}
    </View>
  );
});

export default StatsRow;

/**
 * BinaryHeatmap Grid Generation
 *
 * Core grid generation for the GitHub-style binary heatmap.
 */

import {
  format,
  isAfter,
  isBefore,
  isSameDay,
  startOfWeek,
  startOfDay,
  addDays,
  subDays,
} from 'date-fns';

import type {
  TimeRange,
  BinaryDay,
  BinaryMonthLabel,
  BinaryGridData,
} from './types';
import { TIME_RANGE_CONFIG } from './constants';
import { calculateBinaryGridStats } from './gridStats';

/** Get the number of days for a given time range */
export function getTimeRangeDays(timeRange: TimeRange): number {
  return TIME_RANGE_CONFIG[timeRange].days;
}

/** Generate the binary heatmap grid for a given time range */
export function generateBinaryGrid(
  timeRange: TimeRange,
  completedDates: Set<string>,
  habitCreatedAt?: number,
  currentDate: Date = new Date()
): BinaryGridData {
  const today = startOfDay(currentDate);
  const todayStr = format(today, 'yyyy-MM-dd');
  const daysToShow = getTimeRangeDays(timeRange);
  const endDate = today;
  const startDate = subDays(today, daysToShow - 1);
  const gridStartDate = startOfWeek(startDate, { weekStartsOn: 0 });
  const habitCreatedDate = habitCreatedAt
    ? startOfDay(new Date(habitCreatedAt))
    : null;

  const weeks: (BinaryDay | null)[][] = [];
  const monthLabels: BinaryMonthLabel[] = [];
  let currentWeek: (BinaryDay | null)[] = [];
  let weekIndex = 0;
  let lastMonth = -1;
  let iterDate = new Date(gridStartDate);

  while (iterDate <= endDate) {
    const dayOfWeek = iterDate.getDay();
    const dateStr = format(iterDate, 'yyyy-MM-dd');
    const isInRange = iterDate >= startDate && iterDate <= endDate;
    const isToday = dateStr === todayStr;
    const isFuture = isAfter(iterDate, today) && !isToday;
    const hasCompletionData = completedDates.has(dateStr);
    const isBeforeCreation = habitCreatedDate
      ? isBefore(iterDate, habitCreatedDate) &&
        !isSameDay(iterDate, habitCreatedDate) &&
        !hasCompletionData
      : false;

    if (isInRange) {
      const currentMonth = iterDate.getMonth();
      if (currentMonth !== lastMonth) {
        monthLabels.push({ label: format(iterDate, 'MMM'), weekIndex });
        lastMonth = currentMonth;
      }
      currentWeek[dayOfWeek] = {
        completed: completedDates.has(dateStr),
        date: dateStr,
        isBeforeCreation,
        isFuture,
        isToday,
      };
    } else if (iterDate < startDate) {
      currentWeek[dayOfWeek] = null;
    }

    if (dayOfWeek === 6) {
      for (let i = 0; i < 7; i++) {
        if (currentWeek[i] === undefined) currentWeek[i] = null;
      }
      weeks.push([...currentWeek]);
      currentWeek = [];
      weekIndex++;
    }
    iterDate = addDays(iterDate, 1);
  }

  if (currentWeek.length > 0) {
    for (let i = 0; i < 7; i++) {
      if (currentWeek[i] === undefined) currentWeek[i] = null;
    }
    weeks.push([...currentWeek]);
  }

  return { monthLabels, stats: calculateBinaryGridStats(weeks), weeks };
}

/**
 * Button Component - React Native
 * Based on UX Specification Section 4.2
 *
 * Variants: Primary (filled), Secondary (outlined), Ghost (text only), Icon (circular)
 * States: Default, Pressed (scale 0.95), Disabled (50% opacity), Loading (spinner)
 * Sizes: Small (32pt), Medium (44pt), Large (56pt)
 */

import { Pressable, type ViewStyle } from 'react-native';
import Animated from 'react-native-reanimated';
import { useAppTheme } from '../../theme';
import { ButtonContent } from './ButtonContent';
import { styles } from './styles';
import type { ButtonProps } from './types';
import { useButtonAnimation } from './useButtonAnimation';
import { useButtonConfig } from './useButtonConfig';

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

export function Button({
  children,
  variant = 'primary',
  size = 'medium',
  loading = false,
  disabled = false,
  icon,
  iconPosition = 'left',
  fullWidth = false,
  style,
  textStyle,
  onPress,
  ...pressableProps
}: ButtonProps) {
  const theme = useAppTheme();
  const { animatedStyle, handlePressIn, handlePressOut } = useButtonAnimation();
  const { config, variantStyles } = useButtonConfig(size, variant);

  const disabledStyles: ViewStyle = disabled || loading ? { opacity: 0.5 } : {};

  return (
    <AnimatedPressable
      accessible
      accessibilityRole='button'
      accessibilityState={{ disabled: disabled || loading }}
      disabled={disabled || loading}
      style={[
        animatedStyle,
        styles.base,
        {
          borderRadius:
            variant === 'icon'
              ? config.height / 2
              : theme.custom.borderRadius.small,
          height: config.height,
          paddingHorizontal: variant === 'icon' ? 0 : config.paddingHorizontal,
        },
        variantStyles.container,
        disabledStyles,
        fullWidth && styles.fullWidth,
        variant !== 'icon' && theme.custom.shadows.card,
        style,
      ]}
      onPress={disabled || loading ? undefined : onPress}
      onPressIn={handlePressIn}
      onPressOut={handlePressOut}
      {...pressableProps}
    >
      <ButtonContent
        icon={icon}
        iconPosition={iconPosition}
        loading={loading}
        textStyle={textStyle}
        variant={variant}
        variantStyles={variantStyles}
      >
        {children}
      </ButtonContent>
    </AnimatedPressable>
  );
}

export default Button;

export { Button } from './Button';
export { default } from './Button';
export type { ButtonProps, ButtonVariant, ButtonSize } from './types';

