import type { ViewStyle, TextStyle } from 'react-native';
import { useAppTheme } from '../../theme';
import type { ButtonSize, ButtonVariant, SizeConfig, VariantStyles } from './types';

/**
 * Custom hook for button size and variant configuration
 */
export function useButtonConfig(size: ButtonSize, variant: ButtonVariant): {
  config: SizeConfig;
  variantStyles: VariantStyles;
} {
  const theme = useAppTheme();

  const sizeConfigs: Record<ButtonSize, SizeConfig> = {
    large: {
      fontSize: 17,
      height: 56,
      iconSize: 24,
      paddingHorizontal: theme.custom.spacing.xl,
    },
    medium: {
      fontSize: 17,
      height: theme.custom.componentSpacing.button.height,
      iconSize: 20,
      paddingHorizontal: theme.custom.spacing.lg,
    },
    small: {
      fontSize: 15,
      height: 32,
      iconSize: 16,
      paddingHorizontal: theme.custom.spacing.base,
    },
  };

  const config = sizeConfigs[size];

  const getVariantStyles = (): VariantStyles => {
    switch (variant) {
      case 'primary':
        return {
          container: {
            backgroundColor: theme.custom.colors.primary[500],
            borderWidth: 0,
          },
          text: { color: '#FFFFFF' },
        };

      case 'secondary':
        return {
          container: {
            backgroundColor: 'transparent',
            borderColor: theme.custom.colors.primary[500],
            borderWidth: 1.5,
          },
          text: { color: theme.custom.colors.primary[500] },
        };

      case 'ghost':
        return {
          container: {
            backgroundColor: 'transparent',
            borderWidth: 0,
          },
          text: { color: theme.custom.colors.primary[500] },
        };

      case 'icon':
        return {
          container: {
            backgroundColor: theme.custom.colors.gray[100],
            borderRadius: config.height / 2,
            borderWidth: 0,
            height: config.height,
            paddingHorizontal: 0,
            width: config.height,
          },
          text: { color: theme.custom.colors.gray[700] },
        };

      default:
        return { container: {}, text: {} };
    }
  };

  return { config, variantStyles: getVariantStyles() };
}

/**
 * CalendarTimeline Component - Example Usage
 *
 * This file demonstrates different ways to use the CalendarTimeline component
 * based on the Figma design (node 201:87).
 */

import React, { useState } from 'react';
import { View, Text } from 'react-native';
import { CalendarTimeline } from './CalendarTimeline';
import { addDays, startOfWeek, format } from 'date-fns';

/**
 * Example 1: Basic Timeline (Mon-Fri)
 * Matches the Figma design exactly - shows 5 weekdays
 */
export function BasicTimelineExample() {
  // Get Monday of current week
  const monday = startOfWeek(new Date(), { weekStartsOn: 1 });

  // Generate Mon-Fri dates
  const weekdays = Array.from({ length: 5 }, (_, i) => addDays(monday, i));

  return (
    <View className='bg-white'>
      <CalendarTimeline showSeparator dates={weekdays} />
    </View>
  );
}

/**
 * Example 2: Interactive Timeline with Selection
 * Allows users to select a date from the timeline
 */
export function InteractiveTimelineExample() {
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());

  const today = new Date();
  const dates = Array.from({ length: 7 }, (_, i) => addDays(today, i));

  return (
    <View className='bg-white'>
      <CalendarTimeline
        showSeparator
        dates={dates}
        selectedDate={selectedDate}
        onDateSelect={(date) => {
          setSelectedDate(date);
          console.log('Selected date:', format(date, 'MMM d, yyyy'));
        }}
      />

      {/* Display selected date */}
      <View className='px-6 py-4'>
        <Text className='text-[14px] text-[#4a5565]'>
          Selected: {format(selectedDate, 'EEEE, MMMM d, yyyy')}
        </Text>
      </View>
    </View>
  );
}

/**
 * Example 3: Extended Week View
 * Shows a full 7-day week (Sun-Sat)
 */
export function ExtendedWeekExample() {
  const sunday = startOfWeek(new Date(), { weekStartsOn: 0 });
  const fullWeek = Array.from({ length: 7 }, (_, i) => addDays(sunday, i));

  return (
    <View className='bg-white'>
      <CalendarTimeline showSeparator dates={fullWeek} />
    </View>
  );
}

/**
 * Example 4: Scrolling Timeline (2 weeks)
 * Demonstrates horizontal scrolling with more dates
 */
export function ScrollingTimelineExample() {
  const today = new Date();
  const twoWeeks = Array.from({ length: 14 }, (_, i) => addDays(today, i));

  return (
    <View className='bg-white'>
      <View className='pb-2 pt-4'>
        <Text className='px-6 text-[16px] font-semibold text-[#101727]'>
          Next 2 Weeks
        </Text>
      </View>
      <CalendarTimeline showSeparator dates={twoWeeks} />
    </View>
  );
}

/**
 * Example 5: Minimal Timeline (No Separator)
 * Clean version without the gradient separator line
 */
export function MinimalTimelineExample() {
  const today = new Date();
  const dates = Array.from({ length: 5 }, (_, i) => addDays(today, i));

  return (
    <View className='bg-[#fafaf9]'>
      <CalendarTimeline dates={dates} showSeparator={false} />
    </View>
  );
}

/**
 * Example 6: Timeline in a Card
 * Shows how to integrate the timeline within a larger UI component
 */
export function TimelineInCardExample() {
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());

  const monday = startOfWeek(new Date(), { weekStartsOn: 1 });
  const weekdays = Array.from({ length: 5 }, (_, i) => addDays(monday, i));
  const lastWeekday = weekdays.at(-1);

  return (
    <View className='bg-[#f5f5f4] p-4'>
      <View className='overflow-hidden rounded-2xl bg-white shadow-sm'>
        {/* Header */}
        <View className='border-b border-[#e7e5e4] px-6 py-4'>
          <Text className='text-[18px] font-semibold text-[#101727]'>
            This Week
          </Text>
          <Text className='mt-1 text-[13px] text-[#6a7282]'>
            {format(weekdays[0], 'MMM d')} -{' '}
            {format(lastWeekday, 'MMM d, yyyy')}
          </Text>
        </View>

        {/* Timeline */}
        <CalendarTimeline
          showSeparator
          dates={weekdays}
          selectedDate={selectedDate}
          onDateSelect={setSelectedDate}
        />

        {/* Content area */}
        <View className='p-6'>
          <Text className='text-[14px] text-[#4a5565]'>
            {format(selectedDate, 'EEEE, MMMM d')}
          </Text>
          {/* Add your habit tracking or other content here */}
        </View>
      </View>
    </View>
  );
}

/**
 * Default export for easy importing
 */
export default function CalendarTimelineExamples() {
  return (
    <View className='gap-8 bg-[#f3f4f6] p-4'>
      <BasicTimelineExample />
      <InteractiveTimelineExample />
      <ExtendedWeekExample />
      <ScrollingTimelineExample />
      <MinimalTimelineExample />
      <TimelineInCardExample />
    </View>
  );
}

import React, { memo } from 'react';
import { View } from 'react-native';
import { format } from 'date-fns';

import { useCalendarTimelineLogic } from './CalendarTimeline.hooks';
import { CONTAINER_SHADOW, getColors } from './CalendarTimeline.styles';
import type {
  CalendarTimelineProps,
  CompletionStatus,
} from './CalendarTimeline.types';
import { DayCell, WeekNavigationHeader } from './components';

const CalendarTimelineComponent: React.FC<CalendarTimelineProps> = ({
  dates,
  onPreviousWeek,
  onNextWeek,
  canNavigateForward = true,
  highContrastMode = false,
  completionByDay = {},
  reduceMotion = false,
  onDayPress,
  isDayPressEnabled,
  disableFutureDayPress = true,
}) => {
  const { isToday, isFuture } = useCalendarTimelineLogic();
  const colors = getColors(highContrastMode);

  const getCompletionStatus = (date: Date): CompletionStatus => {
    if (isFuture(date)) return 'future';
    const dateString = format(date, 'yyyy-MM-dd');
    const dayStatus = completionByDay[dateString];
    if (!dayStatus || dayStatus.total === 0) return 'none';
    if (dayStatus.completed === dayStatus.total) return 'complete';
    if (dayStatus.completed > 0) return 'partial';
    return 'none';
  };

  if (dates.length === 0) {
    return null;
  }

  const firstDate = dates[0];
  const lastDate = dates.at(-1);
  const dateRangeText = `${format(firstDate, 'MMM d')} - ${format(lastDate, 'MMM d')}`;
  const hasCompletionData = Object.keys(completionByDay).length > 0;

  // Augment colors with high contrast border info for DayCell
  const augmentedColors = {
    ...colors,
    borderWidth: highContrastMode ? 2 : 0,
    highContrastBorder: highContrastMode ? colors.dayBorder : undefined,
  };

  return (
    <View
      className='mb-4 rounded-2xl px-3 pb-3 pt-2'
      style={{
        backgroundColor: highContrastMode ? 'transparent' : '#ffffff',
        borderColor: highContrastMode ? 'transparent' : '#f5f5f4',
        borderWidth: highContrastMode ? 0 : 1,
        ...CONTAINER_SHADOW,
      }}
    >
      <WeekNavigationHeader
        canNavigateForward={canNavigateForward}
        colors={colors}
        dateRangeText={dateRangeText}
        onNextWeek={onNextWeek}
        onPreviousWeek={onPreviousWeek}
      />

      <View className='flex-row items-start justify-between'>
        {dates.map((date, index) => (
          <DayCell
            key={`timeline-day-${index}`}
            colors={augmentedColors}
            completionStatus={getCompletionStatus(date)}
            date={date}
            disableFutureDayPress={disableFutureDayPress}
            hasCompletionData={hasCompletionData}
            index={index}
            isCurrentDay={isToday(date)}
            isDayPressEnabled={isDayPressEnabled ?? !!onDayPress}
            isUpcoming={isFuture(date)}
            reduceMotion={reduceMotion}
            onDayPress={onDayPress}
          />
        ))}
      </View>
    </View>
  );
};

export const CalendarTimeline = memo(CalendarTimelineComponent);

/**
 * CalendarTimeline - DEBUG VERSION
 *
 * Super obvious colored gradients to verify the effect is working
 * Use this temporarily to see if gradients render, then switch back to subtle version
 */

import React, { memo } from 'react';
import { View, Text, Pressable } from 'react-native';
import { format } from 'date-fns';
import { ChevronLeft, ChevronRight } from 'lucide-react-native';
import { LinearGradient } from 'expo-linear-gradient';
import { useCalendarTimelineLogic } from './CalendarTimeline.hooks';

export interface CalendarTimelineProps {
  dates: Date[];
  onPreviousWeek?: () => void;
  onNextWeek?: () => void;
  canNavigateForward?: boolean;
  showSeparator?: boolean;
  highContrastMode?: boolean;
  selectedDate?: Date;
  onDateSelect?: (date: Date) => void;
}

const CalendarTimelineDebug: React.FC<CalendarTimelineProps> = ({
  dates,
  onPreviousWeek,
  onNextWeek,
  canNavigateForward = true,
  showSeparator = true,
  highContrastMode = false,
  selectedDate: _selectedDate,
  onDateSelect: _onDateSelect,
}) => {
  const { isToday, isFuture } = useCalendarTimelineLogic();

  if (dates.length === 0) {
    return null;
  }

  const firstDate = dates[0];
  const lastDate = dates.at(-1);
  const dateRangeText = lastDate
    ? `${format(firstDate, 'MMM d')} - ${format(lastDate, 'MMM d')}`
    : format(firstDate, 'MMM d');

  const colors = highContrastMode
    ? {
        currentDayBackground: '#facc15',
        currentDayText: '#000000',
        dayBackground: '#000000',
        dayBorder: '#facc15',
        dayText: '#ffffff',
        icon: '#facc15',
        primaryText: '#ffffff',
        secondaryText: '#facc15',
      }
    : {
        currentDayBackground: '#1a1a1a',
        currentDayText: '#ffffff',
        dayBackground: '#ffffff',
        dayBorder: 'transparent',
        dayText: '#1a1a1a',
        icon: '#1a1a1a',
        primaryText: '#1a1a1a',
        secondaryText: '#9ca3af',
      };

  const backgroundColor = highContrastMode ? 'transparent' : '#f9fafb';

  return (
    <View
      className='mb-0 rounded-2xl pb-3 pt-1'
      style={{ backgroundColor }}
    >
      {/* DEBUG: Bright colored gradients to verify they work */}
      <View className='relative mb-2.5 flex-row items-center justify-between'>
        {/* LEFT GRADIENT - BRIGHT BLUE for debugging */}
        <View
          className='absolute left-0 top-0 bottom-0 pointer-events-none'
          style={{ width: 80, zIndex: 5 }}
        >
          <LinearGradient
            colors={[
              'rgba(59, 130, 246, 0.8)',   // Bright blue
              'rgba(59, 130, 246, 0.5)',
              'rgba(59, 130, 246, 0.3)',
              'rgba(59, 130, 246, 0)',
            ]}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 0 }}
            style={{ flex: 1 }}
          />
        </View>

        <Pressable
          accessibilityLabel='Previous week'
          accessibilityRole='button'
          className='h-9 w-7 items-center justify-center rounded-full'
          hitSlop={{ top: 12, bottom: 12, left: 12, right: 12 }}
          onPress={onPreviousWeek}
          style={{ zIndex: 20 }}
        >
          <ChevronLeft color={colors.icon} size={18} strokeWidth={2} />
        </Pressable>

        <Text
          className='text-[17px] font-semibold leading-[22px]'
          style={{ color: colors.primaryText }}
        >
          {dateRangeText} 🐛 DEBUG
        </Text>

        <Pressable
          accessibilityLabel='Next week'
          accessibilityRole='button'
          accessibilityState={{ disabled: !canNavigateForward }}
          className={`h-9 w-7 items-center justify-center rounded-full ${canNavigateForward ? '' : 'opacity-40'}`}
          disabled={!canNavigateForward}
          hitSlop={{ top: 12, bottom: 12, left: 12, right: 12 }}
          onPress={onNextWeek}
          style={{ zIndex: 20 }}
        >
          <ChevronRight color={colors.icon} size={18} strokeWidth={2} />
        </Pressable>

        {/* RIGHT GRADIENT - BRIGHT GREEN for debugging */}
        {canNavigateForward && (
          <View
            className='absolute right-0 top-0 bottom-0 pointer-events-none'
            style={{ width: 80, zIndex: 5 }}
          >
            <LinearGradient
              colors={[
                'rgba(34, 197, 94, 0)',     // Transparent
                'rgba(34, 197, 94, 0.3)',
                'rgba(34, 197, 94, 0.5)',
                'rgba(34, 197, 94, 0.8)',   // Bright green
              ]}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 0 }}
              style={{ flex: 1 }}
            />
          </View>
        )}
      </View>

      {/* Days Row */}
      <View className='flex-row items-start justify-between'>
        {dates.map((date, index) => {
          const weekday = format(date, 'EEE');
          const dayNumber = format(date, 'd');
          const isCurrentDay = isToday(date);
          const isUpcoming = isFuture(date);

          const baseLabel = `${weekday}, ${format(date, 'MMM')} ${dayNumber}`;
          const accessibilityLabel = isCurrentDay
            ? `Today, ${baseLabel}`
            : baseLabel;

          return (
            <View
              key={`timeline-day-${index}`}
              accessibilityLabel={accessibilityLabel}
              accessibilityRole='text'
              className='flex-1 items-center gap-0.5'
            >
              <Text
                className='text-center text-[13px] font-normal leading-[18px]'
                style={{ color: colors.secondaryText }}
              >
                {weekday}
              </Text>

              <View
                className='h-9 w-9 items-center justify-center rounded-[11px]'
                style={{
                  backgroundColor: isCurrentDay
