import React, { useEffect, useRef } from 'react';
import { Animated, Easing } from 'react-native';

import {
  COMPLETE_DOT_GLOW,
  COMPLETION_DOT_COLORS,
  COMPLETION_DOT_SIZES,
} from '../CalendarTimeline.styles';
import type { CompletionDotProps } from '../CalendarTimeline.types';

/** Animated completion indicator dot */
export const CompletionDot: React.FC<CompletionDotProps> = ({
  status,
  reduceMotion = false,
  isToday = false,
}) => {
  const scaleAnim = useRef(new Animated.Value(0)).current;
  const pulseAnim = useRef(new Animated.Value(1)).current;

  useEffect(() => {
    if (reduceMotion) {
      scaleAnim.setValue(1);
      return;
    }

    const springAnim = Animated.spring(scaleAnim, {
      friction: 6,
      tension: 200,
      toValue: 1,
      useNativeDriver: true,
    });
    springAnim.start();

    // Pulse animation for today's incomplete status
    let pulseAnimation: Animated.CompositeAnimation | null = null;
    if (isToday && status !== 'complete' && status !== 'future') {
      pulseAnimation = Animated.loop(
        Animated.sequence([
          Animated.timing(pulseAnim, {
            duration: 1000,
            easing: Easing.inOut(Easing.ease),
            toValue: 1.3,
            useNativeDriver: true,
          }),
          Animated.timing(pulseAnim, {
            duration: 1000,
            easing: Easing.inOut(Easing.ease),
            toValue: 1,
            useNativeDriver: true,
          }),
        ])
      );
      pulseAnimation.start();
    }

    return () => {
      springAnim.stop();
      if (pulseAnimation) {
        pulseAnimation.stop();
      }
      pulseAnim.setValue(1);
    };
  }, [status, reduceMotion, isToday, scaleAnim, pulseAnim]);

  const color = COMPLETION_DOT_COLORS[status];
  const size = COMPLETION_DOT_SIZES[status];

  return (
    <Animated.View
      style={{
        backgroundColor: color,
        borderRadius: size / 2,
        height: size,
        transform: [
          { scale: scaleAnim },
          { scale: isToday && status !== 'complete' ? pulseAnim : 1 },
        ],
        width: size,
        ...(status === 'complete' && COMPLETE_DOT_GLOW),
      }}
    />
  );
};

import React from 'react';
import { View, Pressable } from 'react-native';
import { format } from 'date-fns';

import type { DayCellProps } from '../CalendarTimeline.types';

import {
  buildAccessibilityLabel,
  getAccessibilityHint,
  getStatusText,
} from './DayCell.helpers';
import { DayCellContent } from './DayCellContent';

/** Renders a single day cell in the timeline */
export const DayCell: React.FC<DayCellProps> = ({
  date,
  index,
  isCurrentDay,
  isUpcoming,
  completionStatus,
  hasCompletionData,
  colors,
  reduceMotion,
  onDayPress,
  isDayPressEnabled,
  disableFutureDayPress,
}) => {
  const weekday = format(date, 'EEE');
  const dayNumber = format(date, 'd');
  const baseLabel = `${weekday}, ${format(date, 'MMM')} ${dayNumber}`;

  const isDayDisabled = isUpcoming && disableFutureDayPress;
  const canPressDay = isDayPressEnabled && onDayPress && !isDayDisabled;

  const statusText = getStatusText(completionStatus);
  const accessibilityLabel = buildAccessibilityLabel(
    isCurrentDay,
    baseLabel,
    statusText
  );
  const accessibilityHint = getAccessibilityHint(canPressDay, isDayDisabled);

  const contentProps = {
    colors,
    completionStatus,
    dayNumber,
    hasCompletionData,
    isCurrentDay,
    isUpcoming,
    reduceMotion,
    weekday,
  };

  if (onDayPress) {
    return (
      <Pressable
        key={`timeline-day-${index}`}
        accessibilityHint={accessibilityHint}
        accessibilityLabel={accessibilityLabel}
        accessibilityRole='button'
        accessibilityState={{ disabled: isDayDisabled }}
        className='flex-1 items-center gap-0.5'
        disabled={isDayDisabled}
        style={{ opacity: isDayDisabled ? 0.5 : 1 }}
        onPress={() => onDayPress(date)}
      >
        {({ pressed }) => (
          <DayCellContent {...contentProps} pressed={pressed} />
        )}
      </Pressable>
    );
  }

  return (
    <View
      key={`timeline-day-${index}`}
      accessibilityLabel={accessibilityLabel}
      accessibilityRole='text'
      className='flex-1 items-center gap-0.5'
    >
      <DayCellContent {...contentProps} />
    </View>
  );
};

