import { Pressable, Text, View } from 'react-native';
import Animated from 'react-native-reanimated';
import { useHapticFeedback } from '../../../../hooks/useHapticFeedback';
import { useCategoryFilterAnimations } from './useCategoryFilterAnimations';
import type { CategoryFilterItemProps } from './CategoryFilters.types';

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

export function CategoryFilterItem({
  category,
  colors,
  index,
  onSelect,
  selected,
}: CategoryFilterItemProps) {
  const { triggerLightImpact, triggerSelection } = useHapticFeedback({});
  const {
    entranceAnimatedStyle,
    pressAnimatedStyle,
    handlePressIn,
    handlePressOut,
  } = useCategoryFilterAnimations(index);

  return (
    <Animated.View style={entranceAnimatedStyle}>
      <AnimatedPressable
        accessibilityLabel={`Filter by ${category.label}`}
        accessibilityRole='button'
        accessibilityState={{ selected }}
        className='flex-row items-center gap-1.5 rounded-full px-4 py-3'
        style={[
          pressAnimatedStyle,
          {
            backgroundColor: selected ? colors.bgSelected : colors.bg,
            borderColor: selected ? colors.bgSelected : colors.border,
            borderWidth: 1.5,
            minHeight: 44,
          },
        ]}
        onPress={() => {
          triggerSelection();
          onSelect(category.id);
        }}
        onPressIn={() => {
          triggerLightImpact();
          handlePressIn();
        }}
        onPressOut={handlePressOut}
      >
        {!selected && (
          <View
            className='h-2 w-2 rounded-full'
            style={{ backgroundColor: colors.bgSelected }}
          />
        )}
        <Text className='text-[15px]'>{category.icon}</Text>
        <Text
          className='text-[15px] font-semibold'
          style={{ color: selected ? '#FFFFFF' : colors.text }}
        >
          {category.label}
        </Text>
      </AnimatedPressable>
    </Animated.View>
  );
}

/**
 * useCategoryFilterAnimations Hook
 * Manages entrance and press animations for category filter items
 */

import { useEffect } from 'react';
import {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withTiming,
  withDelay,
  Easing,
  cancelAnimation,
} from 'react-native-reanimated';
import { useReduceMotion } from '../../../../hooks/useReduceMotion';
import {
  ENTRANCE_STAGGER_DELAY,
  ENTRANCE_DURATION,
  ENTRANCE_TRANSLATE_Y,
} from './CategoryFilters.constants';

export function useCategoryFilterAnimations(index: number) {
  const reduceMotion = useReduceMotion();
  const entranceOpacity = useSharedValue(reduceMotion ? 1 : 0);
  const entranceTranslateY = useSharedValue(
    reduceMotion ? 0 : ENTRANCE_TRANSLATE_Y
  );
  const scale = useSharedValue(1);

  useEffect(() => {
    if (reduceMotion) {
      entranceOpacity.value = 1;
      entranceTranslateY.value = 0;
      return;
    }
    const delay = index * ENTRANCE_STAGGER_DELAY;
    entranceOpacity.value = withDelay(
      delay,
      withTiming(1, {
        duration: ENTRANCE_DURATION,
        easing: Easing.out(Easing.cubic),
      })
    );
    entranceTranslateY.value = withDelay(
      delay,
      withSpring(0, { damping: 18, stiffness: 200 })
    );
    return () => {
      cancelAnimation(entranceOpacity);
      cancelAnimation(entranceTranslateY);
    };
  }, [index, reduceMotion, entranceOpacity, entranceTranslateY]);

  const entranceAnimatedStyle = useAnimatedStyle(() => ({
    opacity: entranceOpacity.value,
    transform: [{ translateY: entranceTranslateY.value }],
  }));

  const pressAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
  }));

  const handlePressIn = () => {
    if (!reduceMotion) scale.value = withTiming(0.95, { duration: 50 });
  };

  const handlePressOut = () => {
    if (!reduceMotion)
      scale.value = withSpring(1, { damping: 15, stiffness: 300 });
  };

  return {
    entranceAnimatedStyle,
    handlePressIn,
    handlePressOut,
    pressAnimatedStyle,
  };
}

