import { useState } from 'react';
import { Animated, Pressable, Text, View } from 'react-native';
import { ChevronDown } from 'lucide-react-native';
import useHapticFeedback from '../../../hooks/useHapticFeedback';

interface CollapsibleAdvancedOptionsProps {
  children: React.ReactNode;
  defaultExpanded?: boolean;
}

export const CollapsibleAdvancedOptions = ({
  children,
  defaultExpanded = false,
}: CollapsibleAdvancedOptionsProps) => {
  const [isExpanded, setIsExpanded] = useState(defaultExpanded);
  const { triggerSelection } = useHapticFeedback();

  const toggleExpanded = () => {
    triggerSelection();
    setIsExpanded(!isExpanded);
  };

  return (
    <View className='mb-6'>
      <Pressable
        accessibilityRole='button'
        accessibilityLabel={isExpanded ? 'Collapse advanced options' : 'Expand advanced options'}
        className='mb-3 flex-row items-center justify-between rounded-xl bg-white p-4'
        onPress={toggleExpanded}
      >
        <View className='flex-row items-center gap-2'>
          <Text className='text-base font-semibold text-stone-800'>⚙️ Advanced Options</Text>
          <Text className='text-xs text-stone-400'>(Optional)</Text>
        </View>
        <Animated.View
          style={{
            transform: [{ rotate: isExpanded ? '180deg' : '0deg' }],
          }}
        >
          <ChevronDown color='#78716c' size={20} />
        </Animated.View>
      </Pressable>

      {isExpanded && <View>{children}</View>}
    </View>
  );
};

export default CollapsibleAdvancedOptions;

import { memo, useCallback } from 'react';
import {
  AccessibilityInfo,
  Animated,
  Keyboard,
  StyleSheet,
  View,
} from 'react-native';
import useHapticFeedback from '../../../../hooks/useHapticFeedback';
import { getColorName } from '../../constants';
import type { ColorButtonProps } from './types';
import { useColorButtonAnimations } from './useColorButtonAnimations';
import { ColorSwatch } from './ColorSwatch';

/**
 * Individual color swatch button with selection animation
 * V12: 44px base with 52px container for better touch targets
 */
const ColorButtonComponent = ({
  color,
  isSelected,
  onSelect,
  reduceMotion,
}: ColorButtonProps) => {
  const { triggerSelection } = useHapticFeedback();
  const colorName = getColorName(color);
  const {
    animatePressIn,
    animatePressOut,
    rippleOpacity,
    rippleScale,
    scale,
    triggerRipple,
  } = useColorButtonAnimations({ isSelected, reduceMotion });

  const handlePress = useCallback(() => {
    Keyboard.dismiss();
    triggerSelection();
    triggerRipple();
    onSelect(color);
    AccessibilityInfo.announceForAccessibility(`Selected ${colorName} color`);
  }, [color, colorName, onSelect, triggerSelection, triggerRipple]);

  const selectedShadowStyle = isSelected
    ? {
        elevation: 6,
        shadowColor: '#000000',
        shadowOffset: { height: 2, width: 0 },
        shadowOpacity: 0.3,
        shadowRadius: 4,
      }
    : undefined;

  return (
    <View style={{ position: 'relative' }}>
      {/* Ripple effect layer */}
      <Animated.View
        pointerEvents='none'
        style={[
          StyleSheet.absoluteFill,
          {
            alignItems: 'center',
            justifyContent: 'center',
            opacity: rippleOpacity,
            transform: [{ scale: rippleScale }],
          },
        ]}
      >
        <View
          style={{
            backgroundColor: color,
            borderRadius: 999,
            height: 44,
            width: 44,
          }}
        />
      </Animated.View>

      {/* Main color button with outer ring for selection */}
      <View
        style={{
          alignItems: 'center',
          height: 52,
          justifyContent: 'center',
          width: 52,
        }}
      >
        <Animated.View
          style={[{ transform: [{ scale }] }, selectedShadowStyle]}
        >
          <ColorSwatch
            color={color}
            colorName={colorName}
            isSelected={isSelected}
            onPress={handlePress}
            onPressIn={animatePressIn}
            onPressOut={animatePressOut}
          />
        </Animated.View>
      </View>
    </View>
  );
};

export const ColorButton = memo(ColorButtonComponent);

