          accessibilityLabel='Start tracking habit'
          accessibilityRole='button'
          className='items-center rounded-2xl bg-stone-900 py-4'
          onPress={onComplete}
        >
          <Text className='text-base font-semibold text-white'>
            Let's get started! →
          </Text>
        </Pressable>
      </Animated.View>
    </Animated.View>
  );
};

/**
 * Animation Sequences
 *
 * Pre-built animation sequences for the success modal
 */

import { Animated } from 'react-native';

import { ANIMATION_DURATIONS } from './constants';

export interface AnimatedValues {
  backdropOpacity: Animated.Value;
  buttonOpacity: Animated.Value;
  buttonTranslateY: Animated.Value;
  cardOpacity: Animated.Value;
  cardScale: Animated.Value;
  iconScale: Animated.Value;
  textOpacity: Animated.Value;
}

export function createEntranceSequence(values: AnimatedValues) {
  const {
    backdropOpacity,
    cardScale,
    cardOpacity,
    iconScale,
    textOpacity,
    buttonOpacity,
    buttonTranslateY,
  } = values;

  return Animated.sequence([
    Animated.timing(backdropOpacity, {
      duration: ANIMATION_DURATIONS.backdropFadeIn,
      toValue: 1,
      useNativeDriver: true,
    }),
    Animated.parallel([
      Animated.spring(cardScale, {
        damping: 10,
        stiffness: 200,
        toValue: 1,
        useNativeDriver: true,
      }),
      Animated.timing(cardOpacity, {
        duration: ANIMATION_DURATIONS.cardBounce,
        toValue: 1,
        useNativeDriver: true,
      }),
    ]),
    Animated.spring(iconScale, {
      damping: 8,
      stiffness: 300,
      toValue: 1,
      useNativeDriver: true,
    }),
    Animated.timing(textOpacity, {
      duration: ANIMATION_DURATIONS.textFadeIn,
      toValue: 1,
      useNativeDriver: true,
    }),
    Animated.parallel([
      Animated.timing(buttonOpacity, {
        duration: ANIMATION_DURATIONS.buttonSlideUp,
        toValue: 1,
        useNativeDriver: true,
      }),
      Animated.spring(buttonTranslateY, {
        damping: 15,
        stiffness: 200,
        toValue: 0,
        useNativeDriver: true,
      }),
    ]),
  ]);
}

export function createExitSequence(
  values: Pick<AnimatedValues, 'backdropOpacity' | 'cardOpacity' | 'cardScale'>
) {
  const { backdropOpacity, cardOpacity, cardScale } = values;
  const duration = ANIMATION_DURATIONS.exitAnimation;

  return Animated.parallel([
    Animated.timing(cardScale, {
      duration,
      toValue: 0.9,
      useNativeDriver: true,
    }),
    Animated.timing(cardOpacity, {
      duration,
      toValue: 0,
      useNativeDriver: true,
    }),
    Animated.timing(backdropOpacity, {
      duration,
      toValue: 0,
      useNativeDriver: true,
    }),
  ]);
}

/**
 * useSuccessAnimations Hook
 *
 * Manages the animation values and sequences for the success modal
 */

import { useEffect, useRef, useCallback } from 'react';
import { Animated } from 'react-native';

import {
  createEntranceSequence,
  createExitSequence,
} from './animationSequences';

interface UseSuccessAnimationsProps {
  visible: boolean;
  onHapticFeedback: () => void;
}

export function useSuccessAnimations({
  visible,
  onHapticFeedback,
}: UseSuccessAnimationsProps) {
  const backdropOpacity = useRef(new Animated.Value(0)).current;
  const cardScale = useRef(new Animated.Value(0.5)).current;
  const cardOpacity = useRef(new Animated.Value(0)).current;
  const iconScale = useRef(new Animated.Value(0)).current;
  const textOpacity = useRef(new Animated.Value(0)).current;
  const buttonOpacity = useRef(new Animated.Value(0)).current;
  const buttonTranslateY = useRef(new Animated.Value(20)).current;

  const animatedValues = {
    backdropOpacity,
    buttonOpacity,
    buttonTranslateY,
    cardOpacity,
    cardScale,
    iconScale,
    textOpacity,
  };

  useEffect(() => {
    if (visible) {
      onHapticFeedback();
      createEntranceSequence(animatedValues).start();
    }
  }, [visible, onHapticFeedback]);

  const runExitAnimation = useCallback(
    (onComplete: () => void) => {
      createExitSequence({ backdropOpacity, cardOpacity, cardScale }).start(
        onComplete
      );
    },
    [backdropOpacity, cardOpacity, cardScale]
  );

  return { animatedValues, runExitAnimation };
}

import { useCallback, useRef } from 'react';
import { Animated, Pressable, Text, View } from 'react-native';
import { Motion } from '../../../constants/motion';
import useHapticFeedback from '../../../hooks/useHapticFeedback';

interface SuggestionChip {
  name: string;
  emoji: string;
  color: string;
}

interface SuggestionChipsProps {
  onSelect: (chip: SuggestionChip) => void;
  visible: boolean;
}

const SUGGESTION_CHIPS: SuggestionChip[] = [
  { name: 'Drink water', emoji: '💧', color: '#3B82F6' },
  { name: 'Read 10 min', emoji: '📖', color: '#8B5CF6' },
  { name: 'Meditate', emoji: '🧘', color: '#22C55E' },
  { name: 'Exercise', emoji: '🏃', color: '#F97316' },
  { name: 'Journal', emoji: '✍️', color: '#EC4899' },
  { name: 'Sleep 8h', emoji: '😴', color: '#1E293B' },
];

interface ChipButtonProps {
  chip: SuggestionChip;
  onPress: () => void;
}

const ChipButton = ({ chip, onPress }: ChipButtonProps) => {
  const scale = useRef(new Animated.Value(1)).current;
  const { triggerSelection } = useHapticFeedback();

  const handlePressIn = useCallback(() => {
    Animated.timing(scale, {
      duration: Motion.duration.fast,
      easing: Motion.easing.inEase,
      toValue: 0.95,
      useNativeDriver: true,
    }).start();
  }, [scale]);

  const handlePressOut = useCallback(() => {
    Animated.spring(scale, {
      toValue: 1,
      damping: 12,
      stiffness: 200,
      useNativeDriver: true,
    }).start();
  }, [scale]);

  const handlePress = useCallback(() => {
    triggerSelection();
    onPress();
  }, [triggerSelection, onPress]);

  return (
    <Animated.View style={{ transform: [{ scale }] }}>
      <Pressable
        accessibilityLabel={`Quick add ${chip.name} habit`}
        accessibilityRole="button"
        className="mr-2 mb-2 flex-row items-center rounded-full bg-white px-3 py-2"
        style={{
          borderWidth: 1,
          borderColor: '#e7e5e4', // stone-200
          shadowColor: '#000',
          shadowOffset: { width: 0, height: 1 },
          shadowOpacity: 0.05,
          shadowRadius: 2,
        }}
        onPress={handlePress}
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
      >
        <Text className="mr-1.5 text-base">{chip.emoji}</Text>
        <Text className="text-sm font-medium text-stone-700">{chip.name}</Text>
      </Pressable>
    </Animated.View>
  );
};

export const SuggestionChips = ({ onSelect, visible }: SuggestionChipsProps) => {
  if (!visible) return null;

  return (
    <View className="mb-3">
      <Text className="mb-2 text-xs font-medium text-stone-500">
        QUICK START
      </Text>
      <View className="flex-row flex-wrap">
        {SUGGESTION_CHIPS.map((chip) => (
          <ChipButton
            key={chip.name}
            chip={chip}
            onPress={() => onSelect(chip)}
          />
        ))}
      </View>
    </View>
  );
};

export default SuggestionChips;
export type { SuggestionChip };

