import { Animated, View } from 'react-native';
import type { Category, CategoryFilter, HabitTemplate } from '../types';
import { CategoryFilters } from './CategoryFilters';
import { TemplateHero } from './TemplateHero';
import { TemplateList } from './TemplateList';

interface TemplateBrowserProps {
  isEditMode: boolean;
  template: {
    isTemplateBrowserOpen: boolean;
    isTemplateBrowserVisible: boolean;
    templateBrowserAnim: Animated.Value;
    templateBrowserTranslate: Animated.AnimatedInterpolation<number>;
    chevronRotation: Animated.AnimatedInterpolation<string>;
    categories: CategoryFilter[];
    selectedCategory: Category;
    handleCategoryPress: (category: Category) => void;
    isLoadingTemplates: boolean;
    filteredTemplates: HabitTemplate[];
    handleTemplateSelect: (template: HabitTemplate) => void;
    closeTemplateBrowser: () => void;
    handleHeroPress: () => void;
    handleTemplateListScroll: (event: unknown) => void;
    handleTemplateListContentSizeChange: (width: number, height: number) => void;
    handleTemplateListLayout: (event: unknown) => void;
    showTemplateTopShadow: boolean;
    showTemplateBottomShadow: boolean;
  };
  onViewScience: (template: HabitTemplate) => void;
}

export const TemplateBrowser = ({ isEditMode, template, onViewScience }: TemplateBrowserProps) => {
  const {
    isTemplateBrowserOpen,
    isTemplateBrowserVisible,
    templateBrowserAnim,
    templateBrowserTranslate,
    chevronRotation,
    categories,
    selectedCategory,
    handleCategoryPress,
    isLoadingTemplates,
    filteredTemplates,
    handleTemplateSelect,
    closeTemplateBrowser,
    handleHeroPress,
    handleTemplateListScroll,
    handleTemplateListContentSizeChange,
    handleTemplateListLayout,
    showTemplateTopShadow,
    showTemplateBottomShadow,
  } = template;

  return (
    <View>
      <TemplateHero
        isEditMode={isEditMode}
        isOpen={isTemplateBrowserOpen}
        chevronRotation={chevronRotation}
        onPress={handleHeroPress}
      />
      {isTemplateBrowserVisible && (
        <Animated.View
          className='mb-6 overflow-hidden rounded-3xl bg-white shadow-lg shadow-black/10'
          pointerEvents={isTemplateBrowserOpen ? 'auto' : 'none'}
          style={{ elevation: 2, opacity: templateBrowserAnim, transform: [{ translateY: templateBrowserTranslate }] }}
        >
          <CategoryFilters
            categories={categories}
            selectedCategory={selectedCategory}
            onSelect={handleCategoryPress}
          />
          <TemplateList
            isLoading={isLoadingTemplates}
            templates={filteredTemplates}
            onSelectTemplate={handleTemplateSelect}
            onViewScience={onViewScience}
            onClose={closeTemplateBrowser}
            onScroll={handleTemplateListScroll}
            onContentSizeChange={handleTemplateListContentSizeChange}
            onLayout={handleTemplateListLayout}
            showTopShadow={showTemplateTopShadow}
            showBottomShadow={showTemplateBottomShadow}
          />
        </Animated.View>
      )}
    </View>
  );
};

import { useEffect } from 'react';
import { Pressable, Text, View } from 'react-native';
import { ChevronDown } from 'lucide-react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withTiming,
  withDelay,
  Easing,
  cancelAnimation,
} from 'react-native-reanimated';
import { useHapticFeedback } from '../../../hooks/useHapticFeedback';
import { useReduceMotion } from '../../../hooks/useReduceMotion';

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

// Entrance animation constants (per UI audit spec)
const ENTRANCE_DELAY = 300; // ms delay (appears after a few templates)
const ENTRANCE_DURATION = 350; // ms total animation duration
const ENTRANCE_TRANSLATE_Y = 20; // pt initial offset

interface TemplateListFooterProps {
  onClose: () => void;
}

export const TemplateListFooter = ({ onClose }: TemplateListFooterProps) => {
  const reduceMotion = useReduceMotion();
  const { triggerLightImpact, triggerSelection } = useHapticFeedback({});

  // Entrance animation values
  const entranceOpacity = useSharedValue(reduceMotion ? 1 : 0);
  const entranceTranslateY = useSharedValue(
    reduceMotion ? 0 : ENTRANCE_TRANSLATE_Y
  );

  // Press animation
  const scale = useSharedValue(1);

  // Entrance animation
  useEffect(() => {
    if (reduceMotion) {
      entranceOpacity.value = 1;
      entranceTranslateY.value = 0;
      return;
    }

    entranceOpacity.value = withDelay(
      ENTRANCE_DELAY,
      withTiming(1, {
        duration: ENTRANCE_DURATION,
        easing: Easing.out(Easing.cubic),
      })
    );
    entranceTranslateY.value = withDelay(
      ENTRANCE_DELAY,
      withSpring(0, { damping: 18, stiffness: 200 })
    );

    return () => {
      cancelAnimation(entranceOpacity);
      cancelAnimation(entranceTranslateY);
    };
  }, [reduceMotion, entranceOpacity, entranceTranslateY]);

  const entranceAnimatedStyle = useAnimatedStyle(() => ({
    opacity: entranceOpacity.value,
    transform: [{ translateY: entranceTranslateY.value }],
  }));

  const pressAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
  }));

  const handlePressIn = () => {
    triggerLightImpact();
    if (!reduceMotion) {
      scale.value = withTiming(0.98, { duration: 50 });
    }
  };

  const handlePressOut = () => {
    if (!reduceMotion) {
      scale.value = withSpring(1, { damping: 15, stiffness: 300 });
    }
  };

  return (
    <Animated.View style={entranceAnimatedStyle}>
      <View className='px-4 pb-6 pt-3'>
        <AnimatedPressable
          accessibilityLabel='Hide template browser'
          accessibilityRole='button'
          className='flex-row items-center justify-center rounded-full bg-[#f4f4f4] px-4 py-3'
          style={[pressAnimatedStyle, { minHeight: 44 }]}
          onPress={() => {
            triggerSelection();
            onClose();
          }}
          onPressIn={handlePressIn}
          onPressOut={handlePressOut}
        >
          <Text className='mr-2 text-[15px] font-semibold text-stone-800'>
            Hide habits
          </Text>
          <ChevronDown color='#1c1917' size={16} />
        </AnimatedPressable>
      </View>
    </Animated.View>
  );
};

import { useEffect } from 'react';
import { Pressable, Text, View } from 'react-native';
import { Microscope } from 'lucide-react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withTiming,
  withDelay,
  Easing,
  cancelAnimation,
} from 'react-native-reanimated';
import { useHapticFeedback } from '../../../hooks/useHapticFeedback';
import { useReduceMotion } from '../../../hooks/useReduceMotion';
import type { HabitTemplate } from '../types';

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

// Entrance animation constants (per UI audit spec)
const ENTRANCE_STAGGER_DELAY = 100; // ms between each item
const ENTRANCE_DURATION = 350; // ms total animation duration
const ENTRANCE_TRANSLATE_Y = 20; // pt initial offset

interface TemplateListItemProps {
  /** Index in list for staggered entrance animation */
  index?: number;
  template: HabitTemplate;
  onSelect: (template: HabitTemplate) => void;
  onViewScience: (template: HabitTemplate) => void;
}

export const TemplateListItem = ({
  index = 0,
  template,
  onSelect,
  onViewScience,
}: TemplateListItemProps) => {
  const reduceMotion = useReduceMotion();
  const { triggerLightImpact, triggerSelection } = useHapticFeedback({});

  // Entrance animation values
  const entranceOpacity = useSharedValue(reduceMotion ? 1 : 0);
  const entranceTranslateY = useSharedValue(
    reduceMotion ? 0 : ENTRANCE_TRANSLATE_Y
  );

  // Press animation for template row
  const templateScale = useSharedValue(1);
  // Press animation for science button
  const scienceScale = useSharedValue(1);

  // Staggered entrance animation
  useEffect(() => {
    if (reduceMotion) {
      entranceOpacity.value = 1;
      entranceTranslateY.value = 0;
      return;
    }

    const delay = index * ENTRANCE_STAGGER_DELAY;
    entranceOpacity.value = withDelay(
      delay,
      withTiming(1, {
        duration: ENTRANCE_DURATION,
        easing: Easing.out(Easing.cubic),
      })
    );
    entranceTranslateY.value = withDelay(
      delay,
      withSpring(0, { damping: 18, stiffness: 200 })
    );

    return () => {
      cancelAnimation(entranceOpacity);
      cancelAnimation(entranceTranslateY);
    };
  }, [index, reduceMotion, entranceOpacity, entranceTranslateY]);

  const entranceAnimatedStyle = useAnimatedStyle(() => ({
    opacity: entranceOpacity.value,
    transform: [{ translateY: entranceTranslateY.value }],
  }));

  const templateAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: templateScale.value }],
  }));

  const scienceAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scienceScale.value }],
  }));

  const handleTemplatePressIn = () => {
    triggerLightImpact();
    if (!reduceMotion) {
      templateScale.value = withTiming(0.98, { duration: 50 });
    }
  };

  const handleTemplatePressOut = () => {
    if (!reduceMotion) {
      templateScale.value = withSpring(1, { damping: 15, stiffness: 300 });
    }
  };

  const handleSciencePressIn = () => {
    triggerLightImpact();
    if (!reduceMotion) {
      scienceScale.value = withTiming(0.95, { duration: 50 });
    }
  };

  const handleSciencePressOut = () => {
    if (!reduceMotion) {
      scienceScale.value = withSpring(1, { damping: 15, stiffness: 300 });
    }
  };

  return (
    <Animated.View style={entranceAnimatedStyle}>
      <View className='flex-row items-center gap-3 border-b border-stone-100 p-4'>
        <AnimatedPressable
          accessibilityLabel={`Select ${template.name} template`}
          accessibilityRole='button'
          className='flex-1 flex-row items-center gap-3'
          style={templateAnimatedStyle}
          onPress={() => {
            triggerSelection();
            onSelect(template);
          }}
          onPressIn={handleTemplatePressIn}
          onPressOut={handleTemplatePressOut}
        >
          <View
            className='h-12 w-12 items-center justify-center rounded-xl'
            style={{ backgroundColor: template.iconColor + '20' }}
          >
            <Text className='text-xl'>{template.icon}</Text>
          </View>
          <View className='flex-1'>
            <Text
              className='text-[15px] font-semibold text-stone-800'
              numberOfLines={1}
            >
              {template.name}
            </Text>
            <Text
              className='text-[13px] font-normal text-stone-500'
              numberOfLines={2}
            >
              {template.description}
            </Text>
          </View>
        </AnimatedPressable>
        <AnimatedPressable
          accessibilityLabel={`View science for ${template.name}`}
          accessibilityRole='button'
          className='h-11 w-11 items-center justify-center rounded-full bg-blue-50'
          style={scienceAnimatedStyle}
          onPress={() => {
            triggerSelection();
            onViewScience(template);
          }}
          onPressIn={handleSciencePressIn}
          onPressOut={handleSciencePressOut}
        >
          <Microscope color='#3B82F6' size={18} strokeWidth={2} />
        </AnimatedPressable>
      </View>
    </Animated.View>
  );
};

import { useRef } from 'react';
import {
  AccessibilityInfo,
  Animated,
  Pressable,
  Text,
  View,
} from 'react-native';
import { LayoutGrid, ChevronRight } from 'lucide-react-native';
import useHapticFeedback from '../../../hooks/useHapticFeedback';

interface TemplatesLinkSectionProps {
  onPress: () => void;
}

/**
 * V8 Templates Link Section
 *
 * A card-style button that links to the templates browse view.
 * Positioned below the Reminder Selector, providing users with
 * inspiration for science-backed habit templates.
 *
 * Design spec:
 * - Layout-grid icon
 * - "Need inspiration?" heading
 * - "Browse science-backed templates" subtext
 * - Chevron indicating actionable link
 */
export const TemplatesLinkSection = ({
  onPress,
}: TemplatesLinkSectionProps) => {
  const scaleAnim = useRef(new Animated.Value(1)).current;
  const { triggerSelection } = useHapticFeedback();

  const handlePressIn = () => {
    Animated.spring(scaleAnim, {
      friction: 10,
      tension: 300,
      toValue: 0.96,
      useNativeDriver: true,
    }).start();
  };

  const handlePressOut = () => {
    Animated.spring(scaleAnim, {
      friction: 10,
      tension: 300,
      toValue: 1,
      useNativeDriver: true,
    }).start();
  };

  const handlePress = () => {
    triggerSelection();
    onPress();
    AccessibilityInfo.announceForAccessibility(
      'Opening templates browser to browse science-backed habit templates'
    );
  };

  return (
    <View className='mb-6' testID='templates-link-section'>
      <Pressable
        accessibilityHint='Opens the templates browser to browse pre-made habit templates'
        accessibilityLabel='Need inspiration? Browse science-backed templates'
        accessibilityRole='button'
        testID='templates-link-button'
        onPress={handlePress}
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
      >
        <Animated.View
          className='flex-row items-center rounded-2xl border border-[#e7e5e4] bg-white px-4 py-4'
          style={{ transform: [{ scale: scaleAnim }] }}
        >
          {/* Icon */}
          <View
            className='mr-4 h-10 w-10 items-center justify-center rounded-xl bg-[#ECFDF5]'
            testID='templates-link-icon'
          >
            <LayoutGrid color='#10B981' size={20} strokeWidth={2} />
          </View>

          {/* Text content */}
          <View className='flex-1'>
            <Text className='text-sm font-semibold text-[#1F2937]'>
              Need inspiration?
            </Text>
            <Text className='mt-0.5 text-xs text-[#78716c]'>
              Browse science-backed templates
            </Text>
          </View>

          {/* Chevron */}
          <ChevronRight color='#9CA3AF' size={20} strokeWidth={2} />
        </Animated.View>
      </Pressable>
    </View>
  );
};

export default TemplatesLinkSection;

