import { useRef } from 'react';
import { AccessibilityInfo, Animated, Pressable, Text, View } from 'react-native';
import useHapticFeedback from '../../../hooks/useHapticFeedback';
import { HUBERMAN_PHASES, PHASE_ORDER, type HubermanPhase } from '../../../constants/hubermanPhases';

/**
 * Maps each Huberman phase to a default reminder time
 * - Phase 1 (Push/Morning): 7:00 AM
 * - Phase 2 (Pivot/Afternoon): 12:00 PM
 * - Phase 3 (Pull/Evening): 8:00 PM
 */
export const PHASE_REMINDER_TIMES: Record<HubermanPhase, { hour: number; minute: number }> = {
  phase1_push: { hour: 7, minute: 0 },
  phase2_pivot: { hour: 12, minute: 0 },
  phase3_pull: { hour: 20, minute: 0 },
};

/**
 * Creates a Date object for the reminder time based on the selected phase
 */
export const getReminderTimeForPhase = (phase: HubermanPhase): Date => {
  const time = PHASE_REMINDER_TIMES[phase];
  const date = new Date();
  date.setHours(time.hour, time.minute, 0, 0);
  return date;
};

interface TimeOfDayButtonProps {
  phase: HubermanPhase;
  isSelected: boolean;
  onPress: () => void;
}

const TimeOfDayButton = ({ phase, isSelected, onPress }: TimeOfDayButtonProps) => {
  const scaleAnim = useRef(new Animated.Value(1)).current;
  const phaseInfo = HUBERMAN_PHASES[phase];

  const handlePressIn = () => {
    Animated.spring(scaleAnim, {
      toValue: 0.95,
      tension: 300,
      friction: 10,
      useNativeDriver: true,
    }).start();
  };

  const handlePressOut = () => {
    Animated.spring(scaleAnim, {
      toValue: 1,
      tension: 300,
      friction: 10,
      useNativeDriver: true,
    }).start();
  };

  return (
    <Pressable
      onPress={onPress}
      onPressIn={handlePressIn}
      onPressOut={handlePressOut}
      accessibilityLabel={`${phaseInfo.shortLabel} - ${phaseInfo.timeRange}`}
      accessibilityRole="button"
      accessibilityState={{ selected: isSelected }}
      className="flex-1"
    >
      <Animated.View
        className="items-center justify-center rounded-xl px-3 py-3"
        style={[
          {
            backgroundColor: isSelected ? '#22C55E' : '#fafaf9',
            borderWidth: 1.5,
            borderColor: isSelected ? '#16A34A' : '#e7e5e4', // #e7e5e4 = stone-200
            transform: [{ scale: scaleAnim }],
          },
        ]}
      >
        <Text className="mb-1 text-lg">{phaseInfo.icon}</Text>
        <Text
          className="text-sm font-semibold"
          style={{ color: isSelected ? '#FFFFFF' : '#1c1917' }}
        >
          {phaseInfo.shortLabel}
        </Text>
      </Animated.View>
    </Pressable>
  );
};

interface TimeOfDaySelectorProps {
  selectedPhase: HubermanPhase | null;
  onSelectPhase: (phase: HubermanPhase) => void;
}

export const TimeOfDaySelector = ({
  selectedPhase,
  onSelectPhase,
}: TimeOfDaySelectorProps) => {
  const { triggerSelection } = useHapticFeedback();

  const handleSelectPhase = (phase: HubermanPhase) => {
    triggerSelection();
    onSelectPhase(phase);
    // Announce time of day selection for screen readers
    const phaseInfo = HUBERMAN_PHASES[phase];
    AccessibilityInfo.announceForAccessibility(`Selected ${phaseInfo.shortLabel}, ${phaseInfo.timeRange}`);
  };

  return (
    <View className="mb-6 rounded-2xl bg-white p-4">
      <Text className="mb-3 text-base font-semibold text-stone-800">When</Text>
      <View className="flex-row gap-3">
        {PHASE_ORDER.map((phase) => (
          <TimeOfDayButton
            key={phase}
            phase={phase}
            isSelected={selectedPhase === phase}
            onPress={() => handleSelectPhase(phase)}
          />
        ))}
      </View>
    </View>
  );
};

export default TimeOfDaySelector;

import { useState, useEffect, useCallback } from 'react';
import { Keyboard, Modal, Platform, Pressable, Text, View } from 'react-native';
import DateTimePicker, {
  DateTimePickerEvent,
} from '@react-native-community/datetimepicker';
import useHapticFeedback from '../../../hooks/useHapticFeedback';

/**
 * Props for the TimePickerModal component.
 */
export interface TimePickerModalProps {
  /** Whether the modal is visible */
  visible: boolean;
  /** Initial time to display when the modal opens */
  initialTime: Date;
  /** Called when user confirms their selection */
  onConfirm: (time: Date) => void;
  /** Called when user cancels/dismisses the modal */
  onCancel: () => void;
  /** Optional title for the modal header (iOS only) */
  title?: string;
}

/**
 * TimePickerModal - Native time picker with consistent cross-platform behavior.
 *
 * Features:
 * - iOS: Modal with spinner wheel picker and confirm/cancel buttons
 * - Android: Native clock picker (handles its own modal)
 * - Dismisses keyboard when opened
 * - Haptic feedback on confirm
 * - Accessible labels for screen readers
 * - Resets to initial time when modal opens
 *
 * Usage:
 * ```tsx
 * <TimePickerModal
 *   visible={showTimePicker}
 *   initialTime={reminderTime}
 *   onConfirm={(time) => {
 *     setReminderTime(time);
 *     setShowTimePicker(false);
 *   }}
 *   onCancel={() => setShowTimePicker(false)}
 * />
 * ```
 */
export const TimePickerModal = ({
  visible,
  initialTime,
  onConfirm,
  onCancel,
  title = 'Set Reminder Time',
}: TimePickerModalProps) => {
  // Local state for the selected time (iOS needs this for preview before confirm)
  const [selectedTime, setSelectedTime] = useState(initialTime);
  const { triggerSelection } = useHapticFeedback();

  // Reset to initial time when modal opens and dismiss keyboard
  useEffect(() => {
    if (visible) {
      setSelectedTime(initialTime);
      Keyboard.dismiss();
    }
  }, [visible, initialTime]);

  // Handle time change from picker
  const handleTimeChange = useCallback(
    (event: DateTimePickerEvent, date?: Date) => {
      if (Platform.OS === 'android') {
        // Android: onChange fires on confirm AND dismiss
        // event.type is 'set' for confirm, 'dismissed' for cancel
        if (event.type === 'set' && date) {
          triggerSelection();
          onConfirm(date);
        } else {
          onCancel();
        }
      } else {
        // iOS: onChange fires as user scrolls, just update local state
        if (date) {
          setSelectedTime(date);
        }
      }
    },
    [onConfirm, onCancel, triggerSelection]
  );

  // Handle iOS confirm button
  const handleConfirm = useCallback(() => {
    triggerSelection();
    onConfirm(selectedTime);
  }, [selectedTime, onConfirm, triggerSelection]);

  // Handle iOS cancel button
  const handleCancel = useCallback(() => {
    triggerSelection();
    onCancel();
  }, [onCancel, triggerSelection]);

  // Android: DateTimePicker handles its own modal UI
  if (Platform.OS === 'android') {
    if (!visible) return null;

    return (
      <DateTimePicker
        display='clock'
        is24Hour={false}
        mode='time'
        testID='time-picker-android'
        value={selectedTime}
        onChange={handleTimeChange}
      />
    );
  }

  // iOS: Custom modal wrapper with spinner picker
  return (
    <Modal
      transparent
      animationType='fade'
      testID='time-picker-modal'
      visible={visible}
      onRequestClose={handleCancel}
    >
      {/* Backdrop - tap to dismiss */}
      <Pressable
        accessibilityLabel='Dismiss time picker'
        accessibilityRole='button'
        className='flex-1 items-center justify-center bg-black/50'
        onPress={handleCancel}
      >
        {/* Modal content - prevent tap propagation */}
        <Pressable
          className='mx-6 w-full max-w-sm rounded-2xl bg-white p-5'
          onPress={(e) => e.stopPropagation()}
        >
          {/* Title */}
          <Text
            accessibilityRole='header'
            className='mb-4 text-center text-lg font-semibold text-stone-900'
          >
            {title}
          </Text>

          {/* Time Picker */}
          <View
            accessibilityLabel='Time picker wheel'
            className='mb-5 items-center'
          >
            <DateTimePicker
              display='spinner'
              is24Hour={false}
              mode='time'
              testID='time-picker-ios'
              textColor='#1c1917'
              value={selectedTime}
              onChange={handleTimeChange}
            />
          </View>

          {/* Action Buttons */}
          <View className='flex-row gap-3'>
            <Pressable
              accessibilityLabel='Cancel'
              accessibilityRole='button'
              className='h-12 flex-1 items-center justify-center rounded-xl bg-stone-100 active:bg-stone-200'
              onPress={handleCancel}
            >
              <Text className='text-base font-semibold text-stone-700'>
                Cancel
              </Text>
            </Pressable>

            <Pressable
              accessibilityLabel={`Set time to ${selectedTime.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })}`}
              accessibilityRole='button'
              className='h-12 flex-1 items-center justify-center rounded-xl bg-emerald-500 active:bg-emerald-600'
              onPress={handleConfirm}
            >
              <Text className='text-base font-semibold text-white'>
                Set Time
              </Text>
            </Pressable>
          </View>
        </Pressable>
      </Pressable>
    </Modal>
  );
};

export default TimePickerModal;

export const DEFAULT_EMOJI = '💪';
export const DEFAULT_COLOR = '#10B981'; // Emerald - V8 default

export const EMOJIS = [
  ...new Set(
    '💪 🧘 📖 💧 🎨 🏃 🍎 🥗 ☕ 💤 🎯 ✍️ 🚴 🧠 🎵 🌞 🌙 ⚡ 🔥 🌱 🏋️ 🚶 🧘‍♀️ 🎨 📝 💼 📚 🎓 💡 🏆'.split(
      ' '
    )
  ),
];

/**
 * V8 Habit Colors - 12 vibrant colors for the color picker
 * Order matches design spec for visual flow
 */
export const HABIT_COLORS = [
  '#EF4444', // Red
  '#F97316', // Orange
  '#FBBF24', // Amber
  '#84CC16', // Lime
  '#10B981', // Emerald (default)
  '#14B8A6', // Teal
  '#06B6D4', // Cyan
  '#3B82F6', // Blue
  '#8B5CF6', // Violet
  '#A855F7', // Purple
  '#EC4899', // Pink
  '#78716C', // Stone
] as const;

/**
 * Human-readable color names for accessibility (VoiceOver)
 * Maps hex values to descriptive names
 */
export const COLOR_NAMES: Record<string, string> = {
  '#EF4444': 'Red',
  '#F97316': 'Orange',
  '#FBBF24': 'Amber',
  '#84CC16': 'Lime',
  '#10B981': 'Emerald',
  '#14B8A6': 'Teal',
  '#06B6D4': 'Cyan',
  '#3B82F6': 'Blue',
  '#8B5CF6': 'Violet',
  '#A855F7': 'Purple',
  '#EC4899': 'Pink',
  '#78716C': 'Stone',
} as const;

/**
 * Get human-readable color name for accessibility
 * Returns the hex value if no name is found
 */
export const getColorName = (hex: string): string => {
  return COLOR_NAMES[hex.toUpperCase()] || COLOR_NAMES[hex] || hex;
};

/** @deprecated Use HABIT_COLORS instead - kept for backward compatibility */
export const COLORS = HABIT_COLORS;

export const HABIT_NAME_REGEX = /^(\p{Emoji})\s+(.+)$/u;

/**
 * useCenteredFormCallbacks Hook
 *
 * Provides memoized form callbacks for CreateHabitModalCentered.
 */

import { useCallback, type RefObject } from 'react';
import type { ScrollView as ScrollViewType } from 'react-native';

interface FormState {
  setHabitName: (name: string) => void;
  setSelectedEmoji: (emoji: string | null) => void;
  setSelectedColor: (color: string) => void;
  setRemindersEnabled: (enabled: boolean) => void;
  setReminderTime: (time: Date) => void;
}

interface UseCenteredFormCallbacksProps {
  form: FormState;
  setShowNameError: (show: boolean) => void;
  scrollViewRef: RefObject<ScrollViewType | null>;
  handleCreate: () => Promise<void>;
}

/**
 * Creates memoized form handlers for the centered habit creation modal.
 */
export function useCenteredFormCallbacks({
  form,
  setShowNameError,
  scrollViewRef,
  handleCreate,
}: UseCenteredFormCallbacksProps) {
  const handleEmojiSelect = useCallback(
    (emoji: string | null) => {
      form.setSelectedEmoji(emoji);
    },
    [form]
  );

  const handleColorSelect = useCallback(
    (color: string) => {
      form.setSelectedColor(color);
    },
    [form]
  );

  const handleNameChange = useCallback(
    (value: string) => {
      form.setHabitName(value);
      // Clear error when user starts typing
      if (value.trim().length > 0) {
        setShowNameError(false);
      }
    },
    [form, setShowNameError]
  );

  const handleValidationError = useCallback(() => {
    setShowNameError(true);
  }, [setShowNameError]);

  const handleReminderToggle = useCallback(
    (enabled: boolean) => {
      form.setRemindersEnabled(enabled);
      // Auto-scroll to show reminder options when enabled
      if (enabled) {
        setTimeout(() => {
          scrollViewRef.current?.scrollToEnd({ animated: true });
        }, 100);
      }
    },
    [form, scrollViewRef]
  );

  const handleReminderTimeChange = useCallback(
    (time: Date) => {
      form.setReminderTime(time);
    },
    [form]
  );

  const handleSubmit = useCallback(() => {
    void handleCreate();
  }, [handleCreate]);

  const handleSave = useCallback(() => {
    void handleCreate();
  }, [handleCreate]);

  return {
    handleColorSelect,
    handleEmojiSelect,
    handleNameChange,
    handleReminderTimeChange,
    handleReminderToggle,
    handleSave,
    handleSubmit,
    handleValidationError,
  };
}

/**
 * useCreateHabitHandlers - Handle habit creation and editing operations
 *
 * Extracted from useCreateHabitModal to separate mutation logic
 * from the main modal orchestration.
 */
import { useMutation } from 'convex/react';
import { api } from '../../../../convex/_generated/api';
import { formatReminderTime } from '../../../utils/notifications';
import { cancelReminder, scheduleReminder } from './useHabitReminders';
import type { Id } from '../../../../convex/_generated/dataModel';

interface HabitData {
  dayPhase: string | null;
  fullHabitName: string;
  hasReminders: boolean;
  reminderSound?: string;
  reminderTime: Date;
  selectedColor: string;
  selectedEmoji: string | null;
}

interface EditHabitData extends HabitData {
  habitToEdit: {
    _id: Id<'habits'>;
    notes?: string;
  };
}

export function useCreateHabitHandlers() {
  const createHabit = useMutation(api.habits.create);
  const updateHabit = useMutation(api.habits.update);

  async function handleEdit({
    habitToEdit,
    hasReminders,
    fullHabitName,
    reminderTime,
    selectedEmoji,
    selectedColor,
    dayPhase,
    reminderSound,
  }: EditHabitData): Promise<void> {
    let finalHasReminders = hasReminders;

    if (hasReminders) {
      const scheduled = await scheduleReminder({
        habitId: habitToEdit._id,
        habitName: fullHabitName,
        reminderTime,
      });
      if (!scheduled) {
        finalHasReminders = false;
        await cancelReminder(habitToEdit._id);
      }
    } else {
      await cancelReminder(habitToEdit._id);
    }

    await updateHabit({
      habitId: habitToEdit._id,
      icon: selectedEmoji ?? undefined,
      iconColor: selectedColor,
      name: fullHabitName,
      notes: habitToEdit.notes ?? '',
      preferredTime: dayPhase ?? undefined,
      remindersEnabled: finalHasReminders,
      reminderSound: finalHasReminders ? reminderSound : undefined,
      reminderTime: finalHasReminders
        ? formatReminderTime(reminderTime)
        : undefined,
    });
  }

  async function handleCreate({
    hasReminders,
    fullHabitName,
    reminderTime,
    selectedEmoji,
    selectedColor,
    dayPhase,
    reminderSound,
  }: HabitData): Promise<void> {
    const habitId = await createHabit({
      icon: selectedEmoji ?? undefined,
      iconColor: selectedColor,
      name: fullHabitName,
      notes: '',
      preferredTime: dayPhase ?? undefined,
      remindersEnabled: hasReminders,
      reminderSound: hasReminders ? reminderSound : undefined,
      reminderTime: hasReminders ? formatReminderTime(reminderTime) : undefined,
    });

    if (hasReminders && habitId) {
      await scheduleReminder({
        habitId,
        habitName: fullHabitName,
        reminderTime,
      });
    }
  }

  return { handleCreate, handleEdit };
}

import { useCallback, useEffect, useMemo } from 'react';
import type { CreateHabitModalProps, HabitTemplate } from '../types';
import { useHabitForm } from './useHabitForm';
import { useScienceModal } from './useScienceModal';
import { useTemplateBrowser } from './useTemplateBrowser';
import useHapticFeedback from '../../../hooks/useHapticFeedback';
import { extractTemplateDetails } from '../utils';
import { checkReminderPermissions } from './useHabitReminders';
import { useCreateHabitHandlers } from './useCreateHabitHandlers';

export const useCreateHabitModal = (props: CreateHabitModalProps) => {
  const { visible, onClose, habitToEdit } = props;
  const isEditMode = !!habitToEdit;
  const form = useHabitForm({ habitToEdit });
  const { triggerSuccess } = useHapticFeedback();
  const { handleEdit, handleCreate: createNewHabit } = useCreateHabitHandlers();
  const {
    closeColorPicker,
    dayPhase,
    fullHabitName,
    habitName,
    reminderSound,
    reminderTime,
    remindersEnabled,
    resetForm,
    selectedColor,
    selectedEmoji,
    setFrequency,
    setHabitName,
    setSelectedColor,
    setSelectedEmoji,
    setShowTimePicker,
  } = form;

  const applyTemplate = useCallback(
    (template: HabitTemplate) => {
      const { emoji, name } = extractTemplateDetails(template);
      setSelectedEmoji(emoji);
      setHabitName(name);
      if (template.iconColor) setSelectedColor(template.iconColor);
      if (template.frequency) setFrequency(template.frequency);
    },
    [setHabitName, setSelectedColor, setSelectedEmoji, setFrequency]
  );

  const template = useTemplateBrowser({
    isEditMode,
    onTemplateSelect: applyTemplate,
    visible,
  });
  const science = useScienceModal({ onSelectTemplate: applyTemplate });

  useEffect(() => {
    if (!visible || isEditMode) return;
    resetForm();
    template.reset();
    template.closeTemplateBrowser();
    science.close();
  }, [visible, isEditMode, resetForm, template, science]);

  const habitData = useMemo(
    () => ({
      dayPhase,
      fullHabitName: fullHabitName,
      reminderSound,
      reminderTime,
      selectedColor,
      selectedEmoji,
    }),
    [
      dayPhase,
      fullHabitName,
      reminderSound,
      reminderTime,
      selectedColor,
      selectedEmoji,
    ]
  );

  const cleanup = useCallback(() => {
    resetForm();
    closeColorPicker();
    setShowTimePicker(false);
    template.reset();
    template.closeTemplateBrowser();
    science.close();
    triggerSuccess();
    onClose();
  }, [
    resetForm,
    closeColorPicker,
    setShowTimePicker,
    template,
    science,
    triggerSuccess,
    onClose,
  ]);

  const handleCreate = useCallback(async () => {
    if (!habitName.trim() || !fullHabitName) return;
    const { hasReminders } = await checkReminderPermissions(remindersEnabled);
    const data = { ...habitData, hasReminders };

    await (isEditMode && habitToEdit
      ? handleEdit({ ...data, habitToEdit })
      : createNewHabit(data));
    cleanup();
  }, [
    habitName,
    fullHabitName,
    remindersEnabled,
    isEditMode,
    habitToEdit,
    habitData,
    handleEdit,
    createNewHabit,
    cleanup,
  ]);

  return { form, handleCreate, isEditMode, science, template };
};

import { useCallback } from 'react';

interface FormState {
  setHabitName: (name: string) => void;
  setSelectedEmoji: (emoji: string | null) => void;
  setSelectedColor: (color: string) => void;
  setReminderOption: (option: string) => void;
  setReminderTime: (time: Date) => void;
  reminderTime: Date;
  reminderOption: string;
}

/**
 * Hook that creates memoized handlers for form field changes.
 * Encapsulates reminder time logic and phase detection.
 */
export function useFormHandlers(form: FormState) {
  const handleNameChange = useCallback(
    (value: string) => {
      form.setHabitName(value);
    },
    [form]
  );

  const handleEmojiSelect = useCallback(
    (emoji: string | null) => {
      form.setSelectedEmoji(emoji);
    },
    [form]
  );

  const handleColorSelect = useCallback(
    (color: string) => {
      form.setSelectedColor(color);
    },
    [form]
  );

  const handleReminderToggle = useCallback(
    (enabled: boolean) => {
      if (enabled) {
        const hour = form.reminderTime.getHours();
        if (hour >= 5 && hour < 10) {
          form.setReminderOption('morning');
        } else if (hour >= 10 && hour < 16) {
          form.setReminderOption('midday');
        } else {
          form.setReminderOption('evening');
        }
      } else {
        form.setReminderOption('none');
      }
    },
    [form]
  );

  const handleReminderTimeChange = useCallback(
    (time: Date) => {
      form.setReminderTime(time);
      if (form.reminderOption === 'none') {
        const hour = time.getHours();
        if (hour >= 5 && hour < 10) {
          form.setReminderOption('morning');
        } else if (hour >= 10 && hour < 16) {
          form.setReminderOption('midday');
        } else {
          form.setReminderOption('evening');
        }
      }
    },
    [form]
  );

  return {
    handleColorSelect,
    handleEmojiSelect,
    handleNameChange,
    handleReminderTimeChange,
    handleReminderToggle,
  };
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import { DEFAULT_COLOR } from '../constants';
import type { HabitDoc } from '../types';
import { buildHabitName, parseHabitName, parseReminderTime } from '../utils';
import {
  type HubermanPhase,
  getPhaseFromPreferredTime,
} from '../../../constants/hubermanPhases';
import type { ReminderOption } from '../components/ReminderSelector';
import { getSmartReminderDefault } from '../../../utils/reminderDefaults';
import { getReminderOptionFromTime } from './reminderUtils';
import { useReminderOptionSync } from './useReminderOptionSync';

const DEFAULT_SOUND = 'Default';

interface UseHabitFormOptions {
  habitToEdit?: HabitDoc | null;
}

export const useHabitForm = ({ habitToEdit }: UseHabitFormOptions) => {
  const parsed = useMemo(
    () => parseHabitName(habitToEdit?.name ?? ''),
    [habitToEdit?.name]
  );

  const [habitName, setHabitName] = useState(parsed.name);
  const [selectedEmoji, setSelectedEmoji] = useState<string | null>(
    parsed.emoji
  );
  const [selectedColor, setSelectedColor] = useState(
    habitToEdit?.iconColor ?? DEFAULT_COLOR
  );
  const [isColorPickerVisible, setColorPickerVisible] = useState(false);
  const [remindersEnabled, setRemindersEnabled] = useState(
    habitToEdit?.remindersEnabled ?? false
  );
  const [reminderTime, setReminderTime] = useState(() =>
    parseReminderTime(habitToEdit?.reminderTime)
  );
  const [showTimePicker, setShowTimePicker] = useState(false);
  const [reminderSound, setReminderSound] = useState(
    habitToEdit?.reminderSound ?? DEFAULT_SOUND
  );
  const [frequency, setFrequency] = useState<string>(
    habitToEdit?.frequency ?? ''
  );
  const [dayPhase, setDayPhase] = useState<HubermanPhase | null>(
    getPhaseFromPreferredTime(habitToEdit?.preferredTime)
  );
  const [reminderOption, setReminderOptionState] = useState<ReminderOption>(
    getReminderOptionFromTime(
      habitToEdit?.remindersEnabled,
      habitToEdit?.reminderTime
    )
  );

  const fullHabitName = useMemo(
    () => buildHabitName(selectedEmoji, habitName),
    [selectedEmoji, habitName]
  );

  const syncReminderOption = useReminderOptionSync({
    setRemindersEnabled,
    setReminderTime,
