  const { triggerLightImpact } = useHapticFeedback({});

  const {
    dateInfo,
    handleBackdropPress,
    handleDonePress,
    handleToggleHabit,
    togglingHabitId,
  } = useDayHabitsSheet({ date, onClose, toggleHabit });

  const { backdropStyle, panGesture, sheetStyle } = useSheetAnimations({
    onClose,
    reduceMotion,
    triggerLightImpact,
    visible,
  });

  // Compute completion count for header
  const completedCount = habits.filter(
    (habit) => getHabitStatus(habit._id, dateInfo.dateString) === 'done'
  ).length;

  return (
    <Modal
      accessibilityViewIsModal
      statusBarTranslucent
      transparent
      animationType='none'
      visible={visible}
      onRequestClose={onClose}
    >
      <View className='flex-1 justify-end'>
        <Pressable
          accessible={false}
          className='absolute inset-0'
          onPress={handleBackdropPress}
        >
          <Animated.View className='flex-1 bg-black' style={backdropStyle} />
        </Pressable>

        <GestureDetector gesture={panGesture}>
          <Animated.View
            className='rounded-t-3xl bg-white'
            style={[getSheetContainerStyle(insets.bottom), sheetStyle]}
          >
            <DragHandle />

            <SheetHeader
              completedCount={completedCount}
              displayDate={dateInfo.displayDate}
              isToday={dateInfo.isToday}
              totalCount={habits.length}
              onDonePress={handleDonePress}
            />

            {habits.length === 0 ? (
              <EmptyState />
            ) : (
              <HabitList
                dateString={dateInfo.dateString}
                getHabitStatus={getHabitStatus}
                habits={habits}
                reduceMotion={reduceMotion}
                togglingHabitId={togglingHabitId}
                onToggleHabit={handleToggleHabit}
              />
            )}
          </Animated.View>
        </GestureDetector>
      </View>
