import React from 'react';
import { useHabitCardEntrance } from '../HabitCard/useHabitCardEntrance';
import { useHapticFeedback } from '../../hooks/useHapticFeedback';
import { useDraggableHabitLogic } from './DraggableHabit.hooks';
import { getCardColors } from './colorUtils';
import { getStrengthPercent } from './strengthUtils';
import { useDraggableHabitAnimations } from './useDraggableHabitAnimations';
import { useStrengthAnimation } from './useStrengthAnimation';
import { usePressHandlers } from './usePressHandlers';
import { DraggableHabitCard } from './DraggableHabitCard';
import type { DraggableHabitProps } from './types';

export default function DraggableHabit({
  celebrationsEnabled,
  completionIcon = 'chain',
  dayShape = 'square',
  entranceDelay = 0,
  entranceVariant = 'widthExpansion',
  habit,
  highContrastMode = false,
  isCompactMode: _isCompactMode = false,
  isConnectedToPreviousWeek = false,
  isJustCreated = false,
  onArchive,
  onEntranceComplete,
  onLongPress,
  onPress,
  onWeekComplete,
  previousStreak,
  reduceMotionPreference,
  showConnectors = true,
  showHabitStrengthPercentage = false,
  streak,
  toggleHabit,
  triggerEntrance = true,
  weekDateStrings,
  weekStatus,
}: DraggableHabitProps) {
  const { emoji, name, accentColor } = useDraggableHabitLogic(habit);

  const {
    cardStyle: entranceCardStyle,
    accentStyle: entranceAccentStyle,
    contentStyle: entranceContentStyle,
  } = useHabitCardEntrance({
    autoTrigger: triggerEntrance,
    delay: entranceDelay,
    onAnimationComplete: onEntranceComplete,
    variant: entranceVariant,
  });

  const { triggerSelection, triggerSuccess } = useHapticFeedback({
    isEnabled: celebrationsEnabled,
    preference: reduceMotionPreference,
  });

  const weekCompleteCount = weekStatus.filter((s) => s === 'done').length;
  const isWeekComplete = weekCompleteCount === 7;
  const bestStreak = habit.bestStreak || 0;
  const isNewPersonalRecord =
    previousStreak !== undefined &&
    streak > bestStreak &&
    streak > (previousStreak || 0);

  const animations = useDraggableHabitAnimations({
    isJustCreated,
    isNewPersonalRecord,
    isWeekComplete,
    reduceMotionPreference,
    triggerSuccess,
  });

  const strengthPercent = getStrengthPercent(habit.strength);
  const { strengthEmojiAnimatedStyle } = useStrengthAnimation(
    strengthPercent,
    reduceMotionPreference
  );

  const colors = getCardColors(highContrastMode);

  const pressHandlers = usePressHandlers({
    archiveFlash: animations.archiveFlash,
    cardScale: animations.cardScale,
    habit,
    onArchive,
    onLongPress,
    triggerSelection,
  });

  return (
    <DraggableHabitCard
      accentColor={accentColor}
      archiveFlash={animations.archiveFlash}
      bestStreak={bestStreak}
      cardScale={animations.cardScale}
      celebrationsEnabled={celebrationsEnabled}
      colors={colors}
      completionIcon={completionIcon}
      dayShape={dayShape}
      emoji={emoji}
      entranceAccentStyle={entranceAccentStyle}
      entranceCardStyle={entranceCardStyle}
      entranceContentStyle={entranceContentStyle}
      fade={animations.fade}
      habit={habit}
      handleLongPress={pressHandlers.handleLongPress}
      handlePressIn={pressHandlers.handlePressIn}
      handlePressOut={pressHandlers.handlePressOut}
      handleSwipeableOpen={pressHandlers.handleSwipeableOpen}
      highContrastMode={highContrastMode}
      highlightGlow={animations.highlightGlow}
      iconPulse={animations.iconPulse}
      isConnectedToPreviousWeek={isConnectedToPreviousWeek}
      isWeekComplete={isWeekComplete}
      name={name}
      newRecordOpacity={animations.newRecordOpacity}
      newRecordScale={animations.newRecordScale}
      reduceMotionPreference={reduceMotionPreference}
      showConnectors={showConnectors}
      showHabitStrengthPercentage={showHabitStrengthPercentage}
      showNewRecord={animations.showNewRecord}
      streak={streak}
      strengthEmojiAnimatedStyle={strengthEmojiAnimatedStyle}
      strengthPercent={strengthPercent}
      toggleHabit={toggleHabit}
      translateY={animations.translateY}
      weekDateStrings={weekDateStrings}
      weekStatus={weekStatus}
      onArchive={onArchive}
      onPress={onPress}
      onWeekComplete={onWeekComplete}
    />
  );
}

import React from 'react';
import { Animated, Pressable, StyleSheet } from 'react-native';
import { Swipeable } from 'react-native-gesture-handler';
import ReAnimated from 'react-native-reanimated';
import { ArchiveAction } from './ArchiveAction';
import { CardContent } from './CardContent';
import { getEffectiveAccentColor, getBorderAccentColor } from './colorUtils';
import type { DraggableHabitCardProps } from './DraggableHabitCard.types';

export type { DraggableHabitCardProps } from './DraggableHabitCard.types';

export function DraggableHabitCard(props: DraggableHabitCardProps) {
  const effectiveAccentColor = getEffectiveAccentColor(props.accentColor);
  const borderAccentColor = getBorderAccentColor(
    props.highContrastMode,
    props.accentColor
  );

  const cardStyle = {
    backgroundColor:
      props.isWeekComplete && !props.highContrastMode
        ? 'rgba(220, 252, 231, 0.3)'
        : props.colors.cardBackground,
    borderColor:
      props.isWeekComplete && !props.highContrastMode
        ? '#86efac'
        : props.colors.border,
    borderWidth: props.highContrastMode ? 2 : 1,
    elevation: 3,
    opacity: props.fade,
    shadowColor: props.isWeekComplete ? '#10b981' : '#78716c',
    shadowOffset: { height: 4, width: 0 },
    shadowOpacity: props.isWeekComplete ? 0.12 : 0.06,
    shadowRadius: 12,
    transform: [{ translateY: props.translateY }, { scale: props.cardScale }],
  };

  const habitCard = (
    <ReAnimated.View style={props.entranceCardStyle}>
      <Pressable
        accessibilityHint='Tap to view habit details, long press for quick actions'
        accessibilityLabel={`${props.habit.name}, ${props.streak} day streak`}
        accessibilityRole='button'
        style={({ pressed }) => ({ opacity: pressed ? 0.92 : 1 })}
        onLongPress={props.handleLongPress}
        onPress={() => props.onPress?.(props.habit)}
        onPressIn={props.handlePressIn}
        onPressOut={props.handlePressOut}
      >
        <Animated.View
          className='flex-row overflow-hidden rounded-3xl'
          style={cardStyle}
        >
          <ReAnimated.View
            style={[
              {
                alignSelf: 'stretch',
                backgroundColor: borderAccentColor,
                borderBottomLeftRadius: 24,
                borderTopLeftRadius: 24,
              },
              props.entranceAccentStyle,
            ]}
          />
          <ReAnimated.View
            className='flex-1'
            style={props.entranceContentStyle}
          >
            <Animated.View
              pointerEvents='none'
              style={{
                backgroundColor: 'rgba(245, 158, 11, 0.18)',
                borderRadius: 24,
                opacity: props.archiveFlash,
                ...StyleSheet.absoluteFillObject,
              }}
            />
            <Animated.View
              pointerEvents='none'
              style={{
                borderColor: props.accentColor ?? '#a855f7',
                borderRadius: 24,
                borderWidth: 2,
                opacity: props.highlightGlow,
                ...StyleSheet.absoluteFillObject,
              }}
            />
            <CardContent
              {...props}
              effectiveAccentColor={effectiveAccentColor}
            />
          </ReAnimated.View>
        </Animated.View>
      </Pressable>
    </ReAnimated.View>
  );

  if (!props.onArchive) return habitCard;

  return (
    <Swipeable
      friction={2}
      overshootRight={false}
      renderRightActions={(_, dragX) => <ArchiveAction dragX={dragX} />}
      rightThreshold={40}
      onSwipeableOpen={props.handleSwipeableOpen}
    >
      {habitCard}
    </Swipeable>
  );
}

