      Animated.spring(scaleAnim, {
        bounciness: 4,
        speed: 50,
        toValue: 0.9,
        useNativeDriver: true,
      }).start();
    }, [scaleAnim]);

    const handlePressOut = useCallback(() => {
      Animated.spring(scaleAnim, {
        bounciness: 4,
        speed: 50,
        toValue: isSelected ? 1.1 : 1,
        useNativeDriver: true,
      }).start();
    }, [scaleAnim, isSelected]);

    return (
      <Pressable
        accessibilityLabel={`Select ${emoji} emoji`}
        accessibilityRole='button'
        style={{
          aspectRatio: 1,
          padding: 2,
          width: `${100 / EMOJIS_PER_ROW}%`,
        }}
        onPress={onPress}
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
      >
        <Animated.View
          style={[
            {
              alignItems: 'center',
              backgroundColor: isSelected ? '#f5f5f4' : '#fafaf9',
              borderColor: isSelected ? '#10b981' : 'transparent',
              borderRadius: 12,
              borderWidth: isSelected ? 2 : 0,
              flex: 1,
              justifyContent: 'center',
              minHeight: 44,
              minWidth: 44,
            },
            {
              transform: [{ scale: scaleAnim }],
            },
          ]}
        >
          <Text style={{ fontSize: 28 }}>{emoji}</Text>
        </Animated.View>
      </Pressable>
    );
  }
);

EmojiItem.displayName = 'EmojiItem';

import { memo, useCallback, useRef } from 'react';
import { Animated, Pressable, Text } from 'react-native';
import type { QuickAccessEmojiItemProps } from '../EmojiPicker.types';

export const QuickAccessEmojiItem = memo(
  ({
    emoji,
    isSelected,
    onPress,
    accessibilityLabelSuffix = '',
  }: QuickAccessEmojiItemProps) => {
    const scaleAnim = useRef(new Animated.Value(isSelected ? 1.1 : 1)).current;

    const handlePressIn = useCallback(() => {
      Animated.spring(scaleAnim, {
        bounciness: 4,
        speed: 50,
        toValue: 0.9,
        useNativeDriver: true,
      }).start();
    }, [scaleAnim]);

    const handlePressOut = useCallback(() => {
      Animated.spring(scaleAnim, {
        bounciness: 4,
        speed: 50,
        toValue: isSelected ? 1.1 : 1,
        useNativeDriver: true,
      }).start();
    }, [scaleAnim, isSelected]);

    const accessibilityLabel = accessibilityLabelSuffix
      ? `Select ${emoji} emoji ${accessibilityLabelSuffix}`
      : `Select ${emoji} emoji`;

    return (
      <Pressable
        accessibilityLabel={accessibilityLabel}
        accessibilityRole='button'
        onPress={onPress}
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
      >
        <Animated.View
          style={[
            {
              alignItems: 'center',
              backgroundColor: isSelected ? '#f5f5f4' : 'white',
              borderColor: isSelected ? '#10b981' : 'transparent',
              borderRadius: 12,
              borderWidth: isSelected ? 2 : 0,
              elevation: 1,
              height: 44,
              justifyContent: 'center',
              shadowColor: '#000',
              shadowOffset: { height: 1, width: 0 },
              shadowOpacity: 0.05,
              shadowRadius: 2,
              width: 44,
            },
            {
              transform: [{ scale: scaleAnim }],
            },
          ]}
        >
          <Text style={{ fontSize: 24 }}>{emoji}</Text>
        </Animated.View>
      </Pressable>
    );
  }
);

QuickAccessEmojiItem.displayName = 'QuickAccessEmojiItem';

// Alias for backward compatibility in tests
export const RecentEmojiItem = QuickAccessEmojiItem;

import { useCallback } from 'react';
import { AccessibilityInfo, findNodeHandle } from 'react-native';
import type { RefObject } from 'react';
import type { View } from 'react-native';
import { addRecentEmoji } from '../../utils/recentEmojis';
import { FOCUS_RETURN_DELAY_MS } from './EmojiPicker.constants';

interface UseEmojiPickerHandlersOptions {
  onClose: () => void;
  onSelect: (emoji: string | null) => void;
  triggerRef?: RefObject<View>;
  setSelectedCategory: (category: string) => void;
  setSearchQuery: (query: string) => void;
  setDebouncedQuery: (query: string) => void;
}

export const useEmojiPickerHandlers = ({
  onClose,
  onSelect,
  triggerRef,
  setSelectedCategory,
  setSearchQuery,
  setDebouncedQuery,
}: UseEmojiPickerHandlersOptions) => {
  const returnFocusToTrigger = useCallback(() => {
    if (triggerRef?.current) {
      const reactTag = findNodeHandle(triggerRef.current);
      if (reactTag) {
        AccessibilityInfo.setAccessibilityFocus(reactTag);
      }
    }
  }, [triggerRef]);

  const handleClose = useCallback(() => {
    onClose();
    setTimeout(returnFocusToTrigger, FOCUS_RETURN_DELAY_MS);
  }, [onClose, returnFocusToTrigger]);

  const handleEmojiSelect = useCallback(
    async (emoji: string) => {
      await addRecentEmoji(emoji);
      onSelect(emoji);
      handleClose();
    },
    [onSelect, handleClose]
  );

  const handleCategorySelect = useCallback(
    (categoryId: string) => {
      setSelectedCategory(categoryId);
      setSearchQuery('');
      setDebouncedQuery('');
    },
    [setSelectedCategory, setSearchQuery, setDebouncedQuery]
  );

  const handleClearSearch = useCallback(() => {
    setSearchQuery('');
    setDebouncedQuery('');
  }, [setSearchQuery, setDebouncedQuery]);

  const handleNoIconSelect = useCallback(() => {
    onSelect(null);
    handleClose();
  }, [onSelect, handleClose]);

  return {
    handleCategorySelect,
    handleClearSearch,
    handleClose,
    handleEmojiSelect,
    handleNoIconSelect,
  };
};

import { useEffect, useMemo, useRef, useState } from 'react';
import { getAllEmojis } from '../../utils/emojiData';
import { HABIT_CATEGORIES } from '../../constants/habitEmojis';
import {
  searchEmojisByKeyword,
  suggestEmojisForHabitName,
} from '../../utils/emojiKeywords';
import { getRecentEmojis } from '../../utils/recentEmojis';
import { SEARCH_DEBOUNCE_MS } from './EmojiPicker.constants';

interface UseEmojiPickerStateOptions {
  visible: boolean;
  habitName?: string;
}

export const useEmojiPickerState = ({
  visible,
  habitName,
}: UseEmojiPickerStateOptions) => {
  const [selectedCategory, setSelectedCategory] = useState<string>('fitness');
  const [searchQuery, setSearchQuery] = useState('');
  const [recentEmojis, setRecentEmojis] = useState<string[]>([]);
  const searchTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [debouncedQuery, setDebouncedQuery] = useState('');

  const suggestedEmojis = useMemo(() => {
    if (!habitName?.trim()) return [];
    return suggestEmojisForHabitName(habitName, 5);
  }, [habitName]);

  useEffect(() => {
    if (visible) {
      getRecentEmojis().then(setRecentEmojis);
    }
  }, [visible]);

  useEffect(() => {
    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }
    searchTimeoutRef.current = setTimeout(() => {
      setDebouncedQuery(searchQuery);
    }, SEARCH_DEBOUNCE_MS);

    return () => {
      if (searchTimeoutRef.current) {
        clearTimeout(searchTimeoutRef.current);
      }
    };
  }, [searchQuery]);

  const allEmojis = useMemo(() => getAllEmojis(), []);

  const displayedEmojis = useMemo(() => {
    if (debouncedQuery.trim()) {
      return searchEmojisByKeyword(debouncedQuery, allEmojis);
    }
    if (selectedCategory === 'all') {
      return allEmojis;
    }
    const category = HABIT_CATEGORIES.find(
      (cat) => cat.id === selectedCategory
    );
    return category?.emojis ?? [];
  }, [selectedCategory, debouncedQuery, allEmojis]);

  const currentCategoryName = useMemo(() => {
    const category = HABIT_CATEGORIES.find(
      (cat) => cat.id === selectedCategory
    );
    return category ? `${category.icon} ${category.name.toUpperCase()}` : '';
  }, [selectedCategory]);

  return {
    currentCategoryName,
    displayedEmojis,
    isSearching: !!searchQuery,
    recentEmojis,
    searchQuery,
    selectedCategory,
    setDebouncedQuery,
    setSearchQuery,
    setSelectedCategory,
    suggestedEmojis,
  };
};

