/**
 * EmojiPickerSheet Component
 * Main orchestrator for the emoji picker bottom sheet
 */

import React, { memo, useCallback } from 'react';
import { Modal, View, Text, Pressable } from 'react-native';
import { GestureDetector } from 'react-native-gesture-handler';
import Animated from 'react-native-reanimated';
import { addRecentEmoji } from '../../../utils/recentEmojis';
import { CategoryPills } from '../CategoryPills';
import { EmojiGrid } from '../EmojiGrid';
import type { EmojiPickerSheetProps } from './EmojiPickerSheet.types';
import { styles } from './EmojiPickerSheet.styles';
import { useEmojiPickerState } from './useEmojiPickerState';
import { useSheetAnimations } from './useSheetAnimations';
import { SearchBar } from './SearchBar';
import { SuggestionsSection } from './SuggestionsSection';

export const EmojiPickerSheet = memo(
  ({
    visible,
    habitName,
    selectedEmoji,
    onSelect,
    onClose,
  }: EmojiPickerSheetProps) => {
    const state = useEmojiPickerState(visible, habitName);
    const animations = useSheetAnimations(visible, onClose);

    const handleEmojiSelect = useCallback(
      async (emoji: string) => {
        await addRecentEmoji(emoji);
        onSelect(emoji);
        animations.closeSheet();
      },
      [onSelect, animations.closeSheet]
    );

    const handleNoIcon = useCallback(() => {
      onSelect(null);
      animations.closeSheet();
    }, [onSelect, animations.closeSheet]);

    return (
      <Modal
        statusBarTranslucent
        transparent
        animationType='none'
        visible={visible}
        onRequestClose={animations.closeSheet}
      >
        <View pointerEvents='box-none' style={styles.container}>
          <Pressable
            accessibilityLabel='Close emoji picker'
            accessibilityRole='button'
            style={{ ...styles.backdrop, position: 'absolute' }}
            onPress={animations.closeSheet}
          >
            <Animated.View
              style={[styles.backdrop, animations.backdropAnimatedStyle]}
            />
          </Pressable>

          <GestureDetector gesture={animations.gesture}>
            <Animated.View
              accessibilityViewIsModal
              style={[styles.sheet, animations.sheetAnimatedStyle]}
            >
              <View
                accessibilityLabel='Drag to dismiss'
                accessibilityRole='adjustable'
                style={styles.handleContainer}
              >
                <View style={styles.handle} />
              </View>

              <SearchBar
                animatedStyle={animations.searchBarAnimatedStyle}
                isSearchFocused={state.isSearchFocused}
                searchFocusAnim={animations.searchFocusAnim}
                setIsSearchFocused={state.setIsSearchFocused}
                value={state.searchQuery}
                onChange={state.setSearchQuery}
                onClear={state.handleClearSearch}
              />

              {!state.searchQuery && (
                <SuggestionsSection
                  habitName={habitName}
                  selectedEmoji={selectedEmoji}
                  suggestedEmojis={state.suggestedEmojis}
                  onEmojiSelect={handleEmojiSelect}
                />
              )}

              {!state.searchQuery && (
                <CategoryPills
                  selectedCategory={state.selectedCategory}
                  onCategorySelect={state.handleCategorySelect}
                />
              )}

              <EmojiGrid
                categoryName={
                  state.searchQuery ? undefined : state.currentCategoryName
                }
                emojis={state.displayedEmojis}
                selectedEmoji={selectedEmoji}
                showCategoryHeader={!state.searchQuery}
                onEmojiSelect={handleEmojiSelect}
              />

              <View style={styles.noIconContainer}>
                <Pressable
                  accessibilityLabel='Select no icon for this habit'
                  accessibilityRole='button'
                  style={styles.noIconButton}
                  onPress={handleNoIcon}
                >
                  <Text style={styles.noIconText}>No icon</Text>
                </Pressable>
              </View>
            </Animated.View>
          </GestureDetector>
        </View>
      </Modal>
    );
  }
);

EmojiPickerSheet.displayName = 'EmojiPickerSheet';
export default EmojiPickerSheet;

/**
 * SearchBar Component
 * Animated search input with focus effects
 */

import React, { useCallback } from 'react';
import { View, TextInput, Pressable, type ViewStyle } from 'react-native';
import { Search, X } from 'lucide-react-native';
import Animated, {
  useSharedValue,
  withTiming,
  type AnimatedStyle,
} from 'react-native-reanimated';
import { styles } from './EmojiPickerSheet.styles';

interface SearchBarProps {
  value: string;
  onChange: (text: string) => void;
  onClear: () => void;
  isSearchFocused: boolean;
  setIsSearchFocused: (focused: boolean) => void;
  searchFocusAnim: Animated.SharedValue<number>;
  animatedStyle: AnimatedStyle<ViewStyle>;
}

export function SearchBar({
  value,
  onChange,
  onClear,
  isSearchFocused,
  setIsSearchFocused,
  searchFocusAnim,
  animatedStyle,
}: SearchBarProps) {
  const handleFocus = useCallback(() => {
    setIsSearchFocused(true);
    searchFocusAnim.value = withTiming(1, { duration: 200 });
  }, [searchFocusAnim, setIsSearchFocused]);

  const handleBlur = useCallback(() => {
    setIsSearchFocused(false);
    searchFocusAnim.value = withTiming(0, { duration: 150 });
  }, [searchFocusAnim, setIsSearchFocused]);

  return (
    <View style={styles.searchContainer}>
      <Animated.View style={[styles.searchBar, animatedStyle]}>
        <Search color={isSearchFocused ? '#3b82f6' : '#a8a29e'} size={20} />
        <TextInput
          accessibilityHint='Type keywords to search for emojis'
          accessibilityLabel='Search emojis'
          placeholder='Search or type habit name...'
          placeholderTextColor='#a8a29e'
          returnKeyType='search'
          style={styles.searchInput}
          value={value}
          onBlur={handleBlur}
          onChangeText={onChange}
          onFocus={handleFocus}
        />
        {value.length > 0 && (
          <Pressable
            accessibilityLabel='Clear search'
            accessibilityRole='button'
            onPress={onClear}
          >
            <X color='#9ca3af' size={18} />
          </Pressable>
        )}
      </Animated.View>
    </View>
  );
}

/**
 * useEmojiPickerState Hook
 * Manages search, category, and emoji selection state
 */

import { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import { HABIT_CATEGORIES } from '../../../constants/habitEmojis';
import { getAllEmojis } from '../../../utils/emojiData';
import {
  searchEmojisByKeyword,
  suggestEmojisForHabitName,
} from '../../../utils/emojiKeywords';
import { getRecentEmojis } from '../../../utils/recentEmojis';

export function useEmojiPickerState(visible: boolean, habitName: string) {
  const [searchQuery, setSearchQuery] = useState('');
  const [debouncedQuery, setDebouncedQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('fitness');
  const [recentEmojis, setRecentEmojis] = useState<string[]>([]);
  const [isSearchFocused, setIsSearchFocused] = useState(false);
  const searchTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Compute suggested emojis based on habit name
  const suggestedEmojis = useMemo(() => {
    if (!habitName?.trim()) return [];
    return suggestEmojisForHabitName(habitName, 5);
  }, [habitName]);

  // Debounce search query
  useEffect(() => {
    if (searchTimeoutRef.current) clearTimeout(searchTimeoutRef.current);
    searchTimeoutRef.current = setTimeout(
      () => setDebouncedQuery(searchQuery),
      150
    );
    return () => {
      if (searchTimeoutRef.current) clearTimeout(searchTimeoutRef.current);
    };
  }, [searchQuery]);

  // Get all emojis (cached)
  const allEmojis = useMemo(() => getAllEmojis(), []);

  // Get emojis to display based on category and search
  const displayedEmojis = useMemo(() => {
    if (debouncedQuery.trim())
      return searchEmojisByKeyword(debouncedQuery, allEmojis);
    if (selectedCategory === 'all') return allEmojis;
    const category = HABIT_CATEGORIES.find(
      (cat) => cat.id === selectedCategory
    );
    return category?.emojis ?? [];
  }, [selectedCategory, debouncedQuery, allEmojis]);

  // Load recent emojis on mount
  useEffect(() => {
    if (visible) getRecentEmojis().then(setRecentEmojis);
  }, [visible]);

  // Get current category name for header
  const currentCategoryName = useMemo(() => {
    const category = HABIT_CATEGORIES.find(
      (cat) => cat.id === selectedCategory
    );
    return category ? `${category.icon} ${category.name.toUpperCase()}` : '';
  }, [selectedCategory]);

  const handleCategorySelect = useCallback((categoryId: string) => {
    setSelectedCategory(categoryId);
    setSearchQuery('');
    setDebouncedQuery('');
  }, []);

  const handleClearSearch = useCallback(() => {
    setSearchQuery('');
    setDebouncedQuery('');
  }, []);

  return {
    currentCategoryName,
    displayedEmojis,
    handleCategorySelect,
    handleClearSearch,
    isSearchFocused,
    searchQuery,
    selectedCategory,
    setIsSearchFocused,
    setSearchQuery,
    suggestedEmojis,
  };
}

/**
 * useSheetAnimations Hook
 * Manages bottom sheet animations and gesture handling
 */

import { useEffect, useCallback } from 'react';
import { Gesture } from 'react-native-gesture-handler';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withTiming,
  runOnJS,
  interpolate,
  Extrapolation,
} from 'react-native-reanimated';
import { SHEET_HEIGHT } from './EmojiPickerSheet.styles';

export function useSheetAnimations(visible: boolean, onClose: () => void) {
  const translateY = useSharedValue(SHEET_HEIGHT);
  const backdropOpacity = useSharedValue(0);
  const context = useSharedValue({ y: 0 });
  const searchFocusAnim = useSharedValue(0);

  // Sheet open/close animations
  useEffect(() => {
    if (visible) {
      translateY.value = withSpring(0, { damping: 20, stiffness: 200 });
      backdropOpacity.value = withTiming(1, { duration: 300 });
    } else {
      translateY.value = withSpring(SHEET_HEIGHT, {
        damping: 20,
        stiffness: 200,
      });
      backdropOpacity.value = withTiming(0, { duration: 300 });
    }
  }, [visible]);

  const closeSheet = useCallback(() => {
    translateY.value = withSpring(SHEET_HEIGHT, {
      damping: 20,
      stiffness: 200,
    });
    backdropOpacity.value = withTiming(0, { duration: 200 });
    setTimeout(onClose, 200);
  }, [onClose]);

  // Gesture handler for drag dismissal
  const gesture = Gesture.Pan()
    .onStart(() => {
      context.value = { y: translateY.value };
    })
    .onUpdate((event) => {
      translateY.value = Math.max(context.value.y + event.translationY, 0);
    })
    .onEnd((event) => {
      const velocityY = Math.round(event.velocityY);
      if (translateY.value > SHEET_HEIGHT * 0.25 || velocityY > 500) {
        runOnJS(closeSheet)();
      } else {
        translateY.value = withSpring(0, { damping: 20, stiffness: 200 });
      }
    });

  const sheetAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ translateY: translateY.value }],
  }));

  const backdropAnimatedStyle = useAnimatedStyle(() => ({
    opacity: interpolate(
      backdropOpacity.value,
      [0, 1],
      [0, 0.4],
      Extrapolation.CLAMP
    ),
  }));

  const searchBarAnimatedStyle = useAnimatedStyle(() => ({
    borderColor: searchFocusAnim.value === 1 ? '#3b82f6' : '#e7e5e4',
    shadowColor: '#3b82f6',
    shadowOffset: { height: 0, width: 0 },
    shadowOpacity: interpolate(
      searchFocusAnim.value,
      [0, 1],
      [0, 0.2],
      Extrapolation.CLAMP
    ),
    shadowRadius: interpolate(
      searchFocusAnim.value,
      [0, 1],
      [0, 6],
      Extrapolation.CLAMP
    ),
  }));

  return {
    backdropAnimatedStyle,
    closeSheet,
    gesture,
    searchBarAnimatedStyle,
    searchFocusAnim,
    sheetAnimatedStyle,
  };
}

/**
 * EmptyState - Re-export for backward compatibility
 * @deprecated Import from './EmptyState/index' instead
 */

export { EmptyState, default } from './EmptyState/index';
export type { EmptyStateProps, EmptyStateVariant } from './EmptyState/types';

/**
 * EmptyState Component
 * Based on UX Specification Section 4.2 & Section 8.2 (Empty State Transitions)
 *
 * Purpose: Guide users when no data exists
 * Variants: No Habits (first-time), No Data Yet (<7 days), No Results (search/filter), Premium Locked
 * Elements: Illustration/icon, headline, description, CTA button
 * Usage: Home screen (no habits), Analytics (no data), Search results
 */

import React from 'react';
import { View } from 'react-native';
import Animated from 'react-native-reanimated';
import { useAppTheme } from '../../theme';
import Button from '../Button/Button';
import type { EmptyStateProps } from './types';
import { VARIANT_CONFIG } from './constants';
import { useEmptyStateAnimations } from './useEmptyStateAnimations';
import { styles } from './styles';

export function EmptyState({
  variant = 'noHabits',
  icon,
  headline,
  description,
  ctaLabel,
  onCTA,
  hideCTA = false,
  style,
}: EmptyStateProps) {
  const theme = useAppTheme();
  const config = VARIANT_CONFIG[variant];
  const { iconStyle, headlineStyle, descriptionStyle, ctaStyle } =
    useEmptyStateAnimations(variant);

  // Use custom values or fall back to variant config
  const displayIcon = icon || config.icon;
  const displayHeadline = headline || config.headline;
  const displayDescription = description || config.description;
  const displayCTALabel = ctaLabel || config.ctaLabel;

  return (
    <View
      accessible
      accessibilityLabel={`${displayHeadline}. ${displayDescription}`}
      accessibilityRole='text'
      style={[styles.container, style]}
    >
      {/* Icon/Illustration */}
      <Animated.Text style={[styles.icon, iconStyle]}>
        {displayIcon}
      </Animated.Text>

      {/* Headline */}
      <Animated.Text
        style={[
          theme.custom.typography.heading2,
          styles.headline,
          { color: theme.custom.colors.gray[900] },
          headlineStyle,
        ]}
      >
        {displayHeadline}
      </Animated.Text>

      {/* Description */}
      <Animated.Text
        style={[
          theme.custom.typography.body,
          styles.description,
          { color: theme.custom.colors.gray[500] },
          descriptionStyle,
        ]}
      >
        {displayDescription}
      </Animated.Text>

      {/* CTA Button */}
      {!hideCTA && onCTA && (
        <Animated.View style={ctaStyle}>
          <Button
            accessibilityHint={`Tap to ${displayCTALabel.toLowerCase()}`}
            accessibilityLabel={displayCTALabel}
            size='medium'
            variant='primary'
            onPress={onCTA}
          >
            {displayCTALabel}
          </Button>
        </Animated.View>
      )}
    </View>
  );
}

export default EmptyState;

/**
 * useEmptyStateAnimations Hook
 * Entrance animation with stagger (UX spec Section 8.2)
 */

import { useEffect } from 'react';
import {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withDelay,
} from 'react-native-reanimated';
import type { EmptyStateVariant } from './types';

const SPRING_CONFIG = { damping: 15, stiffness: 150 };

export function useEmptyStateAnimations(variant: EmptyStateVariant) {
  const iconOpacity = useSharedValue(0);
  const iconScale = useSharedValue(0.9);
  const headlineOpacity = useSharedValue(0);
  const descriptionOpacity = useSharedValue(0);
  const ctaOpacity = useSharedValue(0);
  const ctaTranslateY = useSharedValue(20);

  useEffect(() => {
    // Icon: fade in and scale up
    iconOpacity.value = withSpring(1, SPRING_CONFIG);
    iconScale.value = withSpring(1, SPRING_CONFIG);

    // Headline: fade in with delay
    headlineOpacity.value = withDelay(200, withSpring(1, SPRING_CONFIG));

    // Description: fade in with delay
    descriptionOpacity.value = withDelay(300, withSpring(1, SPRING_CONFIG));

    // CTA: fade in and slide up with delay
    ctaOpacity.value = withDelay(400, withSpring(1, SPRING_CONFIG));
    ctaTranslateY.value = withDelay(400, withSpring(0, SPRING_CONFIG));
  }, [variant]);

  const iconStyle = useAnimatedStyle(() => ({
    opacity: iconOpacity.value,
    transform: [{ scale: iconScale.value }],
  }));

  const headlineStyle = useAnimatedStyle(() => ({
    opacity: headlineOpacity.value,
  }));

  const descriptionStyle = useAnimatedStyle(() => ({
    opacity: descriptionOpacity.value,
  }));

  const ctaStyle = useAnimatedStyle(() => ({
    opacity: ctaOpacity.value,
    transform: [{ translateY: ctaTranslateY.value }],
  }));

  return { ctaStyle, descriptionStyle, headlineStyle, iconStyle };
}

