/**
 * FloatingXPText Component
 *
 * Displays "+X XP" text that floats up and fades out
 * Used when user completes a habit or earns bonus XP
 *
 * Based on Part B: Micro-Transitions Strategy
 * Duration: 800ms
 * Movement: Floats up 40px
 * Opacity: 1 → 0
 */

import React, { useEffect } from 'react';
import { StyleSheet } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withTiming,
  Easing,
  runOnJS,
} from 'react-native-reanimated';
import { LinearGradient } from 'expo-linear-gradient';

export interface FloatingXPTextProps {
  /** XP value to display (e.g., 10, 50, 100) */
  value: number;

  /** Position where animation starts */
  startPosition: { x: number; y: number };

  /** Callback when animation completes */
  onComplete?: () => void;

  /** Show coin icon instead of XP */
  showCoin?: boolean;
}

export function FloatingXPText({
  value,
  startPosition,
  onComplete,
  showCoin = false,
}: FloatingXPTextProps) {
  const translateY = useSharedValue(0);
  const opacity = useSharedValue(1);

  useEffect(() => {
    // Animate upward movement
    translateY.value = withTiming(-40, {
      duration: 800,
      easing: Easing.out(Easing.cubic),
    });

    // Animate fade out
    opacity.value = withTiming(
      0,
      {
        duration: 800,
        easing: Easing.in(Easing.cubic),
      },
      (finished) => {
        if (finished && onComplete) {
          runOnJS(onComplete)();
        }
      }
    );
  }, []);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ translateY: translateY.value }],
    opacity: opacity.value,
  }));

  return (
    <Animated.View
      style={[
        styles.container,
        {
          position: 'absolute',
          left: startPosition.x,
          top: startPosition.y,
        },
        animatedStyle,
      ]}
      pointerEvents="none"
    >
      {showCoin ? (
        // Coin variant (gold color)
        <Animated.Text style={styles.coinText}>
          +{value} 🪙
        </Animated.Text>
      ) : (
        // XP variant (green gradient - simulate with shadow for now)
        <Animated.Text style={styles.xpText}>
          +{value} XP
        </Animated.Text>
      )}
    </Animated.View>
  );
}

const styles = StyleSheet.create({
  container: {
    alignItems: 'center',
    justifyContent: 'center',
    zIndex: 1000,
  },
  xpText: {
    fontSize: 18,
    fontWeight: 'bold',
    color: '#10B981', // Green 500
    textShadowColor: '#10B981',
    textShadowOffset: { width: 0, height: 0 },
    textShadowRadius: 8,
  },
  coinText: {
    fontSize: 18,
    fontWeight: 'bold',
    color: '#F59E0B', // Amber 500
    textShadowColor: '#F59E0B',
    textShadowOffset: { width: 0, height: 0 },
    textShadowRadius: 8,
  },
});

export default FloatingXPText;

import React, { useState } from 'react';
import { Pressable, Text, View, ActivityIndicator } from 'react-native';
import { useMutation } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import { assertUpdateStrengthResponse } from './types';
import type { ForceUpdateButtonProps } from './types';

export function ForceUpdateButton({
  habitId,
  habitName: _habitName,
  currentStrength,
}: ForceUpdateButtonProps) {
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<string | null>(null);
  const updateStrength = useMutation(api.habitStrength.updateHabitStrength);

  const handleClick = async () => {
    setLoading(true);
    setResult(null);

    try {
      const today = new Date().toISOString().split('T')[0];
      const response = await updateStrength({
        behaviorPerformed: true,
        date: today,
        habitId,
      });

      assertUpdateStrengthResponse(response);
      setResult(
        `✅ ${response.previousStrength.toFixed(3)} → ${response.newStrength.toFixed(3)}`
      );
      console.log('Force update result:', response);
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      setResult(`❌ Error: ${errorMessage}`);
      console.error('Force update error:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <View className='mt-2 gap-2'>
      <Pressable
        className={`rounded-lg px-4 py-2 ${
          loading ? 'bg-stone-400' : 'bg-green-600'
        }`}
        disabled={loading}
        onPress={handleClick}
      >
        {loading ? (
          <View className='flex-row items-center justify-center gap-2'>
            <ActivityIndicator color='white' size='small' />
            <Text className='font-semibold text-white'>Updating...</Text>
          </View>
        ) : (
          <Text className='text-center font-semibold text-white'>
            🚀 Force Update Strength +15%
          </Text>
        )}
      </Pressable>

      {result && (
        <View
          className={`rounded-lg p-2 ${
            result.startsWith('✅') ? 'bg-green-100' : 'bg-red-100'
          }`}
        >
          <Text
            className={`text-xs ${
              result.startsWith('✅') ? 'text-green-800' : 'text-red-800'
            }`}
          >
            {result}
          </Text>
        </View>
      )}

      <Text className='text-xs text-stone-500'>
        Current: {(currentStrength * 100).toFixed(1)}%
      </Text>
    </View>
  );
}

/**
 * FullsizeTemplatePreview - Main orchestration component
 * A fullsize preview modal for template cards
 */

import React from 'react';
import { View, ScrollView } from 'react-native';
import Animated from 'react-native-reanimated';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import Modal from '../Modal';
import { useReduceMotion } from '../../hooks/useReduceMotion';
import {
  HeroSection,
  DescriptionSection,
  ScienceBox,
  TipsBox,
  FooterSection,
  ModalHeader,
  ConfettiOverlay,
} from './components';
import {
  useEntranceAnimations,
  useSuccessAnimations,
  useButtonAnimations,
  useAnimatedStyles,
  useHandlers,
} from './hooks';
import { layoutStyles } from './styles';
import { DEFAULT_ICON_COLOR } from './FullsizeTemplatePreview.constants';
import type { FullsizeTemplatePreviewProps } from './FullsizeTemplatePreview.types';

export default function FullsizeTemplatePreview({
  template,
  visible,
  onClose,
  onImport,
  onCustomize,
  isImporting = false,
  isImported = false,
}: FullsizeTemplatePreviewProps) {
  const insets = useSafeAreaInsets();
  const reducedMotion = useReduceMotion();
  const iconColor = template?.iconColor?.trim() || DEFAULT_ICON_COLOR;
  const entranceAnimations = useEntranceAnimations({
    reducedMotion,
    template,
    visible,
  });
  const successAnimations = useSuccessAnimations({ isImported, reducedMotion });
  const {
    closeButtonScale,
    importButtonScale,
    customizeButtonScale,
    createPressHandlers,
  } = useButtonAnimations({ reducedMotion });
  const handlers = useHandlers({
    isImported,
    isImporting,
    onClose,
    onCustomize,
    onImport,
    reducedMotion,
    template,
  });
  const animatedStyles = useAnimatedStyles({
    ...entranceAnimations,
    closeButtonScale,
    customizeButtonScale,
    importButtonScale,
    ...successAnimations,
  });

  if (!template) return null;
  const tips = (template as any).tips;

  return (
    <Modal
      disableBackdropClose={isImporting}
      variant='fullScreen'
      visible={visible}
      onClose={handlers.handleClose}
    >
      <Animated.View
        style={[layoutStyles.container, animatedStyles.contentStyle]}
      >
        <Animated.View
          pointerEvents='none'
          style={[
            layoutStyles.successGlowOverlay,
            { backgroundColor: '#22c55e' },
            animatedStyles.successGlowStyle,
          ]}
        />
        <ModalHeader
          closeButtonAnimatedOpacityStyle={
            animatedStyles.closeButtonAnimatedOpacityStyle
          }
          closeButtonPressHandlers={createPressHandlers(closeButtonScale, 0.9)}
          closeButtonStyle={animatedStyles.closeButtonStyle}
          topInset={insets.top}
          onClose={handlers.handleClose}
        />
        <ScrollView
          bounces
          contentContainerStyle={layoutStyles.contentContainer}
          showsVerticalScrollIndicator={false}
        >
          <HeroSection
            iconAnimatedStyle={animatedStyles.iconAnimatedStyle}
            iconColor={iconColor}
            iconGlowStyle={animatedStyles.iconGlowStyle}
            template={template}
          />
          <DescriptionSection description={template.description} />
          <ScienceBox
            template={template}
            onResearchPress={handlers.handleResearchPress}
          />
          {tips && Array.isArray(tips) && tips.length > 0 && (
            <TipsBox iconColor={iconColor} tips={tips} />
          )}
          <View style={layoutStyles.bottomSpacer} />
        </ScrollView>
        <FooterSection
          bottomInset={insets.bottom}
          checkmarkAnimatedStyle={animatedStyles.checkmarkAnimatedStyle}
          createPressHandlers={createPressHandlers}
          customizeButtonScale={customizeButtonScale}
          customizeButtonStyle={animatedStyles.customizeButtonStyle}
          iconColor={iconColor}
          importButtonScale={importButtonScale}
          importButtonStyle={animatedStyles.importButtonStyle}
          isImported={isImported}
          isImporting={isImporting}
          successButtonGlowStyle={animatedStyles.successButtonGlowStyle}
          successIconBounceStyle={animatedStyles.successIconBounceStyle}
          templateName={template.name}
          onCustomize={handlers.handleCustomize}
          onImport={handlers.handleImport}
        />
        <ConfettiOverlay
          ref={successAnimations.confettiRef}
          visible={isImported && !reducedMotion}
        />
      </Animated.View>
    </Modal>
  );
}

/**
 * Footer section for FullsizeTemplatePreview
 * Contains import and customize buttons with success state
 */

import React from 'react';
import { View, Text, Pressable } from 'react-native';
import Animated from 'react-native-reanimated';
import { LinearGradient } from 'expo-linear-gradient';
import { Check } from 'lucide-react-native';
import { footerStyles } from '../styles';
import type { SharedValue } from 'react-native-reanimated';
import type { PressHandlers } from '../FullsizeTemplatePreview.types';

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

interface FooterSectionProps {
  templateName: string;
  iconColor: string;
  isImporting: boolean;
  isImported: boolean;
  bottomInset: number;
  importButtonStyle: object;
  customizeButtonStyle: object;
  checkmarkAnimatedStyle: object;
  successButtonGlowStyle: object;
  successIconBounceStyle: object;
  createPressHandlers: (
    scale: SharedValue<number>,
    scaleValue?: number
  ) => PressHandlers;
  importButtonScale: SharedValue<number>;
  customizeButtonScale: SharedValue<number>;
  onImport: () => void;
  onCustomize: () => void;
}

export function FooterSection({
  templateName,
  iconColor,
  isImporting,
  isImported,
  bottomInset,
  importButtonStyle,
  customizeButtonStyle,
  checkmarkAnimatedStyle,
  successButtonGlowStyle,
  successIconBounceStyle,
  createPressHandlers,
  importButtonScale,
  customizeButtonScale,
  onImport,
  onCustomize,
}: FooterSectionProps) {
  return (
    <View style={footerStyles.footerGradientWrapper}>
      <LinearGradient
        colors={[
          'rgba(250, 250, 249, 0)',
          'rgba(250, 250, 249, 1)',
          'rgba(250, 250, 249, 1)',
        ]}
        style={footerStyles.footerGradient}
      >
        <View
          style={[
            footerStyles.footer,
            { paddingBottom: Math.max(bottomInset, 20) },
          ]}
        >
          {isImported ? (
            <View style={footerStyles.successButtonWrapper}>
              <Animated.View
                pointerEvents='none'
                style={[footerStyles.successButtonGlow, successButtonGlowStyle]}
              />
              <Animated.View
                style={[footerStyles.successButton, checkmarkAnimatedStyle]}
              >
                <Animated.View style={successIconBounceStyle}>
                  <Check color='#fff' size={22} strokeWidth={3} />
                </Animated.View>
                <Text style={footerStyles.successButtonText}>Added!</Text>
              </Animated.View>
            </View>
          ) : (
            <AnimatedPressable
              accessible
              accessibilityLabel={`Import ${templateName} habit`}
              accessibilityRole='button'
              disabled={isImporting}
              style={[
                footerStyles.importButton,
                { backgroundColor: iconColor },
                isImporting && { opacity: 0.6 },
                importButtonStyle,
              ]}
              onPress={onImport}
              {...createPressHandlers(importButtonScale)}
            >
              <Text style={footerStyles.importButtonText}>
                {isImporting ? 'Importing...' : 'Import This Habit'}
              </Text>
            </AnimatedPressable>
          )}

          {!isImported && (
            <AnimatedPressable
              accessible
              accessibilityLabel='Customize habit before importing'
              accessibilityRole='button'
              disabled={isImporting}
              style={[footerStyles.customizeLink, customizeButtonStyle]}
              onPress={onCustomize}
              {...createPressHandlers(customizeButtonScale, 0.98)}
            >
              <Text style={footerStyles.customizeLinkText}>
                Customize First →
              </Text>
            </AnimatedPressable>
          )}
        </View>
      </LinearGradient>
    </View>
  );
}

/**
 * Hero section for FullsizeTemplatePreview
 * Displays the template icon, name, and metadata pills
 */

import React from 'react';
import { View, Text } from 'react-native';
import Animated from 'react-native-reanimated';
import { LinearGradient } from 'expo-linear-gradient';
import { Clock, Sparkles } from 'lucide-react-native';
import { useAppTheme } from '../../../theme';
import { heroStyles } from '../styles';
import {
  FREQUENCY_LABELS,
  CATEGORY_LABELS,
} from '../FullsizeTemplatePreview.constants';
import type { Doc } from '../../../../convex/_generated/dataModel';

interface HeroSectionProps {
  template: Doc<'templates'>;
  iconColor: string;
  iconAnimatedStyle: object;
  iconGlowStyle: object;
}

export function HeroSection({
  template,
  iconColor,
  iconAnimatedStyle,
  iconGlowStyle,
}: HeroSectionProps) {
  const theme = useAppTheme();
  const gradientColors = [
    `${iconColor}15`,
    `${iconColor}08`,
    '#FAFAF9',
  ] as const;
  const formattedFrequency =
    FREQUENCY_LABELS[template.frequency] || template.frequency;
  const formattedCategory =
    CATEGORY_LABELS[template.category] || template.category;

  return (
    <LinearGradient colors={gradientColors} style={heroStyles.heroGradient}>
      <View style={heroStyles.heroContent}>
        <Animated.View style={[heroStyles.iconWrapper, iconAnimatedStyle]}>
          <Animated.View
            style={[
              heroStyles.iconGlow,
              { backgroundColor: iconColor, shadowColor: iconColor },
              iconGlowStyle,
            ]}
          />
          <View
            style={[
              heroStyles.iconContainer,
              { backgroundColor: `${iconColor}20` },
            ]}
          >
            <Text style={heroStyles.iconText}>{template.icon}</Text>
          </View>
        </Animated.View>

        <Text
          style={[
            heroStyles.templateName,
            { fontFamily: theme.custom.fontFamilies.primary.text },
          ]}
        >
          {template.name}
        </Text>

        <View style={heroStyles.pillsRow}>
          <View
            style={[
              heroStyles.metadataPill,
              {
                backgroundColor: `${iconColor}10`,
                borderColor: `${iconColor}20`,
              },
            ]}
          >
            <Clock color={iconColor} size={14} strokeWidth={2} />
            <Text style={[heroStyles.metadataPillText, { color: iconColor }]}>
              {formattedFrequency}
            </Text>
          </View>
          <View
            style={[
              heroStyles.metadataPill,
              {
                backgroundColor: `${iconColor}10`,
                borderColor: `${iconColor}20`,
              },
            ]}
          >
            <Sparkles color={iconColor} size={14} strokeWidth={2} />
            <Text style={[heroStyles.metadataPillText, { color: iconColor }]}>
              {formattedCategory}
            </Text>
          </View>
          <View
            style={[
              heroStyles.metadataPill,
              {
                backgroundColor: `${iconColor}10`,
                borderColor: `${iconColor}20`,
              },
            ]}
          >
            <Text style={[heroStyles.metadataPillText, { color: iconColor }]}>
              ⏱️ 5-10 min
            </Text>
          </View>
        </View>
      </View>
    </LinearGradient>
  );
}

/**
 * Animated styles for FullsizeTemplatePreview
 */

import { useAnimatedStyle, type SharedValue } from 'react-native-reanimated';

interface UseAnimatedStylesProps {
  backdropOpacity: SharedValue<number>;
  contentTranslateY: SharedValue<number>;
  contentOpacity: SharedValue<number>;
  iconScale: SharedValue<number>;
  iconGlowScale: SharedValue<number>;
  iconGlowOpacity: SharedValue<number>;
  closeButtonScale: SharedValue<number>;
  closeButtonOpacity: SharedValue<number>;
  importButtonScale: SharedValue<number>;
  customizeButtonScale: SharedValue<number>;
  successGlow: SharedValue<number>;
  successGlowScale: SharedValue<number>;
  checkmarkScale: SharedValue<number>;
  checkmarkRotation: SharedValue<number>;
  successButtonGlow: SharedValue<number>;
  successIconBounce: SharedValue<number>;
}

export const useAnimatedStyles = (props: UseAnimatedStylesProps) => {
  const backdropStyle = useAnimatedStyle(() => ({
    opacity: props.backdropOpacity.value,
  }));

  const contentStyle = useAnimatedStyle(() => ({
    opacity: props.contentOpacity.value,
    transform: [{ translateY: props.contentTranslateY.value }],
  }));

  const iconAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: props.iconScale.value }],
  }));

  const iconGlowStyle = useAnimatedStyle(() => ({
    opacity: props.iconGlowOpacity.value,
    transform: [{ scale: props.iconGlowScale.value }],
  }));

  const closeButtonStyle = useAnimatedStyle(() => ({
    transform: [{ scale: props.closeButtonScale.value }],
  }));

  const closeButtonAnimatedOpacityStyle = useAnimatedStyle(() => ({
    opacity: props.closeButtonOpacity.value,
  }));

  const importButtonStyle = useAnimatedStyle(() => ({
    transform: [{ scale: props.importButtonScale.value }],
  }));

  const customizeButtonStyle = useAnimatedStyle(() => ({
    transform: [{ scale: props.customizeButtonScale.value }],
  }));

  const successGlowStyle = useAnimatedStyle(() => ({
    opacity: props.successGlow.value,
    transform: [{ scale: props.successGlowScale.value }],
  }));

  const checkmarkAnimatedStyle = useAnimatedStyle(() => ({
    opacity: props.checkmarkScale.value,
    transform: [
      { scale: props.checkmarkScale.value },
      { rotate: `${Math.round(props.checkmarkRotation.value)}deg` },
    ],
  }));

  const successButtonGlowStyle = useAnimatedStyle(() => ({
    opacity: props.successButtonGlow.value,
  }));

  const successIconBounceStyle = useAnimatedStyle(() => ({
    transform: [{ translateY: props.successIconBounce.value }],
  }));

  return {
    backdropStyle,
    checkmarkAnimatedStyle,
    closeButtonAnimatedOpacityStyle,
    closeButtonStyle,
    contentStyle,
    customizeButtonStyle,
    iconAnimatedStyle,
    iconGlowStyle,
    importButtonStyle,
    successButtonGlowStyle,
    successGlowStyle,
    successIconBounceStyle,
  };
};

/**
 * Entrance animation logic for FullsizeTemplatePreview
 */

import { useEffect } from 'react';
import {
  useSharedValue,
  withSpring,
  withDelay,
  withTiming,
  Easing,
} from 'react-native-reanimated';
import { Springs } from '../../../constants/motion';
import type { Doc } from '../../../../convex/_generated/dataModel';

interface UseEntranceAnimationsProps {
  visible: boolean;
  template: Doc<'templates'> | null;
  reducedMotion: boolean;
}

export const useEntranceAnimations = ({
  visible,
  template,
  reducedMotion,
}: UseEntranceAnimationsProps) => {
  const backdropOpacity = useSharedValue(0);
  const contentTranslateY = useSharedValue(100);
  const contentOpacity = useSharedValue(0);
  const iconScale = useSharedValue(0.8);
  const iconGlowScale = useSharedValue(1);
  const iconGlowOpacity = useSharedValue(0.25);
  const closeButtonOpacity = useSharedValue(1);

  useEffect(() => {
    if (visible && template) {
      backdropOpacity.value = 0;
      contentTranslateY.value = 100;
      contentOpacity.value = 0;
      iconScale.value = 0.8;
      closeButtonOpacity.value = 0;

      if (reducedMotion) {
        backdropOpacity.value = 0.5;
        contentTranslateY.value = 0;
        contentOpacity.value = 1;
        iconScale.value = 1;
        closeButtonOpacity.value = 1;
      } else {
        backdropOpacity.value = withTiming(0.5, {
          duration: 350,
          easing: Easing.out(Easing.cubic),
        });
        contentTranslateY.value = withSpring(0, Springs.gentle);
        contentOpacity.value = withTiming(1, {
          duration: 400,
          easing: Easing.out(Easing.cubic),
        });
        closeButtonOpacity.value = withDelay(
          200,
          withTiming(1, { duration: 300, easing: Easing.out(Easing.cubic) })
        );
        iconScale.value = withDelay(250, withSpring(1, Springs.micro));
        iconGlowScale.value = withDelay(400, withSpring(1.12, Springs.pulse));
      }
    }
  }, [visible, template, reducedMotion]);

  return {
    backdropOpacity,
    closeButtonOpacity,
    contentOpacity,
    contentTranslateY,
    iconGlowOpacity,
    iconGlowScale,
    iconScale,
  };
};

/**
 * Event handlers for FullsizeTemplatePreview
 */

import { useCallback } from 'react';
import { Linking } from 'react-native';
import * as Haptics from 'expo-haptics';
import type { Doc, Id } from '../../../../convex/_generated/dataModel';

interface UseHandlersProps {
  template: Doc<'templates'> | null;
  isImporting: boolean;
  isImported: boolean;
  reducedMotion: boolean;
  onClose: () => void;
  onImport: (templateId: Id<'templates'>) => void;
  onCustomize: (template: Doc<'templates'>) => void;
}

export const useHandlers = ({
  template,
  isImporting,
  isImported,
  reducedMotion,
  onClose,
  onImport,
  onCustomize,
}: UseHandlersProps) => {
  const handleClose = useCallback(() => {
    if (!reducedMotion) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    }
    onClose();
  }, [onClose, reducedMotion]);

  const handleImport = useCallback(() => {
    if (!template || isImporting || isImported) return;
    if (!reducedMotion) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    }
    onImport(template._id);
  }, [template, isImporting, isImported, onImport, reducedMotion]);

  const handleCustomize = useCallback(() => {
    if (!template) return;
    if (!reducedMotion) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    }
    onCustomize(template);
  }, [template, onCustomize, reducedMotion]);

  const handleResearchPress = useCallback(async () => {
    if (!template?.scientificLink) return;
    if (!reducedMotion) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    }
    const canOpen = await Linking.canOpenURL(template.scientificLink);
    if (canOpen) {
      await Linking.openURL(template.scientificLink);
    }
  }, [template?.scientificLink, reducedMotion]);

  return {
    handleClose,
    handleCustomize,
    handleImport,
    handleResearchPress,
  };
};

/**
 * Success state animation logic for FullsizeTemplatePreview
 */

import { useEffect, useCallback, useRef } from 'react';
import {
  useSharedValue,
  withSpring,
  withDelay,
  withSequence,
  withTiming,
  Easing,
} from 'react-native-reanimated';
import * as Haptics from 'expo-haptics';
import ConfettiCannon from 'react-native-confetti-cannon';

interface UseSuccessAnimationsProps {
  isImported: boolean;
  reducedMotion: boolean;
}

export const useSuccessAnimations = ({
  isImported,
  reducedMotion,
}: UseSuccessAnimationsProps) => {
  const confettiRef = useRef<ConfettiCannon>(null);
  const successGlow = useSharedValue(0);
  const successGlowScale = useSharedValue(1);
  const checkmarkScale = useSharedValue(0);
  const checkmarkRotation = useSharedValue(-30);
  const successButtonGlow = useSharedValue(0);
  const successIconBounce = useSharedValue(0);

  const triggerSuccessHaptic = useCallback(() => {
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
  }, []);

  const triggerConfetti = useCallback(() => {
    if (confettiRef.current && !reducedMotion) confettiRef.current.start();
  }, [reducedMotion]);

  useEffect(() => {
    if (isImported) {
      if (reducedMotion) {
        checkmarkScale.value = 1;
        checkmarkRotation.value = 0;
        successGlow.value = 0.4;
        successGlowScale.value = 1;
        successButtonGlow.value = 0;
        successIconBounce.value = 0;
      } else {
        triggerSuccessHaptic();
        triggerConfetti();
        successGlow.value = withSequence(
          withTiming(0.5, { duration: 150, easing: Easing.out(Easing.ease) }),
          withTiming(0.2, { duration: 300, easing: Easing.inOut(Easing.ease) }),
          withTiming(0, { duration: 500, easing: Easing.out(Easing.ease) })
        );
        successGlowScale.value = withSequence(
          withTiming(1.3, { duration: 200, easing: Easing.out(Easing.ease) }),
          withTiming(1, { duration: 400, easing: Easing.inOut(Easing.ease) })
        );
        checkmarkScale.value = withDelay(
          100,
          withSpring(1, { damping: 6, mass: 1, stiffness: 180 })
        );
        checkmarkRotation.value = withDelay(
          100,
          withSpring(0, { damping: 10, stiffness: 150 })
        );
        successButtonGlow.value = withDelay(
          200,
          withSequence(
            withTiming(1, { duration: 200 }),
            withTiming(0.3, { duration: 300 }),
            withTiming(0.8, { duration: 200 }),
            withTiming(0.4, { duration: 400 })
          )
        );
        successIconBounce.value = withDelay(
          300,
          withSequence(
            withSpring(-3, { damping: 8, stiffness: 300 }),
            withSpring(0, { damping: 12, stiffness: 200 })
          )
        );
      }
    } else {
      checkmarkScale.value = 0;
      checkmarkRotation.value = -30;
      successGlow.value = 0;
      successGlowScale.value = 1;
      successButtonGlow.value = 0;
      successIconBounce.value = 0;
    }
  }, [isImported, reducedMotion, triggerSuccessHaptic, triggerConfetti]);

  return {
    checkmarkRotation,
    checkmarkScale,
    confettiRef,
    successButtonGlow,
    successGlow,
    successGlowScale,
    successIconBounce,
  };
};

