import { useState } from 'react';
import { format } from 'date-fns';
import { getEmojiAndName } from '../DraggableHabit/DraggableHabit.hooks';
import {
  calculateBestStreak,
  calculateCompletionPercentage,
} from '../../utils/habitCalculations';
import { buildScheduleLabel, getLatestMissedBadge } from './utils';
import type { CalendarView, Habit, TrackingEntry } from './types';
import type { Id } from '../../../convex/_generated/dataModel';

interface UseHabitCalendarModalProps {
  habit: Habit | null;
  tracking: TrackingEntry[];
  toggleHabit: (args: { habitId: Id<'habits'>; date: string }) => void;
  onClose: () => void;
  onOpenMotivationTab?: () => void;
}

export function useHabitCalendarModal({
  habit,
  tracking,
  toggleHabit,
  onClose,
  onOpenMotivationTab,
}: UseHabitCalendarModalProps) {
  const [showEditScreen, setShowEditScreen] = useState(false);
  const [calendarView, setCalendarView] = useState<CalendarView>('month');

  const todayDateString = format(new Date(), 'yyyy-MM-dd');

  if (!habit) {
    return { isValid: false } as const;
  }

  const { emoji, name } = getEmojiAndName(habit.name);
  const scheduleLabel = buildScheduleLabel(habit);
  const habitTrackingEntries = tracking.filter((t) => t.habitId === habit._id);
  const habitTracking = habitTrackingEntries.map((t) => ({
    completed: t.completed,
    date: t.date,
  }));
  const todayTracking = habitTrackingEntries.find((t) => t.date === todayDateString);
  const isTodayCompleted = Boolean(todayTracking?.completed);
  const recentMissBadge = getLatestMissedBadge(habitTrackingEntries, todayDateString);
  const bestStreak = calculateBestStreak(habitTracking);
  const completionPercentage = calculateCompletionPercentage(
    habit.createdAt || Date.now(),
    habitTracking
  );

  const handleEditPress = () => setShowEditScreen(true);
  const handleCloseEdit = () => setShowEditScreen(false);
  const handleQuickLogPress = () => {
    if (isTodayCompleted) return;
    toggleHabit({ habitId: habit._id, date: todayDateString });
  };
  const handleOpenAdvancedFeatures = () => {
    setShowEditScreen(false);
    onClose();
    onOpenMotivationTab?.();
  };

  return {
    isValid: true,
    emoji,
    name,
    scheduleLabel,
    habitTrackingEntries,
    isTodayCompleted,
    recentMissBadge,
    bestStreak,
    completionPercentage,
    showEditScreen,
    calendarView,
    setCalendarView,
    handleEditPress,
    handleCloseEdit,
    handleQuickLogPress,
    handleOpenAdvancedFeatures,
  } as const;
}

import { format, parseISO } from 'date-fns';
import type { Habit, TrackingEntry } from './types';

const FREQUENCY_LABELS: Record<string, string> = {
  daily: 'Daily',
  weekly: 'Weekly',
  custom: 'Custom',
};

export function buildScheduleLabel(habit: Habit): string | undefined {
  const { frequency, reminderTime, preferredTime } = habit;
  const formattedFrequency = frequency
    ? FREQUENCY_LABELS[frequency] ||
      frequency
        .split('_')
        .map((segment) => segment.charAt(0).toUpperCase() + segment.slice(1))
        .join(' ')
    : undefined;
  const formattedTime =
    reminderTime ||
    (preferredTime ? preferredTime.charAt(0).toUpperCase() + preferredTime.slice(1) : undefined);

  if (formattedFrequency && formattedTime) {
    return `${formattedFrequency} · ${formattedTime}`;
  }

  return formattedFrequency || formattedTime;
}

export function getLatestMissedBadge(
  trackingEntries: TrackingEntry[],
  todayDate: string
): string | null {
  const previousMiss = trackingEntries
    .filter((entry) => !entry.completed && entry.date < todayDate)
    .sort((a, b) => (a.date < b.date ? 1 : -1))[0];

  if (!previousMiss) {
    return null;
  }

  return `Missed ${format(parseISO(previousMiss.date), 'EEE')}`;
}

import {
  startOfMonth,
  endOfMonth,
  eachDayOfInterval,
  addMonths,
  subMonths,
  parse,
  startOfDay,
  startOfToday,
  isBefore,
  isSameDay,
} from 'date-fns';
import { useCallback, useMemo, useState } from 'react';
import type { Id } from '../../../convex/_generated/dataModel';

export type HabitStatus = 'done' | 'missed' | 'planned' | 'upcoming';

interface UseHabitCalendarViewLogicProps {
  habitId: Id<'habits'>;
  tracking: Array<{ habitId: Id<'habits'>; date: string; completed: boolean }>;
}

export const useHabitCalendarViewLogic = ({
  habitId,
  tracking,
}: UseHabitCalendarViewLogicProps) => {
  const [currentMonth, setCurrentMonth] = useState(new Date());

  const trackingMap = useMemo(() => {
    const map = new Map<string, boolean>();
    for (const { habitId: entryHabitId, date, completed } of tracking) {
      if (entryHabitId === habitId) {
        map.set(date, completed);
      }
    }
    return map;
  }, [habitId, tracking]);

  const getHabitStatus = useCallback(
    (dateString: string): HabitStatus => {
      const parsedDate = startOfDay(
        parse(dateString, 'yyyy-MM-dd', new Date())
      );
      const today = startOfToday();
      const completion = trackingMap.get(dateString);

      if (completion) {
        return 'done';
      }

      if (isSameDay(parsedDate, today)) {
        return 'planned';
      }

      if (isBefore(parsedDate, today)) {
        return 'missed';
      }

      return 'upcoming';
    },
    [trackingMap]
  );

  const handlePreviousMonth = () => {
    setCurrentMonth((prev) => subMonths(prev, 1));
  };

  const handleNextMonth = () => {
    setCurrentMonth((prev) => addMonths(prev, 1));
  };

  const handleToday = () => {
    setCurrentMonth(new Date());
  };

  const { daysInMonth, emptyDays } = useMemo(() => {
    const monthStart = startOfMonth(currentMonth);
    const monthEnd = endOfMonth(currentMonth);
    const days = eachDayOfInterval({ end: monthEnd, start: monthStart });
    const firstDayOfWeek = monthStart.getDay();

    return {
      daysInMonth: days,
      emptyDays: Array.from({ length: firstDayOfWeek }, (_, i) => i),
    };
  }, [currentMonth]);

  return {
    currentMonth,
    daysInMonth,
    emptyDays,
    getHabitStatus,
    handleNextMonth,
    handlePreviousMonth,
    handleToday,
  };
};

