);

import React from 'react';
import { Animated } from 'react-native';
import type { DayConnectorProps } from './types';
import { getStrengthConfig } from './strengthConfig';
import { useDayConnectorAnimations } from './useDayConnectorAnimations';

/**
 * DayConnector - Visual link between consecutive completed days
 * Features strength-based evolution with shimmer effect for longer streaks.
 */
export const DayConnector: React.FC<DayConnectorProps> = ({
  accentColor,
  baseColor,
  currentStreak,
  style,
  visible,
}) => {
  const strengthConfig = getStrengthConfig(currentStreak);
  const connectorColor = strengthConfig.useAccent ? accentColor : baseColor;

  const { opacity, shimmerPosition } = useDayConnectorAnimations({
    shimmerSpeed: strengthConfig.shimmerSpeed,
    visible,
  });

  return (
    <Animated.View
      style={[
        {
          backgroundColor: connectorColor,
          borderRadius: strengthConfig.height / 2,
          height: strengthConfig.height,
          minWidth: 14,
          opacity: opacity.interpolate({
            inputRange: [0, 1],
            outputRange: [0, strengthConfig.maxOpacity],
          }),
          overflow: 'hidden',
        },
        strengthConfig.useAccent &&
          currentStreak >= 30 && {
            shadowColor: accentColor,
            shadowOffset: { height: 0, width: 0 },
            shadowOpacity: 0.4,
            shadowRadius: 3,
          },
        style,
      ]}
    >
      {strengthConfig.shimmerSpeed > 0 && (
        <Animated.View
          style={{
            backgroundColor: 'rgba(255, 255, 255, 0.4)',
            borderRadius: strengthConfig.height,
            height: '100%',
            position: 'absolute',
            transform: [
              {
                translateX: shimmerPosition.interpolate({
                  inputRange: [0, 1],
                  outputRange: [-20, 34],
                }),
              },
            ],
            width: 20,
          }}
        />
      )}
    </Animated.View>
  );
};

import React from 'react';
import { View } from 'react-native';
import { DayConnector } from './DayConnector';
import { ChainDayItem } from './ChainDayItem';
import { useChainVisualizerState } from './useChainVisualizerState';
import type { HabitChainVisualizerProps } from './types';

export const HabitChainVisualizer: React.FC<HabitChainVisualizerProps> = ({
  accentColor,
  celebrationsEnabled = true,
  completionIcon = 'chain',
  currentStreak = 0,
  habitId,
  highContrastMode = false,
  isConnectedToPreviousWeek = false,
  onToggle,
  onWeekComplete,
  reduceMotionPreference = false,
  shape = 'square',
  showConnectors = true,
  weekDateStrings,
  weekStatus,
}) => {
  const connectorColor = highContrastMode ? '#facc15' : '#e0e0e0';

  const {
    isCompleted,
    isFutureDate,
    isToday,
    activeBurst,
    setActiveBurst,
    shouldReduceMotion,
    todayLabel,
    dateLabels,
    handleToggleDay,
  } = useChainVisualizerState({
    celebrationsEnabled,
    habitId,
    onToggle,
    onWeekComplete,
    reduceMotionPreference,
    weekDateStrings,
    weekStatus,
  });

  const getAccessibilityLabel = (dateLabel: string, completed: boolean) =>
    dateLabel === todayLabel
      ? `Today, ${completed ? 'Completed' : 'Not completed'}`
      : `${dateLabel}: ${completed ? 'Completed' : 'Not completed'}`;

  return (
    <View className='flex-row items-center justify-between'>
      {showConnectors && isConnectedToPreviousWeek && isCompleted(0) && (
        <View
          style={{
            left: -10,
            marginTop: -1,
            position: 'absolute',
            top: '50%',
            zIndex: -1,
          }}
        >
          <DayConnector
            visible
            accentColor={accentColor}
            baseColor={connectorColor}
            currentStreak={currentStreak}
          />
        </View>
      )}

      {weekDateStrings.map((dateString, index) => {
        const completed = isCompleted(index);
        const disabled = isFutureDate(index);
        const isLastItem = index === weekDateStrings.length - 1;

        return (
          <ChainDayItem
            key={dateString}
            accentColor={accentColor}
            accessibilityHint={
              disabled
                ? 'Future dates are unavailable'
                : `Tap to toggle completion for ${dateLabels[index]}`
            }
            accessibilityLabel={getAccessibilityLabel(
              dateLabels[index],
              completed
            )}
            activeBurst={activeBurst}
            celebrationsEnabled={celebrationsEnabled}
            completed={completed}
            completionIcon={completionIcon}
            connectorColor={connectorColor}
            currentStreak={currentStreak}
            dateString={dateString}
            disabled={disabled}
            highContrastMode={highContrastMode}
            isToday={isToday(index)}
            shape={shape}
            shouldReduceMotion={shouldReduceMotion}
            showConnector={
              showConnectors &&
              !isLastItem &&
              completed &&
              isCompleted(index + 1)
            }
            onBurstComplete={() => setActiveBurst(null)}
            onPress={() =>
              handleToggleDay(dateString, completed, disabled, index)
            }
          />
        );
      })}
    </View>
  );
};

import React from 'react';
import { Animated, Pressable } from 'react-native';
import clsx from 'clsx';
import { ChainLinkIcon } from '../ChainLinkIcon/ChainLinkIcon';
import { Check } from 'lucide-react-native';
import type { HabitDayToggleProps } from './types';
import { useHabitDayToggleAnimations } from './useHabitDayToggleAnimations';
import { useHabitDayToggleHandlers } from './useHabitDayToggleHandlers';
import {
  getTodayGlowStyle,
  getCompletedShadowStyle,
  getBackgroundColor,
  getBorderColor,
} from './habitDayToggleStyles';

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

export const HabitDayToggle: React.FC<HabitDayToggleProps> = ({
  accentColor,
  accessibilityHint,
  accessibilityLabel,
  completionIcon,
  completed,
  disabled,
  highContrastMode,
  isToday,
  onPress,
  shape,
}) => {
  const { completion, buttonScale, combinedScale } =
    useHabitDayToggleAnimations({
      completed,
      isToday,
    });

  const { handlePressIn, handlePressOut, handlePress } =
    useHabitDayToggleHandlers({
      buttonScale,
      completed,
      onPress,
    });

  const isCircle = shape === 'circle';
  const borderRadius = isCircle ? 20 : 9;
  const backgroundColor = getBackgroundColor(
    completed,
    accentColor,
    highContrastMode
  );
  const borderColor = getBorderColor(
    completed,
    isToday,
    accentColor,
    highContrastMode
  );

  return (
    <Animated.View
      style={isToday ? getTodayGlowStyle(borderRadius) : undefined}
    >
      <AnimatedPressable
        accessibilityHint={accessibilityHint}
        accessibilityLabel={accessibilityLabel}
        accessibilityRole='button'
        accessibilityState={{ disabled }}
        className={clsx(
          'h-9 w-9 items-center justify-center',
          !completed && 'border-2'
        )}
        disabled={disabled}
        style={{
          backgroundColor,
          borderColor,
          borderRadius,
          borderWidth: completed ? 0 : 2,
          opacity: disabled ? 0.5 : 1,
          transform: [{ scale: combinedScale }],
          ...(completed &&
            !highContrastMode &&
            getCompletedShadowStyle(isToday, accentColor)),
        }}
        onPress={handlePress}
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
      >
        <Animated.View
          style={{
            opacity: completion,
            transform: [
              {
                scale: completion.interpolate({
                  inputRange: [0, 1],
                  outputRange: [0.5, 1],
                }),
              },
            ],
          }}
        >
          {completionIcon === 'checkbox' ? (
            <Check color='#ffffff' size={20} strokeWidth={2.25} />
          ) : (
            <ChainLinkIcon color='#ffffff' size={20} variant='stroke' />
          )}
        </Animated.View>
      </AnimatedPressable>
    </Animated.View>
  );
};

import { useMemo, useState } from 'react';
import { parse, format } from 'date-fns';
import type { Id } from '../../../convex/_generated/dataModel';
import { useHabitChainVisualizerLogic } from './HabitChainVisualizer.hooks';
import { useHapticFeedback } from '../../hooks/useHapticFeedback';
import { useToggleDayHandler } from './useToggleDayHandler';
import type { HabitStatus } from './types';

interface UseChainVisualizerStateParams {
  weekDateStrings: string[];
  weekStatus: HabitStatus[];
  celebrationsEnabled: boolean;
  reduceMotionPreference: boolean;
  habitId: Id<'habits'>;
  onToggle: (args: { habitId: Id<'habits'>; date: string }) => void;
  onWeekComplete?: (args: { completedDate: string }) => void;
}

export const useChainVisualizerState = ({
  weekDateStrings,
  weekStatus,
  celebrationsEnabled,
  reduceMotionPreference,
  habitId,
  onToggle,
  onWeekComplete,
}: UseChainVisualizerStateParams) => {
  const { isCompleted, isFutureDate, isToday } = useHabitChainVisualizerLogic(
    weekDateStrings,
    weekStatus
  );
  const [activeBurst, setActiveBurst] = useState<string | null>(null);

  const { triggerSelection, triggerSuccess } = useHapticFeedback({
    isEnabled: celebrationsEnabled,
    preference: reduceMotionPreference,
  });

  const shouldReduceMotion = useMemo(
    () => reduceMotionPreference || !celebrationsEnabled,
    [celebrationsEnabled, reduceMotionPreference]
  );

  const todayLabel = format(new Date(), 'MMM d, EEE').toUpperCase();

  const dateLabels = useMemo(
    () =>
      weekDateStrings.map((dateString) => {
        const parsedDate = parse(dateString, 'yyyy-MM-dd', new Date());
        return format(parsedDate, 'MMM d, EEE').toUpperCase();
      }),
    [weekDateStrings]
  );

  const handleToggleDay = useToggleDayHandler({
    celebrationsEnabled,
    habitId,
    onToggle,
    onWeekComplete,
    setActiveBurst,
    triggerSelection,
    triggerSuccess,
    weekStatus,
  });

  return {
    activeBurst,
    dateLabels,
    handleToggleDay,
    isCompleted,
    isFutureDate,
    isToday,
    setActiveBurst,
    shouldReduceMotion,
    todayLabel,
  };
};

import { useEffect, useMemo, useRef } from 'react';
import { Animated, Easing } from 'react-native';

interface UseHabitDayToggleAnimationsParams {
  completed: boolean;
  isToday: boolean;
}

export const useHabitDayToggleAnimations = ({
  completed,
  isToday,
}: UseHabitDayToggleAnimationsParams) => {
  const completion = useRef(new Animated.Value(completed ? 1 : 0)).current;
  const buttonScale = useRef(new Animated.Value(1)).current;
  const breathingPulse = useRef(new Animated.Value(1)).current;

  // Combine scale values using Animated.multiply
  const combinedScale = useMemo(
    () => Animated.multiply(buttonScale, breathingPulse),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    []
  );

  useEffect(() => {
    let animation: Animated.CompositeAnimation | null = null;

    animation = completed
      ? Animated.parallel([
          Animated.spring(buttonScale, {
            friction: 6,
            tension: 300,
            toValue: 1,
            useNativeDriver: true,
          }),
          Animated.timing(completion, {
            duration: 220,
            easing: Easing.out(Easing.cubic),
            toValue: 1,
            useNativeDriver: true,
          }),
        ])
      : Animated.timing(completion, {
          duration: 150,
          easing: Easing.in(Easing.ease),
          toValue: 0,
          useNativeDriver: true,
        });

    animation.start();

    return () => {
      animation?.stop();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [completed]);

  useEffect(() => {
    if (!completed && isToday) {
      const breathingAnimation = Animated.loop(
        Animated.sequence([
          Animated.timing(breathingPulse, {
            duration: 1500,
            easing: Easing.inOut(Easing.ease),
            toValue: 1.03,
            useNativeDriver: true,
          }),
          Animated.timing(breathingPulse, {
            duration: 1500,
            easing: Easing.inOut(Easing.ease),
            toValue: 1,
            useNativeDriver: true,
          }),
        ])
      );
      breathingAnimation.start();

      return () => {
        breathingAnimation.stop();
      };
    } else {
      breathingPulse.setValue(1);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [completed, isToday]);

  return { buttonScale, combinedScale, completion };
};

import { useCallback, useRef } from 'react';
import type { Id } from '../../../convex/_generated/dataModel';
import type { HabitStatus } from './types';

interface UseToggleDayHandlerParams {
  weekStatus: HabitStatus[];
  celebrationsEnabled: boolean;
  habitId: Id<'habits'>;
  onToggle: (args: { habitId: Id<'habits'>; date: string }) => void;
  onWeekComplete?: (args: { completedDate: string }) => void;
  triggerSelection: () => void;
  triggerSuccess: () => void;
  setActiveBurst: (dateString: string | null) => void;
}

export const useToggleDayHandler = ({
  weekStatus,
  celebrationsEnabled,
  habitId,
  onToggle,
  onWeekComplete,
  triggerSelection,
  triggerSuccess,
  setActiveBurst,
}: UseToggleDayHandlerParams) => {
  const weekStatusRef = useRef(weekStatus);
  weekStatusRef.current = weekStatus;

  const handleToggleDay = useCallback(
    (
      dateString: string,
      completed: boolean,
      disabled: boolean,
      index: number
    ) => {
      if (disabled) {
        triggerSelection();
        return;
      }

      const isTogglingToComplete = !completed;
      const currentWeekStatus = weekStatusRef.current;
      const willCompleteWeek =
        isTogglingToComplete &&
        currentWeekStatus.every((status, i) =>
          i === index ? true : status === 'done'
        );

      if (completed || !celebrationsEnabled) {
        triggerSelection();
      } else {
        triggerSuccess();
        if (willCompleteWeek) {
          setActiveBurst(dateString);
        }
      }

      onToggle({ date: dateString, habitId });

      if (willCompleteWeek) {
        onWeekComplete?.({ completedDate: dateString });
      }
    },
    [
      celebrationsEnabled,
      habitId,
      onToggle,
      onWeekComplete,
      triggerSelection,
      triggerSuccess,
      setActiveBurst,
    ]
  );

  return handleToggleDay;
};

/**
 * HabitDetailTabs Component
 *
 * Tab bar navigation for the Habit Detail screen.
 * Uses a pill/segment control style with smooth sliding animation.
 */

import React, { useCallback, useEffect } from 'react';
import { View, LayoutChangeEvent } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  useDerivedValue,
} from 'react-native-reanimated';
import * as Haptics from 'expo-haptics';

import type { TabType, HabitDetailTabsProps } from './HabitDetailTabs.types';
import {
  TABS,
  PILL_SPRING_CONFIG,
  CONTAINER_PADDING,
  TAB_GAP,
} from './HabitDetailTabs.constants';
import { TabButton } from './components/TabButton';

export function HabitDetailTabs({
  activeTab,
  onTabChange,
}: HabitDetailTabsProps) {
  const containerWidth = useSharedValue(0);
  const indicatorPosition = useSharedValue(
    TABS.findIndex((t) => t.id === activeTab)
  );

  const pillWidth = useDerivedValue(() => {
    if (containerWidth.value === 0) return 0;
    const availableWidth =
      containerWidth.value -
      CONTAINER_PADDING * 2 -
      TAB_GAP * (TABS.length - 1);
    return availableWidth / TABS.length;
  });

  const handleLayout = useCallback(
    (event: LayoutChangeEvent) => {
      containerWidth.value = event.nativeEvent.layout.width;
    },
    [containerWidth]
  );

  useEffect(() => {
    const index = TABS.findIndex((t) => t.id === activeTab);
    indicatorPosition.value = withSpring(index, PILL_SPRING_CONFIG);
  }, [activeTab, indicatorPosition]);

  const pillStyle = useAnimatedStyle(() => {
    const width = pillWidth.value;
    if (width === 0) return { opacity: 0 };
    const leftOffset =
      CONTAINER_PADDING + indicatorPosition.value * (width + TAB_GAP);
    return { left: leftOffset, opacity: 1, width };
  });

  const handleTabPress = useCallback(
    (tab: TabType) => {
      if (tab !== activeTab) {
        Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
        onTabChange(tab);
      }
    },
    [activeTab, onTabChange]
  );

  return (
    <View
      accessibilityRole='tablist'
      className='mx-4 my-3'
      onLayout={handleLayout}
    >
      <View className='relative rounded-xl bg-stone-100 p-1'>
        <Animated.View
          className='absolute bottom-1 top-1 rounded-lg bg-violet-600 shadow-sm'
          style={pillStyle}
        />
        <View className='flex-row' style={{ gap: TAB_GAP }}>
          {TABS.map((tab) => (
            <TabButton
              key={tab.id}
              isActive={activeTab === tab.id}
              label={tab.label}
              onPress={() => handleTabPress(tab.id)}
            />
          ))}
        </View>
      </View>
    </View>
  );
}

export default HabitDetailTabs;

/**
 * TabContent Component
 * Manages tab content with scroll position preservation and animations
 */

import React, { useRef } from 'react';
import { View, ScrollView } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withTiming,
  Easing,
} from 'react-native-reanimated';

import type {
  TabType,
  TabContentProps,
  TabSectionProps,
  TabPaneProps,
} from './HabitDetailTabs.types';

const AnimatedView = Animated.View;

function TabPane({ children, isActive, tabId }: TabPaneProps) {
  const scrollRef = useRef<ScrollView>(null);
  const scrollPosition = useRef(0);

  const opacity = useSharedValue(isActive ? 1 : 0);
  const translateY = useSharedValue(isActive ? 0 : 10);

  React.useEffect(() => {
    if (isActive) {
      opacity.value = withTiming(1, {
        duration: 200,
        easing: Easing.out(Easing.cubic),
      });
      translateY.value = withTiming(0, {
        duration: 200,
        easing: Easing.out(Easing.cubic),
      });
    } else {
      opacity.value = 0;
      translateY.value = 10;
    }
  }, [isActive, opacity, translateY]);

  const animatedStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [{ translateY: translateY.value }],
  }));

  if (!isActive) {
    return null;
  }

  return (
    <AnimatedView
      accessible
      accessibilityLabel={`${tabId} tab content`}
      className='flex-1'
      style={animatedStyle}
    >
      {children}
    </AnimatedView>
  );
}

export function TabContent({ activeTab, children }: TabContentProps) {
  const childArray = React.Children.toArray(children);

  return (
    <View className='flex-1'>
      {childArray.map((child) => {
        if (!React.isValidElement<TabSectionProps>(child)) return null;

        const tabId = child.props.tabId;
        const isActive = tabId === activeTab;

        return (
          <TabPane key={tabId} isActive={isActive} tabId={tabId}>
            {child}
          </TabPane>
        );
      })}
    </View>
  );
}

export function TabSection({ children }: TabSectionProps) {
  return <>{children}</>;
}

export default TabContent;

