          {value}
        </Text>
        <Text className='text-xs text-stone-500' numberOfLines={1}>
          {label}
        </Text>
      </View>
    </Animated.View>
  );
}

// WCAG AA compliant colors (4.5:1 minimum contrast ratio)
const DELTA_COLORS = {
  positive: '#047857', // Emerald-700 (WCAG AA: 5.48:1)
  negative: '#dc2626', // Red-600 (WCAG AA: 4.83:1)
  neutral: '#78716c', // Stone-500 (WCAG AA: 4.80:1)
} as const;

/**
 * Get the appropriate icon for the delta value
 */
function getDeltaIcon(delta: number): React.ReactNode {
  const size = 18;

  if (delta > 0) {
    return (
      <TrendingUp
        color={DELTA_COLORS.positive}
        size={size}
        testID='icon-trending-up'
      />
    );
  } else if (delta < 0) {
    return (
      <TrendingDown
        color={DELTA_COLORS.negative}
        size={size}
        testID='icon-trending-down'
      />
    );
  }
  return <Minus color={DELTA_COLORS.neutral} size={size} testID='icon-minus' />;
}

/**
 * Get the color for the delta value text
 */
function getDeltaColor(delta: number): string {
  if (delta > 0) return DELTA_COLORS.positive;
  if (delta < 0) return DELTA_COLORS.negative;
  return DELTA_COLORS.neutral;
}

/**
 * Format the delta value with sign and percentage
 */
function formatDelta(delta: number): string {
  if (delta > 0) {
    return `+${delta.toFixed(0)}%`;
  } else if (delta < 0) {
    return `${delta.toFixed(0)}%`;
  }
  return '0%';
}

/**
 * StrengthInsightsRow - Three-column metrics layout
 */
export function StrengthInsightsRow({
  deltaVsMonth,
  peak,
  lowest,
}: StrengthInsightsRowProps) {
  return (
    <View
      accessible
      accessibilityLabel='Habit strength insights and statistics'
      accessibilityRole='none'
      className='flex-row gap-2'
    >
      {/* Delta vs Month Card */}
      <InsightCard
        accessibilityLabel={`${deltaVsMonth >= 0 ? 'Improved' : 'Declined'} ${Math.abs(deltaVsMonth).toFixed(0)} percent compared to last month`}
        animationDelay={ANIMATION_DELAY_BASE}
        icon={getDeltaIcon(deltaVsMonth)}
        label='vs Month'
        value={formatDelta(deltaVsMonth)}
        valueColor={getDeltaColor(deltaVsMonth)}
      />

      {/* Peak Card */}
      <InsightCard
        accessibilityLabel={`Peak strength: ${Math.round(peak)} percent`}
        animationDelay={ANIMATION_DELAY_BASE + 100}
        icon={<Trophy color='#f59e0b' size={18} testID='icon-trophy' />}
        label='Peak'
        value={`${Math.round(peak)}%`}
      />

      {/* Lowest Card */}
      <InsightCard
        accessibilityLabel={`Lowest strength: ${Math.round(lowest)} percent`}
        animationDelay={ANIMATION_DELAY_BASE + 200}
        icon={<BarChart3 color='#6b7280' size={18} testID='icon-chart' />}
        label='Lowest'
        value={`${Math.round(lowest)}%`}
      />
    </View>
  );
}

export default StrengthInsightsRow;

/**
 * StrengthTimelineChart Component - SVG area chart for habit strength evolution
 */

import React, { useMemo } from 'react';
import Animated, { FadeIn } from 'react-native-reanimated';

import { getStrengthColor } from '../strengthUtils';
import {
  DEFAULT_HEIGHT,
  DEFAULT_CHART_COLOR,
  MIN_HISTORY_LENGTH,
  PATH_ANIMATION_DURATION,
} from './constants';
import { generateChartPaths } from './pathUtils';
import { generateXAxisLabels, calculateTrendDescription } from './axisUtils';
import { useChartDimensions } from './useChartDimensions';
import { usePathAnimation } from './usePathAnimation';
import { usePulseAnimation } from './usePulseAnimation';
import { ChartSvg } from './ChartSvg';
import { XAxisLabels } from './XAxisLabels';
import { NoDataState, BuildingHistoryState } from './EmptyStates';
import type { StrengthTimelineChartProps } from './types';

export function StrengthTimelineChart({
  strengthHistory,
  habitColor,
  height = DEFAULT_HEIGHT,
}: StrengthTimelineChartProps) {
  const dimensions = useChartDimensions(height);

  const chartColor = useMemo(() => {
    if (habitColor) return habitColor;
    if (strengthHistory.length > 0)
      return getStrengthColor(strengthHistory.at(-1)!.strength);
    return DEFAULT_CHART_COLOR;
  }, [habitColor, strengthHistory]);

  const { areaPath, linePath, lastPoint } = useMemo(
    () => generateChartPaths(strengthHistory, dimensions),
    [strengthHistory, dimensions]
  );

  const xAxisLabels = useMemo(
    () => generateXAxisLabels(strengthHistory.length, dimensions),
    [strengthHistory.length, dimensions]
  );

  const { animatedLineProps } = usePathAnimation({
    historyLength: strengthHistory.length,
  });
  const { pulsingRingProps } = usePulseAnimation({ lastPoint });
  const trendDescription = useMemo(
    () => calculateTrendDescription(strengthHistory),
    [strengthHistory]
  );

  if (strengthHistory.length === 0) return <NoDataState height={height} />;
  if (strengthHistory.length < MIN_HISTORY_LENGTH)
    return <BuildingHistoryState height={height} />;

  return (
    <Animated.View
      accessible
      accessibilityLabel={`Strength timeline chart showing ${strengthHistory.length} days of history. ${trendDescription}`}
      accessibilityRole='image'
      className='overflow-hidden rounded-xl bg-stone-50'
      entering={FadeIn.duration(PATH_ANIMATION_DURATION)}
    >
      <ChartSvg
        animatedLineProps={animatedLineProps}
        areaPath={areaPath}
        chartColor={chartColor}
        dimensions={dimensions}
        lastPoint={lastPoint}
        linePath={linePath}
        pulsingRingProps={pulsingRingProps}
      />
      <XAxisLabels labels={xAxisLabels} />
    </Animated.View>
  );
}

export default StrengthTimelineChart;

/**
 * Full Variant (for habit detail view)
 * Shows header with emoji, label, percentage, progress bar, and description
 */

import React from 'react';
