/**
 * HabitStrengthSection Component (Redesigned)
 *
 * Comprehensive habit strength display combining:
 * - Time range switcher (1M/1Y/All)
 * - Circular progress ring (72x72px) with animated fill
 * - Full-width timeline chart with bezier curves
 * - Comparison stats row
 *
 * @see habit-strength-redesign-spec.md for design details
 *
 * @example
 * ```tsx
 * <HabitStrengthSection
 *   habitId={habit._id}
 *   completedDates={completedDates}
 *   habitCreatedAt={habit.createdAt}
 *   habitColor={habit.iconColor}
 * />
 * ```
 */

import React, { useMemo, useState } from 'react';
import { Text, View } from 'react-native';

import Animated, { FadeInDown } from 'react-native-reanimated';

import { useHabitStrength } from '../../hooks/useHabitStrength';
import { getStrengthLabel } from '../HabitStrengthHistory/strengthUtils';
import { COLORS } from './constants';
import { StrengthChart } from './StrengthChart';
import { StrengthHero } from './StrengthHero';
import { TimeRangeToggle } from './TimeRangeToggle';
import type { HabitStrengthSectionProps, TimeRange } from './types';
import { calculateExtendedMetrics, generateChartDataFromCompletions, sampleHistoryForChart } from './utils';

/**
 * Main HabitStrengthSection component.
 *
 * Composes TimeRangeToggle, StrengthHero, StrengthChart, and StrengthStatsRow
 * into a cohesive card with shadow and rounded corners.
 */
export const HabitStrengthSection = React.memo(function HabitStrengthSection({
  habitId: _habitId,
  completedDates,
  habitCreatedAt,
  habitColor,
  habitStrength,
}: HabitStrengthSectionProps) {
  // Time range state (default to 1 year)
  const [timeRange, setTimeRange] = useState<TimeRange>('1y');

  // Get strength data from existing hook (for history and metrics)
  const { currentStrength: calculatedStrength, strengthHistory, metrics, isCalculating } =
    useHabitStrength(completedDates, habitCreatedAt);

  // Use database strength if provided (converted from 0-1 to 0-100), otherwise use calculated
  // This ensures consistency with HabitCard which uses habit.strength
  const currentStrength =
    habitStrength !== undefined ? Math.round(habitStrength * 100) : calculatedStrength;

  // Calculate extended metrics with time range filtering
  const extendedMetrics = useMemo(() => {
    return calculateExtendedMetrics(
      completedDates,
      habitCreatedAt,
      currentStrength,
      metrics.deltaVsMonth,
      strengthHistory,
      timeRange
    );
  }, [
    completedDates,
    habitCreatedAt,
    currentStrength,
    metrics.deltaVsMonth,
    strengthHistory,
    timeRange,
  ]);

  // Generate chart data directly from completedDates (bypasses broken strengthHistory)
  const chartData = useMemo(() => {
    const rawChartData = generateChartDataFromCompletions(completedDates, timeRange);
    return sampleHistoryForChart(rawChartData, 50);
  }, [completedDates, timeRange]);

  // Get strength label for display
  const strengthLabel = getStrengthLabel(currentStrength);

  // Handle loading state
  if (isCalculating) {
    return (
      <View className="rounded-2xl bg-white p-5 shadow-sm">
        <View className="h-48 items-center justify-center">
          <Text className="text-stone-400">Calculating strength...</Text>
        </View>
      </View>
    );
  }

  // Handle empty state (no completions)
  if (completedDates.size === 0) {
    return (
      <View className="rounded-2xl bg-white p-5 shadow-sm">
        <Text className="mb-2 text-lg font-bold text-stone-800">
          Habit Strength
        </Text>
        <View className="items-center justify-center py-8">
          <Text className="mb-2 text-4xl">🌱</Text>
          <Text className="text-center text-stone-500">
            Complete your first day to start building strength!
          </Text>
        </View>
      </View>
    );
  }

  return (
    <Animated.View
      className="overflow-hidden rounded-2xl bg-white shadow-sm"
      entering={FadeInDown.delay(100).springify()}
      style={{
        shadowColor: COLORS.textPrimary,
        shadowOffset: { width: 0, height: 2 },
        shadowOpacity: 0.05,
        shadowRadius: 8,
        elevation: 2,
      }}
    >
      {/* Compact padding (p-4 instead of p-5) for above-fold layout */}
      <View className="p-4">
        {/* Header with Time Range Switcher */}
        <View className="mb-3 flex-row items-center justify-between">
          <Text className="text-base font-bold text-stone-800">
            Habit Strength
          </Text>
          <TimeRangeToggle value={timeRange} onChange={setTimeRange} />
        </View>

        {/* Hero Section - Ring + Status */}
        <View className="mb-3">
          <StrengthHero
            strength={currentStrength}
            label={strengthLabel}
            delta={extendedMetrics.deltaVsMonth}
            deltaLabel="vs last month"
            color={habitColor}
          />
        </View>

        {/* Full-Width Chart - compact margins */}
        <View className="mb-3 -mx-4">
          <StrengthChart
            data={chartData}
            timeRange={timeRange}
            currentStrength={currentStrength}
            color={habitColor}
          />
        </View>

      </View>
    </Animated.View>
  );
});

export default HabitStrengthSection;

/**
 * StrengthChart - Full-width timeline chart with smooth bezier curve,
 * gradient fill, grid lines, X-axis labels, and a pulsing dot.
 */
import React, { useEffect, useMemo, useState } from 'react';
import { AccessibilityInfo, LayoutChangeEvent, View } from 'react-native';

import Svg from 'react-native-svg';

import {
  CHART_HEIGHT,
  CHART_PADDING_BOTTOM,
  CHART_PADDING_X,
  STRENGTH_COLORS,
} from '../constants';
import type { StrengthChartProps } from '../types';

import { ChartCurve } from './ChartCurve';
import { ChartGrid } from './ChartGrid';
import { EmptyState } from './EmptyState';
import { PulsingDot } from './PulsingDot';
import {
  getStrengthLabel,
  getXAxisLabelsFromData,
} from './StrengthChart.utils';
import { useChartData } from './useChartData';
import { useChartGridLines } from './useChartGridLines';
import { useStrengthChartAnimations } from './useStrengthChartAnimations';
import { XAxisLabels } from './XAxisLabels';

export const StrengthChart = React.memo(function StrengthChart({
  data,
  currentStrength,
  color,
}: StrengthChartProps) {
  const [chartWidth, setChartWidth] = useState(300);
  const [reduceMotion, setReduceMotion] = useState(false);

  const strengthLabel = getStrengthLabel(currentStrength);
  const chartColor = color || STRENGTH_COLORS[strengthLabel].primary;

  useEffect(() => {
    void AccessibilityInfo.isReduceMotionEnabled().then(setReduceMotion);
  }, []);

  const handleLayout = (event: LayoutChangeEvent) => {
    setChartWidth(event.nativeEvent.layout.width);
  };

  const { lastPoint, pathD, fillPathD, pathLength } = useChartData({
    chartWidth,
    data,
  });
  const gridLines = useChartGridLines();
  const { animatedPathProps, animatedDotProps } = useStrengthChartAnimations({
    dataLength: data.length,
    pathLength,
    reduceMotion,
  });

  const xAxisLabels = useMemo(() => getXAxisLabelsFromData(data), [data]);
  const accessibilityLabel = useMemo(() => {
    if (data.length < 2) return 'No strength history available';
    const startStrength = Math.round(data[0].strength);
    const endStrength = Math.round(data.at(-1).strength);
    const trend = endStrength > startStrength ? 'upward' : 'downward';
    return `Strength chart showing ${trend} trend from ${startStrength}% to ${endStrength}%`;
  }, [data]);

  if (data.length < 2) return <EmptyState />;

  return (
    <View
      accessibilityLabel={accessibilityLabel}
      accessibilityRole='image'
      onLayout={handleLayout}
    >
      <Svg height={CHART_HEIGHT} width={chartWidth}>
        <ChartGrid
          chartWidth={chartWidth}
          gridLines={gridLines}
          paddingX={CHART_PADDING_X}
        />
        <ChartCurve
          animatedPathProps={animatedPathProps}
          chartColor={chartColor}
          fillPathD={fillPathD}
          pathD={pathD}
          pathLength={pathLength}
        />
        <PulsingDot
          animatedDotProps={animatedDotProps}
          color={chartColor}
          cx={lastPoint.x}
          cy={lastPoint.y}
        />
      </Svg>
      <XAxisLabels height={CHART_PADDING_BOTTOM} labels={xAxisLabels} />
    </View>
  );
});

/**
 * ProgressRing Component
 *
 * Circular SVG progress ring with animated fill.
 */

import React from 'react';
import { View } from 'react-native';

import Animated, { useAnimatedProps } from 'react-native-reanimated';
import Svg, { Circle } from 'react-native-svg';

import {
  COLORS,
  RING_CIRCUMFERENCE,
  RING_RADIUS,
  RING_SIZE,
  RING_STROKE_WIDTH,
  STRENGTH_LABELS,
} from '../constants';
import { AnimatedPercentage } from './AnimatedPercentage';
import type { ProgressRingProps } from './types';

const AnimatedCircle = Animated.createAnimatedComponent(Circle);

/**
 * Displays a circular progress ring with animated percentage.
 */
export function ProgressRing({
  roundedStrength,
  ringColor,
  animatedStrength,
}: ProgressRingProps) {
  const center = RING_SIZE / 2;

  // Animated props for the progress circle
  const animatedCircleProps = useAnimatedProps(() => {
    const progress = animatedStrength.value / 100;
    return {
      strokeDashoffset: RING_CIRCUMFERENCE * (1 - progress),
    };
  });

  return (
    <View
      accessibilityLabel={`Habit strength ${roundedStrength}%, ${STRENGTH_LABELS.strong}`}
      accessibilityRole='progressbar'
      accessibilityValue={{ max: 100, min: 0, now: roundedStrength }}
      style={{ height: RING_SIZE, width: RING_SIZE }}
    >
      <Svg height={RING_SIZE} width={RING_SIZE}>
        {/* Background track */}
        <Circle
          cx={center}
          cy={center}
          fill='none'
          r={RING_RADIUS}
          stroke={COLORS.ringTrack}
          strokeWidth={RING_STROKE_WIDTH}
        />
        {/* Progress arc */}
        <AnimatedCircle
          animatedProps={animatedCircleProps}
          cx={center}
          cy={center}
          fill='none'
          origin={`${center}, ${center}`}
          r={RING_RADIUS}
          rotation='-90'
          stroke={ringColor}
          strokeDasharray={RING_CIRCUMFERENCE}
          strokeDashoffset={RING_CIRCUMFERENCE}
          strokeLinecap='round'
          strokeWidth={RING_STROKE_WIDTH}
        />
      </Svg>

      {/* Center content */}
      <View
        accessibilityElementsHidden
        className='absolute inset-0 items-center justify-center'
      >
        <AnimatedPercentage animatedValue={animatedStrength} />
      </View>
    </View>
  );
}

/**
 * StrengthStatsRow Component
 *
 * Three-column layout displaying comparison metrics:
 * - Since Start: Total growth since habit creation
 * - Last Month: Month-over-month change
 * - Last Week: Week-over-week change
 *
 * Positive changes are highlighted in emerald.
 *
 * @example
 * ```tsx
 * <StrengthStatsRow
 *   sinceStart={72}
 *   lastMonth={12}
 *   lastWeek={3}
 * />
 * ```
 */

import React from 'react';
import { Text, View } from 'react-native';

import { COLORS } from './constants';
import type { StrengthStatsRowProps } from './types';

/**
 * Format a delta value for display with + or - prefix.
 */
function formatDelta(value: number): string {
  if (value === 0) return '0%';
  return value > 0 ? `+${value}%` : `${value}%`;
}

/**
 * Single stat column component (compact version for above-fold layout).
 */
function StatColumn({
  label,
  value,
  isPositive,
}: {
  label: string;
  value: string;
  isPositive: boolean;
}) {
  return (
    <View className="flex-1 items-center">
      {/* Smaller label text for compact layout */}
      <Text className="text-[10px] text-stone-400">{label}</Text>
      <Text
        className="text-sm font-semibold"
        style={{
          color: isPositive ? COLORS.positive : COLORS.textPrimary,
        }}
      >
        {value}
      </Text>
    </View>
  );
}

/**
 * Vertical divider between stat columns (compact height).
 */
function Divider() {
  return (
    <View
      className="h-6 w-px"
      style={{ backgroundColor: COLORS.border }}
    />
  );
}

/**
 * StrengthStatsRow displays three comparison metrics in a row (compact version).
 */
export const StrengthStatsRow = React.memo(function StrengthStatsRow({
  sinceStart,
  lastMonth,
  lastWeek,
}: StrengthStatsRowProps) {
  return (
    <View
      className="flex-row items-center justify-between rounded-lg bg-stone-50 px-3 py-2"
      accessibilityLabel={`Statistics: ${sinceStart}% since start, ${formatDelta(lastMonth)} last month, ${formatDelta(lastWeek)} last week`}
    >
      <StatColumn
        label="Since Start"
        value={`${sinceStart}%`}
        isPositive={sinceStart > 0}
      />

      <Divider />

      <StatColumn
        label="Last Month"
        value={formatDelta(lastMonth)}
        isPositive={lastMonth > 0}
      />

      <Divider />

      <StatColumn
        label="Last Week"
        value={formatDelta(lastWeek)}
        isPositive={lastWeek > 0}
      />
    </View>
  );
});

