/**
 * HapticTest Component
 *
 * Diagnostic tool to test expo-haptics functionality on physical device.
 * This isolates haptic testing from gesture handlers to identify issues.
 */

import React, { useState } from 'react';
import { View, StyleSheet, ScrollView, Platform } from 'react-native';
import { Button, Text, Surface } from 'react-native-paper';
import * as Haptics from 'expo-haptics';
import { useAppTheme } from '../theme';

export function HapticTest() {
  const theme = useAppTheme();
  const [lastResult, setLastResult] = useState<string>(
    'Tap any button to test'
  );
  const [testCount, setTestCount] = useState(0);

  const testHaptic = async (name: string, hapticFn: () => Promise<void>) => {
    const timestamp = new Date().toLocaleTimeString();
    console.log(`🔵 [${timestamp}] Testing: ${name}`);
    console.log('🔵 Platform:', Platform.OS);
    console.log('🔵 Device:', Platform.Version);

    try {
      await hapticFn();
      const successMsg = `✅ ${name} - Success at ${timestamp}`;
      console.log(successMsg);
      setLastResult(successMsg);
      setTestCount((prev) => prev + 1);
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      const errorMsg = `❌ ${name} - FAILED: ${errorMessage}`;
      console.error(errorMsg);
      setLastResult(errorMsg);
    }
  };

  return (
    <ScrollView
      contentContainerStyle={styles.contentContainer}
      style={[
        styles.container,
        { backgroundColor: theme.custom.colors.light.background },
      ]}
    >
      <Surface elevation={1} style={styles.surface}>
        <Text style={styles.title} variant='headlineMedium'>
          Haptic Feedback Test
        </Text>

        <Text style={styles.subtitle} variant='bodyMedium'>
          🚨 Physical Device Only - Simulators don't support haptics
        </Text>

        <View style={styles.statusBox}>
          <Text style={styles.statusLabel} variant='labelLarge'>
            Last Result:
          </Text>
          <Text style={styles.statusText} variant='bodyMedium'>
            {lastResult}
          </Text>
          <Text style={styles.counter} variant='bodySmall'>
            Tests run: {testCount}
          </Text>
        </View>

        <Text style={styles.sectionTitle} variant='titleMedium'>
          Impact Feedback
        </Text>

        <Button
          mode='contained'
          style={styles.button}
          onPress={() =>
            testHaptic('Light Impact', () =>
              Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light)
            )
          }
        >
          Test Light Impact
        </Button>

        <Button
          mode='contained'
          style={styles.button}
          onPress={() =>
            testHaptic('Medium Impact', () =>
              Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium)
            )
          }
        >
          Test Medium Impact
        </Button>

        <Button
          mode='contained'
          style={styles.button}
          onPress={() =>
            testHaptic('Heavy Impact', () =>
              Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Heavy)
            )
          }
        >
          Test Heavy Impact
        </Button>

        <Text style={styles.sectionTitle} variant='titleMedium'>
          Selection Feedback
        </Text>

        <Button
          mode='contained'
          style={styles.button}
          onPress={() =>
            testHaptic('Selection', () => Haptics.selectionAsync())
          }
        >
          Test Selection
        </Button>

        <Text style={styles.sectionTitle} variant='titleMedium'>
          Notification Feedback
        </Text>

        <Button
          mode='contained'
          style={styles.button}
          onPress={() =>
            testHaptic('Success Notification', () =>
              Haptics.notificationAsync(
                Haptics.NotificationFeedbackType.Success
              )
            )
          }
        >
          Test Success Notification
        </Button>

        <Button
          mode='contained'
          style={styles.button}
          onPress={() =>
            testHaptic('Warning Notification', () =>
              Haptics.notificationAsync(
                Haptics.NotificationFeedbackType.Warning
              )
            )
          }
        >
          Test Warning Notification
        </Button>

        <Button
          mode='contained'
          style={styles.button}
          onPress={() =>
            testHaptic('Error Notification', () =>
              Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error)
            )
          }
        >
          Test Error Notification
        </Button>

        <Text style={styles.sectionTitle} variant='titleMedium'>
          Rapid Fire Test
        </Text>

        <Button
          mode='outlined'
          style={styles.button}
          onPress={async () => {
            console.log('🔥 Starting rapid fire test...');
            for (let i = 0; i < 5; i++) {
              await testHaptic(`Rapid ${i + 1}`, () =>
                Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light)
              );
              await new Promise((resolve) => setTimeout(resolve, 200));
            }
            console.log('🔥 Rapid fire test complete');
          }}
        >
          Rapid Fire (5x Light)
        </Button>

        <View style={styles.infoBox}>
          <Text style={styles.infoText} variant='bodySmall'>
            ℹ️ Check console logs for detailed output
          </Text>
          <Text style={styles.infoText} variant='bodySmall'>
            ℹ️ Platform: {Platform.OS} {Platform.Version}
          </Text>
          <Text style={styles.infoText} variant='bodySmall'>
            ℹ️ expo-haptics version: 15.0.7
          </Text>
        </View>
      </Surface>
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  button: {
    marginVertical: 6,
  },
  container: {
    flex: 1,
  },
  contentContainer: {
    padding: 16,
  },
  counter: {
    opacity: 0.6,
  },
  infoBox: {
    backgroundColor: '#e3f2fd',
    borderRadius: 8,
    marginTop: 24,
    padding: 12,
  },
  infoText: {
    marginVertical: 2,
    opacity: 0.8,
  },
  sectionTitle: {
    fontWeight: 'bold',
    marginBottom: 12,
    marginTop: 24,
  },
  statusBox: {
    backgroundColor: '#f5f5f5',
    borderRadius: 8,
    marginBottom: 16,
    padding: 16,
  },
  statusLabel: {
    fontWeight: 'bold',
    marginBottom: 4,
  },
  subtitle: {
    marginBottom: 20,
    opacity: 0.7,
    textAlign: 'center',
  },
  statusText: {
    marginBottom: 8,
  },
  surface: {
    borderRadius: 12,
    padding: 20,
  },
  title: {
    marginBottom: 8,
    textAlign: 'center',
  },
});

export default HapticTest;

/**
 * HeaderCompleteToggle Component
 * Compact completion toggle for habit detail header
 *
 * Features:
 * - Small pill design: "✓ Done" when complete, "○ Mark Done" when incomplete
 * - Haptic feedback on toggle
 * - Confetti animation on completion (respects reduce motion)
 */

import React from 'react';
import { Pressable, Text, View } from 'react-native';
import Animated, { useAnimatedStyle } from 'react-native-reanimated';
import { Check, Circle } from 'lucide-react-native';
import { MiniConfettiBurst } from './MiniConfettiBurst';
import { useHeaderToggle } from './useHeaderToggle';
import { styles } from './styles';
import type { HeaderCompleteToggleProps } from './types';

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

export function HeaderCompleteToggle({
  completedToday,
  habitId,
  habitName,
  onComplete,
  onUncomplete,
}: HeaderCompleteToggleProps) {
  const { isToggling, localCompleted, showConfetti, buttonScale, handlePress } =
    useHeaderToggle({
      completedToday,
      habitId,
      onComplete,
      onUncomplete,
    });

  const buttonAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: buttonScale.value }],
  }));

  return (
    <View style={styles.wrapper}>
      <MiniConfettiBurst isActive={showConfetti} />

      <AnimatedPressable
        accessibilityHint={
          localCompleted
            ? 'Double tap to mark as not complete'
            : 'Double tap to mark as complete'
        }
        accessibilityLabel={
          localCompleted
            ? `${habitName} completed today. Tap to undo.`
            : `Mark ${habitName} complete for today`
        }
        accessibilityRole='button'
        accessibilityState={{ checked: localCompleted }}
        className={`flex-row items-center gap-1.5 rounded-full px-3 py-1.5 ${
          localCompleted
            ? 'bg-emerald-500 shadow-sm'
            : 'border-2 border-emerald-400 bg-emerald-50'
        } `}
        disabled={isToggling}
        style={buttonAnimatedStyle}
        onPress={handlePress}
      >
        {localCompleted ? (
          <>
            <Check className='text-white' size={14} strokeWidth={3} />
            <Text className='text-xs font-semibold text-white'>Done</Text>
          </>
        ) : (
          <>
            <Circle className='text-emerald-500' size={14} strokeWidth={2} />
            <Text className='text-xs font-semibold text-emerald-600'>
              Mark Done
            </Text>
          </>
        )}
      </AnimatedPressable>
    </View>
  );
}

export default HeaderCompleteToggle;

/**
 * Mini ConfettiBurst component for header toggle
 */

import React from 'react';
import { View } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
} from 'react-native-reanimated';
import { CONFETTI_COLORS, PARTICLE_COUNT } from './constants';
import { styles } from './styles';
import { animateParticle } from './confettiAnimations';

interface MiniConfettiBurstProps {
  isActive: boolean;
}

export function MiniConfettiBurst({ isActive }: MiniConfettiBurstProps) {
  const particles = Array.from({ length: PARTICLE_COUNT }, (_, i) => ({
    angle: (i / PARTICLE_COUNT) * Math.PI * 2 + (Math.random() * 0.3 - 0.15),

    color: CONFETTI_COLORS[i % CONFETTI_COLORS.length],

    distance: Math.round(25 + Math.random() * 20),

    // eslint-disable-next-line react-hooks/rules-of-hooks
    opacity: useSharedValue(0),

    // eslint-disable-next-line react-hooks/rules-of-hooks
    scale: useSharedValue(0),

    size: Math.round(3 + Math.random() * 3),

    // eslint-disable-next-line react-hooks/rules-of-hooks
    translateX: useSharedValue(0),
    // eslint-disable-next-line react-hooks/rules-of-hooks
    translateY: useSharedValue(0),
  }));

  React.useEffect(() => {
    if (isActive) {
      for (const [i, particle] of particles.entries())
        animateParticle(particle, i);
    }
  }, [isActive]);

  const particleStyles = particles.map((particle) =>
    // eslint-disable-next-line react-hooks/rules-of-hooks
    useAnimatedStyle(() => ({
      opacity: particle.opacity.value,
      transform: [
        { translateX: particle.translateX.value },
        { translateY: particle.translateY.value },
        { scale: particle.scale.value },
      ],
    }))
  );

  if (!isActive) return null;

  return (
    <View pointerEvents='none' style={styles.confettiContainer}>
      {particles.map((particle, i) => (
        <Animated.View
          key={i}
          style={[
            styles.confettiParticle,
            {
              backgroundColor: particle.color,
              borderRadius: particle.size / 2,
              height: particle.size,
              width: particle.size,
            },
            particleStyles[i],
          ]}
        />
      ))}
    </View>
  );
}

/**
 * Hook for HeaderCompleteToggle toggle logic
 */

import { useState, useCallback, useEffect } from 'react';
import {
  useSharedValue,
  withSequence,
  withTiming,
  withSpring,
} from 'react-native-reanimated';
import * as Haptics from 'expo-haptics';
import { useMutation } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import type { Id } from '../../../convex/_generated/dataModel';
import { useReduceMotion } from '../../hooks/useReduceMotion';

interface UseHeaderToggleProps {
  completedToday: boolean;
  habitId: Id<'habits'>;
  onComplete?: () => void;
  onUncomplete?: () => void;
}

export function useHeaderToggle({
  completedToday,
  habitId,
  onComplete,
  onUncomplete,
}: UseHeaderToggleProps) {
  const [isToggling, setIsToggling] = useState(false);
  const [localCompleted, setLocalCompleted] = useState(completedToday);
  const [showConfetti, setShowConfetti] = useState(false);
  const reduceMotion = useReduceMotion();

  const buttonScale = useSharedValue(1);

  const toggleCompletionMutation = useMutation(api.habits.toggleHabit);
  const today = new Date().toISOString().split('T')[0];

  // Sync local state with prop - always trust the source of truth
  useEffect(() => {
    setLocalCompleted(completedToday);
  }, [completedToday]);

  const handlePress = useCallback(async () => {
    if (isToggling) return;

    setIsToggling(true);

    // Haptic feedback
    Haptics.impactAsync(
      localCompleted
        ? Haptics.ImpactFeedbackStyle.Light
        : Haptics.ImpactFeedbackStyle.Medium
    );

    // Button animation
    buttonScale.value = withSequence(
      withTiming(0.95, { duration: 60 }),
      withSpring(1, { damping: 12, stiffness: 200 })
    );

    // Optimistic update
    const wasCompleted = localCompleted;
    setLocalCompleted(!wasCompleted);

    if (!wasCompleted && !reduceMotion) {
      setShowConfetti(true);
      setTimeout(() => setShowConfetti(false), 500);
      onComplete?.();
    } else if (wasCompleted) {
      onUncomplete?.();
    }

    try {
      await toggleCompletionMutation({ date: today, habitId });
      // Mutation succeeded - prop will update via Convex reactivity
    } catch (error) {
      // Revert on error
      setLocalCompleted(wasCompleted);
      console.error('Failed to toggle completion:', error);
    } finally {
      setIsToggling(false);
    }
  }, [
    isToggling,
    localCompleted,
    reduceMotion,
    habitId,
    today,
    toggleCompletionMutation,
    buttonScale,
    onComplete,
    onUncomplete,
  ]);

  return {
    buttonScale,
    handlePress,
    isToggling,
    localCompleted,
    showConfetti,
  };
}

/**
 * Temporary component to initialize habit strength for all existing habits
 * Add this to your App.tsx temporarily, run once, then remove it
 */

import React, { useState } from 'react';
import { View, Text, Pressable, ActivityIndicator } from 'react-native';
import { useMutation, useQuery } from 'convex/react';
import { api } from '../../convex/_generated/api';

export function InitializeHabitStrength() {
  const [isInitializing, setIsInitializing] = useState(false);
  const [result, setResult] = useState<{
    total: number;
    updated: number;
    processed: number;
    failed: number;
  } | null>(null);
  const [error, setError] = useState<string | null>(null);

  const habits = useQuery(api.habits.list);
  const recalculate = useMutation(api.habitStrength.recalculateHabitStrength);

  const handleInitialize = async () => {
    if (!habits || habits.length === 0) {
      setError('No habits found');
      return;
    }

    setIsInitializing(true);
    setError(null);
    let updated = 0;
    let failed = 0;

    try {
      for (const habit of habits) {
        try {
          await recalculate({ habitId: habit._id });
          updated++;
          console.log(`✓ Initialized: ${habit.name}`);
        } catch (error_) {
          console.error(`✗ Failed: ${habit.name}`, error_);
          failed++;
        }
      }

      setResult({
        failed,
        processed: habits.length,
        total: habits.length,
        updated,
      });
    } catch (error_) {
      setError(error_ instanceof Error ? error_.message : 'Unknown error');
    } finally {
      setIsInitializing(false);
    }
  };

  if (!habits) {
    return (
      <View className='items-center justify-center p-4'>
        <ActivityIndicator size='large' />
        <Text className='mt-2 text-sm text-stone-600'>Loading habits...</Text>
      </View>
    );
  }

  return (
    <View className='m-4 rounded-lg border border-blue-300 bg-blue-50 p-4'>
      <Text className='mb-2 text-lg font-bold text-blue-900'>
        🚀 Initialize Habit Strength
      </Text>

      <Text className='mb-3 text-sm text-blue-800'>
        Found {habits.length} habit{habits.length === 1 ? '' : 's'}. This will
        calculate habit strength from your tracking history.
      </Text>

      {!result && !error && (
        <Pressable
          className={`rounded-lg px-4 py-3 ${
            isInitializing ? 'bg-blue-300' : 'bg-blue-500'
          }`}
          disabled={isInitializing}
          onPress={handleInitialize}
        >
          {isInitializing ? (
            <View className='flex-row items-center justify-center gap-2'>
              <ActivityIndicator color='white' />
              <Text className='font-semibold text-white'>
                Initializing... ({habits.length} habits)
              </Text>
            </View>
          ) : (
            <Text className='text-center font-semibold text-white'>
              Initialize Now
            </Text>
          )}
        </Pressable>
      )}

      {result && (
        <View className='mt-3 rounded-lg bg-green-100 p-3'>
          <Text className='font-semibold text-green-900'>
            ✅ Initialization Complete!
          </Text>
          <Text className='mt-1 text-sm text-green-800'>
            • Total habits: {result.total}
          </Text>
          <Text className='text-sm text-green-800'>
            • Successfully updated: {result.updated}
          </Text>
          {result.failed > 0 && (
            <Text className='text-sm text-red-600'>
              • Failed: {result.failed}
            </Text>
          )}
          <Text className='mt-2 text-xs text-green-700'>
            You can now remove this component from your App.tsx
          </Text>
        </View>
      )}

      {error && (
        <View className='mt-3 rounded-lg bg-red-100 p-3'>
          <Text className='font-semibold text-red-900'>❌ Error</Text>
          <Text className='mt-1 text-sm text-red-800'>{error}</Text>
        </View>
      )}

      <Text className='mt-3 text-xs text-stone-600'>
        💡 Tip: After initialization, habit strength will update automatically
        when you check off habits.
      </Text>
    </View>
  );
}

/**
 * InsightsSection Component
 * Displays habit insights: best days, streak records, and trends
 */

import React, { useMemo } from 'react';
import Animated, { FadeInDown } from 'react-native-reanimated';
import type { InsightsSectionProps } from './InsightsSection.types';
import { MIN_TRACKING_DAYS_FOR_INSIGHTS } from './InsightsSection.constants';
import {
  calculateDayOfWeekStats,
  calculateStreakRecords,
  calculateTrendComparison,
  calculateCurrentStreak,
  findBestDay,
  findWorstDay,
} from './utils';
import {
  JourneyStatsSection,
  BestDaysSection,
  StreakRecordsSection,
  TrendSection,
  EmptyInsightsState,
} from './components';

export function InsightsSection({
  tracking,
  habitCreatedAt,
  totalCompletions,
  successRate,
  daysTracking,
}: InsightsSectionProps) {
  const dayStats = useMemo(
    () => calculateDayOfWeekStats(tracking, habitCreatedAt),
    [tracking, habitCreatedAt]
  );
  const bestDay = useMemo(() => findBestDay(dayStats), [dayStats]);
  const worstDay = useMemo(() => findWorstDay(dayStats), [dayStats]);
  const maxRate = useMemo(
    () => Math.max(...dayStats.map((d) => d.rate), 1),
    [dayStats]
  );
  const currentStreak = useMemo(
    () => calculateCurrentStreak(tracking),
    [tracking]
  );
  const streakRecords = useMemo(
    () => calculateStreakRecords(tracking, currentStreak),
    [tracking, currentStreak]
  );
  const trend = useMemo(() => calculateTrendComparison(tracking), [tracking]);

  if (tracking.length < MIN_TRACKING_DAYS_FOR_INSIGHTS) {
    return (
      <EmptyInsightsState
        daysRemaining={MIN_TRACKING_DAYS_FOR_INSIGHTS - tracking.length}
      />
    );
  }

  return (
    <Animated.View
      className='gap-4'
      entering={FadeInDown.delay(100).springify()}
    >
      <JourneyStatsSection
        daysTracking={daysTracking}
        successRate={successRate}
        totalCompletions={totalCompletions}
      />
      <BestDaysSection
        bestDay={bestDay}
        dayStats={dayStats}
        maxRate={maxRate}
        worstDay={worstDay}
      />
      <StreakRecordsSection streakRecords={streakRecords} />
      <TrendSection trend={trend} />
    </Animated.View>
  );
}

export default InsightsSection;

/**
 * DayBar Component
 * Animated bar showing completion rate for a day of the week
 */

import React, { useEffect } from 'react';
import { View, Text } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withDelay,
  withSpring,
  withTiming,
} from 'react-native-reanimated';
import type { DayBarProps } from '../InsightsSection.types';
import { DAY_LABELS_SHORT } from '../InsightsSection.constants';

/**
 * Get background color class based on day statistics
 */
function getBarColorClass(
  isBest: boolean,
  isWorst: boolean,
  rate: number
): string {
  if (isBest) return 'bg-emerald-500';
  if (isWorst && rate < 70) return 'bg-amber-400';
  if (rate >= 80) return 'bg-emerald-400';
  if (rate >= 60) return 'bg-blue-400';
  if (rate >= 40) return 'bg-stone-300';
  return 'bg-stone-200';
}

export function DayBar({
  dayStats,
  isBest,
  isWorst,
  maxRate,
  index,
}: DayBarProps) {
  const height = useSharedValue(0);
  const opacity = useSharedValue(0);

  const normalizedHeight = maxRate > 0 ? (dayStats.rate / maxRate) * 100 : 0;
  const minHeight = dayStats.rate > 0 ? 15 : 4;
  const finalHeight = Math.max(normalizedHeight, minHeight);

  useEffect(() => {
    opacity.value = withDelay(index * 50, withTiming(1, { duration: 200 }));
    height.value = withDelay(
      index * 50 + 100,
      withSpring(finalHeight, { damping: 12 })
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps -- shared values are stable refs
  }, [index, finalHeight]);

  const barStyle = useAnimatedStyle(() => ({
    height: `${height.value}%`,
    opacity: opacity.value,
  }));

  const bgColor = getBarColorClass(isBest, isWorst, dayStats.rate);

  return (
    <View className='flex-1 items-center'>
      <View className='h-20 w-full items-center justify-end px-0.5'>
        <Animated.View
          className={`w-full rounded-t-md ${bgColor}`}
          style={barStyle}
        />
      </View>
      <Text
        className={`mt-1.5 text-xs font-medium ${
          isBest
            ? 'text-emerald-600'
            : isWorst
              ? 'text-amber-600'
              : 'text-stone-500'
        }`}
      >
        {DAY_LABELS_SHORT[dayStats.dayIndex]}
      </Text>
      <Text
        className={`text-[10px] ${
          isBest
            ? 'font-bold text-emerald-700'
            : isWorst
              ? 'font-medium text-amber-700'
              : 'text-stone-400'
        }`}
      >
        {dayStats.rate}%
      </Text>
    </View>
  );
}

/**
 * MilestoneCelebration Component
 * Based on UX Specification Section 8.2: Milestone Celebration Animation
 *
 * Purpose: Celebrate when user reaches new habit strength level (20%, 40%, 60%, 80%)
 * Features: Full-screen modal, confetti animation, badge display with emoji, haptic feedback
 * Accessibility: Reduce Motion support, VoiceOver announcements
 * Performance: 60fps target on iPhone SE
 */

import React from 'react';
import { View } from 'react-native';
import ConfettiCannon from 'react-native-confetti-cannon';
import { Modal } from '../Modal';
import { useReduceMotion } from '../../hooks/useReduceMotion';
import type { MilestoneCelebrationProps } from './types';
import { styles } from './styles';
import { CONFETTI_COLORS, SCREEN_WIDTH } from './constants';
import { useMilestoneAnimations } from './useMilestoneAnimations';
import { useMilestoneAnimatedStyles } from './useMilestoneAnimatedStyles';
import { useConfetti } from './useConfetti';
import { useAccessibilityAnnouncement } from './useAccessibilityAnnouncement';
import { MilestoneContent } from './MilestoneContent';
import { MilestoneActions } from './MilestoneActions';

export function MilestoneCelebration({
  visible,
  onClose,
  level,
  strength,
  habitName,
  onShare,
}: MilestoneCelebrationProps) {
  const reduceMotion = useReduceMotion();

  const animations = useMilestoneAnimations({
    reduceMotion,
    strength,
    visible,
  });

  const animatedStyles = useMilestoneAnimatedStyles(animations);
  const confettiRef = useConfetti({ reduceMotion, visible });

  useAccessibilityAnnouncement({
    habitName,
    level,
    strength,
    visible,
  });

  return (
    <>
      <Modal
        backdropOpacity={0.6}
        style={styles.modalContent}
        variant='fullScreen'
        visible={visible}
        onClose={onClose}
      >
        <View style={styles.container}>
          <MilestoneContent
            badgeContainerStyle={animatedStyles.badgeContainerStyle}
            glowStyle={animatedStyles.glowStyle}
            habitName={habitName}
            labelStyle={animatedStyles.labelStyle}
            level={level}
            percentageStyle={animatedStyles.percentageStyle}
            strength={strength}
          />

          <MilestoneActions
            continueButtonStyle={animatedStyles.continueButtonStyle}
            shareButtonStyle={animatedStyles.shareButtonStyle}
            onClose={onClose}
            onShare={onShare}
          />
        </View>
      </Modal>

      {/* Confetti Animation - Only if Reduce Motion is disabled */}
      {!reduceMotion && visible && (
        <ConfettiCannon
          ref={confettiRef}
          fadeOut
          autoStart={false}
          colors={CONFETTI_COLORS}
          count={100}
          explosionSpeed={350}
          fallSpeed={2500}
          origin={{ x: SCREEN_WIDTH / 2, y: 0 }}
        />
      )}
    </>
  );
}

export default MilestoneCelebration;

