/**
 * MiniTemplateCard Component
 * Compact template card for horizontal scrolling previews within category sections
 */

import React from 'react';
import { Pressable, Text, View } from 'react-native';
import Animated from 'react-native-reanimated';
import { useReduceMotion } from '../../hooks/useReduceMotion';
import type { MiniTemplateCardProps } from './MiniTemplateCard.types';
import { styles } from './MiniTemplateCard.styles';
import { DEFAULT_ICON_COLOR, SUCCESS_COLOR } from './constants';
import {
  useMiniTemplateCardAnimations,
  useAnimatedCardStyle,
} from './useMiniTemplateCardAnimations';
import {
  useImportButtonStyle,
  useCheckmarkStyle,
  useGlowStyle,
  useChevronStyle,
  useScienceBadgeStyle,
} from './useAnimatedStyles';
import { createPressHandlers, createImportHandler } from './usePressHandlers';
import { CardHeader } from './CardHeader';
import { ImportButton } from './ImportButton';

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

export function MiniTemplateCard(props: MiniTemplateCardProps) {
  const {
    icon,
    iconColor: iconColorProp,
    name,
    description,
    hasResearch,
    onPress,
    onImport,
    isImporting,
    isImported,
  } = props;
  const reducedMotion = useReduceMotion();
  const iconColor =
    iconColorProp && iconColorProp.trim() !== ''
      ? iconColorProp
      : DEFAULT_ICON_COLOR;

  const animations = useMiniTemplateCardAnimations({
    hasImportHandler: !!onImport,
    hasResearch,
    isImported,
    isImporting,
    reducedMotion,
  });

  const animatedCardStyle = useAnimatedCardStyle(
    animations.shadowElevation,
    animations.pressScale,
    animations.pressRotation
  );
  const importButtonStyle = useImportButtonStyle(animations.buttonPulse);
  const checkmarkStyle = useCheckmarkStyle(animations.checkmarkScale);
  const glowStyle = useGlowStyle(animations.successGlow);
  const chevronStyle = useChevronStyle(animations.chevronTranslate);
  const scienceBadgeStyle = useScienceBadgeStyle(animations.scienceBadgePulse);

  const { handlePressIn, handlePressOut, handlePress } = createPressHandlers(
    animations,
    reducedMotion,
    onPress
  );
  const handleImport = createImportHandler(isImporting, isImported, onImport);

  return (
    <AnimatedPressable
      accessible
      accessibilityLabel={`${name} template`}
      accessibilityRole='button'
      style={[
        styles.card,
        { backgroundColor: `${iconColor}08` },
        animatedCardStyle,
      ]}
      onPress={handlePress}
      onPressIn={handlePressIn}
      onPressOut={handlePressOut}
    >
      <Animated.View
        pointerEvents='none'
        style={[
          styles.glowOverlay,
          { backgroundColor: SUCCESS_COLOR },
          glowStyle,
        ]}
      />
      <View
        style={[
          styles.accent,
          { backgroundColor: isImported ? SUCCESS_COLOR : iconColor },
        ]}
      />
      <CardHeader
        chevronStyle={chevronStyle}
        hasResearch={hasResearch}
        icon={icon}
        iconColor={iconColor}
        scienceBadgeStyle={scienceBadgeStyle}
      />
      <Text numberOfLines={1} style={styles.name}>
        {name}
      </Text>
      {description && (
        <Text numberOfLines={2} style={styles.description}>
          {description}
        </Text>
      )}
      {onImport && (
        <ImportButton
          checkmarkStyle={checkmarkStyle}
          iconColor={iconColor}
          importButtonStyle={importButtonStyle}
          isImported={isImported}
          isImporting={isImporting}
          name={name}
          onImport={handleImport}
        />
      )}
    </AnimatedPressable>
  );
}

export default MiniTemplateCard;

/**
 * Press handlers for MiniTemplateCard component
 */

import { SharedValue, withSpring, withTiming } from 'react-native-reanimated';
import * as Haptics from 'expo-haptics';

interface AnimationValues {
  pressScale: SharedValue<number>;
  pressRotation: SharedValue<number>;
  shadowElevation: SharedValue<number>;
  chevronTranslate: SharedValue<number>;
}

export function createPressHandlers(
  animations: AnimationValues,
  reducedMotion: boolean,
  onPress: () => void
) {
  const { pressScale, pressRotation, shadowElevation, chevronTranslate } =
    animations;

  const handlePressIn = () => {
    if (reducedMotion) {
      pressScale.value = withSpring(0.97, { damping: 15, stiffness: 300 });
    } else {
      pressScale.value = withSpring(0.97, { damping: 15, stiffness: 300 });
      shadowElevation.value = withTiming(8, { duration: 100 });
      pressRotation.value = withSpring(-0.5, { damping: 20, stiffness: 400 });
      chevronTranslate.value = withSpring(2, { damping: 15, stiffness: 300 });
    }
  };

  const handlePressOut = () => {
    pressScale.value = withSpring(1, { damping: 12, stiffness: 200 });
    if (!reducedMotion) {
      shadowElevation.value = withTiming(3, { duration: 150 });
      pressRotation.value = withSpring(0, { damping: 15, stiffness: 300 });
      chevronTranslate.value = withSpring(0, { damping: 15, stiffness: 300 });
    }
  };

  const handlePress = () => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    onPress();
  };

  return { handlePress, handlePressIn, handlePressOut };
}

export function createImportHandler(
  isImporting: boolean | undefined,
  isImported: boolean | undefined,
  onImport: (() => void) | undefined
) {
  return () => {
    if (isImporting || isImported || !onImport) return;
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    onImport();
  };
}

/**
 * Modal Component - Main orchestrator
 * Variants: Bottom Sheet, Full Screen, Center Alert
 */

import React from 'react';
import { Modal as RNModal, View } from 'react-native';
import type { ModalProps } from './Modal.types';
import { styles } from './Modal.styles';
import { useReduceMotion } from './useReduceMotion';
import { useModalAnimations } from './useModalAnimations';
import { useModalStyles } from './useModalStyles';
import { useModalGestures } from './useModalGestures';
import { ModalBackdrop } from './ModalBackdrop';
import { ModalContent } from './ModalContent';

export function Modal({
  visible,
  onClose,
  variant = 'bottomSheet',
  children,
  disableBackdropClose = false,
  disableGestureClose = false,
  backdropOpacity = 0.5,
  style,
  respectReduceMotion = true,
}: ModalProps) {
  const reduceMotion = useReduceMotion(respectReduceMotion);
  const animationValues = useModalAnimations({
    backdropOpacity,
    reduceMotion,
    respectReduceMotion,
    variant,
    visible,
  });
  const animatedStyles = useModalStyles(animationValues);
  const { panGestureBottomSheet, panGestureFullScreen } = useModalGestures({
    disableGestureClose,
    fullScreenGestureY: animationValues.fullScreenGestureY,
    fullScreenProgress: animationValues.fullScreenProgress,
    onClose,
    translateY: animationValues.translateY,
    variant,
  });

  return (
    <RNModal
      statusBarTranslucent
      transparent
      animationType='none'
      visible={visible}
      onRequestClose={onClose}
    >
      <View
        style={[
          styles.container,
          variant === 'fullScreen' && styles.containerFullScreen,
          variant === 'centerAlert' && styles.containerCenterAlert,
        ]}
      >
        <ModalBackdrop
          backdropStyle={animatedStyles.backdropStyle}
          disableBackdropClose={disableBackdropClose}
          onClose={onClose}
        />
        <ModalContent
          animatedStyles={animatedStyles}
          customStyle={style}
          panGestureBottomSheet={panGestureBottomSheet}
          panGestureFullScreen={panGestureFullScreen}
          variant={variant}
        >
          {children}
        </ModalContent>
      </View>
    </RNModal>
  );
}

export default Modal;

