/**
 * useModalAnimations Hook
 * Manages animation values for Modal variants
 */

import { useEffect } from 'react';
import { useSharedValue } from 'react-native-reanimated';
import type { ModalVariant } from './Modal.types';
import { SCREEN_HEIGHT } from './Modal.constants';
import { runEnterAnimation, runExitAnimation } from './modalAnimationEffects';

interface UseModalAnimationsParams {
  visible: boolean;
  variant: ModalVariant;
  backdropOpacity: number;
  reduceMotion: boolean;
  respectReduceMotion: boolean;
}

export function useModalAnimations({
  visible,
  variant,
  backdropOpacity,
  reduceMotion,
  respectReduceMotion,
}: UseModalAnimationsParams) {
  // Bottom sheet animation value
  const translateY = useSharedValue(SCREEN_HEIGHT);

  // Full screen animation values (Apple-like)
  const fullScreenProgress = useSharedValue(0);
  const fullScreenGestureY = useSharedValue(0);

  // Center alert animation values
  const scale = useSharedValue(0.92);
  const alertOpacity = useSharedValue(0);

  // Backdrop opacity
  const backdropOpacityValue = useSharedValue(0);

  // Collect all values for animation functions
  const animationValues = {
    alertOpacity,
    backdropOpacityValue,
    fullScreenGestureY,
    fullScreenProgress,
    scale,
    translateY,
  };

  // Enter/Exit animations
  useEffect(() => {
    const useReducedAnimation = reduceMotion && respectReduceMotion;

    if (visible) {
      runEnterAnimation(
        variant,
        useReducedAnimation,
        backdropOpacity,
        animationValues
      );
    } else {
      runExitAnimation(variant, useReducedAnimation, animationValues);
    }
  }, [visible, variant, reduceMotion, respectReduceMotion]);

  return animationValues;
}

/**
 * useModalGestures Hook
 * Gesture handlers for Modal dismissal (bottom sheet and full screen)
 */

import { Gesture } from 'react-native-gesture-handler';
import { withSpring, runOnJS, type SharedValue } from 'react-native-reanimated';
import * as Haptics from 'expo-haptics';
import type { ModalVariant } from './Modal.types';
import {
  SCREEN_HEIGHT,
  DISMISS_THRESHOLD,
  VELOCITY_THRESHOLD,
  BOTTOM_SHEET_SPRING_CONFIG,
  EXIT_SPRING_CONFIG,
  GESTURE_SPRING_CONFIG,
} from './Modal.constants';

interface UseModalGesturesParams {
  variant: ModalVariant;
  disableGestureClose: boolean;
  translateY: SharedValue<number>;
  fullScreenProgress: SharedValue<number>;
  fullScreenGestureY: SharedValue<number>;
  onClose: () => void;
}

export function useModalGestures({
  variant,
  disableGestureClose,
  translateY,
  fullScreenProgress,
  fullScreenGestureY,
  onClose,
}: UseModalGesturesParams) {
  // Pan gesture for bottom sheet (pull down to dismiss)
  const panGestureBottomSheet = Gesture.Pan()
    .enabled(!disableGestureClose && variant === 'bottomSheet')
    .onUpdate((event) => {
      if (event.translationY > 0) {
        translateY.value = event.translationY;
      }
    })
    .onEnd((event) => {
      // Use Math.round on velocity to avoid precision loss error in Reanimated
      const velocityY = Math.round(event.velocityY);
      if (
        event.translationY > DISMISS_THRESHOLD ||
        velocityY > VELOCITY_THRESHOLD
      ) {
        translateY.value = withSpring(
          SCREEN_HEIGHT,
          BOTTOM_SHEET_SPRING_CONFIG
        );
        runOnJS(Haptics.impactAsync)(Haptics.ImpactFeedbackStyle.Light);
        runOnJS(onClose)();
      } else {
        translateY.value = withSpring(0, BOTTOM_SHEET_SPRING_CONFIG);
      }
    });

  // Pan gesture for fullScreen (swipe down to dismiss - Apple sheet style)
  const panGestureFullScreen = Gesture.Pan()
    .enabled(!disableGestureClose && variant === 'fullScreen')
    .onUpdate((event) => {
      // Allow downward drag with rubber band effect
      if (event.translationY > 0) {
        // Rubber band effect: resistance increases as you drag
        const resistance = 0.4;
        fullScreenGestureY.value = event.translationY * resistance;
      }
    })
    .onEnd((event) => {
      // Use Math.round on velocity to avoid precision loss error in Reanimated
      const velocityY = Math.round(event.velocityY);
      if (
        event.translationY > DISMISS_THRESHOLD ||
        velocityY > VELOCITY_THRESHOLD
      ) {
        // Dismiss
        fullScreenProgress.value = withSpring(0, EXIT_SPRING_CONFIG);
        fullScreenGestureY.value = withSpring(0, GESTURE_SPRING_CONFIG);
        runOnJS(Haptics.impactAsync)(Haptics.ImpactFeedbackStyle.Light);
        runOnJS(onClose)();
      } else {
        // Spring back
        fullScreenGestureY.value = withSpring(0, GESTURE_SPRING_CONFIG);
      }
    });

  return {
    panGestureBottomSheet,
    panGestureFullScreen,
  };
}

/**
 * useModalStyles Hook
 * Animated styles for Modal variants
 */

import {
  useAnimatedStyle,
  interpolate,
  Extrapolation,
  type SharedValue,
} from 'react-native-reanimated';

interface UseModalStylesParams {
  translateY: SharedValue<number>;
  fullScreenProgress: SharedValue<number>;
  fullScreenGestureY: SharedValue<number>;
  scale: SharedValue<number>;
  alertOpacity: SharedValue<number>;
  backdropOpacityValue: SharedValue<number>;
}

export function useModalStyles({
  translateY,
  fullScreenProgress,
  fullScreenGestureY,
  scale,
  alertOpacity,
  backdropOpacityValue,
}: UseModalStylesParams) {
  const backdropStyle = useAnimatedStyle(() => ({
    opacity: backdropOpacityValue.value,
  }));

  const bottomSheetStyle = useAnimatedStyle(() => ({
    transform: [{ translateY: translateY.value }],
  }));

  // Apple-like fullScreen animated style
  const fullScreenStyle = useAnimatedStyle(() => {
    // Scale: starts at 0.94, ends at 1.0
    const scaleValue = interpolate(
      fullScreenProgress.value,
      [0, 1],
      [0.94, 1],
      Extrapolation.CLAMP
    );

    // Opacity: starts at 0, ends at 1
    const opacityValue = interpolate(
      fullScreenProgress.value,
      [0, 0.5, 1],
      [0, 0.8, 1],
      Extrapolation.CLAMP
    );

    // TranslateY: starts at 80, ends at 0 (slides up)
    const translateYValue = interpolate(
      fullScreenProgress.value,
      [0, 1],
      [80, 0],
      Extrapolation.CLAMP
    );

    // Add gesture translation
    const gestureTranslateY = fullScreenGestureY.value;

    // Scale down slightly when dragging (interactive feedback)
    const gestureScale = interpolate(
      gestureTranslateY,
      [0, 200],
      [1, 0.96],
      Extrapolation.CLAMP
    );

    return {
      opacity: opacityValue,
      transform: [
        { translateY: translateYValue + gestureTranslateY },
        { scale: scaleValue * gestureScale },
      ],
    };
  });

  const centerAlertStyle = useAnimatedStyle(() => ({
    opacity: alertOpacity.value,
    transform: [{ scale: scale.value }],
  }));

  return {
    backdropStyle,
    bottomSheetStyle,
    centerAlertStyle,
    fullScreenStyle,
  };
}

/**
 * useReduceMotion Hook
 * Checks for system reduce motion preference
 */

import { useEffect, useState } from 'react';
import { AccessibilityInfo } from 'react-native';

export function useReduceMotion(respectReduceMotion: boolean) {
  const [reduceMotion, setReduceMotion] = useState(false);

  useEffect(() => {
    if (respectReduceMotion) {
      AccessibilityInfo.isReduceMotionEnabled().then(setReduceMotion);
      const subscription = AccessibilityInfo.addEventListener(
        'reduceMotionChanged',
        setReduceMotion
      );
      return () => subscription?.remove();
    }
  }, [respectReduceMotion]);

  return reduceMotion;
}

