    if (reduceMotion) return;
    shimmerPosition.value = withRepeat(
      withTiming(1, { duration: 2000, easing: Easing.inOut(Easing.ease) }),
      -1,
      true
    );
  }, [shimmerPosition, reduceMotion]);

  const handlePress = useCallback(() => {
    triggerSelection();
    onUpgrade();
  }, [onUpgrade, triggerSelection]);

  return (
    <View
      className='absolute inset-0 items-center justify-center rounded-xl bg-stone-900/60 px-4 py-6'
      testID={testID}
    >
      <View className='mb-4 items-center'>
        <View className='absolute h-16 w-16 rounded-full bg-violet-500/30' />
        <View className='h-14 w-14 items-center justify-center rounded-full bg-violet-100'>
          <Lock className='text-violet-600' size={28} />
        </View>
      </View>

      <Text className='mb-1 text-center text-lg font-bold text-white'>
        {meta.title}
      </Text>
      <Text className='mb-4 text-center text-sm text-stone-200'>
        {meta.description}
      </Text>

      {showScience && (
        <View className='mb-4 flex-row items-start gap-2 rounded-lg bg-white/10 px-3 py-2'>
          <Sparkles className='mt-0.5 text-amber-300' size={14} />
          <Text className='flex-1 text-xs italic text-stone-200'>
            {meta.scienceBasis}
          </Text>
        </View>
      )}

      <Pressable
        accessibilityHint='Opens premium subscription options'
        accessibilityLabel='Unlock with Premium'
        accessibilityRole='button'
        className='w-full'
        onPress={handlePress}
      >
        <LinearGradient
          className='flex-row items-center justify-center gap-2 rounded-xl px-6 py-3'
          colors={['#8b5cf6', '#7c3aed']}
          end={{ x: 1, y: 0 }}
          start={{ x: 0, y: 0 }}
        >
          <Crown color='#ffffff' size={18} />
          <Text className='text-base font-semibold text-white'>
            Unlock with Premium
          </Text>
          <ChevronRight color='#ffffff' size={18} />
        </LinearGradient>
      </Pressable>

      {meta.freeLimit && (
        <Text className='mt-2 text-center text-xs text-stone-300'>
          Free tier: {meta.freeLimit}
        </Text>
      )}
    </View>
  );
}

/**
 * FailureViz Component
 * Dedicated failure visualization for Rescue Mode
 *
 * Part of the Motivation System - Rescue phase
 * Story T8.4: Create `FailureViz` component (always shows failure)
 *
 * Scientific Basis:
 * - Andrew Huberman (Stanford) Dual Visualization Protocol
 * - Key insight: In Rescue Mode, ALWAYS show failure (user is struggling)
 * - Loss aversion (Kahneman & Tversky, Nobel Prize): Losses hurt 2x more
 *
 * Differences from ContextAwareViz:
 * - Always shows failure visualization (no motivation check)
 * - More dramatic, urgent styling
 * - Includes streak loss preview
 * - Designed for emotional impact
 */

import React, { useEffect } from 'react';
import { View, Text } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withTiming,
} from 'react-native-reanimated';
import { AlertTriangle, Brain, Heart, User } from 'lucide-react-native';
import { clsx } from 'clsx';

import type { FailureVizProps } from './FailureViz.types';
import { SPRING_GENTLE } from './FailureViz.constants';
import { VizField } from './VizField';
import { StreakLossPreview } from './StreakLossPreview';
import { EmptyVizState } from './EmptyVizState';

export function FailureViz({
  visualization,
  streakCount,
  reduceMotion = false,
  className,
}: FailureVizProps) {
  const scale = useSharedValue(reduceMotion ? 1 : 0.95);
  const opacity = useSharedValue(reduceMotion ? 1 : 0);

  useEffect(() => {
    if (reduceMotion) {
      scale.value = 1;
      opacity.value = 1;
      return;
    }

    scale.value = withSpring(1, SPRING_GENTLE);
    opacity.value = withTiming(1, { duration: 300 });
  }, [reduceMotion, scale, opacity]);

  const containerAnimatedStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [{ scale: scale.value }],
  }));

  const hasAnyField =
    visualization?.failureBody ||
    visualization?.failureMind ||
    visualization?.failureEmotion;

  return (
    <Animated.View
      className={clsx(
        'rounded-2xl border-l-4 border-l-rose-400 bg-rose-50/80 p-4',
        className
      )}
      style={containerAnimatedStyle}
    >
      <View className='mb-4 flex-row items-center gap-3'>
        <View className='h-10 w-10 items-center justify-center rounded-xl bg-rose-100'>
          <AlertTriangle className='text-rose-600' size={20} />
        </View>
        <View className='flex-1'>
          <Text className='text-base font-semibold text-rose-800'>
            If You Skip Today...
          </Text>
          <Text className='text-xs text-rose-500'>
            Feel the weight of not doing this
          </Text>
        </View>
      </View>

      {hasAnyField ? (
        <View className='gap-1'>
          {visualization?.failureBody && (
            <VizField
              icon={<User className='text-rose-500' size={16} />}
              index={0}
              label='Body'
              reduceMotion={reduceMotion}
              value={visualization.failureBody}
            />
          )}
          {visualization?.failureMind && (
            <VizField
              icon={<Brain className='text-rose-500' size={16} />}
              index={1}
              label='Mind'
              reduceMotion={reduceMotion}
              value={visualization.failureMind}
            />
          )}
          {visualization?.failureEmotion && (
            <VizField
              icon={<Heart className='text-rose-500' size={16} />}
              index={2}
              label='Emotion'
              reduceMotion={reduceMotion}
              value={visualization.failureEmotion}
            />
          )}
        </View>
      ) : (
        <EmptyVizState />
      )}

      {streakCount !== undefined && streakCount > 0 && (
        <StreakLossPreview
          reduceMotion={reduceMotion}
          streakCount={streakCount}
        />
      )}

      <View className='mt-3 rounded-lg bg-rose-100/50 px-3 py-2'>
        <Text className='text-center text-xs text-rose-600'>
          💡 Loss aversion: This feeling moves you 2x more effectively than
          rewards
        </Text>
      </View>
    </Animated.View>
  );
}

export default FailureViz;

/**
 * PreviousStreakVoiceNotes Component
 * Displays voice notes from the user's best streak period during rescue mode
 *
 * Scientific Basis:
 * - Voice has 40% higher emotional recall than text (cognitive psychology)
 * - Reconnecting with "peak motivation self" during struggle creates powerful anchor
 * - Hearing your own voice from when you were most committed reinforces identity
 */

import React, { useCallback, useEffect, useState } from 'react';
import { View, Text } from 'react-native';
import * as Haptics from 'expo-haptics';
import { SectionHeader } from './SectionHeader';
import { StreakVoiceNoteCard } from './StreakVoiceNoteCard';
import type { PreviousStreakVoiceNotesProps } from './types';

export function PreviousStreakVoiceNotes({
  voiceNotes,
  bestStreak,
  onPlayStart,
  onPlayFinish,
  reduceMotion = false,
}: PreviousStreakVoiceNotesProps) {
  const [expandedId, setExpandedId] = useState<string | null>(null);

  // Auto-expand the first note on mount (the one from highest streak day)
  useEffect(() => {
    if (voiceNotes.length > 0 && expandedId === null) {
      setExpandedId(voiceNotes[0].id);
    }
  }, [voiceNotes, expandedId]);

  const handleToggleExpand = useCallback(
    (id: string) => {
      if (expandedId === id) {
        setExpandedId(null);
      } else {
        setExpandedId(id);
        Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
      }
    },
    [expandedId]
  );

  if (voiceNotes.length === 0) {
    return null;
  }

  return (
    <View className='rounded-2xl border-l-4 border-l-amber-400 bg-white p-4'>
      <SectionHeader bestStreak={bestStreak} />

      {/* Science callout */}
      <View className='mb-3 rounded-lg bg-amber-50 p-2'>
        <Text className='text-center text-xs italic text-amber-600'>
          Hearing your voice from when you were most committed creates a
          powerful reconnection
        </Text>
      </View>

      {/* Voice note cards */}
      <View>
        {voiceNotes.map((note) => (
          <StreakVoiceNoteCard
            key={note.id}
            bestStreak={bestStreak}
            isExpanded={expandedId === note.id}
            reduceMotion={reduceMotion}
            voiceNote={note}
            onPlayFinish={onPlayFinish}
            onPlayStart={onPlayStart}
            onToggleExpand={() => handleToggleExpand(note.id)}
          />
        ))}
      </View>

      {/* Encouragement */}
      <Text className='mt-2 text-center text-sm font-medium text-amber-700'>
        This was you at your best. You can get there again.
      </Text>
    </View>
  );
}

export default PreviousStreakVoiceNotes;

