  onPremiumRequired,
  reduceMotion = false,
  currentCount = 0,
  maxCount = DEFAULT_MAX_COUNT,
  variant = 'full',
  hasHabitContext = false,
}: GenerateAffirmationsButtonProps) {
  const remainingSlots = maxCount - currentCount;
  const canGenerate = remainingSlots > 0 && !isGenerating;

  const {
    showSuccess,
    animatedStyle,
    handlePress,
    handlePressIn,
    handlePressOut,
  } = useGenerateButton({
    canGenerate,
    isGenerating,
