/**
 * useImageUploader Hook
 * Handles image picking and uploading for the Vision Board
 */

import { useState, useCallback } from 'react';
import { Alert } from 'react-native';
import * as Haptics from 'expo-haptics';
import { useImagePicker } from '../../../../hooks/useImagePicker';
import { useImageUpload } from '../../../../hooks/useImageUpload';
import type { Id } from '../../../../../convex/_generated/dataModel';
import { MAX_IMAGES } from './types';

interface UseImageUploaderProps {
  isPremium: boolean;
  canAddMore: boolean;
  onAddImage: (storageId: Id<'_storage'>, caption?: string) => Promise<void>;
  onPremiumRequired: () => void;
}

export function useImageUploader({
  isPremium,
  canAddMore,
  onAddImage,
  onPremiumRequired,
}: UseImageUploaderProps) {
  const [isUploading, setIsUploading] = useState(false);
  const {
    pickFromCamera,
    pickFromLibrary,
    isLoading: isPickerLoading,
  } = useImagePicker();
  const { uploadImage, isUploading: isUploadInProgress } = useImageUpload();

  const isLoading = isPickerLoading || isUploadInProgress || isUploading;

  const handleAddImage = useCallback(
    async (source: 'camera' | 'library') => {
      if (!isPremium) {
        onPremiumRequired();
        return;
      }
      if (!canAddMore) {
        Alert.alert(
          'Vision Board Full',
          `You can add up to ${MAX_IMAGES} images to your Vision Board.`
        );
        return;
      }

      setIsUploading(true);
      try {
        const image =
          source === 'camera'
            ? await pickFromCamera({ aspect: [1, 1], quality: 0.8 })
            : await pickFromLibrary({ aspect: [1, 1], quality: 0.8 });

        if (!image) {
          setIsUploading(false);
          return;
        }

        const result = await uploadImage(image);
        if (!result) throw new Error('Failed to upload image');

        await onAddImage(result.storageId);
        Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
      } catch (error) {
        console.error('Failed to add image:', error);
        Alert.alert(
          'Upload Failed',
          'There was a problem adding your image. Please try again.'
        );
      } finally {
        setIsUploading(false);
      }
    },
    [
      isPremium,
      canAddMore,
      pickFromCamera,
      pickFromLibrary,
      uploadImage,
      onAddImage,
      onPremiumRequired,
    ]
  );

  return { handleAddImage, isLoading };
}

/**
 * useImageViewer Hook - State and handlers for the image viewer modal
 */

import { useState, useCallback, useEffect } from 'react';
import { Alert } from 'react-native';
import type { VisionBoardImage } from './types';

interface UseImageViewerProps {
  image: VisionBoardImage | null;
  onUpdateCaption: (caption?: string) => Promise<void>;
  onDelete: () => Promise<void>;
  onClose: () => void;
}

export function useImageViewer({
  image,
  onUpdateCaption,
  onDelete,
  onClose,
}: UseImageViewerProps) {
  const [isEditingCaption, setIsEditingCaption] = useState(false);
  const [captionText, setCaptionText] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  useEffect(() => {
    if (image) {
      setCaptionText(image.caption || '');
      setIsEditingCaption(false);
    }
  }, [image?.id]);

  const handleSaveCaption = useCallback(async () => {
    setIsSaving(true);
    try {
      await onUpdateCaption(captionText.trim() || undefined);
      setIsEditingCaption(false);
    } catch (error) {
      console.error('Failed to save caption:', error);
    } finally {
      setIsSaving(false);
    }
  }, [captionText, onUpdateCaption]);

  const handleDelete = useCallback(() => {
    Alert.alert(
      'Delete Image',
      'Are you sure you want to remove this image from your Vision Board?',
      [
        { style: 'cancel', text: 'Cancel' },
        {
          onPress: async () => {
            setIsDeleting(true);
            try {
              await onDelete();
              onClose();
            } catch (error) {
              console.error('Failed to delete:', error);
            } finally {
              setIsDeleting(false);
            }
          },
          style: 'destructive',
          text: 'Delete',
        },
      ]
    );
  }, [onDelete, onClose]);

  const handleCancel = useCallback(() => {
    setCaptionText(image?.caption || '');
    setIsEditingCaption(false);
  }, [image?.caption]);

  const toggleEdit = useCallback(() => setIsEditingCaption((v) => !v), []);

  return {
    captionText,
    handleCancel,
    handleDelete,
    handleSaveCaption,
    isDeleting,
    isEditingCaption,
    isSaving,
    setCaptionText,
    toggleEdit,
  };
}

