/**
 * useVoiceNotePlayback Hook
 * Manages audio playback state and handlers for VoiceNotePlaybackUI
 */

import { useCallback, useEffect, useState } from 'react';
import {
  useAudioPlayback,
  PlaybackSpeed,
} from '../../../../hooks/useAudioPlayback';
import { formatInitialDuration } from './utils';

interface UseVoiceNotePlaybackOptions {
  audioUri: string;
  initialDuration?: number;
  onPlayStart?: () => void;
  onPlayFinish?: () => void;
  onError?: (error: Error) => void;
}

export function useVoiceNotePlayback({
  audioUri,
  initialDuration = 0,
  onPlayStart,
  onPlayFinish,
  onError,
}: UseVoiceNotePlaybackOptions) {
  const [hasStartedPlayback, setHasStartedPlayback] = useState(false);

  const audioPlayback = useAudioPlayback({
    onError,
    onFinish: onPlayFinish,
  });

  const {
    status,
    loadAudio,
    togglePlayPause,
    seekToProgress,
    setSpeed,
    toggleMute,
    replay,
    isPlaying,
    isReady,
    isLoading,
    formattedPosition,
    formattedDuration,
    formattedRemaining,
  } = audioPlayback;

  useEffect(() => {
    if (audioUri) {
      loadAudio(audioUri);
    }
  }, [audioUri, loadAudio]);

  useEffect(() => {
    if (isPlaying && !hasStartedPlayback) {
      setHasStartedPlayback(true);
      onPlayStart?.();
    }
  }, [isPlaying, hasStartedPlayback, onPlayStart]);

  const handlePlayPausePress = useCallback(async () => {
    await (status.state === 'finished' ? replay() : togglePlayPause());
  }, [status.state, replay, togglePlayPause]);

  const handleSeek = useCallback(
    async (progress: number) => {
      await seekToProgress(progress);
    },
    [seekToProgress]
  );

  const handleSpeedChange = useCallback(
    async (speed: PlaybackSpeed) => {
      await setSpeed(speed);
    },
    [setSpeed]
  );

  const handleRetry = useCallback(() => {
    loadAudio(audioUri);
  }, [loadAudio, audioUri]);

  const isFinished = status.state === 'finished';
  const hasError = status.state === 'error';
  const displayDuration =
    status.durationSeconds > 0
      ? formattedDuration
      : initialDuration > 0
        ? formatInitialDuration(initialDuration)
        : '0:00';

  return {
    displayDuration,
    formattedPosition,
    formattedRemaining,
    handlePlayPausePress,
    hasError,
    handleRetry,
    isLoading,
    handleSeek,
    isPlaying,
    handleSpeedChange,
    status,
    isFinished,
    isReady,
    toggleMute,
  };
}

/**
 * Hooks for VoiceNotesSection component
 */

import { useCallback, useState } from 'react';
import { Alert } from 'react-native';
import * as Haptics from 'expo-haptics';
import { useAudioRecording } from '../../../../hooks/useAudioRecording';
import { MAX_RECORDING_DURATION, FREE_TIER_MAX_NOTES } from './VoiceNotesSection.constants';

interface UseVoiceNotesSectionOptions {
  voiceNoteCount: number;
  isPremium: boolean;
  onSaveRecording: (audioUri: string, durationSeconds: number, isDay1: boolean) => Promise<void>;
  onPremiumRequired: () => void;
}

export function useVoiceNotesSection({
  voiceNoteCount,
  isPremium,
  onSaveRecording,
  onPremiumRequired,
}: UseVoiceNotesSectionOptions) {
  const [isDay1Recording, setIsDay1Recording] = useState(false);
  const canRecord = isPremium || voiceNoteCount < FREE_TIER_MAX_NOTES;

  const recording = useAudioRecording({
    maxDurationSeconds: MAX_RECORDING_DURATION,
    warningThresholdSeconds: 30,
    onError: (error) => console.error('Recording error:', error),
    onMaxDurationReached: () => recording.stopRecording(),
    onPermissionDenied: (canAskAgain) => {
      console.log('Microphone permission denied, canAskAgain:', canAskAgain);
    },
    onRecordingComplete: async (uri, durationSeconds) => {
      const shouldMarkAsDay1 = isDay1Recording || voiceNoteCount === 0;
      try {
        await onSaveRecording(uri, durationSeconds, shouldMarkAsDay1);
        recording.reset();
        setIsDay1Recording(false);
      } catch {
        Alert.alert('Error', 'Failed to save recording. Please try again.');
      }
    },
    onWarningThresholdReached: (secondsRemaining) => {
      Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning);
      console.log(`Recording warning: ${secondsRemaining}s remaining`);
    },
  });

  const handleStartRecording = useCallback(() => {
    if (!canRecord) {
      onPremiumRequired();
      return;
    }
    recording.startRecording();
  }, [canRecord, onPremiumRequired, recording]);

  const handleStopRecording = useCallback(async () => {
    await recording.stopRecording();
  }, [recording]);

  const handleSectionPress = useCallback(() => {
    if (!recording.isRecording && !canRecord) {
      onPremiumRequired();
    }
  }, [recording.isRecording, canRecord, onPremiumRequired]);

  return {
    ...recording,
    canRecord,
    handleStartRecording,
    handleStopRecording,
    handleSectionPress,
  };
}

