/**
 * SectionCard - Card with press animation (app-card style, 16px radius, subtle shadow)
 */
import React, { useCallback } from 'react';
import { View, Pressable } from 'react-native';
import Animated, { useAnimatedStyle, useSharedValue, withSpring, interpolate } from 'react-native-reanimated';
import { clsx } from 'clsx';
import * as Haptics from 'expo-haptics';
import { SPRING_BUTTON } from '../../../../animations';

interface SectionCardProps {
  children: React.ReactNode;
  className?: string;
  onPress?: () => void;
  accessibilityLabel?: string;
  disabled?: boolean;
}

export function SectionCard({
  children,
  className,
  onPress,
  accessibilityLabel,
  disabled,
}: SectionCardProps) {
  const scale = useSharedValue(1);
  const shadowOpacity = useSharedValue(0.05);
  const elevation = useSharedValue(2);

  const animatedStyle = useAnimatedStyle(() => ({
    elevation: elevation.value,
    shadowOffset: {
      height: interpolate(elevation.value, [1, 2], [1, 2]),
      width: 0,
    },
    shadowOpacity: shadowOpacity.value,
    shadowRadius: interpolate(elevation.value, [1, 2], [4, 8]),
    transform: [{ scale: scale.value }],
  }));

  const handlePressIn = useCallback(() => {
    'worklet';
    scale.value = withSpring(0.98, SPRING_BUTTON);
    shadowOpacity.value = withSpring(0.02, SPRING_BUTTON);
    elevation.value = withSpring(1, SPRING_BUTTON);
  }, [scale, shadowOpacity, elevation]);

  const handlePressOut = useCallback(() => {
    'worklet';
    scale.value = withSpring(1, SPRING_BUTTON);
    shadowOpacity.value = withSpring(0.05, SPRING_BUTTON);
    elevation.value = withSpring(2, SPRING_BUTTON);
  }, [scale, shadowOpacity, elevation]);

  const handlePress = useCallback(() => {
    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    onPress?.();
  }, [onPress]);

  if (onPress) {
    return (
      <Animated.View style={[animatedStyle, { shadowColor: '#000' }]}>
        <Pressable
          accessibilityLabel={accessibilityLabel}
          accessibilityRole='button'
          accessibilityState={{ disabled }}
          className={clsx('rounded-xl border border-stone-200 bg-white p-3', className)}
          disabled={disabled}
          onPress={handlePress}
          onPressIn={handlePressIn}
          onPressOut={handlePressOut}
        >
          {children}
        </Pressable>
      </Animated.View>
    );
  }

  return (
    <View
      className={clsx('rounded-xl border border-stone-200 bg-white p-3', className)}
      style={{
        shadowColor: '#000',
        shadowOffset: { width: 0, height: 2 },
        shadowOpacity: 0.05,
        shadowRadius: 8,
        elevation: 2,
      }}
    >
      {children}
    </View>
  );
}

/**
 * VoiceNoteItem - Individual voice note with expandable playback UI
 */
import React, { useCallback, useState } from 'react';
import { View } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
} from 'react-native-reanimated';
import * as Haptics from 'expo-haptics';
import { SPRING_BUTTON } from '../../../../animations';
import { VoiceNotePlaybackUI } from '../../VoiceNotePlaybackUI';
import { VoiceNoteItemHeader } from './VoiceNoteItemHeader';
import type { VoiceNoteSummary } from '../VoiceNotesSection.types';

interface VoiceNoteItemProps {
  note: VoiceNoteSummary;
  reduceMotion?: boolean;
  onPlayStart?: () => void;
  onPlayFinish?: () => void;
}

export function VoiceNoteItem({
  note,
  reduceMotion = false,
  onPlayStart,
  onPlayFinish,
}: VoiceNoteItemProps) {
  const [isExpanded, setIsExpanded] = useState(false);
  const expandedHeight = useSharedValue(0);
  const rotateIcon = useSharedValue(0);
  const hasPlayback = !!note.audioUrl;

  const handleToggleExpand = useCallback(() => {
    if (!note.audioUrl) return;
    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    const willExpand = !isExpanded;
    setIsExpanded(willExpand);
    if (reduceMotion) {
      expandedHeight.value = willExpand ? 1 : 0;
      rotateIcon.value = willExpand ? 1 : 0;
    } else {
      expandedHeight.value = withSpring(willExpand ? 1 : 0, SPRING_BUTTON);
      rotateIcon.value = withSpring(willExpand ? 1 : 0, SPRING_BUTTON);
    }
  }, [note.audioUrl, isExpanded, reduceMotion, expandedHeight, rotateIcon]);

  const expandedStyle = useAnimatedStyle(() => ({
    height: expandedHeight.value === 0 ? 0 : 'auto',
    opacity: expandedHeight.value,
    overflow: 'hidden' as const,
  }));
  const iconStyle = useAnimatedStyle(() => ({
    transform: [{ rotate: `${Math.round(rotateIcon.value * 180)}deg` }],
  }));

  return (
    <View className='rounded-lg bg-stone-50'>
      <VoiceNoteItemHeader
        hasPlayback={hasPlayback}
        iconStyle={iconStyle}
        isExpanded={isExpanded}
        note={note}
        onPress={handleToggleExpand}
      />
      {note.audioUrl && isExpanded && (
        <Animated.View style={expandedStyle}>
          <View className='border-t border-stone-100 p-3'>
            <VoiceNotePlaybackUI
              compact
              audioUri={note.audioUrl}
              initialDuration={note.duration}
              isDay1={note.isDay1}
              label={note.label}
              reduceMotion={reduceMotion}
              showSpeedControl={false}
              onPlayFinish={onPlayFinish}
              onPlayStart={onPlayStart}
            />
          </View>
        </Animated.View>
      )}
    </View>
  );
}

