/**
 * OfflinePendingBanner Component
 * UI component showing pending offline submissions
 */

import React from 'react';
import { View, Pressable } from 'react-native';

import { styles } from './OfflinePendingBanner.styles';
import { useOfflineBannerState } from './useOfflineBannerState';
import {
  useOfflineBannerAnimations,
  useOfflineBannerHandlers,
} from './OfflinePendingBanner.hooks';
import { BannerIcon } from './BannerIcon';
import { BannerContent } from './BannerContent';
import { ProgressBar } from './ProgressBar';
import { SyncButton } from './SyncButton';
import { ExpandedStats } from './ExpandedStats';
import type { OfflinePendingBannerProps } from './types';

export function OfflinePendingBanner({
  processingState,
  reduceMotion = false,
  onPress,
  onSyncPress,
  showSyncButton = true,
  queueStats: externalStats,
  forceShow = false,
}: OfflinePendingBannerProps) {
  const state = useOfflineBannerState({
    forceShow,
    processingState,
    queueStats: externalStats,
  });

  const animations = useOfflineBannerAnimations({
    isOnline: state.isOnline,
    isProcessing: state.isProcessing,
    reduceMotion,
  });

  const handlers = useOfflineBannerHandlers({
    expandProgress: animations.expandProgress,
    externalStats,
    getStats: state.getStats,
    isExpanded: state.isExpanded,
    onPress,
    onSyncPress,
    setIsExpanded: state.setIsExpanded,
    setStats: state.setStats,
  });

  if (!state.shouldRender) return null;

  const a11yLabel = state.isOffline
    ? `Offline. ${state.queueCount} items pending sync`
    : `${state.queueCount} items waiting to sync`;

  return (
    <View style={styles.container}>
      <Pressable
        accessibilityHint='Tap to expand details'
        accessibilityLabel={a11yLabel}
        accessibilityRole='button'
        style={styles.banner}
        onPress={handlers.handlePress}
      >
        <BannerIcon
          hasPendingItems={state.hasPendingItems}
          isOffline={state.isOffline}
          isProcessing={state.isProcessing}
          pulseAnimatedStyle={animations.pulseAnimatedStyle}
          spinAnimatedStyle={animations.spinAnimatedStyle}
        />

        <BannerContent
          hasPendingItems={state.hasPendingItems}
          isOffline={state.isOffline}
          isProcessing={state.isProcessing}
          processingState={processingState}
          queueCount={state.queueCount}
        />

        <ProgressBar
          isProcessing={state.isProcessing}
          processingState={processingState}
        />

        <SyncButton
          chevronAnimatedStyle={animations.chevronAnimatedStyle}
          hasPendingItems={state.hasPendingItems}
          isOnline={state.isOnline}
          isProcessing={state.isProcessing}
          showSyncButton={showSyncButton}
          onSyncPress={handlers.handleSyncPress}
        />
      </Pressable>

      <ExpandedStats
        expandAnimatedStyle={animations.expandAnimatedStyle}
        stats={state.displayStats}
      />
    </View>
  );
}

export default OfflinePendingBanner;

import { useEffect } from 'react';
import {
  useSharedValue,
  useAnimatedStyle,
  withRepeat,
  withTiming,
  interpolate,
  Extrapolation,
} from 'react-native-reanimated';

interface UseOfflineBannerAnimationsParams {
  isProcessing: boolean;
  isOnline: boolean;
  reduceMotion: boolean;
}

export const useOfflineBannerAnimations = ({
  isProcessing,
  isOnline,
  reduceMotion,
}: UseOfflineBannerAnimationsParams) => {
  const expandProgress = useSharedValue(0);
  const spinProgress = useSharedValue(0);
  const pulseProgress = useSharedValue(0);

  // Spinner animation when processing
  useEffect(() => {
    spinProgress.value =
      isProcessing && !reduceMotion
        ? withRepeat(withTiming(1, { duration: 1000 }), -1, false)
        : 0;
  }, [isProcessing, reduceMotion, spinProgress]);

  // Pulse animation for offline indicator
  useEffect(() => {
    pulseProgress.value =
      !isOnline && !reduceMotion
        ? withRepeat(withTiming(1, { duration: 2000 }), -1, true)
        : 0;
  }, [isOnline, reduceMotion, pulseProgress]);

  const expandAnimatedStyle = useAnimatedStyle(() => ({
    height: interpolate(
      expandProgress.value,
      [0, 1],
      [0, 120],
      Extrapolation.CLAMP
    ),
    opacity: expandProgress.value,
  }));

  const chevronAnimatedStyle = useAnimatedStyle(() => ({
    transform: [
      {
        rotate: `${Math.round(interpolate(expandProgress.value, [0, 1], [0, 180]))}deg`,
      },
    ],
  }));

  const spinAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ rotate: `${Math.round(spinProgress.value * 360)}deg` }],
  }));

  const pulseAnimatedStyle = useAnimatedStyle(() => ({
    opacity: interpolate(
      pulseProgress.value,
      [0, 0.5, 1],
      [1, 0.5, 1],
      Extrapolation.CLAMP
    ),
  }));

  return {
    chevronAnimatedStyle,
    expandAnimatedStyle,
    expandProgress,
    pulseAnimatedStyle,
    spinAnimatedStyle,
  };
};

import { useState } from 'react';
import { useNetworkStatus } from '../../contexts/NetworkStatusContext';
import { useOfflineQueue, type QueueStats } from '../../hooks/useOfflineQueue';
import type { ProcessingState } from '../OfflineQueueProcessor';

interface UseOfflineBannerStateParams {
  processingState?: ProcessingState;
  queueStats?: QueueStats;
  forceShow?: boolean;
}

export const useOfflineBannerState = ({
  processingState,
  queueStats: externalStats,
  forceShow = false,
}: UseOfflineBannerStateParams) => {
  const { isOnline } = useNetworkStatus();
  const { hasQueuedItems, queueCount, getStats } = useOfflineQueue();

  const [isExpanded, setIsExpanded] = useState(false);
  const [stats, setStats] = useState<QueueStats | null>(externalStats ?? null);

  const isProcessing = processingState?.isProcessing ?? false;
  const displayStats = externalStats ?? stats;
  const isOffline = !isOnline;
  const hasPendingItems = hasQueuedItems;
  const shouldRender = forceShow || !isOnline || hasQueuedItems;

  return {
    displayStats,
    hasPendingItems,
    getStats,
    isExpanded,
    hasQueuedItems,
    isOffline,
    isOnline,
    isProcessing,
    queueCount,
    setIsExpanded,
    setStats,
    shouldRender,
    stats,
  };
};

/**
 * OfflineQueueProcessor Component
 * Processes queued submissions when network is restored.
 */

import React, { useEffect, useCallback, useMemo } from 'react';
import { useOnlineCallback } from '../../contexts/NetworkStatusContext';
import { useQueueProcessor } from './useQueueProcessor';
import {
  DEFAULT_MIN_PROCESSING_INTERVAL_MS,
  type OfflineQueueProcessorProps,
} from './types';

export function OfflineQueueProcessor({
  autoProcess = true,
  minProcessingIntervalMs = DEFAULT_MIN_PROCESSING_INTERVAL_MS,
  onProcessingStart,
  onProcessingComplete,
  onItemProcessed,
  onItemFailed,
  onStateChange,
  children,
}: OfflineQueueProcessorProps) {
  const callbacks = useMemo(
    () => ({
      onItemFailed,
      onItemProcessed,
      onProcessingComplete,
      onProcessingStart,
      onStateChange,
    }),
    [
      onItemFailed,
      onItemProcessed,
      onProcessingComplete,
      onProcessingStart,
      onStateChange,
    ]
  );

  const {
    hasQueuedItems,
    isOnline,
    isProcessingRef,
    processQueue,
    processingState,
  } = useQueueProcessor(minProcessingIntervalMs, callbacks);

  // Auto-process when coming back online
  useOnlineCallback(() => {
    if (autoProcess && hasQueuedItems) {
      setTimeout(() => void processQueue(), 1000);
    }
  });

  // Periodic check for items ready to retry
  useEffect(() => {
    if (!autoProcess || !isOnline) return;

    const interval = setInterval(() => {
      if (hasQueuedItems && !isProcessingRef.current) {
        void processQueue();
      }
    }, minProcessingIntervalMs * 2);

    return () => clearInterval(interval);
  }, [
    autoProcess,
    isOnline,
    hasQueuedItems,
    minProcessingIntervalMs,
    processQueue,
    isProcessingRef,
  ]);

  const triggerProcessQueue = useCallback(() => {
    void processQueue();
  }, [processQueue]);

  if (children) {
    return <>{children(processingState, triggerProcessQueue)}</>;
  }

  return null;
}

export default OfflineQueueProcessor;

import type {
  AffirmationPayload,
  HabitUpdatePayload,
  LetterPayload,
  QueuedSubmission,
  ReflectionPayload,
} from '../../hooks/useOfflineQueue';

interface Mutations {
  upsertReflection: (args: {
    habitId: never;
    date: string;
    emoji?: string;
    note?: string;
  }) => Promise<unknown>;
  createLetter: (args: {
    habitId: never;
    content: string;
    unlockDays: number;
    title?: string;
  }) => Promise<unknown>;
  createAffirmation: (args: {
    habitId: never;
    text: string;
    type?: string;
  }) => Promise<unknown>;
  updateHabit: (
    args: { habitId: never } & Record<string, unknown>
  ) => Promise<unknown>;
}

export async function processItem(
  item: QueuedSubmission,
  mutations: Mutations
): Promise<boolean> {
  try {
    switch (item.type) {
      case 'reflection': {
        const payload = item.payload as ReflectionPayload;
        await mutations.upsertReflection({
          date: payload.date,
          emoji: payload.emoji,
          habitId: payload.habitId as never,
          note: payload.note,
        });
        return true;
      }

      case 'letter': {
        const payload = item.payload as LetterPayload;
        await mutations.createLetter({
          content: payload.content,
          habitId: payload.habitId as never,
          title: payload.title,
          unlockDays: payload.unlockDays,
        });
        return true;
      }

      case 'affirmation': {
        const payload = item.payload as AffirmationPayload;
        await mutations.createAffirmation({
          habitId: payload.habitId as never,
          text: payload.text,
          type: payload.type,
        });
        return true;
      }

      case 'habitUpdate': {
        const payload = item.payload as HabitUpdatePayload;
        await mutations.updateHabit({
          habitId: payload.habitId as never,
          ...payload.updates,
        });
        return true;
      }

      case 'voiceNote':
      case 'visionBoardImage': {
        console.warn(
          `${item.type} offline sync not yet implemented - requires file re-upload`
        );
        return false;
      }

      default: {
        const _exhaustiveCheck: never = item.type;
        console.warn(`Unknown submission type: ${_exhaustiveCheck as string}`);
        return false;
      }
    }
  } catch (error) {
    console.warn(`Failed to process ${item.type}:`, error);
    throw error;
  }
}

import { useCallback, useRef, useState, useMemo } from 'react';
import { useMutation } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import { useNetworkStatus } from '../../contexts/NetworkStatusContext';
import { useOfflineQueue } from '../../hooks/useOfflineQueue';
import { executeQueueProcessing } from './processQueue';
import {
  INITIAL_PROCESSING_STATE,
  type ProcessingState,
  type OfflineQueueProcessorProps,
} from './types';

type ProcessorCallbacks = Pick<
  OfflineQueueProcessorProps,
  | 'onProcessingStart'
  | 'onProcessingComplete'
  | 'onItemProcessed'
  | 'onItemFailed'
  | 'onStateChange'
>;

export function useQueueProcessor(
  minProcessingIntervalMs: number,
  callbacks: ProcessorCallbacks
) {
  const { isOnline } = useNetworkStatus();
  const { getRetryableItems, dequeue, markFailed, hasQueuedItems } =
    useOfflineQueue();

  const upsertReflection = useMutation(api.reflections.upsert);
  const createLetter = useMutation(api.letters.create);
  const createAffirmation = useMutation(api.affirmations.create);
  const updateHabit = useMutation(api.habits.updateHabit);

  const [processingState, setProcessingState] = useState<ProcessingState>(
    INITIAL_PROCESSING_STATE
  );

  const isProcessingRef = useRef(false);
  const lastProcessTimeRef = useRef(0);

  const mutations = useMemo(
    () => ({ createAffirmation, createLetter, updateHabit, upsertReflection }),
    [createAffirmation, createLetter, updateHabit, upsertReflection]
  );

  const updateState = useCallback(
    (updates: Partial<ProcessingState>) => {
      setProcessingState((prev) => {
        const newState = { ...prev, ...updates };
        callbacks.onStateChange?.(newState);
        return newState;
      });
    },
    [callbacks]
  );

  const processQueue = useCallback(async () => {
    if (isProcessingRef.current) return;

    const now = Date.now();
    if (now - lastProcessTimeRef.current < minProcessingIntervalMs) return;
    if (!isOnline) return;

    const items = await getRetryableItems();
    if (items.length === 0) return;

    isProcessingRef.current = true;
    lastProcessTimeRef.current = now;

    updateState({
      failedCount: 0,
      isProcessing: true,
      processedCount: 0,
      progress: 0,
      totalItems: items.length,
    });

    const { processedCount, failedCount } = await executeQueueProcessing({
      callbacks,
      isOnline,
      items,
      mutations,
      operations: { dequeue, markFailed },
      updateState,
    });

    updateState({
      currentItem: null,
      failedCount,
      isProcessing: false,
      processedCount,
      progress: 1,
    });

    isProcessingRef.current = false;
    callbacks.onProcessingComplete?.(processedCount, failedCount);
  }, [
    isOnline,
    minProcessingIntervalMs,
    getRetryableItems,
    dequeue,
    markFailed,
    updateState,
    callbacks,
    mutations,
  ]);

  return {
    hasQueuedItems,
    isOnline,
    isProcessingRef,
    processingState,
    processQueue,
  };
}

