                      Strength preserved:{' '}
                      {Math.round(habit.strengthAtPause * 100)}%
                    </Text>
                  )}
                </View>
                <View className='flex-row gap-2'>
                  <TouchableOpacity
                    accessibilityLabel={`Resume ${habit.name}`}
                    accessibilityRole='button'
                    className='flex-1 items-center rounded-xl border border-blue-500 py-3'
                    onPress={() => handleResume(habit._id, habit.name)}
                  >
                    <Text className='text-xs font-bold tracking-[2px] text-blue-500'>
                      RESUME
                    </Text>
                  </TouchableOpacity>
                </View>
              </View>
            ))}
          </View>
        )}
      </ScrollView>
    </>
  );
}

/**
 * PredictionInsights Component
 * Phase 3: Habit Strength Prediction & Risk Assessment
 * Based on UX Specification Section 2.1 (Prediction Insights - Premium)
 */

import React from 'react';
import { View, Text } from 'react-native';

import { useAppTheme } from '../../theme';

import { styles } from './PredictionInsights.styles';
import type { PredictionInsightsProps } from './PredictionInsights.types';
import {
  ConfidenceLevel,
  RiskBadge,
  RiskWarningBox,
  SuggestedActions,
  TrendIndicator,
} from './components';

export default function PredictionInsights({
  data,
  showSuggestions = true,
}: PredictionInsightsProps) {
  const theme = useAppTheme();
  const strengthChange = data.predictedStrength - data.currentStrength;

  return (
    <View style={styles.container}>
      {/* Prediction Header */}
      <View style={styles.predictionHeader}>
        <View>
          <Text
            style={[
              theme.custom.typography.caption,
              { color: theme.custom.colors.gray[600] },
            ]}
          >
            7-Day Forecast
          </Text>
          <Text
            style={[
              theme.custom.typography.heading1,
              {
                color: theme.custom.colors.gray[900],
                fontFamily: theme.custom.fontFamilies.monospace,
              },
            ]}
          >
            {data.predictedStrength.toFixed(0)}%
          </Text>
        </View>
        <RiskBadge level={data.riskLevel} theme={theme} />
      </View>

      <TrendIndicator
        change={strengthChange}
        theme={theme}
        trend={data.trend}
      />

      <ConfidenceLevel confidence={data.confidence} theme={theme} />

      {data.riskLevel === 'high' && <RiskWarningBox theme={theme} />}

      {showSuggestions && (
        <SuggestedActions suggestions={data.suggestions} theme={theme} />
      )}

      {/* Methodology Note */}
      <View style={styles.methodologyNote}>
        <Text
          style={[
            theme.custom.typography.caption,
            { color: theme.custom.colors.gray[500], fontStyle: 'italic' },
          ]}
        >
          Predictions are based on your recent tracking patterns and historical
          data. Results may vary based on your consistency.
        </Text>
      </View>
    </View>
  );
}

/**
 * PremiumBadge Component
 * Displays subtle premium indicator on template cards
 *
 * Variants:
 * - 'pro' - Gold badge with lock icon
 * - 'popular' - Fire emoji badge
 * - 'new' - Blue "New" badge
 */

import React from 'react';
import { View, Text, StyleSheet } from 'react-native';
import { Lock, Flame, Sparkles } from 'lucide-react-native';
import { LinearGradient } from 'expo-linear-gradient';

type PremiumBadgeVariant = 'pro' | 'popular' | 'new';

interface PremiumBadgeProps {
  variant?: PremiumBadgeVariant;
  style?: any;
}

export function PremiumBadge({ variant = 'pro', style }: PremiumBadgeProps) {
  if (variant === 'popular') {
    return (
      <View style={[styles.badge, styles.popularBadge, style]}>
        <Flame color='#ff4500' size={12} strokeWidth={2.5} />
        <Text style={[styles.badgeText, { color: '#ff4500' }]}>Popular</Text>
      </View>
    );
  }

  if (variant === 'new') {
    return (
      <View style={[styles.badge, styles.newBadge, style]}>
        <Sparkles color='#3b82f6' size={12} strokeWidth={2.5} />
        <Text style={[styles.badgeText, { color: '#3b82f6' }]}>New</Text>
      </View>
    );
  }

  // Pro badge with violet gradient (premium color)
  return (
    <LinearGradient
      colors={['#8b5cf6', '#7c3aed']}
      end={{ x: 1, y: 1 }}
      start={{ x: 0, y: 0 }}
      style={[styles.badge, styles.proBadge, style]}
    >
      <Lock color='#ffffff' size={11} strokeWidth={2.75} />
      <Text style={[styles.badgeText, styles.proBadgeText]}>PRO</Text>
    </LinearGradient>
  );
}

const styles = StyleSheet.create({
  badge: {
    alignItems: 'center',
    borderRadius: 6,
    flexDirection: 'row',
    gap: 4,
    elevation: 3,
    paddingHorizontal: 8,
    paddingVertical: 4,
    position: 'absolute',
    right: 12,
    shadowColor: '#000',
    shadowOffset: { height: 2, width: 0 },
    top: 12,
    shadowOpacity: 0.15,
    shadowRadius: 3,
    zIndex: 10,
  },
  badgeText: {
    fontSize: 10,
    fontWeight: '700',
    letterSpacing: 0.5,
    textTransform: 'uppercase',
  },
  newBadge: {
    backgroundColor: '#eff6ff',
    borderColor: '#bfdbfe',
    borderWidth: 1,
  },
  popularBadge: {
    backgroundColor: '#fff5f5',
    borderColor: '#fecaca',
    borderWidth: 1,
  },
  proBadge: {
    // Gradient applied via LinearGradient
  },
  proBadgeText: {
    color: '#ffffff',
  },
});

export default PremiumBadge;

