/**
 * PersonalBestsCard Component
 *
 * @deprecated This component is deprecated and will be removed in the next major version.
 * Use `ProgressSectionConsolidated` from `../ProgressSectionConsolidated` instead.
 *
 * Migration Guide:
 * - Import `ProgressSectionConsolidated` from `../ProgressSectionConsolidated`
 * - The new component combines YourProgressCard, PersonalBestsCard, and ThisMonthCard
 *   into a single unified card with improved visual hierarchy
 * - Streak records are now in a collapsible accordion (StreakRecordsAccordion)
 * - Best/worst day info is shown in horizontal InsightChips
 *
 * Old:
 *   <PersonalBestsCard streakRecords={...} currentStreak={5} bestDay={...} worstDay={...} />
 *
 * New:
 *   <ProgressSectionConsolidated tracking={...} strength={75} ... />
 *
 * Section 2: Combines Streak Records + Best/Worst Days.
 * Features:
 * - Top 3 streak medals (compact horizontal layout)
 * - Current streak highlighted with pulse animation + "NOW 🔥" badge
 * - Best day card (emerald theme)
 * - "Focus On" card for worst day (amber theme, tappable for tips)
 * - Amber/orange gradient theme
 */

import React, { useEffect } from 'react';
import { View, Text, Pressable, AccessibilityInfo } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withRepeat,
  withSequence,
  withTiming,
  Easing,
} from 'react-native-reanimated';
import { Trophy, AlertTriangle, ChevronRight } from 'lucide-react-native';
import * as Haptics from 'expo-haptics';

import type { PersonalBestsCardProps } from './types';

// Medal configurations
const MEDALS = ['🥇', '🥈', '🥉'];
const MEDAL_COLORS = [
  { bg: 'bg-amber-50', border: 'border-amber-200', text: 'text-amber-700', subtext: 'text-amber-500' },
  { bg: 'bg-stone-50', border: 'border-stone-200', text: 'text-stone-700', subtext: 'text-stone-500' },
  { bg: 'bg-orange-50', border: 'border-orange-200', text: 'text-orange-700', subtext: 'text-orange-500' },
];

export function PersonalBestsCard({
  streakRecords,
  currentStreak,
  bestDay,
  worstDay,
  onWorstDayPress,
}: PersonalBestsCardProps) {
  // Track reduce motion preference
  const [reduceMotion, setReduceMotion] = React.useState(false);

  // Pulse animation for current streak
  const pulseScale = useSharedValue(1);
  const pulseOpacity = useSharedValue(0.6);

  useEffect(() => {
    AccessibilityInfo.isReduceMotionEnabled().then(setReduceMotion);
  }, []);

  useEffect(() => {
    if (reduceMotion || currentStreak === 0) return;

    // 2000ms infinite pulse glow
    pulseScale.value = withRepeat(
      withSequence(
        withTiming(1.05, { duration: 1000, easing: Easing.inOut(Easing.ease) }),
        withTiming(1, { duration: 1000, easing: Easing.inOut(Easing.ease) })
      ),
      -1,
      true
    );

    pulseOpacity.value = withRepeat(
      withSequence(
        withTiming(1, { duration: 1000, easing: Easing.inOut(Easing.ease) }),
        withTiming(0.6, { duration: 1000, easing: Easing.inOut(Easing.ease) })
      ),
      -1,
      true
    );
  }, [currentStreak, reduceMotion]);

  const pulseAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: pulseScale.value }],
    opacity: pulseOpacity.value,
  }));

  const handleWorstDayPress = () => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    onWorstDayPress?.();
  };

  const top3Records = streakRecords.slice(0, 3);
  const hasRecords = top3Records.length > 0;
  // Always show best/worst cards if both exist
  const showBestWorst = bestDay !== null && worstDay !== null;

  return (
    <View
      className="overflow-hidden rounded-2xl shadow-sm shadow-stone-200/50"
      accessible={true}
      accessibilityLabel={`Personal bests${currentStreak > 0 ? `, current streak ${currentStreak} days` : ''}`}
    >
      {/* Gradient Background */}
      <View className="absolute inset-0 bg-gradient-to-br from-amber-50/30 via-white to-orange-50/30" />
      <View className="absolute inset-0 border border-amber-500/20 rounded-2xl" />

      <View className="p-4">
        {/* Header */}
        <View className="mb-3 flex-row items-center gap-2">
          <View className="h-8 w-8 items-center justify-center rounded-lg bg-amber-100">
            <Trophy className="text-amber-500" size={16} />
          </View>
          <Text className="text-base font-semibold text-stone-800">Personal Bests</Text>
        </View>

        {/* Medal row (top 3 streaks) - matches mockup layout */}
        {hasRecords && (
          <View className="mb-4 flex-row gap-2">
            {top3Records.map((record, i) => {
              const colors = MEDAL_COLORS[i];
              const isCurrentRecord = record.isCurrent || (currentStreak > 0 && record.days === currentStreak);

              return (
                <Animated.View
                  key={`${record.startDate}-${record.days}`}
                  className={`flex-1 items-center rounded-xl border p-2.5 ${colors.bg} ${colors.border}`}
                  style={isCurrentRecord ? pulseAnimatedStyle : undefined}
                  accessibilityLabel={`${i === 0 ? 'First' : i === 1 ? 'Second' : 'Third'} best streak: ${record.days} days${isCurrentRecord ? ', current streak' : ''}`}
                >
                  <Text className="mb-0.5 text-base">{MEDALS[i]}</Text>
                  <Text className={`text-lg font-bold ${colors.text}`}>{record.days}</Text>
                  <Text className={`text-[9px] ${colors.subtext}`}>days</Text>
                  {isCurrentRecord && (
                    <View className="mt-1 rounded-full bg-orange-100 px-1.5 py-0.5">
                      <Text className="text-[8px] font-semibold text-orange-700">NOW 🔥</Text>
                    </View>
                  )}
                </Animated.View>
              );
            })}
            {/* Fill empty slots if less than 3 records */}
            {top3Records.length < 3 &&
              Array.from({ length: 3 - top3Records.length }).map((_, i) => (
                <View
                  key={`empty-${i}`}
                  className="flex-1 items-center rounded-xl border border-stone-100 bg-stone-50/50 p-2.5"
                >
                  <Text className="mb-0.5 text-base opacity-30">
                    {MEDALS[top3Records.length + i]}
                  </Text>
                  <Text className="text-lg font-bold text-stone-300">-</Text>
                  <Text className="text-[9px] text-stone-300">days</Text>
                </View>
              ))}
          </View>
        )}

        {/* Best/Worst day cards */}
        {showBestWorst && (
          <View className="flex-row gap-2">
            {/* Best Day */}
            <View
              className="flex-1 rounded-xl border border-emerald-100 bg-emerald-50 p-3"
              accessibilityLabel={`Best day: ${bestDay.day} with ${bestDay.rate}% success rate`}
            >
              <View className="flex-row items-center gap-1.5 mb-1">
                <Trophy className="text-emerald-500" size={14} />
                <Text className="text-xs font-medium text-emerald-600">Best Day</Text>
              </View>
              <Text className="text-lg font-bold text-emerald-700">{bestDay.day}</Text>
              <Text className="text-xs text-emerald-600">{bestDay.rate}% success</Text>
            </View>

            {/* Worst Day (tappable) */}
            <Pressable
              className="flex-1 rounded-xl border border-amber-100 bg-amber-50 p-3 active:bg-amber-100"
              onPress={handleWorstDayPress}
              accessibilityLabel={`Focus on ${worstDay.day} with ${worstDay.rate}% success rate. Tap for tips.`}
              accessibilityRole="button"
              accessibilityHint="Opens tips to improve this day"
            >
              <View className="flex-row items-center justify-between mb-1">
                <View className="flex-row items-center gap-1.5">
                  <AlertTriangle className="text-amber-500" size={14} />
                  <Text className="text-xs font-medium text-amber-600">Focus On</Text>
                </View>
                <ChevronRight className="text-amber-400" size={14} />
              </View>
              <Text className="text-lg font-bold text-amber-700">{worstDay.day}</Text>
              <Text className="text-xs text-amber-600">
                {worstDay.rate}% • tap for tips
              </Text>
            </Pressable>
          </View>
        )}

        {/* Empty state */}
        {!hasRecords && currentStreak === 0 && (
          <View className="items-center py-4">
            <Text className="text-sm text-stone-400">
              Complete 2+ consecutive days to start tracking streaks
            </Text>
          </View>
        )}
      </View>
    </View>
  );
}

export default PersonalBestsCard;

/**
 * ProgressSection Component
 *
 * @deprecated This component is deprecated and will be removed in the next major version.
 * Use `ProgressSectionConsolidated` from `../ProgressSectionConsolidated` instead.
 *
 * Migration Guide:
 * - Import `ProgressSectionConsolidated` from `../ProgressSectionConsolidated`
 * - The new component combines all 3 child cards into a single unified card
 * - ~35% reduction in vertical space with improved visual hierarchy
 * - Same props interface (tracking, habitCreatedAt, strength, weeklyChange, callbacks)
 *
 * Old:
 *   import { ProgressSection } from '../ProgressSection';
 *   <ProgressSection tracking={...} strength={75} ... />
 *
 * New:
 *   import { ProgressSectionConsolidated } from '../ProgressSectionConsolidated';
 *   <ProgressSectionConsolidated tracking={...} strength={75} ... />
 *
 * Main container for the consolidated Progress tab content.
 * Combines 3 focused, always-visible sections:
 * 1. YourProgressCard - Habit strength + actionable guidance
 * 2. PersonalBestsCard - Streak records + best/worst days
 * 3. ThisMonthCard - Bar chart + monthly trend
 */

import React, { useMemo } from 'react';
import { View } from 'react-native';
import Animated, { FadeInDown } from 'react-native-reanimated';

import { YourProgressCard } from './YourProgressCard';
import { PersonalBestsCard } from './PersonalBestsCard';
import { ThisMonthCard } from './ThisMonthCard';
import type { ProgressSectionProps } from './types';
import {
  calculateDayOfWeekStats,
  calculateStreakRecords,
  calculateTrendComparison,
  calculateCurrentStreak,
  generateActionableTip,
} from './utils';

export function ProgressSection({
  tracking,
  habitCreatedAt,
  strength,
  weeklyChange = 0,
  onInfoPress,
  onWorstDayPress,
  onSeeAllPress,
}: ProgressSectionProps) {
  // Calculate all derived data
  const dayStats = useMemo(
    () => calculateDayOfWeekStats(tracking, habitCreatedAt),
    [tracking, habitCreatedAt]
  );

  const currentStreak = useMemo(
    () => calculateCurrentStreak(tracking),
    [tracking]
  );

  const streakRecords = useMemo(
    () => calculateStreakRecords(tracking, currentStreak),
    [tracking, currentStreak]
  );

  const trend = useMemo(
    () => calculateTrendComparison(tracking),
    [tracking]
  );

  const bestDay = useMemo(() => {
    const withData = dayStats.filter((d) => d.total > 0);
    if (withData.length === 0) return null;
    return withData.reduce((best, curr) => (curr.rate > best.rate ? curr : best));
  }, [dayStats]);

  const worstDay = useMemo(() => {
    const withData = dayStats.filter((d) => d.total > 0);
    if (withData.length === 0) return null;
    return withData.reduce((worst, curr) => (curr.rate < worst.rate ? curr : worst));
  }, [dayStats]);

  const actionableTip = useMemo(
    () => generateActionableTip(dayStats, currentStreak),
    [dayStats, currentStreak]
  );

  // Calculate this month's completed days
  const thisMonthStats = useMemo(() => {
    const today = new Date();
    const thisMonthStart = new Date(today.getFullYear(), today.getMonth(), 1);

    const completedDates = new Set(
      tracking.filter((t) => t.completed).map((t) => t.date)
    );

    let completedDays = 0;
    let totalDays = 0;

    const current = new Date(thisMonthStart);
    while (current <= today) {
      totalDays++;
      if (completedDates.has(current.toISOString().split('T')[0])) {
        completedDays++;
      }
      current.setDate(current.getDate() + 1);
    }

    return { completedDays, totalDays };
  }, [tracking]);

  const hasEnoughData = tracking.length >= 7;

  return (
    <Animated.View
      className="gap-4"
      entering={FadeInDown.delay(100).springify()}
    >
      {/* Section 1: Your Progress */}
      <YourProgressCard
        strength={strength}
        weeklyChange={weeklyChange}
        actionableTip={actionableTip}
        onInfoPress={onInfoPress}
      />

      {/* Section 2: Personal Bests (only show with enough data) */}
      {hasEnoughData && (
        <PersonalBestsCard
          streakRecords={streakRecords}
          currentStreak={currentStreak}
          bestDay={bestDay}
          worstDay={worstDay}
          onWorstDayPress={onWorstDayPress}
        />
      )}

      {/* Section 3: This Month (only show with enough data) */}
      {hasEnoughData && (
        <ThisMonthCard
          dayStats={dayStats}
          thisMonthRate={trend.thisMonth}
          lastMonthRate={trend.lastMonth}
          completedDays={thisMonthStats.completedDays}
          totalDays={thisMonthStats.totalDays}
          onSeeAllPress={onSeeAllPress}
        />
      )}
    </Animated.View>
  );
}

export default ProgressSection;

/**
 * ThisMonthCard - Re-export for backward compatibility
 * @deprecated Use ProgressSectionConsolidated instead. Import from './ThisMonthCard/index'
 */

export { ThisMonthCard, default } from './ThisMonthCard/index';

/**
 * DayBar Component
 * Individual animated bar for the weekly chart
 */

import React, { useEffect } from 'react';
import { View, Text } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withDelay,
  withSpring,
  withTiming,
} from 'react-native-reanimated';
import type { DayStats } from '../types';
import { DAY_LABELS_SHORT, BAR_ANIMATION } from './constants';

interface DayBarProps {
  dayStats: DayStats;
  isBest: boolean;
  isWorst: boolean;
  maxRate: number;
  index: number;
  reduceMotion: boolean;
}

function getBgColor(isBest: boolean, isWorst: boolean, rate: number): string {
  if (isBest) return 'bg-emerald-500';
  if (isWorst && rate < 70) return 'bg-amber-500';
  if (rate >= 70) return 'bg-emerald-500/70';
  if (rate >= 50) return 'bg-blue-500/60';
  return 'bg-amber-500/70';
}

export function DayBar({
  dayStats,
  isBest,
  isWorst,
  maxRate,
  index,
  reduceMotion,
}: DayBarProps) {
  const height = useSharedValue(0);
  const opacity = useSharedValue(reduceMotion ? 1 : 0);

  const normalizedHeight = maxRate > 0 ? (dayStats.rate / maxRate) * 100 : 0;
  const minHeight = dayStats.rate > 0 ? 15 : 4;
  const finalHeight = Math.max(normalizedHeight, minHeight);

  useEffect(() => {
    if (reduceMotion) {
      height.value = finalHeight;
      return;
    }

    const delay = index * BAR_ANIMATION.staggerDelay;
    opacity.value = withDelay(
      delay,
      withTiming(1, { duration: BAR_ANIMATION.fadeInDuration })
    );
    height.value = withDelay(
      delay,
      withSpring(finalHeight, BAR_ANIMATION.springConfig)
    );
  }, [index, finalHeight, reduceMotion]);

  const barStyle = useAnimatedStyle(() => ({
    height: `${height.value}%`,
    opacity: opacity.value,
  }));

  const bgColor = getBgColor(isBest, isWorst, dayStats.rate);
  const label = DAY_LABELS_SHORT[dayStats.dayIndex];
  const a11yLabel = `${label}: ${dayStats.rate}% completion${isBest ? ', best day' : ''}${isWorst ? ', needs improvement' : ''}`;

  return (
    <View accessibilityLabel={a11yLabel} className='flex-1 items-center'>
      <View className='h-16 w-full items-center justify-end px-0.5'>
        <Animated.View
          className={`w-full rounded-t-md ${bgColor}`}
          style={barStyle}
        />
      </View>
      <Text
        className={`mt-1 text-xs font-medium ${
          isBest
            ? 'text-emerald-600'
            : isWorst
              ? 'text-amber-600'
              : 'text-stone-500'
        }`}
      >
        {label}
      </Text>
      <Text
        className={`text-[9px] ${
          isBest
            ? 'font-bold text-emerald-700'
            : isWorst
              ? 'font-medium text-amber-700'
              : 'text-stone-400'
        }`}
      >
        {dayStats.rate}%
      </Text>
    </View>
  );
}

/**
 * ThisMonthCard Component
 *
 * @deprecated This component is deprecated and will be removed in the next major version.
 * Use `ProgressSectionConsolidated` from `../ProgressSectionConsolidated` instead.
 *
 * Section 3: Combines Best Days chart + Monthly Trend.
 * Features:
 * - Animated bar chart (7 days, staggered animation)
 * - Best day highlighted (emerald), worst day highlighted (amber)
 * - Summary row: "+X% vs last month" + "Y/Z days completed"
 */

import React, { useEffect, useState } from 'react';
import { View, Text, Pressable, AccessibilityInfo } from 'react-native';
import Animated, { FadeIn } from 'react-native-reanimated';
import { BarChart3, ChevronRight } from 'lucide-react-native';

import type { ThisMonthCardProps } from '../types';
import { useDayStats } from './useDayStats';
import { DayBar } from './DayBar';
import { SummaryRow } from './SummaryRow';

export function ThisMonthCard({
  dayStats,
  thisMonthRate,
  lastMonthRate,
  completedDays,
  totalDays,
  onSeeAllPress,
}: ThisMonthCardProps) {
  const [reduceMotion, setReduceMotion] = useState(false);
  const { bestDay, worstDay, maxRate } = useDayStats(dayStats);
  const trendChange = thisMonthRate - lastMonthRate;

  useEffect(() => {
    AccessibilityInfo.isReduceMotionEnabled().then(setReduceMotion);
  }, []);

  return (
    <View
      accessible
      accessibilityLabel={`This month: ${completedDays} of ${totalDays} days completed, ${thisMonthRate}% success rate`}
      className='overflow-hidden rounded-2xl shadow-sm shadow-stone-200/50'
    >
      {/* Gradient Background */}
      <View className='absolute inset-0 bg-gradient-to-br from-violet-50/30 via-white to-blue-50/30' />
