/**
 * useInsightChipAnimations Hook
 *
 * Manages entrance and pulse animations for an individual insight chip
 */

import { useEffect } from 'react';
import {
  useSharedValue,
  useAnimatedStyle,
  withTiming,
  withDelay,
  withSpring,
  withRepeat,
  withSequence,
  Easing,
  cancelAnimation,
} from 'react-native-reanimated';

import { Springs } from '../../../constants/motion';
import {
  CHIP_STAGGER_DELAY,
  CHIP_ENTRANCE_DURATION,
  PULSE_DURATION,
} from './constants';

interface UseInsightChipAnimationsProps {
  index: number;
  reduceMotion: boolean;
  hasPulse: boolean;
}

export function useInsightChipAnimations({
  index,
  reduceMotion,
  hasPulse,
}: UseInsightChipAnimationsProps) {
  const opacity = useSharedValue(reduceMotion ? 1 : 0);
  const translateX = useSharedValue(reduceMotion ? 0 : 20);
  const pulseScale = useSharedValue(1);
  const pulseOpacity = useSharedValue(0);
  const pressScale = useSharedValue(1);

  // Entrance animation
  useEffect(() => {
    if (reduceMotion) {
      opacity.value = 1;
      translateX.value = 0;
      return;
    }

    const delay = index * CHIP_STAGGER_DELAY;
    opacity.value = withDelay(
      delay,
      withTiming(1, {
        duration: CHIP_ENTRANCE_DURATION,
        easing: Easing.out(Easing.cubic),
      })
    );
    translateX.value = withDelay(
      delay,
      withSpring(0, { damping: 18, stiffness: 120 })
    );
  }, [index, reduceMotion, opacity, translateX]);

  // Pulse animation for active streak
  useEffect(() => {
    if (!hasPulse || reduceMotion) {
      pulseScale.value = 1;
      pulseOpacity.value = 0;
      return;
    }

    pulseScale.value = withRepeat(
      withSequence(
        withTiming(1.05, { duration: PULSE_DURATION / 2 }),
        withTiming(1, { duration: PULSE_DURATION / 2 })
      ),
      -1,
      true
    );

    pulseOpacity.value = withRepeat(
      withSequence(
        withTiming(0.6, { duration: PULSE_DURATION / 2 }),
        withTiming(0, { duration: PULSE_DURATION / 2 })
      ),
      -1,
      false
    );

    return () => {
      cancelAnimation(pulseScale);
      cancelAnimation(pulseOpacity);
    };
  }, [hasPulse, reduceMotion, pulseScale, pulseOpacity]);

  const handlePressIn = () => {
    pressScale.value = withSpring(0.95, Springs.button);
  };
  const handlePressOut = () => {
    pressScale.value = withSpring(1, Springs.button);
  };

  const containerStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [{ translateX: translateX.value }, { scale: pressScale.value }],
  }));

  const pulseRingStyle = useAnimatedStyle(() => ({
    opacity: pulseOpacity.value,
    transform: [{ scale: pulseScale.value }],
  }));

  return { containerStyle, handlePressIn, handlePressOut, pulseRingStyle };
}

/**
 * useInsightChipsData Hook
 *
 * Builds the chip data array from the provided props
 */

import { useMemo } from 'react';

import type { InsightChipData } from './types';
import type { InsightChipsProps } from '../types';

export function useInsightChipsData({
  currentStreak,
  bestDay,
  focusDay,
  monthlyCompleted,
  monthlyTotal,
  onFocusDayPress,
}: InsightChipsProps): InsightChipData[] {
  return useMemo(() => {
    const chips: InsightChipData[] = [];

    // Current Streak chip
    chips.push({
      borderColor: 'orange-200',
      hasPulse: currentStreak > 0,
      icon: '🔥',
      id: 'streak',
      isInteractive: false,
      label: 'Current Streak',
      value: currentStreak === 1 ? '1 day' : `${currentStreak} days`,
    });

    // Best Day chip
    if (bestDay) {
      chips.push({
        borderColor: 'emerald-200',
        icon: '🏆',
        id: 'bestDay',
        isInteractive: false,
        label: `${Math.round(bestDay.rate)}% completion`,
        value: bestDay.name,
      });
    }

    // Focus Day chip (interactive)
    if (focusDay) {
      chips.push({
        borderColor: 'amber-200',
        icon: '⚡',
        id: 'focusDay',
        isInteractive: !!onFocusDayPress,
        label: 'Focus day',
        onPress: onFocusDayPress,
        value: focusDay.name,
      });
    }

    // Monthly Progress chip
    chips.push({
      borderColor: 'violet-200',
      icon: '📅',
      id: 'monthly',
      isInteractive: false,
      label: 'This month',
      value: `${monthlyCompleted}/${monthlyTotal}`,
    });

    return chips;
  }, [
    currentStreak,
    bestDay,
    focusDay,
    monthlyCompleted,
    monthlyTotal,
    onFocusDayPress,
  ]);
}

