 * with icon, value, label, and optional trend indicator.
 *
 * Features:
 * - Color-coded backgrounds per stat type
 * - Staggered entrance animation
 * - Press animation for interactive cards
 * - Trend indicator badge
 * - Full accessibility support
 *
 * @see docs/specs/habit-details-screen/progress-tab-improvements-spec.md
 */

import React, { useEffect } from 'react';
import { View, Text, Pressable } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withTiming,
  withDelay,
  withSpring,
  Easing,
} from 'react-native-reanimated';
import { TrendingUp, TrendingDown } from 'lucide-react-native';

import { Springs } from '../../constants/motion';
import type { StatCardProps } from './StatsGridTypes';

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

/** Stagger delay between card entrance animations (ms) */
const CARD_STAGGER_DELAY = 50;

/** Duration of card entrance animation (ms) */
const CARD_ENTRANCE_DURATION = 280;

/**
 * StatCard - Individual stat display card
 * Memoized to prevent unnecessary re-renders
 */
export const StatCard = React.memo(function StatCard({
  config,
  index,
  reduceMotion,
  isInteractive = false,
  onPress,
  onHapticFeedback,
}: StatCardProps) {
  // Entrance animation values
  const opacity = useSharedValue(reduceMotion ? 1 : 0);
  const scale = useSharedValue(reduceMotion ? 1 : 0.9);

  // Press animation
  const pressScale = useSharedValue(1);

  // Run entrance animation
  useEffect(() => {
    if (reduceMotion) {
      opacity.value = 1;
      scale.value = 1;
      return;
    }

    const delay = index * CARD_STAGGER_DELAY;

    opacity.value = withDelay(
      delay,
      withTiming(1, {
        duration: CARD_ENTRANCE_DURATION,
        easing: Easing.out(Easing.cubic),
      })
    );

    scale.value = withDelay(delay, withSpring(1, Springs.gentle));
  }, [index, reduceMotion, opacity, scale]);

  // Press handlers
  const handlePressIn = () => {
    if (!isInteractive) return;
    pressScale.value = withSpring(0.95, Springs.button);
  };

  const handlePressOut = () => {
    if (!isInteractive) return;
    pressScale.value = withSpring(1, Springs.button);
  };

  const handlePress = () => {
    if (!isInteractive || !onPress) return;
    onHapticFeedback();
    onPress();
  };

  // Animated styles
  const containerStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [{ scale: scale.value * pressScale.value }],
  }));

  // Trend indicator component
  const renderTrendIndicator = () => {
    if (!config.showTrend || config.trend === undefined || config.trend === 0) {
      return null;
    }

    const isPositive = config.trend > 0;
    const Icon = isPositive ? TrendingUp : TrendingDown;
    const color = isPositive ? '#16a34a' : '#dc2626'; // green-600 : red-600
    const bgColor = isPositive ? '#dcfce7' : '#fee2e2'; // green-100 : red-100
    const prefix = isPositive ? '+' : '';
    const label = config.id === 'monthly' ? '' : '%';

    return (
      <View
        accessibilityLabel={`${isPositive ? 'Up' : 'Down'} ${Math.abs(config.trend)}${label}`}
        className='ml-1 flex-row items-center rounded-full px-1.5 py-0.5'
        style={{ backgroundColor: bgColor }}
      >
        <Icon color={color} size={10} />
        <Text className='ml-0.5 text-[10px] font-medium' style={{ color }}>
          {prefix}
          {config.trend}
          {label}
        </Text>
      </View>
    );
  };

  const accessibilityLabel = `${config.label}: ${config.value}${
    config.showTrend && config.trend
      ? `, ${config.trend > 0 ? 'up' : 'down'} ${Math.abs(config.trend)}`
      : ''
  }`;

  const accessibilityHint = isInteractive
    ? 'Double tap to view details'
    : undefined;

  return (
    <AnimatedPressable
      accessibilityHint={accessibilityHint}
      accessibilityLabel={accessibilityLabel}
      accessibilityRole={isInteractive ? 'button' : 'text'}
      disabled={!isInteractive}
      style={containerStyle}
      onPress={handlePress}
      onPressIn={handlePressIn}
      onPressOut={handlePressOut}
    >
      <View
        className='flex-1 rounded-xl px-3 py-2'
        style={{
          backgroundColor: config.backgroundColor,
          minHeight: 60,
        }}
      >
        {/* Icon and Value row */}
        <View className='flex-row items-center'>
          <Text className='text-base'>{config.icon}</Text>
          <Text className='ml-1.5 text-base font-bold text-stone-900'>
            {config.value}
          </Text>
          {renderTrendIndicator()}
        </View>

        {/* Label */}
        <Text className='mt-0.5 text-xs text-stone-500'>{config.label}</Text>
      </View>
    </AnimatedPressable>
  );
});

export default StatCard;

/**
 * StatsGrid Component
 *
 * Compact 2x2 layout displaying key habit statistics with a strength ring.
 * Replaces the horizontal scroll InsightChips with a more scannable grid.
 *
 * Layout:
 * ┌─────────────┬─────────────────────────────┐
 * │             │  🔥 14      │  📅 18/21    │
 * │  Strength   │  Day Streak │  This Month  │
 * │    Ring     ├─────────────┼──────────────┤
 * │   (56px)    │  🏆 Tue     │  ⚡ Sat      │
 * │             │  Best Day   │  Focus Day   │
 * └─────────────┴─────────────────────────────┘
 *
 * Features:
 * - Compact 56px strength ring
 * - 4 color-coded stat cards in 2x2 grid
 * - Trend indicators on monthly and strength
 * - Staggered entrance animations
 * - Focus day is interactive
 * - Full accessibility support
 *
 * @see docs/specs/habit-details-screen/progress-tab-improvements-spec.md
 */

import React, { useMemo, useEffect } from 'react';
import { View } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
} from 'react-native-reanimated';

import { useHapticFeedback } from '../../hooks/useHapticFeedback';
import { useReduceMotion } from '../../hooks/useReduceMotion';
import { Springs } from '../../constants/motion';

import { CompactStrengthRing } from './CompactStrengthRing';
import { StatCard } from './StatCard';
import type { StatsGridProps, StatItemConfig } from './StatsGridTypes';
import { STAT_CARD_COLORS } from './StatsGridTypes';

/**
 * StatsGrid - Compact 2x2 statistics grid with strength ring
 * Memoized to prevent unnecessary re-renders
 */
export const StatsGrid = React.memo(function StatsGrid({
  strength,
  currentStreak,
  monthlyCompleted,
  monthlyTotal,
  bestDay,
  focusDay,
  weeklyChange = 0,
  monthlyChange,
  onFocusDayPress,
}: StatsGridProps) {
  const reduceMotion = useReduceMotion();
  const { triggerSelection } = useHapticFeedback();

  // Entrance animation for container
  const containerScale = useSharedValue(reduceMotion ? 1 : 0.95);

  useEffect(() => {
    if (reduceMotion) {
      containerScale.value = 1;
      return;
    }

    containerScale.value = withSpring(1, Springs.gentle);
  }, [reduceMotion, containerScale]);

  const containerStyle = useAnimatedStyle(() => ({
    transform: [{ scale: containerScale.value }],
  }));

  // Build stat cards configuration
  const statCards = useMemo<StatItemConfig[]>(() => {
    const cards: StatItemConfig[] = [];

    // Streak card (top-left of grid)
    cards.push(
      {
        backgroundColor: STAT_CARD_COLORS.streak.bgHex,
        icon: '🔥',
        id: 'streak',
        label: currentStreak === 1 ? 'Day Streak' : 'Day Streak',
        value: currentStreak === 1 ? '1' : `${currentStreak}`,
      },
      {
        backgroundColor: STAT_CARD_COLORS.monthly.bgHex,
        icon: '📅',
        id: 'monthly',
        label: 'This Month',
        showTrend: monthlyChange !== undefined && monthlyChange !== 0,
        trend: monthlyChange,
        value: `${monthlyCompleted}/${monthlyTotal}`,
      }
    );

    // Best Day card (bottom-left of grid)
    if (bestDay) {
      cards.push({
        backgroundColor: STAT_CARD_COLORS.bestDay.bgHex,
        icon: '🏆',

        id: 'bestDay',
        // Abbreviate to first 3 chars
        label: `Best Day (${Math.round(bestDay.rate)}%)`,
        value: bestDay.name.slice(0, 3),
      });
    }

    // Focus Day card (bottom-right of grid)
    if (focusDay) {
      cards.push({
        backgroundColor: STAT_CARD_COLORS.focusDay.bgHex,
        icon: '⚡',

        id: 'focusDay',
        // Abbreviate to first 3 chars
        label: `Focus Day (${Math.round(focusDay.rate)}%)`,
        value: focusDay.name.slice(0, 3),
      });
    }

    return cards;
  }, [
    currentStreak,
    monthlyCompleted,
    monthlyTotal,
    bestDay,
    focusDay,
    monthlyChange,
  ]);

  // Separate cards into rows for grid layout
  const topRowCards = statCards.slice(0, 2);
  const bottomRowCards = statCards.slice(2, 4);

  const accessibilityLabel = `Statistics overview: ${currentStreak} day streak, ${monthlyCompleted} of ${monthlyTotal} days this month${
    bestDay ? `, best day is ${bestDay.name}` : ''
  }${focusDay ? `, focus day is ${focusDay.name}` : ''}`;

  return (
    <Animated.View
      accessibilityLabel={accessibilityLabel}
      accessibilityRole='summary'
      className='mb-4'
      style={containerStyle}
    >
      <View className='flex-row'>
        {/* Left side: Compact Strength Ring */}
        <View className='mr-3 items-center justify-center'>
          <CompactStrengthRing
            strength={strength}
            weeklyChange={weeklyChange}
          />
        </View>

        {/* Right side: 2x2 Stats Grid */}
        <View className='flex-1'>
          {/* Top row */}
          <View className='mb-2 flex-row gap-2'>
            {topRowCards.map((card, index) => (
              <View key={card.id} className='flex-1'>
                <StatCard
                  config={card}
                  index={index}
                  isInteractive={false}
                  reduceMotion={reduceMotion}
                  onHapticFeedback={triggerSelection}
                />
              </View>
            ))}
          </View>

          {/* Bottom row */}
          <View className='flex-row gap-2'>
            {bottomRowCards.map((card, index) => (
              <View key={card.id} className='flex-1'>
                <StatCard
                  config={card}
                  index={index + 2} // Continue stagger from top row
                  isInteractive={card.id === 'focusDay' && !!onFocusDayPress}
                  reduceMotion={reduceMotion}
                  onHapticFeedback={triggerSelection}
                  onPress={card.id === 'focusDay' ? onFocusDayPress : undefined}
                />
              </View>
            ))}
          </View>
        </View>
      </View>
    </Animated.View>
  );
});

export default StatsGrid;

/**
 * MedalCard - Single medal display card for streak records
 */

import React from 'react';
import { View, Text } from 'react-native';
import Animated from 'react-native-reanimated';
import type { AnimatedStyleProp, ViewStyle } from 'react-native-reanimated';
import { MEDALS, MEDAL_COLORS } from './constants';
import { formatDate } from './utils';

interface MedalCardProps {
  record: {
    days: number;
    startDate: string;
    endDate: string;
    isCurrent?: boolean;
  };
  index: number;
  isCurrentRecord: boolean;
  pulseStyle?: AnimatedStyleProp<ViewStyle>;
  reduceMotion: boolean;
  isForMeasurement?: boolean;
}

export function MedalCard({
  record,
  index,
  isCurrentRecord,
  pulseStyle,
  reduceMotion,
  isForMeasurement = false,
}: MedalCardProps) {
  const colors = MEDAL_COLORS[index];
  const medal = MEDALS[index];
  const positionLabel =
    index === 0 ? 'First' : index === 1 ? 'Second' : 'Third';

  const content = (
    <>
      <Text className='mb-0.5 text-base'>{medal}</Text>
      <Text className='text-lg font-bold' style={{ color: colors.text }}>
        {record.days}
      </Text>
      <Text className='text-[9px]' style={{ color: colors.subtext }}>
        days
      </Text>
      {isCurrentRecord && (
        <View
          className='mt-1 rounded-full px-1.5 py-0.5'
          style={{ backgroundColor: '#ffedd5' }}
        >
          <Text
            className='text-[8px] font-semibold'
            style={{ color: '#c2410c' }}
          >
            NOW 🔥
          </Text>
        </View>
      )}
      <Text
        className='mt-1 text-center text-[8px]'
        style={{ color: colors.subtext }}
      >
        {formatDate(record.startDate)} - {formatDate(record.endDate)}
      </Text>
    </>
  );

  const baseStyle = { backgroundColor: colors.bg, borderColor: colors.border };

  if (isForMeasurement) {
    return (
      <View
        key={`measure-${record.startDate}-${record.days}`}
        className='flex-1 items-center rounded-xl border p-2.5'
        style={baseStyle}
      >
        {content}
      </View>
    );
  }

  return (
    <Animated.View
      key={`${record.startDate}-${record.days}`}
      accessibilityLabel={`${positionLabel} best streak: ${record.days} days, from ${formatDate(record.startDate)} to ${formatDate(record.endDate)}${isCurrentRecord ? ', current streak' : ''}`}
      className='flex-1 items-center rounded-xl border p-2.5'
      style={[
        baseStyle,
        isCurrentRecord && !reduceMotion ? pulseStyle : undefined,
      ]}
    >
      {content}
    </Animated.View>
  );
}

/**
 * StreakRecordsAccordion Component
 * Collapsible section showing streak medal records.
 */

import React, { useState, useCallback, useMemo } from 'react';
import { View, Text } from 'react-native';
import Animated from 'react-native-reanimated';
import { useReduceMotion } from '../../../hooks/useReduceMotion';
import { useHapticFeedback } from '../../../hooks/useHapticFeedback';
import type { StreakRecordsAccordionProps } from '../types';
import { MEDALS } from './constants';
import { usePulseAnimation } from './usePulseAnimation';
import { useExpandAnimation } from './useExpandAnimation';
import { AccordionHeader } from './AccordionHeader';
import { MedalCardsRow } from './MedalCardsRow';

export const StreakRecordsAccordion = React.memo(
  function StreakRecordsAccordion({
    streakRecords,
    currentStreak,
    defaultExpanded = false,
  }: StreakRecordsAccordionProps) {
    const reduceMotion = useReduceMotion();
    const { triggerSelection } = useHapticFeedback();

    const [isExpanded, setIsExpanded] = useState(defaultExpanded);
    const [contentHeight, setContentHeight] = useState(0);
    const [hasContentMeasured, setHasContentMeasured] = useState(false);

    const pulseAnimatedStyle = usePulseAnimation({
      currentStreak,
      reduceMotion,
    });
    const { animateToggle, contentAnimatedStyle, chevronAnimatedStyle } =
      useExpandAnimation({
        contentHeight,
        defaultExpanded,
        hasContentMeasured,
        reduceMotion,
      });

    const handleContentLayout = useCallback((event: any) => {
      const { height } = event.nativeEvent.layout;
      if (height > 0) {
        setContentHeight(height);
        setHasContentMeasured(true);
      }
    }, []);

    const handleToggle = useCallback(() => {
      triggerSelection();
      const newExpanded = !isExpanded;
      setIsExpanded(newExpanded);
      animateToggle(newExpanded);
    }, [isExpanded, triggerSelection, animateToggle]);

    const top3Records = useMemo(
      () => streakRecords.slice(0, 3),
      [streakRecords]
    );
    const hasRecords = top3Records.length > 0;
    const previewText = useMemo(
      () => top3Records.map((r, i) => `${MEDALS[i]}${r.days}`).join(' '),
      [top3Records]
    );

    const accessibilityLabel = useMemo(
      () =>
        hasRecords
          ? `Streak records. ${top3Records.map((r, i) => `${['Gold', 'Silver', 'Bronze'][i]}: ${r.days} days${r.isCurrent ? ', current streak' : ''}`).join(', ')}. ${isExpanded ? 'Expanded' : 'Collapsed'}.`
          : 'No streak records yet.',
      [hasRecords, top3Records, isExpanded]
    );

    if (!hasRecords && currentStreak === 0) {
      return (
        <View
          accessibilityLabel='No streak records yet.'
          className='mt-3 items-center rounded-xl border border-stone-200 bg-white p-4'
        >
          <Text className='text-sm text-stone-400'>
            Complete 2+ consecutive days to start tracking streaks
          </Text>
        </View>
      );
    }

    return (
      <View
        accessibilityLabel={accessibilityLabel}
        className='mt-3 overflow-hidden rounded-xl border border-stone-200 bg-white'
      >
        <AccordionHeader
          chevronStyle={chevronAnimatedStyle}
          hasRecords={hasRecords}
          isExpanded={isExpanded}
          previewText={previewText}
          onToggle={handleToggle}
        />

        <Animated.View style={contentAnimatedStyle}>
          <View className='px-3 pb-3' onLayout={handleContentLayout}>
            <MedalCardsRow
              currentStreak={currentStreak}
              pulseStyle={pulseAnimatedStyle}
              records={top3Records}
              reduceMotion={reduceMotion}
            />
          </View>
        </Animated.View>

        {!hasContentMeasured && (
          <View
            accessibilityElementsHidden
            className='absolute opacity-0'
            importantForAccessibility='no-hide-descendants'
            pointerEvents='none'
            onLayout={handleContentLayout}
          >
            <View className='px-3 pb-3'>
              <MedalCardsRow
                isForMeasurement
                currentStreak={currentStreak}
                records={top3Records}
                reduceMotion={reduceMotion}
              />
            </View>
          </View>
        )}
      </View>
    );
  }
);

export default StreakRecordsAccordion;

