/**
 * ConfettiParticle Component
 *
 * A single confetti particle with its own animated values.
 * Used by ConfettiBurst to create the celebration effect.
 */

import React, { useEffect } from 'react';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withTiming,
  withSequence,
  withDelay,
  Easing,
} from 'react-native-reanimated';

import { styles } from '../TodaysFocusCard.styles';

export interface ConfettiParticleProps {
  angle: number;
  color: string;
  delay: number;
  distance: number;
  isActive: boolean;
  size: number;
}

export const ConfettiParticle = React.memo(function ConfettiParticle({
  angle,
  color,
  delay,
  distance,
  isActive,
  size,
}: ConfettiParticleProps) {
  const opacity = useSharedValue(0);
  const scale = useSharedValue(0);
  const translateX = useSharedValue(0);
  const translateY = useSharedValue(0);

  useEffect(() => {
    if (isActive) {
      // Round to avoid "Loss of precision during arithmetic conversion" error
      const targetX = Math.round(Math.cos(angle) * distance);
      const targetY = Math.round(Math.sin(angle) * distance) - 30; // Bias upward

      // Reset to center
      translateX.value = 0;
      translateY.value = 0;
      scale.value = 0;
      opacity.value = 0;

      // Animate outward with spring physics
      translateX.value = withDelay(
        delay,
        withSpring(targetX, { damping: 12, mass: 1, stiffness: 200 })
      );
      translateY.value = withDelay(
        delay,
        withSpring(targetY, { damping: 12, mass: 1, stiffness: 200 })
      );
      scale.value = withDelay(
        delay,
        withSequence(
          withSpring(1.3, { damping: 8, stiffness: 300 }),
          withTiming(0, { duration: 400, easing: Easing.out(Easing.ease) })
        )
      );
      opacity.value = withDelay(
        delay,
        withSequence(
          withTiming(1, { duration: 50 }),
          withDelay(
            250,
            withTiming(0, { duration: 350, easing: Easing.out(Easing.ease) })
          )
        )
      );
    }
  }, [
    isActive,
    angle,
    delay,
    distance,
    opacity,
    scale,
    translateX,
    translateY,
  ]);

  const animatedStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [
      { translateX: translateX.value },
      { translateY: translateY.value },
      { scale: scale.value },
    ],
  }));

  return (
    <Animated.View
      style={[
        styles.confettiParticle,
        {
          backgroundColor: color,
          borderRadius: size / 2,
          height: size,
          width: size,
        },
        animatedStyle,
      ]}
    />
  );
});

export default ConfettiParticle;

/**
 * useCelebrationEffects Hook
 *
 * Handles celebration state animations and confetti effects.
 */

import { useEffect, useState, useCallback } from 'react';
import {
  withSpring,
  withTiming,
  withSequence,
  withDelay,
  SharedValue,
} from 'react-native-reanimated';
import * as Haptics from 'expo-haptics';

import type { FocusState } from '../../TodaysFocusCardTypes';
import { CONFETTI_DURATION } from '../TodaysFocusCard.constants';

export interface UseCelebrationEffectsResult {
  showConfetti: boolean;
  handleCelebrationAcknowledge: () => void;
  handleSharePress: () => void;
}

export function useCelebrationEffects(
  focusState: FocusState,
  reduceMotion: boolean,
  badgeScale: SharedValue<number>,
  shareButtonOpacity: SharedValue<number>,
  currentStreak: number,
  onMilestoneCelebrated?: (milestone: number) => void,
  onShare?: () => void
): UseCelebrationEffectsResult {
  const [showConfetti, setShowConfetti] = useState(false);

  useEffect(() => {
    if (focusState === 'celebrating' && !reduceMotion) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Heavy);
      setShowConfetti(true);
      const timer = setTimeout(() => setShowConfetti(false), CONFETTI_DURATION);

      badgeScale.value = withSequence(
        withSpring(1.4, { damping: 8, stiffness: 200 }),
        withSpring(1, { damping: 12, stiffness: 150 })
      );
      shareButtonOpacity.value = withDelay(
        400,
        withTiming(1, { duration: 300 })
      );

      return () => clearTimeout(timer);
    } else if (focusState === 'celebrating' && reduceMotion) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
      badgeScale.value = 1;
      shareButtonOpacity.value = 1;
    }
  }, [focusState, reduceMotion, badgeScale, shareButtonOpacity]);

  const handleCelebrationAcknowledge = useCallback(() => {
    if (focusState === 'celebrating' && onMilestoneCelebrated) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
      onMilestoneCelebrated(currentStreak);
    }
  }, [focusState, currentStreak, onMilestoneCelebrated]);

  const handleSharePress = useCallback(() => {
    if (onShare) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
      onShare();
    }
  }, [onShare]);

  return {
    handleCelebrationAcknowledge,
    handleSharePress,
    showConfetti,
  };
}

/**
 * useFocusAnimations Hook
 *
 * Animation hooks for entrance, shimmer, celebration, and badge effects.
 */

import { useEffect } from 'react';
import {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withTiming,
  withRepeat,
  withSequence,
  withDelay,
  Easing,
  interpolate,
  SharedValue,
} from 'react-native-reanimated';

import { Springs } from '../../../../constants/motion';
import {
  ENTRANCE_DURATION,
  SHIMMER_DURATION,
} from '../TodaysFocusCard.constants';

export interface UseFocusAnimationsResult {
  scale: SharedValue<number>;
  opacity: SharedValue<number>;
  shimmerPosition: SharedValue<number>;
  badgeScale: SharedValue<number>;
  shareButtonOpacity: SharedValue<number>;
  containerAnimatedStyle: ReturnType<typeof useAnimatedStyle>;
  shimmerAnimatedStyle: ReturnType<typeof useAnimatedStyle>;
  badgeAnimatedStyle: ReturnType<typeof useAnimatedStyle>;
  shareButtonAnimatedStyle: ReturnType<typeof useAnimatedStyle>;
}

export function useFocusAnimations(
  reduceMotion: boolean
): UseFocusAnimationsResult {
  const scale = useSharedValue(reduceMotion ? 1 : 0.95);
  const opacity = useSharedValue(reduceMotion ? 1 : 0);
  const shimmerPosition = useSharedValue(0);
  const badgeScale = useSharedValue(0);
  const shareButtonOpacity = useSharedValue(0);

  // Entrance animation
  useEffect(() => {
    if (reduceMotion) {
      scale.value = 1;
      opacity.value = 1;
      return;
    }

    scale.value = withSpring(1, {
      ...Springs.gentle,
      damping: 20,
      stiffness: 200,
    });
    opacity.value = withTiming(1, {
      duration: ENTRANCE_DURATION,
      easing: Easing.out(Easing.cubic),
    });
  }, [reduceMotion, scale, opacity]);

  // Shimmer animation
  useEffect(() => {
    if (reduceMotion) return;

    shimmerPosition.value = withRepeat(
      withSequence(
        withTiming(1, {
          duration: SHIMMER_DURATION,
          easing: Easing.inOut(Easing.ease),
        }),
        withTiming(0, { duration: 0 })
      ),
      -1,
      false
    );
  }, [reduceMotion, shimmerPosition]);

  // Animated styles
  const containerAnimatedStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [{ scale: scale.value }],
  }));

  const shimmerAnimatedStyle = useAnimatedStyle(() => ({
    opacity: interpolate(shimmerPosition.value, [0, 0.5, 1], [0, 0.3, 0]),
    transform: [
      { translateX: interpolate(shimmerPosition.value, [0, 1], [-200, 400]) },
    ],
  }));

  const badgeAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: badgeScale.value }],
  }));

  const shareButtonAnimatedStyle = useAnimatedStyle(() => ({
    opacity: shareButtonOpacity.value,
  }));

  return {
    badgeAnimatedStyle,
    badgeScale,
    containerAnimatedStyle,
    opacity,
    scale,
    shareButtonAnimatedStyle,
    shareButtonOpacity,
    shimmerAnimatedStyle,
    shimmerPosition,
  };
}

/**
 * useFocusState Hook
 *
 * Computes the focus state, goal values, and accessibility labels.
 */

import { useMemo } from 'react';

import type {
  TodaysFocusCardProps,
  FocusState,
} from '../../TodaysFocusCardTypes';
import {
  getCelebrationMilestone,
  getNextCelebrationMilestone,
} from '../../TodaysFocusCardTypes';
import {
  determineFocusState,
  calculateGoalValue,
} from '../TodaysFocusCard.utils';
import { FOCUS_STATE_CONFIGS } from '../TodaysFocusCard.constants';

export interface UseFocusStateResult {
  focusState: FocusState;
  config: (typeof FOCUS_STATE_CONFIGS)[FocusState];
  goalValue: number;
  goalLabel: string;
  message: string;
  celebrationConfig: ReturnType<typeof getCelebrationMilestone>;
  celebrationSubtext: string | null;
  nextMilestoneLabel: string | null;
  accessibilityLabel: string;
}

export function useFocusState(
  props: TodaysFocusCardProps
): UseFocusStateResult {
  const { currentStreak, bestStreak, celebratedMilestones = [] } = props;

  const focusState = useMemo(
    () => determineFocusState(props, celebratedMilestones),
    [props, celebratedMilestones]
  );

  const celebrationConfig = useMemo(
    () =>
      focusState === 'celebrating'
        ? getCelebrationMilestone(currentStreak)
        : null,
    [focusState, currentStreak]
  );

  const config = FOCUS_STATE_CONFIGS[focusState];
  const goalValue = useMemo(
    () => calculateGoalValue(focusState, props),
    [focusState, props]
  );

  const message = useMemo(() => {
    switch (focusState) {
      case 'thriving': {
        return config.getMessage(goalValue);
      }
      case 'building':
      case 'completed':
      case 'celebrating': {
        return config.getMessage(currentStreak);
      }
      case 'recovering': {
        return config.getMessage(bestStreak);
      }
      default: {
        return config.getMessage(0);
      }
    }
  }, [focusState, config, goalValue, currentStreak, bestStreak]);

  const goalLabel = config.getGoalLabel();

  const celebrationSubtext = useMemo(() => {
    if (focusState === 'celebrating' && celebrationConfig) {
      return celebrationConfig.subtext;
    }
    return null;
  }, [focusState, celebrationConfig]);

  const nextMilestoneLabel = useMemo(() => {
    if (focusState === 'celebrating') {
      const nextMilestone = getNextCelebrationMilestone(currentStreak);
      if (nextMilestone) {
        return `Next: ${nextMilestone.days} days ${nextMilestone.badge}`;
      }
    }
    return null;
  }, [focusState, currentStreak]);

  const accessibilityLabel =
    focusState === 'celebrating'
      ? `Milestone celebration: ${message}. ${celebrationSubtext ?? ''}. Next goal: ${goalValue} days`
      : `Today's focus: ${message}. Goal: ${goalValue} ${goalLabel}`;

  return {
    accessibilityLabel,
    celebrationConfig,
    celebrationSubtext,
    config,
    focusState,
    goalLabel,
    goalValue,
    message,
    nextMilestoneLabel,
  };
}

