/**
 * SparkleEffect Component
 *
 * Renders a subtle sparkle animation for perfect week celebration.
 */

import React, { useEffect } from 'react';
import { Text } from 'react-native';

import Animated, {
  Easing,
  useAnimatedStyle,
  useSharedValue,
  withRepeat,
  withSequence,
  withTiming,
} from 'react-native-reanimated';

import { styles } from './WeeklySummaryStripStyles';

interface SparkleEffectProps {
  isActive: boolean;
  reduceMotion: boolean;
}

/** Animation timing constants */
const SPARKLE_DURATION = 2000;

/**
 * SparkleEffect Component
 * Renders a subtle sparkle animation for perfect week celebration
 */
export const SparkleEffect = React.memo(function SparkleEffect({
  isActive,
  reduceMotion,
}: SparkleEffectProps) {
  const sparkleOpacity = useSharedValue(0);
  const sparkleScale = useSharedValue(1);

  useEffect(() => {
    if (isActive && !reduceMotion) {
      // Continuous subtle sparkle animation
      sparkleOpacity.value = withRepeat(
        withSequence(
          withTiming(0.7, {
            duration: SPARKLE_DURATION / 2,
            easing: Easing.inOut(Easing.ease),
          }),
          withTiming(0.2, {
            duration: SPARKLE_DURATION / 2,
            easing: Easing.inOut(Easing.ease),
          })
        ),
        -1, // Infinite repeat
        true // Reverse
      );

      sparkleScale.value = withRepeat(
        withSequence(
          withTiming(1.15, {
            duration: SPARKLE_DURATION / 2,
            easing: Easing.inOut(Easing.ease),
          }),
          withTiming(1, {
            duration: SPARKLE_DURATION / 2,
            easing: Easing.inOut(Easing.ease),
          })
        ),
        -1,
        true
      );
    } else {
      sparkleOpacity.value = 0;
      sparkleScale.value = 1;
    }
  }, [isActive, reduceMotion, sparkleOpacity, sparkleScale]);

  const sparkleAnimatedStyle = useAnimatedStyle(() => ({
    opacity: sparkleOpacity.value,
    transform: [{ scale: sparkleScale.value }],
  }));

  if (!isActive || reduceMotion) return null;

  return (
    <Animated.View
      accessibilityElementsHidden
      importantForAccessibility='no-hide-descendants'
      pointerEvents='none'
      style={[styles.sparkleContainer, sparkleAnimatedStyle]}
      testID='perfect-week-sparkle'
    >
      <Text style={styles.sparkleEmoji}>&#10024;</Text>
    </Animated.View>
  );
});

/**
 * WeeklySummaryStrip Component
 *
 * Provides a visual 7-day view of the current week's habit completion progress.
 *
 * @see docs/specs/habit-details-screen/progress-tab-improvements-spec.md
 */

import React, { useEffect, useMemo } from 'react';
import { View } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withTiming,
  withSpring,
  Easing,
} from 'react-native-reanimated';
import { LinearGradient } from 'expo-linear-gradient';

import { useReduceMotion } from '../../../hooks/useReduceMotion';
import { Springs } from '../../../constants/motion';

import type { WeeklySummaryStripProps } from '../WeeklySummaryStripTypes';
import { getTrendDirection } from './WeeklySummaryStripUtils';
import { CardContent } from './CardContent';
import { styles } from './WeeklySummaryStripStyles';

/** Animation timing constants */
const ENTRANCE_DURATION = 300;

export const WeeklySummaryStrip = React.memo(function WeeklySummaryStrip({
  lastWeekCompleted,
  onTodayPress,
  weekData,
}: WeeklySummaryStripProps) {
  const reduceMotion = useReduceMotion();
  const today = useMemo(() => new Date(), []);

  const currentWeekCompleted = useMemo(
    () => weekData.filter((d) => d.completed).length,
    [weekData]
  );

  const trend = useMemo(
    () => getTrendDirection(currentWeekCompleted, lastWeekCompleted),
    [currentWeekCompleted, lastWeekCompleted]
  );

  const isPerfectWeek = currentWeekCompleted === 7;

  const scale = useSharedValue(reduceMotion ? 1 : 0.95);
  const opacity = useSharedValue(reduceMotion ? 1 : 0);

  useEffect(() => {
    if (reduceMotion) {
      scale.value = 1;
      opacity.value = 1;
      return;
    }

    scale.value = withSpring(1, Springs.gentle);
    opacity.value = withTiming(1, {
      duration: ENTRANCE_DURATION,
      easing: Easing.out(Easing.cubic),
    });
  }, [reduceMotion, scale, opacity]);

  const containerAnimatedStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [{ scale: scale.value }],
  }));

  const accessibilityLabel = useMemo(() => {
    const completionText = `${currentWeekCompleted} of 7 days completed this week`;
    const trendText =
      trend === 'up'
        ? `up from ${lastWeekCompleted} last week`
        : trend === 'down'
          ? `down from ${lastWeekCompleted} last week`
          : `same as last week`;
    return `Weekly summary: ${completionText}, ${trendText}${isPerfectWeek ? '. Perfect week!' : ''}`;
  }, [currentWeekCompleted, lastWeekCompleted, trend, isPerfectWeek]);

  const cardContentProps = {
    currentWeekCompleted,
    isPerfectWeek,
    lastWeekCompleted,
    onTodayPress,
    reduceMotion,
    today,
    trend,
    weekData,
  };

  return (
    <Animated.View
      accessibilityLabel={accessibilityLabel}
      accessibilityRole='summary'
      style={[styles.container, containerAnimatedStyle]}
    >
      {isPerfectWeek ? (
        <LinearGradient
          colors={['#ecfdf5', '#dcfce7']}
          end={{ x: 1, y: 1 }}
          start={{ x: 0, y: 0 }}
          style={styles.cardGradient}
        >
          <CardContent {...cardContentProps} />
        </LinearGradient>
      ) : (
        <View style={styles.card}>
          <CardContent {...cardContentProps} />
        </View>
      )}
    </Animated.View>
  );
});

export default WeeklySummaryStrip;

/**
 * useProgressSectionStats Hook
 *
 * Computes all derived statistics for the ProgressSectionConsolidated component.
 */

import { useMemo } from 'react';

import type { TrackingRecord } from './types';
import {
  calculateCurrentStreak,
  calculateDayOfWeekStats,
  calculateStreakRecords,
  generateActionableTip,
  getBestAndWorstDays,
} from '../ProgressSection/utils';
import { calculateMonthlyChangeForStatsGrid } from '../../utils/trendCalculations';

interface UseProgressSectionStatsProps {
  tracking: TrackingRecord[];
  habitCreatedAt?: string;
}

/**
 * Computes all statistics needed for the progress section.
 */
export function useProgressSectionStats({
  tracking,
  habitCreatedAt,
}: UseProgressSectionStatsProps) {
  // Convert habitCreatedAt string to timestamp
  const habitCreatedTimestamp = useMemo(() => {
    if (!habitCreatedAt) return;
    try {
      return new Date(habitCreatedAt).getTime();
    } catch {
      return;
    }
  }, [habitCreatedAt]);

  // Calculate day of week statistics
  const dayStats = useMemo(
    () => calculateDayOfWeekStats(tracking, habitCreatedTimestamp),
    [tracking, habitCreatedTimestamp]
  );

  // Calculate current streak
  const currentStreak = useMemo(
    () => calculateCurrentStreak(tracking),
    [tracking]
  );

  // Calculate streak records for accordion
  const streakRecords = useMemo(
    () => calculateStreakRecords(tracking, currentStreak),
    [tracking, currentStreak]
  );

  // Calculate monthly change for trend indicator
  const monthlyChange = useMemo(
    () => calculateMonthlyChangeForStatsGrid(tracking),
    [tracking]
  );

  // Get best and worst performing days
  const { bestDay, worstDay } = useMemo(
    () => getBestAndWorstDays(dayStats),
    [dayStats]
  );

  // Generate actionable tip based on patterns
  const actionableTip = useMemo(
    () => generateActionableTip(dayStats, currentStreak),
    [dayStats, currentStreak]
  );

  // Calculate this month's completed/total days
  const { monthlyCompleted, monthlyTotal } = useMemo(() => {
    const today = new Date();
    const thisMonthStart = new Date(today.getFullYear(), today.getMonth(), 1);

    const completedDates = new Set(
      tracking.filter((t) => t.completed).map((t) => t.date)
    );

    let completed = 0;
    let total = 0;

    const current = new Date(thisMonthStart);
    while (current <= today) {
      total++;
      if (completedDates.has(current.toISOString().split('T')[0])) {
        completed++;
      }
      current.setDate(current.getDate() + 1);
    }

    return { monthlyCompleted: completed, monthlyTotal: total };
  }, [tracking]);

  // Determine if we have enough data to show detailed sections
  const hasEnoughData = tracking.length >= 7;

  // Format best/worst days for InsightChips
  const bestDayData = useMemo(() => {
    if (!bestDay) return null;
    return { name: bestDay.day, rate: bestDay.rate };
  }, [bestDay]);

  const focusDayData = useMemo(() => {
    if (!worstDay) return null;
    // Only show focus day if it's different from best day and below 70%
    if (bestDay && worstDay.dayIndex === bestDay.dayIndex) return null;
    if (worstDay.rate >= 70) return null;
    return { name: worstDay.day, rate: worstDay.rate };
  }, [worstDay, bestDay]);

  return {
    actionableTip,
    bestDayData,
    currentStreak,
    dayStats,
    focusDayData,
    hasEnoughData,
    monthlyChange,
    monthlyCompleted,
    monthlyTotal,
    streakRecords,
  };
}

