/**
 * useConfettiParticles Hook
 * Creates and manages confetti particle animations
 */

import { useEffect } from 'react';
import {
  useAnimatedStyle,
  useSharedValue,
  withSequence,
  withSpring,
  withTiming,
  withDelay,
  Easing,
} from 'react-native-reanimated';
import {
  CONFETTI_COLORS,
  PARTICLE_COUNT,
} from '../QuickCompleteButton.constants';

const SPRING_CONFIG = { damping: 12, mass: 1, stiffness: 200 };

export function useConfettiParticles(isActive: boolean) {
  const particles = Array.from({ length: PARTICLE_COUNT }, (_, i) => ({
    angle: (i / PARTICLE_COUNT) * Math.PI * 2 + (Math.random() * 0.3 - 0.15),

    color: CONFETTI_COLORS[i % CONFETTI_COLORS.length],

    distance: Math.round(40 + Math.random() * 30),

    // eslint-disable-next-line react-hooks/rules-of-hooks
    opacity: useSharedValue(0),

    // eslint-disable-next-line react-hooks/rules-of-hooks
    scale: useSharedValue(0),

    size: Math.round(4 + Math.random() * 4),

    // eslint-disable-next-line react-hooks/rules-of-hooks
    translateX: useSharedValue(0),
    // eslint-disable-next-line react-hooks/rules-of-hooks
    translateY: useSharedValue(0),
  }));

  useEffect(() => {
    if (!isActive) return;
    for (const [i, p] of particles.entries()) {
      const delay = i * 15;
      const targetX = Math.round(Math.cos(p.angle) * p.distance);
      const targetY = Math.round(Math.sin(p.angle) * p.distance) - 20;

      p.translateX.value = 0;
      p.translateY.value = 0;
      p.scale.value = 0;
      p.opacity.value = 0;

      p.translateX.value = withDelay(delay, withSpring(targetX, SPRING_CONFIG));
      p.translateY.value = withDelay(delay, withSpring(targetY, SPRING_CONFIG));
      p.scale.value = withDelay(
        delay,
        withSequence(
          withSpring(1.2, { damping: 8, stiffness: 300 }),
          withTiming(0, { duration: 400, easing: Easing.out(Easing.ease) })
        )
      );
      p.opacity.value = withDelay(
        delay,
        withSequence(
          withTiming(1, { duration: 50 }),
          withDelay(
            200,
            withTiming(0, { duration: 300, easing: Easing.out(Easing.ease) })
          )
        )
      );
    }
  }, [isActive]);

  const particleStyles = particles.map((p) =>
    // eslint-disable-next-line react-hooks/rules-of-hooks
    useAnimatedStyle(() => ({
      opacity: p.opacity.value,
      transform: [
        { translateX: p.translateX.value },
        { translateY: p.translateY.value },
        { scale: p.scale.value },
      ],
    }))
  );

  return { particles, particleStyles };
}

/**
 * useQuickCompleteButton Hook
 * Manages state and animations for the QuickCompleteButton
 */

import { useState, useEffect } from 'react';
import {
  useSharedValue,
  withSequence,
  withSpring,
  withTiming,
  Easing,
} from 'react-native-reanimated';
import * as Haptics from 'expo-haptics';
import { useMutation } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import { useReduceMotion } from '../../hooks/useReduceMotion';
import { useQuickCompleteAnimations } from './useQuickCompleteAnimations';
import type { QuickCompleteButtonProps } from './QuickCompleteButton.types';

type UseQuickCompleteButtonParams = Pick<
  QuickCompleteButtonProps,
  'completedToday' | 'habitId' | 'onComplete' | 'onUncomplete'
>;

export function useQuickCompleteButton({
  completedToday,
  habitId,
  onComplete,
  onUncomplete,
}: UseQuickCompleteButtonParams) {
  const [isToggling, setIsToggling] = useState(false);
  const [localCompleted, setLocalCompleted] = useState(completedToday);
  const [showConfetti, setShowConfetti] = useState(false);
  const reduceMotion = useReduceMotion();

  const buttonScale = useSharedValue(1);
  const checkScale = useSharedValue(completedToday ? 1 : 0);
  const checkRotation = useSharedValue(completedToday ? 0 : -90);

  const { buttonAnimatedStyle, checkAnimatedStyle } =
    useQuickCompleteAnimations({
      buttonScale,
      checkRotation,
      checkScale,
    });

  const toggleCompletionMutation = useMutation(api.habits.toggleHabit);
  const today = new Date().toISOString().split('T')[0];

  useEffect(() => {
    setLocalCompleted(completedToday);
    checkScale.value = completedToday ? 1 : 0;
    checkRotation.value = completedToday ? 0 : -90;
  }, [completedToday]);

  const handlePress = async () => {
    if (isToggling) return;
    setIsToggling(true);

    Haptics.impactAsync(
      localCompleted
        ? Haptics.ImpactFeedbackStyle.Light
        : Haptics.ImpactFeedbackStyle.Heavy
    );
    buttonScale.value = withSequence(
      withTiming(0.96, { duration: 80 }),
      withSpring(1, { damping: 12, stiffness: 200 })
    );

    const wasCompleted = localCompleted;
    setLocalCompleted(!wasCompleted);

    if (wasCompleted) {
      checkScale.value = withTiming(0, { duration: 150 });
      checkRotation.value = withTiming(-90, { duration: 150 });
      onUncomplete?.();
    } else {
      checkScale.value = withSequence(
        withSpring(1.3, { damping: 6, stiffness: 200 }),
        withSpring(1, { damping: 10, stiffness: 180 })
      );
      checkRotation.value = withTiming(0, {
        duration: 300,
        easing: Easing.out(Easing.cubic),
      });
      if (!reduceMotion) {
        setShowConfetti(true);
        setTimeout(() => setShowConfetti(false), 700);
      }
      onComplete?.();
    }

    try {
      await toggleCompletionMutation({ date: today, habitId });
    } catch (error) {
      setLocalCompleted(wasCompleted);
      checkScale.value = wasCompleted ? 1 : 0;
      checkRotation.value = wasCompleted ? 0 : -90;
      console.error('Failed to toggle completion:', error);
    } finally {
      setTimeout(() => setIsToggling(false), 300);
    }
  };

  return {
    buttonAnimatedStyle,
    checkAnimatedStyle,
    handlePress,
    isToggling,
    localCompleted,
    showConfetti,
  };
}

