import { useQuery } from 'convex/react';
import { format, startOfDay, subDays } from 'date-fns';
import { useMemo } from 'react';
import { Text, View } from 'react-native';
import { api } from '../../../convex/_generated/api';
import HabitStats from './HabitStats';

export default function StatsOverview() {
  const habits = useQuery(api.habits.list) ?? [];

  const today = useMemo(() => startOfDay(new Date()), []);
  const todayString = format(today, 'yyyy-MM-dd');

  const last7Days = useMemo(
    () =>
      Array.from({ length: 7 }, (_, i) =>
        format(subDays(today, i), 'yyyy-MM-dd')
      ),
    [today]
  );

  const tracking = useQuery(api.habits.getTracking, { dates: last7Days }) ?? [];
  const todayTracking =
    useQuery(api.habits.getTracking, {
      dates: [todayString],
    }) ?? [];

  // Today's completion
  const todayCompleted = useMemo(
    () => todayTracking.filter((t) => t.completed).length,
    [todayTracking]
  );

  const totalHabits = habits.length;

  // Weekly completion %
  const weeklyCompletionPercent = useMemo(() => {
    const possibleCompletions = habits.length * 7;
    if (possibleCompletions === 0) return 0;
    const actualCompletions = tracking.filter((t) => t.completed).length;
    return Math.round((actualCompletions / possibleCompletions) * 100);
  }, [tracking, habits.length]);

  // Longest streak across all habits
  const longestStreak = useMemo(() => {
    let maxStreak = 0;

    for (const habit of habits) {
      const habitTracking = tracking.filter((t) => t.habitId === habit._id);
      const completedDates = new Set(
        habitTracking.filter((t) => t.completed).map((t) => t.date)
      );

      const currentDate = new Date(today);
      let streak = 0;

      // Count consecutive days backward from today
      while (true) {
        const dateString = format(currentDate, 'yyyy-MM-dd');
        if (completedDates.has(dateString)) {
          streak++;
          currentDate.setDate(currentDate.getDate() - 1);
        } else {
          break;
        }
      }

      maxStreak = Math.max(maxStreak, streak);
    }

    return maxStreak;
  }, [habits, tracking, today]);

  const activeHabits = habits.length;

  return (
    <View className='gap-8'>
      {/* Overview Section */}
      <View className='gap-4'>
        <Text className='text-lg font-semibold text-stone-900'>Overview</Text>

        <View className='gap-3'>
          {/* Today's completion */}
          <View className='rounded-2xl bg-stone-50 p-4'>
            <Text className='text-xs font-semibold uppercase tracking-[2px] text-stone-500'>
              TODAY
            </Text>
            <View className='mt-2 flex-row items-baseline gap-2'>
              <Text className='text-3xl font-bold text-[#48bb78]'>
                {todayCompleted}
              </Text>
              <Text className='text-xl font-semibold text-stone-400'>
                / {totalHabits}
              </Text>
            </View>
            <Text className='mt-1 text-sm text-stone-600'>
              Habits completed today
            </Text>
          </View>

          {/* Weekly completion */}
          <View className='rounded-2xl bg-stone-50 p-4'>
            <Text className='text-xs font-semibold uppercase tracking-[2px] text-stone-500'>
              THIS WEEK
            </Text>
            <View className='mt-2 flex-row items-baseline gap-2'>
              <Text className='text-3xl font-bold text-[#48bb78]'>
                {weeklyCompletionPercent}%
              </Text>
            </View>
            <Text className='mt-1 text-sm text-stone-600'>
              Completion rate (last 7 days)
            </Text>
          </View>

          {/* Longest streak */}
          <View className='rounded-2xl bg-stone-50 p-4'>
            <Text className='text-xs font-semibold uppercase tracking-[2px] text-stone-500'>
              LONGEST STREAK
            </Text>
            <View className='mt-2 flex-row items-baseline gap-2'>
              <Text className='text-3xl font-bold text-[#48bb78]'>
                {longestStreak}
              </Text>
              <Text className='text-xl font-semibold text-stone-400'>
                {longestStreak === 1 ? 'day' : 'days'}
              </Text>
            </View>
            <Text className='mt-1 text-sm text-stone-600'>
              Across all habits
            </Text>
          </View>

          {/* Active habits */}
          <View className='rounded-2xl bg-stone-50 p-4'>
            <Text className='text-xs font-semibold uppercase tracking-[2px] text-stone-500'>
              ACTIVE HABITS
            </Text>
            <View className='mt-2'>
              <Text className='text-3xl font-bold text-stone-900'>
                {activeHabits}
              </Text>
            </View>
            <Text className='mt-1 text-sm text-stone-600'>
              Currently tracking
            </Text>
          </View>
        </View>
      </View>

      {/* Separator */}
      <View className='h-px bg-stone-200' />

      {/* Per-Habit Stats Section */}
      <HabitStats />
    </View>
  );
}

import React from 'react';
import { View, Text } from 'react-native';
import { Feather } from '@expo/vector-icons';
import { useStreakChainLogic } from './StreakChain.hooks';

export type DayStatus = 'done' | 'missed' | 'planned';

export interface StreakChainProps {
  label: string;
  statuses: DayStatus[];
  size?: number;
}

/**
 * StreakChain renders a compact chain visualization similar to the provided design.
 * - Left: label (e.g., "Reading Chain")
 * - Right: rounded pill with streak days
 * - Below: row of circles with link icon, connected by short bars
 *
 * Design language:
 * - Typography and colors align with existing app styles (#1c1917 titles, #78716c secondary, #e7e5e4 borders)
 * - Primary color uses #3B82F6 (blue)
 */
export default function StreakChain({
  label,
  statuses,
  size = 28,
}: StreakChainProps) {
  const { circleSize, iconSize, streakDays } = useStreakChainLogic(
    statuses,
    size
  );

  return (
    <View className='pb-3 pt-1'>
      <View className='mb-2 flex-row items-center justify-between'>
        <Text className='text-base font-bold tracking-tight text-stone-900'>
          {label}
        </Text>
        <View
          accessibilityLabel={`${streakDays} days`}
          className='rounded-full bg-indigo-50 px-2.5 py-1'
        >
          <Text className='text-xs font-semibold text-stone-900'>
            {streakDays} days
          </Text>
        </View>
      </View>

      <View className='flex-row items-center'>
        {statuses.map((status, idx) => {
          const isDone = status === 'done';
          const isFuture = status === 'planned'; // treat planned as future/disabled
          const connectorActive = idx < statuses.length - 1 && isDone;

          return (
            <View key={idx} className='flex-row items-center'>
              <View
                className='items-center justify-center'
                style={{
                  backgroundColor: isDone ? '#3B82F6' : '#E5E7EB',
                  borderRadius: circleSize / 2,
                  height: circleSize,
                  opacity: isFuture ? 0.5 : 1,
                  width: circleSize,
                }}
              >
                <Feather
                  color={isDone ? '#FFFFFF' : '#64748B'}
                  name='link-2'
                  size={iconSize}
                />
              </View>

              {idx < statuses.length - 1 && (
                <View
                  className='mx-1.5 h-0.5 w-[18px] rounded-sm'
                  style={{
                    backgroundColor: connectorActive ? '#93C5FD' : '#E5E7EB',
                  }}
                />
              )}
            </View>
          );
        })}
      </View>
    </View>
  );
}

/**
 * DayCircle Component
 * Individual day indicator in the 7-day streak chain
 */

import React, { useEffect } from 'react';
import { View, Text } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withDelay,
  withRepeat,
  withSequence,
  withSpring,
  withTiming,
  Easing,
  cancelAnimation,
} from 'react-native-reanimated';
import { Check, Zap } from 'lucide-react-native';
import type { DayCircleProps } from './types';

export function DayCircle({
  completed,
  index,
  isToday,
  label,
  todayCompleted,
}: DayCircleProps) {
  const scale = useSharedValue(0);
  const opacity = useSharedValue(0);
  const pulse = useSharedValue(1);

  useEffect(() => {
    const delay = index * 35;
    scale.value = withDelay(
      delay,
      withSpring(1, { damping: 12, stiffness: 200 })
    );
    opacity.value = withDelay(delay, withTiming(1, { duration: 120 }));

    if (isToday && !todayCompleted) {
      pulse.value = withRepeat(
        withSequence(
          withTiming(1.1, { duration: 700, easing: Easing.inOut(Easing.ease) }),
          withTiming(1, { duration: 700, easing: Easing.inOut(Easing.ease) })
        ),
        -1,
        false
      );
    }

    return () => {
      cancelAnimation(scale);
      cancelAnimation(opacity);
      cancelAnimation(pulse);
    };
  }, [index, isToday, todayCompleted, scale, opacity, pulse]);

  const animatedStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [
      {
        scale:
          isToday && !todayCompleted ? scale.value * pulse.value : scale.value,
      },
    ],
  }));

  const circleClass = completed
    ? 'bg-emerald-500'
    : isToday
      ? 'border-2 border-amber-400 bg-amber-50'
      : 'bg-stone-100';

  const labelColor = isToday
    ? 'text-amber-600'
    : completed
      ? 'text-emerald-600'
      : 'text-stone-400';

  return (
    <Animated.View className='flex-1 items-center' style={animatedStyle}>
      <View
        className={`mb-1.5 h-10 w-10 items-center justify-center rounded-full ${circleClass}`}
      >
        {completed ? (
          <Check className='text-white' size={20} strokeWidth={3} />
        ) : isToday ? (
          <Zap className='text-amber-500' fill='#f59e0b' size={18} />
        ) : null}
      </View>
      <Text className={`text-[10px] font-medium ${labelColor}`}>{label}</Text>
    </Animated.View>
  );
}

/**
 * Contextual Message Utilities
 * Generates motivational messages based on streak progress
 */

import type { ContextualMessageData, MessageType } from './types';

export function getContextualMessage(
  currentStreak: number,
  bestStreak: number,
  todayCompleted: boolean
): ContextualMessageData {
  // New record achieved
  if (currentStreak > 0 && currentStreak > bestStreak) {
    return { emoji: '🎉', message: 'New personal record!', type: 'record' };
  }

  // Just tied the record
  if (currentStreak > 0 && currentStreak === bestStreak && bestStreak > 1) {
    return {
      emoji: '🏆',
      message: 'You matched your best! Keep going!',
      type: 'celebrate',
    };
  }

  // Zero streak - encourage starting
  if (currentStreak === 0) {
    if (todayCompleted) {
      return {
        emoji: '🚀',
        message: 'Great start! Day 1 begins!',
        type: 'start',
      };
    }
    return { emoji: '⚡', message: 'Start a new streak today!', type: 'start' };
  }

  // Has a record to beat - show progress
  const daysToRecord = bestStreak - currentStreak;
  if (daysToRecord > 0 && daysToRecord <= 3) {
    return {
      emoji: '🔥',
      message: `${daysToRecord} more ${daysToRecord === 1 ? 'day' : 'days'} to beat your record!`,
      type: 'motivation',
    };
  }

  if (daysToRecord > 3 && daysToRecord <= 7) {
    return {
      emoji: '💪',
      message: `Keep going! ${daysToRecord} days to your best!`,
      type: 'motivation',
    };
  }

  // General motivation based on streak milestones
  return getMilestoneMessage(currentStreak, daysToRecord);
}

function getMilestoneMessage(
  currentStreak: number,
  daysToRecord: number
): ContextualMessageData {
  const milestoneMessages: Record<number, ContextualMessageData> = {
    1: {
      emoji: '🌱',
      message: 'Day 1 complete! Build that momentum!',
      type: 'motivation',
    },
    3: {
      emoji: '💪',
      message: '3 days strong! Habit forming!',
      type: 'celebrate',
    },
    7: {
      emoji: '🔥',
      message: "A full week! You're on fire!",
      type: 'celebrate',
    },
    14: {
      emoji: '⭐',
      message: 'Two weeks! Incredible consistency!',
      type: 'celebrate',
    },
    21: {
      emoji: '👑',
      message: 'Three weeks! Habit is forming!',
      type: 'celebrate',
    },
    30: {
      emoji: '💎',
      message: 'One month! Legendary streak!',
      type: 'celebrate',
    },
  };

  if (milestoneMessages[currentStreak]) {
    return milestoneMessages[currentStreak];
  }

  if (daysToRecord > 7) {
    return {
      emoji: '🔗',
      message: 'Keep the chain going!',
      type: 'motivation',
    };
  }

  return {
    emoji: '✨',
    message: 'Great progress! Keep it up!',
    type: 'motivation',
  };
}

export const MESSAGE_STYLES: Record<
  MessageType,
  { bgColor: string; textColor: string }
> = {
  celebrate: {
    bgColor: 'bg-gradient-to-r from-emerald-50 to-teal-50 border-emerald-200',
    textColor: 'text-emerald-700',
  },
  motivation: {
    bgColor: 'bg-gradient-to-r from-violet-50 to-purple-50 border-violet-200',
    textColor: 'text-violet-700',
  },
  record: {
    bgColor: 'bg-gradient-to-r from-amber-100 to-yellow-100 border-amber-200',
    textColor: 'text-amber-700',
  },
  start: {
    bgColor: 'bg-gradient-to-r from-orange-50 to-amber-50 border-orange-200',
    textColor: 'text-orange-700',
  },
};

