/**
 * Hook for StreakIndicator animation and state logic
 */

import { useEffect } from 'react';
import {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withSequence,
} from 'react-native-reanimated';
import { useAppTheme } from '../../theme';
import type { Milestone } from './StreakIndicator.types';
import { MILESTONES, MILESTONE_BADGES } from './StreakIndicator.constants';

interface UseStreakIndicatorOptions {
  currentStreak: number;
  onMilestone?: (streak: number) => void;
  accessibilityLabel?: string;
  bestStreak: number;
}

export function useStreakIndicator({
  currentStreak,
  onMilestone,
  accessibilityLabel,
  bestStreak,
}: UseStreakIndicatorOptions) {
  const theme = useAppTheme();
  const scale = useSharedValue(1);

  // Get the highest milestone reached
  let currentMilestone: Milestone | null = null;
  for (const milestone of MILESTONES) {
    if (currentStreak >= milestone) {
      currentMilestone = milestone;
    }
  }

  // Trigger animation and callback when milestone changes
  useEffect(() => {
    if (currentMilestone && onMilestone) {
      onMilestone(currentMilestone);
      scale.value = withSequence(
        withSpring(1.2, { damping: 8 }),
        withSpring(1, { damping: 10 })
      );
    }
  }, [currentMilestone, onMilestone]);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
  }));

  const getFireColor = () => {
    if (currentStreak === 0) return theme.custom.colors.gray[400];
    if (currentMilestone === 100) return theme.custom.colors.info;
    if (currentMilestone === 30) return theme.custom.colors.warning[500];
    return theme.custom.colors.primary[500];
  };

  const getAccessibilityLabel = () => {
    if (accessibilityLabel) return accessibilityLabel;
    const streakText = `${currentStreak}-day streak`;
    const bestText = bestStreak > 0 ? `, best ${bestStreak} days` : '';
    const milestoneText = currentMilestone
      ? `, ${MILESTONE_BADGES[currentMilestone].label} achieved`
      : '';
    return `${streakText}${bestText}${milestoneText}`;
  };

  return {
    animatedStyle,
    currentMilestone,
    getAccessibilityLabel,
    getFireColor,
  };
}

import React, { useEffect } from 'react';
import { View, Text } from 'react-native';
import { Pie, PolarChart } from 'victory-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withTiming,
  interpolate,
} from 'react-native-reanimated';
import { styles } from './StrengthDistributionChart.styles';
import {
  CHART_SIZE,
  LEVEL_COLORS,
  STRENGTH_LEVELS,
} from './StrengthDistributionChart.constants';
import { Legend } from './components';
import type {
  StrengthDistributionChartProps,
  ChartDataItem,
} from './StrengthDistributionChart.types';

export default function StrengthDistributionChart({
  data,
  onSegmentPress,
}: StrengthDistributionChartProps) {
  const animationProgress = useSharedValue(0);
  const containerScale = useSharedValue(0);

  useEffect(() => {
    containerScale.value = withSpring(1, { damping: 15, stiffness: 100 });
    animationProgress.value = withTiming(1, { duration: 400 });
  }, [data, animationProgress, containerScale]);

  const containerAnimatedStyle = useAnimatedStyle(() => ({
    opacity: interpolate(containerScale.value, [0, 1], [0, 1]),
    transform: [{ scale: containerScale.value }],
  }));

  if (!data || data.total === 0) {
    return (
      <View style={styles.emptyContainer}>
        <Text style={styles.emptyText}>No habits to display</Text>
        <Text style={styles.emptySubtext}>
          Create your first habit to see analytics
        </Text>
      </View>
    );
  }

  const chartData: ChartDataItem[] = STRENGTH_LEVELS.map((level) => ({
    color: LEVEL_COLORS[level],
    label: `${data[level].percentage.toFixed(0)}%`,
    level,
    value: data[level].count,
  })).filter((item) => item.value > 0);

  return (
    <View style={styles.container}>
      <Animated.View style={[styles.chartContainer, containerAnimatedStyle]}>
        <View style={styles.chartWrapper}>
          <PolarChart
            colorKey='color'
            data={chartData}
            labelKey='label'
            valueKey='value'
          >
            <Pie.Chart innerRadius={CHART_SIZE * 0.3} />
          </PolarChart>
        </View>
        <View style={styles.centerLabel}>
          <Text style={styles.centerLabelValue}>{data.total}</Text>
          <Text style={styles.centerLabelText}>Total Habits</Text>
        </View>
      </Animated.View>
      <Legend data={data} onSegmentPress={onSegmentPress} />
    </View>
  );
}

import React from 'react';
import { View } from 'react-native';
import Svg, { Line, Circle, Path } from 'react-native-svg';

import { useAppTheme } from '../../../theme';
import { styles } from '../StrengthHistoryChart.styles';
import type { ChartPoint } from '../StrengthHistoryChart.types';

interface ChartSvgProps {
  chartWidth: number;
  chartHeight: number;
  padding: number;
  linePath: string;
  points: ChartPoint[];
  height: number;
}

export function ChartSvg({
  chartWidth,
  chartHeight,
  padding,
  linePath,
  points,
  height,
}: ChartSvgProps) {
  const theme = useAppTheme();

  return (
    <View
      style={[
        styles.chartContainer,
        {
          backgroundColor: theme.custom.colors.gray[50],
          borderRadius: theme.custom.borderRadius.medium,
          height,
        },
      ]}
    >
      <Svg height={chartHeight} width={chartWidth}>
        {/* Grid lines */}
        <Line
          stroke={theme.custom.colors.gray[300]}
          strokeWidth='1'
          x1={padding}
          x2={chartWidth - padding}
          y1={chartHeight - padding}
          y2={chartHeight - padding}
        />
        <Line
          stroke={theme.custom.colors.gray[200]}
          strokeDasharray='4,4'
          strokeWidth='1'
          x1={padding}
          x2={chartWidth - padding}
          y1={chartHeight / 2}
          y2={chartHeight / 2}
        />
        <Line
          stroke={theme.custom.colors.gray[300]}
          strokeWidth='1'
          x1={padding}
          x2={chartWidth - padding}
          y1={padding}
          y2={padding}
        />

        {/* Main line path */}
        <Path
          d={linePath}
          fill='none'
          stroke={theme.custom.colors.primary[500]}
          strokeLinecap='round'
          strokeLinejoin='round'
          strokeWidth='2.5'
        />

        {/* Data point circles */}
        {points.map((point, index) => (
          <Circle
            key={index}
            cx={point.x}
            cy={point.y}
            fill={theme.custom.colors.primary[500]}
            r={4}
            stroke={theme.custom.colors.light.background}
            strokeWidth='2'
          />
        ))}
      </Svg>
    </View>
  );
}

import React from 'react';
import { View, Text } from 'react-native';

import { useAppTheme } from '../../../theme';
import { styles } from '../StrengthHistoryChart.styles';
import type { TrendDirection } from '../StrengthHistoryChart.types';

interface StatsRowProps {
  latestStrength: number;
  strengthChange: number;
  trend: TrendDirection;
  dataLength: number;
}

export function StatsRow({
  latestStrength,
  strengthChange,
  trend,
  dataLength,
}: StatsRowProps) {
  const theme = useAppTheme();

  const changeColor =
    trend === 'up'
      ? theme.custom.colors.success[600]
      : trend === 'down'
        ? theme.custom.colors.error[600]
        : theme.custom.colors.gray[600];

  return (
    <View style={styles.statsRow}>
      <View>
        <Text
          style={[
            theme.custom.typography.caption,
            { color: theme.custom.colors.gray[600] },
          ]}
        >
          Current
        </Text>
        <Text
          style={[
            theme.custom.typography.heading3,
            { color: theme.custom.colors.gray[900] },
          ]}
        >
          {latestStrength.toFixed(0)}%
        </Text>
      </View>
      <View style={{ alignItems: 'flex-end' }}>
        <Text
          style={[
            theme.custom.typography.caption,
            { color: theme.custom.colors.gray[600] },
          ]}
        >
          {dataLength}-Day Change
        </Text>
        <Text
          style={[theme.custom.typography.heading3, { color: changeColor }]}
        >
          {strengthChange > 0 ? '+' : ''}
          {strengthChange.toFixed(0)}%
        </Text>
      </View>
    </View>
  );
}

/**
 * StrengthProgressBar Component
 * Horizontal progress bar showing habit strength with level indicators
 */

import React from 'react';
import { View, Text } from 'react-native';
import Animated from 'react-native-reanimated';
import type { StrengthProgressBarProps } from './StrengthProgressBar.types';
import {
  getCurrentLevel,
  getNextLevel,
  formatStrengthPercentage,
  SIZE_CONFIG,
  DIVIDER_POSITIONS,
} from './StrengthProgressBar.constants';
import { useStrengthAnimation } from './useStrengthAnimation';
import { styles } from './StrengthProgressBar.styles';
import { ProgressBarBottomRow } from './ProgressBarBottomRow';

export const StrengthProgressBar = ({
  showDividers = true,
  showEmoji = true,
  showLabel = false,
  showNextLevel = true,
  showPercentage = true,
  size = 'default',
  strength,
}: StrengthProgressBarProps) => {
  const clampedStrength = Math.max(0, Math.min(100, strength));
  const strengthLabel = formatStrengthPercentage(clampedStrength);
  const currentLevel = getCurrentLevel(clampedStrength);
  const nextLevel = getNextLevel(clampedStrength);
  const config = SIZE_CONFIG[size];
  const pointsToNext = nextLevel
    ? Math.round(nextLevel.threshold - clampedStrength)
    : 0;

  const { progressAnimatedStyle, emojiAnimatedStyle } = useStrengthAnimation(
    clampedStrength,
    currentLevel.label
  );

  return (
    <View
      accessible
      accessibilityLabel={`${strengthLabel} strength, ${currentLevel.label} level`}
      accessibilityRole='progressbar'
      style={styles.container}
    >
      <View style={[styles.topRow, { gap: config.gap }]}>
        {showEmoji && (
          <View
            style={[
              styles.emojiContainer,
              {
                height: config.emojiContainerSize,
                width: config.emojiContainerSize,
              },
            ]}
          >
            <Animated.Text
              style={[
                styles.emoji,
                { fontSize: config.emojiSize },
                emojiAnimatedStyle,
              ]}
            >
              {currentLevel.emoji}
            </Animated.Text>
          </View>
        )}

        <View
          style={[
            styles.barContainer,
            {
              backgroundColor: '#e5e7eb',
              borderRadius: config.barHeight / 2,
              height: config.barHeight,
            },
          ]}
        >
          <Animated.View
            style={[
              styles.barFill,
              {
                backgroundColor: currentLevel.color,
                borderRadius: config.barHeight / 2,
              },
              progressAnimatedStyle,
            ]}
          />
          {showDividers &&
            DIVIDER_POSITIONS.map((pos) => (
              <View
                key={pos}
                style={[
                  styles.divider,
                  { height: config.barHeight, left: `${pos}%` },
                ]}
              />
            ))}
        </View>

        {showPercentage && (
          <Text
            style={[
              styles.percentage,
              { color: currentLevel.color, fontSize: config.fontSize },
            ]}
          >
            {strengthLabel}
          </Text>
        )}

        {showNextLevel && nextLevel && (
          <View style={styles.nextLevelContainer}>
            <Text style={[styles.arrow, { fontSize: config.fontSize }]}>→</Text>
            <Text
              style={[styles.nextEmoji, { fontSize: config.emojiSize * 0.85 }]}
            >
              {nextLevel.emoji}
            </Text>
          </View>
        )}
      </View>

      <ProgressBarBottomRow
        config={config}
        currentLevel={currentLevel}
        nextLevel={nextLevel}
        pointsToNext={pointsToNext}
        showLabel={showLabel}
        showNextLevel={showNextLevel}
      />
    </View>
  );
};

export type { StrengthProgressBarProps } from './StrengthProgressBar.types';
export default StrengthProgressBar;

/**
 * useStrengthAnimation Hook
 * Handles progress bar and emoji animations
 */

import { useEffect, useRef } from 'react';
import {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withSequence,
  withTiming,
  withDelay,
  Easing,
} from 'react-native-reanimated';
import { useReduceMotion } from '../../hooks/useReduceMotion';

export function useStrengthAnimation(
  clampedStrength: number,
  currentLevelLabel: string
) {
  const reduceMotion = useReduceMotion();
  const previousLevelRef = useRef<string>(currentLevelLabel);
  const previousStrengthRef = useRef<number>(clampedStrength);
  const isFirstRenderRef = useRef(true);

  const progressWidth = useSharedValue(clampedStrength);
  const emojiScale = useSharedValue(1);
  const emojiOpacity = useSharedValue(1);
  const emojiRotation = useSharedValue(0);

  useEffect(() => {
    if (isFirstRenderRef.current) {
      isFirstRenderRef.current = false;
      progressWidth.value = clampedStrength;
      previousStrengthRef.current = clampedStrength;
      return;
    }

    const previousStrength = previousStrengthRef.current;
    previousStrengthRef.current = clampedStrength;

    const isEmptyingTransition =
      clampedStrength <= 5 && previousStrength > clampedStrength;

    if (reduceMotion) {
      progressWidth.value = clampedStrength;
    } else if (isEmptyingTransition) {
      progressWidth.value = withTiming(clampedStrength, {
        duration: 400,
        easing: Easing.out(Easing.cubic),
      });
    } else {
      progressWidth.value = withSpring(clampedStrength, {
        damping: 15,
        stiffness: 100,
      });
    }

    const levelChanged = previousLevelRef.current !== currentLevelLabel;
    previousLevelRef.current = currentLevelLabel;

    if (reduceMotion) return;

    if (levelChanged) {
      emojiOpacity.value = withTiming(0.3, {
        duration: 150,
        easing: Easing.out(Easing.ease),
      });
      emojiScale.value = withTiming(0.6, {
        duration: 150,
        easing: Easing.out(Easing.ease),
      });
      emojiRotation.value = withSequence(
        withTiming(-8, { duration: 80, easing: Easing.inOut(Easing.ease) }),
        withTiming(8, { duration: 80, easing: Easing.inOut(Easing.ease) }),
        withTiming(0, { duration: 60, easing: Easing.out(Easing.ease) })
      );

      emojiOpacity.value = withDelay(
        150,
        withTiming(1, { duration: 200, easing: Easing.out(Easing.ease) })
      );
      emojiScale.value = withDelay(
        150,
        withSequence(
          withSpring(1.4, { damping: 6, stiffness: 120 }),
          withSpring(1, { damping: 10, stiffness: 180 })
        )
      );
    } else {
      emojiScale.value = withSequence(
        withTiming(1.08, { duration: 100, easing: Easing.out(Easing.ease) }),
        withSpring(1, { damping: 15, stiffness: 200 })
      );
    }
  }, [clampedStrength, currentLevelLabel, reduceMotion]);

  const progressAnimatedStyle = useAnimatedStyle(() => ({
    width: `${progressWidth.value}%`,
  }));

  const emojiAnimatedStyle = useAnimatedStyle(() => ({
    opacity: emojiOpacity.value,
    transform: [
      { scale: emojiScale.value },
      { rotate: `${Math.round(emojiRotation.value)}deg` },
    ],
  }));

  return { emojiAnimatedStyle, progressAnimatedStyle };
}

/**
 * StrengthRing - Apple Watch-style ring visualization for habit strength
 */
import React from 'react';
import { View } from 'react-native';

import Animated from 'react-native-reanimated';
import Svg, { Circle } from 'react-native-svg';

import { LevelLabel } from './LevelLabel';
import { RingCenter } from './RingCenter';
import {
  BACKGROUND_COLOR,
  getLevelInfo,
  SIZE_CONFIG,
} from './StrengthRing.constants';
import { styles } from './StrengthRing.styles';
import type { StrengthRingProps } from './StrengthRing.types';
import { useStrengthRingAnimation } from './useStrengthRingAnimation';

const AnimatedCircle = Animated.createAnimatedComponent(Circle);

export function StrengthRing({
  strength,
  size = 'small',
  showPercentage = false,
  showEmoji = false,
  showLevel = false,
  trend,
  weeklyChange,
}: StrengthRingProps) {
  const clampedStrength = Math.max(0, Math.min(100, strength));
  const config = SIZE_CONFIG[size];
  const { ringSize, strokeWidth, fontSize } = config;
  const radius = (ringSize - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const center = ringSize / 2;

  const levelInfo = getLevelInfo(clampedStrength);
  const { animatedProps, emojiAnimatedStyle } = useStrengthRingAnimation({
    circumference,
    levelLabel: levelInfo.label,
    strength: clampedStrength,
  });

  return (
    <View accessible accessibilityRole='progressbar' style={styles.container}>
      <View
        accessible
        accessibilityLabel={`${Math.round(clampedStrength)}% strength, ${levelInfo.label} level ${levelInfo.emoji}`}
        accessibilityRole='text'
      >
        <View style={{ height: ringSize, width: ringSize }}>
          <Svg height={ringSize} width={ringSize}>
            <Circle
              cx={center}
              cy={center}
              fill='none'
              r={radius}
              stroke={BACKGROUND_COLOR}
              strokeWidth={strokeWidth}
            />
            <AnimatedCircle
              animatedProps={animatedProps}
              cx={center}
              cy={center}
              fill='none'
              origin={`${center}, ${center}`}
              r={radius}
              rotation='-90'
              stroke={levelInfo.color}
              strokeDasharray={circumference}
              strokeDashoffset={circumference}
              strokeLinecap='round'
              strokeWidth={strokeWidth}
            />
          </Svg>
          <RingCenter
            emojiAnimatedStyle={emojiAnimatedStyle}
            fontSize={fontSize}
            levelInfo={levelInfo}
            ringSize={ringSize}
            showEmoji={showEmoji}
            showPercentage={showPercentage}
            strength={clampedStrength}
            trend={trend}
          />
        </View>
        {showLevel && (
          <LevelLabel
            fontSize={fontSize}
            levelInfo={levelInfo}
            weeklyChange={weeklyChange}
          />
        )}
      </View>
    </View>
  );
}

/**
 * useStrengthRingAnimation - Animation logic for the strength ring
 */
import { useEffect, useRef } from 'react';

import {
  Easing,
  useAnimatedProps,
  useAnimatedStyle,
  useSharedValue,
  withDelay,
  withSequence,
  withSpring,
  withTiming,
} from 'react-native-reanimated';

interface UseStrengthRingAnimationOptions {
  strength: number;
  levelLabel: string;
  circumference: number;
}

export function useStrengthRingAnimation({
  strength,
  levelLabel,
  circumference,
}: UseStrengthRingAnimationOptions) {
  const previousLevelRef = useRef<string>(levelLabel);
  const animatedStrength = useSharedValue(strength);
  const emojiScale = useSharedValue(1);
  const emojiOpacity = useSharedValue(1);
  const emojiRotation = useSharedValue(0);

  useEffect(() => {
    animatedStrength.value = withSpring(strength, {
      damping: 15,
      mass: 1,
      overshootClamping: false,
      stiffness: 100,
    });

    const levelChanged = previousLevelRef.current !== levelLabel;
    previousLevelRef.current = levelLabel;

    if (levelChanged) {
      // Phase 1: Fade out + shrink old emoji
      emojiOpacity.value = withTiming(0.3, {
        duration: 150,
        easing: Easing.out(Easing.ease),
      });
      emojiScale.value = withTiming(0.6, {
        duration: 150,
        easing: Easing.out(Easing.ease),
      });
      emojiRotation.value = withSequence(
        withTiming(-8, { duration: 80, easing: Easing.inOut(Easing.ease) }),
        withTiming(8, { duration: 80, easing: Easing.inOut(Easing.ease) }),
        withTiming(0, { duration: 60, easing: Easing.out(Easing.ease) })
      );
      // Phase 2: Fade in + grow new emoji
      emojiOpacity.value = withDelay(
        150,
        withTiming(1, { duration: 200, easing: Easing.out(Easing.ease) })
      );
      emojiScale.value = withDelay(
        150,
        withSequence(
          withSpring(1.4, { damping: 6, stiffness: 120 }),
          withSpring(1, { damping: 10, stiffness: 180 })
        )
      );
    } else {
      // Regular strength update: subtle pulse
      emojiScale.value = withSequence(
        withTiming(1.08, { duration: 100, easing: Easing.out(Easing.ease) }),
        withSpring(1, { damping: 15, stiffness: 200 })
      );
    }
  }, [
    strength,
    levelLabel,
    animatedStrength,
    emojiScale,
    emojiOpacity,
    emojiRotation,
  ]);

  const animatedProps = useAnimatedProps(() => ({
    strokeDashoffset: circumference * (1 - animatedStrength.value / 100),
  }));

  const emojiAnimatedStyle = useAnimatedStyle(() => ({
    opacity: emojiOpacity.value,
    transform: [
      { scale: emojiScale.value },
      { rotate: `${Math.round(emojiRotation.value)}deg` },
    ],
  }));

  return { animatedProps, emojiAnimatedStyle };
}

/**
 * ButtonContent - The main pressable button content
 */

import React from 'react';
import { View, Text, Pressable } from 'react-native';
import { ChevronRight } from 'lucide-react-native';
import * as Haptics from 'expo-haptics';
import { clsx } from 'clsx';

interface ButtonContentProps {
  Icon: React.ComponentType<{
    className?: string;
    size?: number;
    strokeWidth?: number;
  }>;
  label: string;
  subtitle?: string;
  isDestructive: boolean;
  isBoost: boolean;
  showChevron: boolean;
  accessibleLabel: string;
  onPress: () => void;
}

export function ButtonContent({
  Icon,
  label,
  subtitle,
  isDestructive,
  isBoost,
  showChevron,
  accessibleLabel,
  onPress,
}: ButtonContentProps) {
  return (
    <Pressable
      accessibilityLabel={accessibleLabel}
      accessibilityRole='button'
      className={clsx(
        'flex-row items-center gap-3 rounded-xl border px-4 py-3.5 active:opacity-70',
        isDestructive && 'border-red-200/60 bg-red-50/50',
        isBoost &&
          'border-violet-200/60 bg-gradient-to-r from-violet-50 to-indigo-50',
        !isDestructive && !isBoost && 'border-stone-200 bg-white/80'
      )}
      onPress={() => {
        Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
        onPress();
      }}
    >
      <View
        className={clsx(
          'h-10 w-10 items-center justify-center rounded-xl',
          isBoost && 'bg-gradient-to-br from-violet-500 to-indigo-600',
          isDestructive && 'bg-red-100',
          !isBoost && !isDestructive && 'bg-stone-100'
        )}
      >
        <Icon
          className={clsx(
            isDestructive && 'text-red-500',
            isBoost && 'text-white',
            !isDestructive && !isBoost && 'text-stone-600'
          )}
          size={20}
          strokeWidth={2.25}
        />
      </View>
      <View className='flex-1'>
        <Text
          className={clsx(
            'text-base font-medium',
            isDestructive && 'text-red-600',
            isBoost && 'text-violet-900',
            !isDestructive && !isBoost && 'text-stone-800'
          )}
        >
          {label}
        </Text>
        {subtitle && (
          <Text
            className={clsx(
              'text-xs',
              isBoost ? 'text-violet-600' : 'text-stone-500'
            )}
          >
            {subtitle}
          </Text>
        )}
      </View>
      {showChevron && (
        <ChevronRight
          className={clsx(
            isDestructive && 'text-red-400',
            isBoost && 'text-violet-400',
            !isDestructive && !isBoost && 'text-stone-400'
          )}
          size={20}
        />
      )}
    </Pressable>
  );
}

/**
 * SwipeActions - Right swipe action panel
 */

import React from 'react';
import { Text, Pressable, Animated } from 'react-native';
import * as Haptics from 'expo-haptics';
import type { Swipeable } from 'react-native-gesture-handler';
import { styles } from './styles';
import type { SwipeColors } from './types';

interface SwipeActionsProps {
  dragX: Animated.AnimatedInterpolation<number>;
  swipeColors: SwipeColors;
  swipeLabel: string;
  label: string;
  swipeableRef: React.RefObject<Swipeable | null>;
  onSwipeAction?: () => void;
  SwipeIcon: React.ComponentType<{
    color: string;
    size: number;
    strokeWidth: number;
  }>;
}

export function SwipeActions({
  dragX,
  swipeColors,
  swipeLabel,
  label,
  swipeableRef,
  onSwipeAction,
  SwipeIcon,
}: SwipeActionsProps) {
  const trans = dragX.interpolate({
    extrapolate: 'clamp',
    inputRange: [-120, 0],
    outputRange: [0, 120],
  });

  // Progressive icon scale based on swipe progress (0.8 → 1.15)
  const iconScale = dragX.interpolate({
    extrapolate: 'clamp',
    inputRange: [-120, -80, -40, 0],
    outputRange: [1.15, 1.05, 0.9, 0.8],
  });

  // Progressive opacity for icon (0.6 → 1.0)
  const iconOpacity = dragX.interpolate({
    extrapolate: 'clamp',
    inputRange: [-120, -50, 0],
    outputRange: [1, 0.85, 0.6],
  });

  return (
    <Animated.View
      style={[styles.swipeAction, { transform: [{ translateX: trans }] }]}
    >
      <Pressable
        accessibilityLabel={`${swipeLabel} ${label}`}
        accessibilityRole='button'
        style={[styles.swipeActionInner, { backgroundColor: swipeColors.bg }]}
        onPress={() => {
          Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning);
          swipeableRef.current?.close();
          onSwipeAction?.();
        }}
      >
        <Animated.View
          style={[
            styles.swipeIconContainer,
            {
              backgroundColor: swipeColors.iconBg,
              opacity: iconOpacity,
              transform: [{ scale: iconScale }],
            },
          ]}
        >
          <SwipeIcon color={swipeColors.text} size={20} strokeWidth={2} />
        </Animated.View>
        <Text style={[styles.swipeLabel, { color: swipeColors.text }]}>
          {swipeLabel}
        </Text>
      </Pressable>
    </Animated.View>
  );
}

/**
 * SwipeableActionButton Component
 *
 * A swipeable wrapper for action buttons in the Manage tab.
 * - Swipe left reveals a delete/action area
 * - Red background slides in for destructive actions
 * - Requires full swipe or tap to confirm
 * - Supports custom swipe action (delete, archive, etc.)
 */

import React, { useRef } from 'react';
import { Animated } from 'react-native';
import { Swipeable } from 'react-native-gesture-handler';
import { Trash2 } from 'lucide-react-native';
import * as Haptics from 'expo-haptics';
import { getSwipeColors } from './styles';
import { SwipeActions } from './SwipeActions';
import { ButtonContent } from './ButtonContent';
import type { SwipeableActionButtonProps } from './types';

export function SwipeableActionButton({
  icon: Icon,
  label,
  subtitle,
  onPress,
  onSwipeAction,
  showChevron = false,
  variant = 'default',
  swipeEnabled = true,
  swipeIcon: SwipeIcon = Trash2,
  swipeLabel = 'Delete',
  swipeVariant = 'destructive',
}: SwipeableActionButtonProps) {
  const swipeableRef = useRef<Swipeable>(null);
  const isDestructive = variant === 'destructive';
  const isBoost = variant === 'boost';
  const swipeColors = getSwipeColors(swipeVariant);

  // Build accessible label with context
  const accessibleLabel = subtitle
    ? `${label}. ${subtitle}${isDestructive ? '. This is a destructive action.' : ''}${swipeEnabled ? '. Swipe left to reveal action.' : ''}`
    : `${label}${isDestructive ? '. This is a destructive action.' : ''}${swipeEnabled ? '. Swipe left to reveal action.' : ''}`;

  const renderRightActions = (
    _progress: Animated.AnimatedInterpolation<number>,
    dragX: Animated.AnimatedInterpolation<number>
  ) => (
    <SwipeActions
      dragX={dragX}
      label={label}
      swipeableRef={swipeableRef}
      swipeColors={swipeColors}
      SwipeIcon={SwipeIcon}
      swipeLabel={swipeLabel}
      onSwipeAction={onSwipeAction}
    />
  );

  const handleSwipeableOpen = () => {
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning);
    swipeableRef.current?.close();
    onSwipeAction?.();
  };

  const button = (
    <ButtonContent
      accessibleLabel={accessibleLabel}
      Icon={Icon}
      isBoost={isBoost}
      isDestructive={isDestructive}
      label={label}
      showChevron={showChevron}
      subtitle={subtitle}
      onPress={onPress}
    />
  );

  if (!swipeEnabled || !onSwipeAction) {
    return button;
  }

  return (
    <Swipeable
      ref={swipeableRef}
