          positiveVisualization={positiveVisualization}
        />
      </ScrollView>

      {/* Actions */}
      <View className='flex-row gap-3'>
        <Pressable
          accessibilityLabel='Go back to edit'
          accessibilityRole='button'
          className='flex-1 items-center rounded-xl border border-stone-200 bg-white py-3.5 active:bg-stone-50'
          onPress={() => {
            Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
            onBack();
          }}
        >
          <Text className='text-sm font-medium text-stone-600'>Edit</Text>
        </Pressable>
        <Pressable
          accessibilityLabel='Save visualization'
          accessibilityRole='button'
          className='flex-1 flex-row items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-violet-600 to-indigo-600 py-3.5 active:opacity-90'
          onPress={() => {
            Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
            onSave();
          }}
        >
          <Save className='text-white' size={18} />
          <Text className='text-sm font-semibold text-white'>Save</Text>
        </Pressable>
      </View>
    </Animated.View>
  );
}

/**
 * HabitListSection Component
 * Collapsible section for habit lists (gained, lost, at-risk)
 */

import React from 'react';
import { View, Text, TouchableOpacity } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { colors } from '../../theme/colors';
import type { HabitChange, HabitChangeType } from './WeeklyInsightsCard.types';
import { styles } from './WeeklyInsightsCard.styles';
import { HabitItem } from './HabitItem';

interface HabitListSectionProps {
  habits: HabitChange[];
  title: string;
  type: HabitChangeType;
  iconName: string;
  iconColor: string;
  badgeBgColor?: string;
  badgeTextColor?: string;
  isExpanded: boolean;
  onToggle: () => void;
  onHabitPress?: (habitId: string) => void;
  children?: React.ReactNode;
}

export function HabitListSection({
  habits,
  title,
  type,
  iconName,
  iconColor,
  badgeBgColor = '#D1FAE5',
  badgeTextColor = colors.success,
  isExpanded,
  onToggle,
  onHabitPress,
  children,
}: HabitListSectionProps) {
  if (habits.length === 0) return null;

  return (
    <TouchableOpacity
      activeOpacity={0.7}
      style={styles.section}
      onPress={onToggle}
    >
      <View style={styles.sectionHeader}>
        <View style={styles.sectionHeaderLeft}>
          <Ionicons color={iconColor} name={iconName as any} size={20} />
          <Text style={styles.sectionTitle}>{title}</Text>
          <View style={[styles.badge, { backgroundColor: badgeBgColor }]}>
            <Text style={[styles.badgeText, { color: badgeTextColor }]}>
              {habits.length}
            </Text>
          </View>
        </View>
        <Ionicons
          color={colors.text.tertiary}
          name={isExpanded ? 'chevron-up' : 'chevron-down'}
          size={20}
        />
      </View>

      {isExpanded && (
        <View style={styles.sectionContent}>
          {habits.map((habit) => (
            <HabitItem
              key={habit.habitId}
              habit={habit}
              type={type}
              onPress={onHabitPress}
            />
          ))}
          {children}
        </View>
      )}
    </TouchableOpacity>
  );
}

/**
 * SummarySection Component
 * Shows week-over-week summary with overall change and total completions
 */

import React from 'react';
import { View, Text, TouchableOpacity } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { colors } from '../../theme/colors';
import type { WeeklyInsights } from './WeeklyInsightsCard.types';
import { styles } from './WeeklyInsightsCard.styles';
import { summaryStyles } from './SummarySection.styles';

interface SummarySectionProps {
  insights: WeeklyInsights;
  isExpanded: boolean;
  onToggle: () => void;
}

export function SummarySection({
  insights,
  isExpanded,
  onToggle,
}: SummarySectionProps) {
  const isPositive = insights.weekOverWeekChange >= 0;
  const changeColor = isPositive ? colors.success : colors.error;
  const changeIcon = isPositive ? 'trending-up' : 'trending-down';

  return (
    <TouchableOpacity
      activeOpacity={0.7}
      style={styles.section}
      onPress={onToggle}
    >
      <View style={styles.sectionHeader}>
        <View style={styles.sectionHeaderLeft}>
          <Ionicons color={colors.primary[500]} name='calendar' size={20} />
          <Text style={styles.sectionTitle}>This Week's Summary</Text>
        </View>
        <Ionicons
          color={colors.text.tertiary}
          name={isExpanded ? 'chevron-up' : 'chevron-down'}
          size={20}
        />
      </View>

      {isExpanded && (
        <View style={styles.sectionContent}>
          <View style={summaryStyles.summaryCard}>
            <View style={summaryStyles.summaryRow}>
              <Text style={summaryStyles.summaryLabel}>Overall Change</Text>
              <View style={summaryStyles.summaryValueContainer}>
                <Ionicons color={changeColor} name={changeIcon} size={16} />
                <Text
                  style={[summaryStyles.summaryValue, { color: changeColor }]}
                >
                  {insights.weekOverWeekChange > 0 ? '+' : ''}
                  {Math.round(insights.weekOverWeekChange)}%
                </Text>
              </View>
            </View>
            <View style={summaryStyles.summaryDivider} />
            <View style={summaryStyles.summaryRow}>
              <Text style={summaryStyles.summaryLabel}>Total Completions</Text>
              <Text style={summaryStyles.summaryCompletions}>
                {insights.totalCompletionsThisWeek} this week •{' '}
                {insights.totalCompletionsLastWeek} last week
              </Text>
            </View>
          </View>
        </View>
      )}
    </TouchableOpacity>
  );
}

