/**
 * WeeklyInsightsCard Component
 * Main orchestrator for weekly habit insights display
 */

import React, { useState } from 'react';
import { View, Text, TouchableOpacity, ScrollView } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { colors } from '../../theme/colors';
import type { WeeklyInsightsCardProps } from './WeeklyInsightsCard.types';
import { styles } from './WeeklyInsightsCard.styles';
import { SummarySection } from './SummarySection';
import { HabitListSection } from './HabitListSection';
import { SuggestedActions } from './SuggestedActions';

export default function WeeklyInsightsCard({
  insights,
  onHabitPress,
  onArchivePress,
}: WeeklyInsightsCardProps) {
  const [expandedSection, setExpandedSection] = useState<string | null>(
    'summary'
  );

  if (!insights) {
    return (
      <View style={styles.loadingContainer}>
        <Text style={styles.loadingText}>Generating insights...</Text>
      </View>
    );
  }

  const toggleSection = (section: string) => {
    setExpandedSection(expandedSection === section ? null : section);
  };

  return (
    <ScrollView showsVerticalScrollIndicator={false} style={styles.container}>
      <SummarySection
        insights={insights}
        isExpanded={expandedSection === 'summary'}
        onToggle={() => toggleSection('summary')}
      />

      <HabitListSection
        habits={insights.gainedStrength}
        iconColor={colors.success}
        iconName='arrow-up-circle'
        isExpanded={expandedSection === 'gained'}
        title='Habits Gained Strength'
        type='gained'
        onHabitPress={onHabitPress}
        onToggle={() => toggleSection('gained')}
      />

      <HabitListSection
        badgeBgColor='#FEE2E2'
        badgeTextColor={colors.error}
        habits={insights.lostStrength}
        iconColor={colors.error}
        iconName='arrow-down-circle'
        isExpanded={expandedSection === 'lost'}
        title='Habits Lost Strength'
        type='lost'
        onHabitPress={onHabitPress}
        onToggle={() => toggleSection('lost')}
      />

      <HabitListSection
        badgeBgColor='#FEF3C7'
        badgeTextColor={colors.warning[700]}
        habits={insights.atRisk}
        iconColor={colors.warning[500]}
        iconName='warning'
        isExpanded={expandedSection === 'risk'}
        title='Habits at Risk'
        type='risk'
        onHabitPress={onHabitPress}
        onToggle={() => toggleSection('risk')}
      >
        <SuggestedActions />
      </HabitListSection>

      <TouchableOpacity
        activeOpacity={0.7}
        style={styles.archiveButton}
        onPress={onArchivePress}
      >
        <Ionicons color={colors.text.secondary} name='archive' size={20} />
        <Text style={styles.archiveButtonText}>View Past Reports</Text>
      </TouchableOpacity>

      <Text style={styles.generatedDate}>
        Generated {new Date(insights.generatedAt).toLocaleDateString()}
      </Text>
    </ScrollView>
  );
}

/**
 * WeeklySummaryCard Component
 *
 * A celebratory summary card shown at the end of the week.
 */

import { View, Pressable, Animated } from 'react-native';
import { format, parseISO } from 'date-fns';
import type { WeeklySummaryCardProps } from './types';
import { useWeeklySummaryStats } from './useWeeklySummaryStats';
import { useWeeklySummaryAnimations } from './useWeeklySummaryAnimations';
import { getMotivationalMessage, getColorScheme } from './utils';
import {
  CardHeader,
  CompletionRateDisplay,
  StatsGrid,
  BestDayCard,
  StreakHighlight,
} from './components';

export function WeeklySummaryCard({
  weekStats,
  currentStreak = 0,
  reduceMotion = false,
  visible = true,
  onViewDetails,
}: WeeklySummaryCardProps) {
  const stats = useWeeklySummaryStats(weekStats);
  const colors = getColorScheme(stats.completionRate);
  const message = getMotivationalMessage(stats.completionRate);
  const bestDayLabel = stats.bestDay
    ? format(parseISO(stats.bestDay.date), 'EEEE')
    : null;

  const { fadeAnim, slideAnim, celebrationScale, starRotationInterpolate } =
    useWeeklySummaryAnimations({
      completionRate: stats.completionRate,
      reduceMotion,
      visible,
    });

  if (!visible || weekStats.length === 0) return null;

  return (
    <Animated.View
      style={{
        opacity: fadeAnim,
        transform: [{ translateY: slideAnim }, { scale: celebrationScale }],
      }}
    >
      <Pressable
        accessibilityLabel={`Weekly summary: ${stats.completionRate}% completion rate`}
        accessibilityRole='button'
        className='overflow-hidden rounded-3xl'
        style={{
          backgroundColor: colors.bg,
          elevation: 4,
          shadowColor: colors.accent,
          shadowOffset: { height: 8, width: 0 },
          shadowOpacity: 0.15,
          shadowRadius: 16,
        }}
        onPress={onViewDetails}
      >
        <CardHeader
          colors={colors}
          starRotation={starRotationInterpolate}
          onViewDetails={onViewDetails}
        />
        <View className='px-5 py-4'>
          <CompletionRateDisplay
            colors={colors}
            completionRate={stats.completionRate}
            messageText={message.text}
          />
          <StatsGrid
            colors={colors}
            perfectDays={stats.perfectDays}
            totalCompleted={stats.totalCompleted}
            totalPossible={stats.totalPossible}
          />
          {bestDayLabel && stats.bestDayRate > 0 && (
            <BestDayCard
              colors={colors}
              dayLabel={bestDayLabel}
              rate={stats.bestDayRate}
            />
          )}
          <StreakHighlight streak={currentStreak} />
        </View>
      </Pressable>
    </Animated.View>
  );
}

