import { useEffect, useRef } from 'react';
import { Animated, Easing } from 'react-native';
import { createCelebrationAnimations } from './celebrationAnimations';

interface UseWeeklySummaryAnimationsParams {
  visible: boolean;
  reduceMotion: boolean;
  completionRate: number;
}

export function useWeeklySummaryAnimations({
  visible,
  reduceMotion,
  completionRate,
}: UseWeeklySummaryAnimationsParams) {
  const fadeAnim = useRef(new Animated.Value(0)).current;
  const slideAnim = useRef(new Animated.Value(20)).current;
  const celebrationScale = useRef(new Animated.Value(1)).current;
  const starRotation = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    if (!visible) {
      fadeAnim.setValue(0);
      slideAnim.setValue(20);
      return;
    }
    if (reduceMotion) {
      fadeAnim.setValue(1);
      slideAnim.setValue(0);
      return;
    }

    const entranceAnim = Animated.parallel([
      Animated.timing(fadeAnim, {
        duration: 400,
        easing: Easing.out(Easing.cubic),
        toValue: 1,
        useNativeDriver: true,
      }),
      Animated.spring(slideAnim, {
        friction: 8,
        tension: 40,
        toValue: 0,
        useNativeDriver: true,
      }),
    ]);
    entranceAnim.start();

    let celebrationAnim: Animated.CompositeAnimation | null = null;
    let rotationAnim: Animated.CompositeAnimation | null = null;
    if (completionRate >= 75) {
      const anims = createCelebrationAnimations(celebrationScale, starRotation);
      celebrationAnim = anims.celebrationAnim;
      rotationAnim = anims.rotationAnim;
      celebrationAnim.start();
      rotationAnim.start();
    }

    return () => {
      entranceAnim.stop();
      celebrationAnim?.stop();
      rotationAnim?.stop();
      celebrationScale.setValue(1);
      starRotation.setValue(0);
    };
  }, [
    visible,
    reduceMotion,
    completionRate,
    fadeAnim,
    slideAnim,
    celebrationScale,
    starRotation,
  ]);

  const starRotationInterpolate = starRotation.interpolate({
    inputRange: [0, 1],
    outputRange: ['0deg', '360deg'],
  });

  return { celebrationScale, fadeAnim, slideAnim, starRotationInterpolate };
}

/**
 * CompletionCheckmark Component
 *
 * A reusable animated checkmark badge that pops in when a section is completed.
 * Used throughout the Workshop and Reward sections in the Motivation System.
 *
 * Animation:
 * - Delayed entrance with staggered timing based on sectionIndex
 * - Bouncy scale animation (0 -> 1.2 -> 1)
 * - Fade in opacity
 * - Accessibility support via reduceMotion prop
 */

import React, { useEffect } from 'react';
import { View } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withSequence,
  withTiming,
} from 'react-native-reanimated';
import { Check } from 'lucide-react-native';
import {
  SPRING_BOUNCY,
  STAGGER_DELAY,
  BASE_CHECKMARK_DELAY,
} from './constants';

export interface CompletionCheckmarkProps {
  /** Whether the checkmark should be visible */
  isVisible: boolean;
  /** Section index for staggered animation timing */
  sectionIndex: number;
  /** Whether to run entrance animation */
  shouldAnimate: boolean;
  /** When true, skips animations for accessibility */
  reduceMotion?: boolean;
}

export function CompletionCheckmark({
  isVisible,
  sectionIndex,
  shouldAnimate,
  reduceMotion = false,
}: CompletionCheckmarkProps) {
  const scale = useSharedValue(
    isVisible && shouldAnimate && !reduceMotion ? 0 : isVisible ? 1 : 0
  );
  const opacity = useSharedValue(
    isVisible && shouldAnimate && !reduceMotion ? 0 : isVisible ? 1 : 0
  );

  useEffect(() => {
    if (!isVisible) {
      scale.value = 0;
      opacity.value = 0;
      return;
    }

    if (!shouldAnimate || reduceMotion) {
      scale.value = 1;
      opacity.value = 1;
      return;
    }

    const delay = sectionIndex * STAGGER_DELAY + BASE_CHECKMARK_DELAY;

    const timeout = setTimeout(() => {
      scale.value = withSequence(
        withSpring(1.2, SPRING_BOUNCY),
        withSpring(1, { damping: 15, stiffness: 200 })
      );
      opacity.value = withTiming(1, { duration: 150 });
    }, delay);

    return () => clearTimeout(timeout);
  }, [isVisible, shouldAnimate, reduceMotion, sectionIndex, scale, opacity]);

  const animatedStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [{ scale: scale.value }],
  }));

  if (!isVisible) return null;

  return (
    <Animated.View
      style={[
        animatedStyle,
        {
          position: 'absolute',
          right: -4,
          top: -4,
        },
      ]}
    >
      <View className='h-5 w-5 items-center justify-center rounded-full bg-emerald-500 shadow-sm'>
        <Check className='text-white' size={12} strokeWidth={3} />
      </View>
    </Animated.View>
  );
}

