import { useOAuth } from '@clerk/clerk-expo';
import * as Linking from 'expo-linking';
import * as WebBrowser from 'expo-web-browser';
import { useState } from 'react';
import { Alert, View } from 'react-native';

import { AppleLogo, GoogleLogo } from '../logos';
import { Divider } from './Divider';
import { getErrorMessage } from './errorUtils';
import { OAuthButton } from './OAuthButton';

WebBrowser.maybeCompleteAuthSession();

/**
 * SocialLoginButtons - OAuth login buttons for Google and Apple
 */
export function SocialLoginButtons() {
  const { startOAuthFlow: startGoogleFlow } = useOAuth({
    strategy: 'oauth_google',
  });
  const { startOAuthFlow: startAppleFlow } = useOAuth({
    strategy: 'oauth_apple',
  });

  const [googleLoading, setGoogleLoading] = useState(false);
  const [appleLoading, setAppleLoading] = useState(false);

  const anyLoading = googleLoading || appleLoading;

  const handleGoogleSignIn = async () => {
    setGoogleLoading(true);
    try {
      const { createdSessionId, setActive } = await startGoogleFlow({
        redirectUrl: Linking.createURL('/'),
      });

      if (createdSessionId && setActive) {
        await setActive({ session: createdSessionId });
      }
    } catch (err: any) {
      console.error('Google OAuth error:', err);
      const errorMessage = getErrorMessage(err);
      if (errorMessage) {
        Alert.alert('Sign In Failed', errorMessage);
      }
    } finally {
      setGoogleLoading(false);
    }
  };

  const handleAppleSignIn = async () => {
    setAppleLoading(true);
    try {
      const { createdSessionId, setActive } = await startAppleFlow({
        redirectUrl: Linking.createURL('/'),
      });

      if (createdSessionId && setActive) {
        await setActive({ session: createdSessionId });
      }
    } catch (err: any) {
      console.error('Apple OAuth error:', err);
      const errorMessage = getErrorMessage(err);
      if (errorMessage) {
        Alert.alert('Sign In Failed', errorMessage);
      }
    } finally {
      setAppleLoading(false);
    }
  };

  return (
    <View className="gap-3">
      <OAuthButton
        onPress={handleGoogleSignIn}
        loading={googleLoading}
        disabled={anyLoading}
        providerName="GOOGLE"
        loadingColor="#4285F4"
        Logo={GoogleLogo}
        accessibilityLabel="Sign in with Google"
        accessibilityHint="Opens Google sign in flow"
      />
      <OAuthButton
        onPress={handleAppleSignIn}
        loading={appleLoading}
        disabled={anyLoading}
        providerName="APPLE"
        loadingColor="#000000"
        Logo={AppleLogo}
        accessibilityLabel="Sign in with Apple"
        accessibilityHint="Opens Apple sign in flow"
      />
      <Divider />
    </View>
  );
}

import {
  SharedValue,
  useAnimatedStyle,
  useSharedValue,
  withSpring,
} from 'react-native-reanimated';

export function usePressAnimation() {
  const scale = useSharedValue(1);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
  }));

  const handlePressIn = () => {
    scale.value = withSpring(0.98, { damping: 15, stiffness: 300 });
  };

  const handlePressOut = () => {
    scale.value = withSpring(1, { damping: 15, stiffness: 300 });
  };

  return { animatedStyle, handlePressIn, handlePressOut };
}

import { useEffect, useRef } from 'react';
import { Animated, Easing, View } from 'react-native';

interface SparkleBurstProps {
  color?: string;
  isActive: boolean;
  onComplete?: () => void;
  reduceMotion?: boolean;
  size?: number;
}

const DOT_COUNT = 6; // Enhanced sparkle for premium celebrations

export const SparkleBurst = ({
  color = '#34D399',
  isActive,
  onComplete,
  reduceMotion = false,
  size = 40, // Slightly larger for more impact
}: SparkleBurstProps) => {
  const opacity = useRef(new Animated.Value(0)).current;
  const scale = useRef(new Animated.Value(0.6)).current;

  useEffect(() => {
    console.log('🌟 SparkleBurst:', { isActive, reduceMotion, color });

    if (!isActive || reduceMotion) {
      if (isActive && reduceMotion) {
        console.log('🌟 SparkleBurst skipped (reduceMotion enabled)');
        onComplete?.();
      }
      return;
    }

    console.log('🌟 SparkleBurst TRIGGERED!');
    opacity.setValue(0.9); // More prominent for celebration
    scale.setValue(0.6);

    Animated.parallel([
      Animated.timing(opacity, {
        duration: 400, // Slightly longer celebration
        easing: Easing.out(Easing.ease),
        toValue: 0,
        useNativeDriver: true,
      }),
      Animated.timing(scale, {
        duration: 400, // Longer expansion for impact
        easing: Easing.out(Easing.cubic),
        toValue: 1.6, // More expansive celebration
        useNativeDriver: true,
      }),
    ]).start(() => {
      console.log('🌟 SparkleBurst completed');
      onComplete?.();
    });
  }, [isActive, onComplete, opacity, reduceMotion, scale]);

  if (!isActive || reduceMotion) {
    return null;
  }

  const dotSize = size * 0.18; // Small, subtle sparkles

  return (
    <Animated.View
      className='absolute items-center justify-center'
      pointerEvents='none'
      style={{
        height: size,
        opacity,
        transform: [{ scale }],
        width: size,
        zIndex: 1000, // Render ABOVE everything
      }}
    >
      {Array.from({ length: DOT_COUNT }).map((_, index) => {
        const angle = (index / DOT_COUNT) * Math.PI * 2;
        // Round to avoid "Loss of precision during arithmetic conversion" error in Reanimated
        const translateX = Math.round(Math.cos(angle) * (size / 2.2));
        const translateY = Math.round(Math.sin(angle) * (size / 2.2));

        return (
          <Animated.View
            // eslint-disable-next-line react/no-array-index-key
            key={index}
            className='absolute rounded-full'
            style={{
              backgroundColor: color, // Use accent color
              height: dotSize,
              left: size / 2 - dotSize / 2,
              top: size / 2 - dotSize / 2,
              transform: [
                { translateX },
                { translateY },
              ],
              width: dotSize,
              shadowColor: color,
              shadowOffset: { width: 0, height: 0 },
              shadowOpacity: 0.5, // Subtle glow
              shadowRadius: 3,
              elevation: 4,
            }}
          />
        );
      })}

      {/* Center glow - subtle */}
      <View
        className='absolute rounded-full'
        pointerEvents='none'
        style={{
          backgroundColor: `${color}40`, // 25% opacity
          height: dotSize * 2,
          width: dotSize * 2,
          shadowColor: color,
          shadowOffset: { width: 0, height: 0 },
          shadowOpacity: 0.4,
          shadowRadius: 4,
        }}
      />
    </Animated.View>
  );
};

export default SparkleBurst;

