              {periodLabel}
            </Text>
          </View>
        )}
      </View>
      <View className='mt-4 flex-row flex-wrap justify-between gap-y-3'>
        {suggestions.map((habit, index) => (
          <QuickStartButton
            key={`${shuffleCount}-${index}`}
            containerStyle={{ width: '48%' }}
