import { useCallback } from 'react';
import { Pressable, Text } from 'react-native';
import Animated, {
  interpolateColor,
  useAnimatedStyle,
} from 'react-native-reanimated';

import { useHapticFeedback } from '../../../../../hooks/useHapticFeedback';
import { BORDER_RADIUS, COLORS, TOUCH_TARGETS } from '../constants';
import type { SuggestionChip } from '../types';
import { useChipAnimations } from './useChipAnimations';

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

export interface ChipProps {
  chip: SuggestionChip;
  index: number;
  isSelected: boolean;
  onPress: () => void;
  staggerDelay: number;
}

export function Chip({ chip, isSelected, onPress, staggerDelay }: ChipProps) {
  const { triggerSelection } = useHapticFeedback();
  const {
    scale,
    translateY,
    shadowOpacity,
    selectionProgress,
    entranceOpacity,
    entranceTranslateY,
    handlePressIn,
    handlePressOut,
    animatePressScale,
  } = useChipAnimations({ isSelected, staggerDelay });

  const animatedStyle = useAnimatedStyle(() => ({
    backgroundColor: interpolateColor(
      selectionProgress.value,
      [0, 1],
      ['#ffffff', '#047857']
    ),
    borderColor: interpolateColor(
      selectionProgress.value,
      [0, 1],
      [COLORS.stone200, '#047857']
    ),
    opacity: entranceOpacity.value,
    shadowOpacity: shadowOpacity.value,
    transform: [
      { translateY: entranceTranslateY.value + translateY.value },
      { scale: scale.value },
    ],
  }));

  const textStyle = useAnimatedStyle(() => ({
    color: interpolateColor(
      selectionProgress.value,
      [0, 1],
      [COLORS.stone700, '#ffffff']
    ),
  }));

  const handlePress = useCallback(() => {
    triggerSelection();
    animatePressScale();
    onPress();
  }, [onPress, animatePressScale, triggerSelection]);

  return (
    <AnimatedPressable
      accessibilityLabel={`Select ${chip.fullName}`}
      accessibilityRole='button'
      accessibilityState={{ selected: isSelected }}
      style={[
        animatedStyle,
        {
          alignItems: 'center',
          borderRadius: BORDER_RADIUS.chip,
          borderWidth: 1,
          elevation: 1,
          flexDirection: 'row',
          gap: 4,
          minHeight: TOUCH_TARGETS.chipHeight,
          paddingHorizontal: 10,
          paddingVertical: 8,
          shadowColor: '#000000',
          shadowOffset: { height: 1, width: 0 },
          shadowRadius: 2,
        },
      ]}
      onPress={handlePress}
      onPressIn={handlePressIn}
      onPressOut={handlePressOut}
    >
      <Text style={{ fontSize: 15 }}>{chip.emoji}</Text>
      <Animated.Text style={[textStyle, { fontSize: 13, fontWeight: '600' }]}>
        {chip.label}
      </Animated.Text>
    </AnimatedPressable>
  );
}

import { useEffect } from 'react';
import {
  Easing,
  useReducedMotion,
  useSharedValue,
  withDelay,
  withSpring,
  withTiming,
} from 'react-native-reanimated';

import { CHIP_STAGGER, ENTRANCE_DELAYS, SPRING_CONFIGS } from '../animations';
import { useChipPressHandlers } from './useChipPressHandlers';

interface UseChipAnimationsParams {
  isSelected: boolean;
  staggerDelay: number;
}

export function useChipAnimations({
  isSelected,
  staggerDelay,
}: UseChipAnimationsParams) {
  const shouldReduceMotion = useReducedMotion();
  const scale = useSharedValue(1);
  const translateY = useSharedValue(0);
  const shadowOpacity = useSharedValue(0);
  const selectionProgress = useSharedValue(isSelected ? 1 : 0);

  const entranceOpacity = useSharedValue(shouldReduceMotion ? 1 : 0);
  const entranceTranslateY = useSharedValue(
    shouldReduceMotion ? 0 : CHIP_STAGGER.translateY
  );

  const totalEntranceDelay = ENTRANCE_DELAYS.chips + staggerDelay;

  useEffect(() => {
    if (shouldReduceMotion) {
      entranceOpacity.value = 1;
      entranceTranslateY.value = 0;
      return;
    }

    entranceOpacity.value = withDelay(
      totalEntranceDelay,
      withTiming(1, {
        duration: CHIP_STAGGER.duration,
        easing: Easing.out(Easing.ease),
      })
    );

    entranceTranslateY.value = withDelay(
      totalEntranceDelay,
      withTiming(0, {
        duration: CHIP_STAGGER.duration,
        easing: Easing.out(Easing.ease),
      })
    );
  }, [
    entranceOpacity,
    entranceTranslateY,
    shouldReduceMotion,
    totalEntranceDelay,
  ]);

  useEffect(() => {
    if (isSelected) {
      selectionProgress.value = shouldReduceMotion
        ? 1
        : withSpring(1, SPRING_CONFIGS.chipPress);
    } else {
      selectionProgress.value = 0;
    }
  }, [isSelected, selectionProgress, shouldReduceMotion]);

  const pressHandlers = useChipPressHandlers({
    scale,
    shadowOpacity,
    shouldReduceMotion,
    translateY,
  });

  return {
    entranceOpacity,
    entranceTranslateY,
    scale,
    selectionProgress,
    shadowOpacity,
    translateY,
    ...pressHandlers,
  };
}

/**
 * CtaButton - Primary call-to-action button
 *
 * Features:
 * - Disabled state with 40% opacity
 * - Press animation (scale 0.98)
 * - Hover animation (translateY -1px)
 * - Loading state with spinner
 * - Shimmer animation when transitioning from disabled to enabled
 */

import { useCallback, useEffect, useRef } from 'react';
import { ActivityIndicator, Pressable, StyleSheet, Text } from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';
import Animated, {
  Easing,
  interpolate,
  useAnimatedStyle,
  useReducedMotion,
  useSharedValue,
  withSpring,
  withTiming,
} from 'react-native-reanimated';

import { CTA_SHIMMER, CTA_TRANSFORMS, SPRING_CONFIGS } from './animations';
import { BORDER_RADIUS, COLORS, COPY, TOUCH_TARGETS } from './constants';
import type { CtaButtonProps } from './types';

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);
const AnimatedLinearGradient = Animated.createAnimatedComponent(LinearGradient);

/**
 * Primary action button with disabled/loading states
 */
export function CtaButton({ disabled, isLoading, onPress }: CtaButtonProps) {
  const shouldReduceMotion = useReducedMotion();
  const scale = useSharedValue(1);
  const translateY = useSharedValue(0);

  // Track previous disabled state for shimmer trigger
  const wasDisabledRef = useRef(disabled);
  const shimmerProgress = useSharedValue(0);

  // Trigger shimmer when disabled changes from true to false
  useEffect(() => {
    const wasDisabled = wasDisabledRef.current;
    wasDisabledRef.current = disabled;

    // Only shimmer on enable transition (disabled: true -> false)
    // Skip shimmer if reduced motion is enabled
    if (wasDisabled && !disabled && !shouldReduceMotion) {
      shimmerProgress.value = 0;
      shimmerProgress.value = withTiming(1, {
        duration: CTA_SHIMMER.duration,
        easing: Easing.inOut(Easing.ease),
      });
    }
  }, [disabled, shimmerProgress, shouldReduceMotion]);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ translateY: translateY.value }, { scale: scale.value }],
  }));

  // Shimmer gradient animation style
  const shimmerAnimatedStyle = useAnimatedStyle(() => {
    // Animate the gradient from left to right across the button
    // Start off-screen left (-100%), end off-screen right (100%)
    const translateX = interpolate(shimmerProgress.value, [0, 1], [-100, 100]);
    return {
      opacity: shimmerProgress.value > 0 && shimmerProgress.value < 1 ? 1 : 0,
      transform: [{ translateX: `${translateX}%` as unknown as number }],
    };
  });

  const handlePressIn = useCallback(() => {
    if (disabled || isLoading || shouldReduceMotion) return;
    scale.value = withSpring(
      CTA_TRANSFORMS.pressScale,
      SPRING_CONFIGS.ctaPress
    );
  }, [disabled, isLoading, scale, shouldReduceMotion]);

  const handlePressOut = useCallback(() => {
    if (shouldReduceMotion) return;
    scale.value = withSpring(1, SPRING_CONFIGS.ctaPress);
    translateY.value = withSpring(0, SPRING_CONFIGS.ctaPress);
  }, [scale, shouldReduceMotion, translateY]);

  const handlePress = useCallback(() => {
    if (disabled || isLoading) return;
    onPress();
  }, [disabled, isLoading, onPress]);

  const isDisabled = disabled || isLoading;

  return (
    <AnimatedPressable
      accessibilityHint={
        isDisabled ? 'Enter a habit name first' : 'Creates your new habit'
      }
      accessibilityLabel={COPY.ctaButton}
      accessibilityRole='button'
      accessibilityState={{ disabled: isDisabled }}
      disabled={isDisabled}
      style={[
        animatedStyle,
        {
          alignItems: 'center',
          // Using emerald-700 for WCAG AA contrast (5.21:1 with white text)
          backgroundColor: '#047857',
          borderRadius: BORDER_RADIUS.cta,
          elevation: isDisabled ? 0 : 4,
          height: TOUCH_TARGETS.ctaHeight,
          justifyContent: 'center',
          opacity: isDisabled ? 0.4 : 1,
          overflow: 'hidden',
          paddingVertical: 16,

          // Required for shimmer to clip at button edges
          // Shadow for depth
          shadowColor: '#047857',
          shadowOffset: { width: 0, height: 4 },
          shadowOpacity: 0.3,
          shadowRadius: 8,
          width: '100%',
        },
      ]}
      onPress={handlePress}
      onPressIn={handlePressIn}
      onPressOut={handlePressOut}
    >
      {/* Shimmer overlay - sweeps across when button becomes enabled */}
      <AnimatedLinearGradient
        colors={[
          'transparent',
          `rgba(255, 255, 255, ${CTA_SHIMMER.gradientOpacity})`,
          'transparent',
        ]}
        end={{ x: 1, y: 0.5 }}
        start={{ x: 0, y: 0.5 }}
        style={[
          StyleSheet.absoluteFillObject,
          { width: '100%' },
          shimmerAnimatedStyle,
        ]}
        testID='cta-shimmer-overlay'
      />
      {isLoading ? (
        <ActivityIndicator color='#ffffff' size='small' />
      ) : (
        <Text
          style={{
            color: '#ffffff',
            fontSize: 15,
            fontWeight: '600',
          }}
        >
          {COPY.ctaButton}
        </Text>
      )}
    </AnimatedPressable>
  );
}

/**
 * Animation hooks for ErrorMessage
 */

import { useCallback, useEffect } from 'react';
import Animated, {
  Easing,
  runOnJS,
  useAnimatedStyle,
  useReducedMotion,
  useSharedValue,
  withSequence,
  withTiming,
} from 'react-native-reanimated';

import { ERROR_ANIMATION } from '../animations';

interface UseErrorAnimationsParams {
  onDismiss: () => void;
  autoDismiss: boolean;
}

export function useErrorAnimations({
  onDismiss,
  autoDismiss,
}: UseErrorAnimationsParams) {
  const shouldReduceMotion = useReducedMotion();
  const opacity = useSharedValue(0);
  const translateY = useSharedValue(-10);
  const translateX = useSharedValue(0);

  const handleDismiss = useCallback(() => {
    opacity.value = withTiming(0, { duration: 150 }, (finished) => {
      if (finished) {
        runOnJS(onDismiss)();
      }
    });
  }, [onDismiss, opacity]);

  useEffect(() => {
    if (shouldReduceMotion) {
      opacity.value = 1;
      translateY.value = 0;
      return;
    }

    const {
      entranceDuration,
      shakeDuration,
      shakeDistance,
      shakeOscillations,
    } = ERROR_ANIMATION;

    opacity.value = withTiming(1, {
      duration: entranceDuration,
      easing: Easing.out(Easing.ease),
    });
    translateY.value = withTiming(0, {
      duration: entranceDuration,
      easing: Easing.out(Easing.ease),
    });

    const segmentDuration = shakeDuration / (shakeOscillations * 2);
    const shakeSequence = [];
    for (let i = 0; i < shakeOscillations; i++) {
      shakeSequence.push(
        withTiming(shakeDistance, { duration: segmentDuration }),
        withTiming(-shakeDistance, { duration: segmentDuration })
      );
    }
    shakeSequence.push(withTiming(0, { duration: segmentDuration }));

    setTimeout(() => {
      translateX.value = withSequence(...shakeSequence);
    }, entranceDuration);
  }, [opacity, shouldReduceMotion, translateX, translateY]);

  useEffect(() => {
    if (!autoDismiss) return;

    const timer = setTimeout(() => {
      handleDismiss();
    }, ERROR_ANIMATION.autoDismissDelay);

    return () => clearTimeout(timer);
  }, [autoDismiss, handleDismiss]);

  const animatedStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [
      { translateY: translateY.value },
      { translateX: translateX.value },
    ],
  }));

  return { animatedStyle, handleDismiss };
}

