/**
 * SuccessContent - Text and action content for success state
 *
 * Displays headline, subtext, tap hint, and add another button.
 */

import { Pressable, Text, ViewStyle } from 'react-native';
import Animated, { AnimatedStyle } from 'react-native-reanimated';

import { BORDER_RADIUS, COLORS, COPY, TOUCH_TARGETS } from './constants';

interface SuccessContentProps {
  habitName: string;
  autoTransition: boolean;
  contentStyle: AnimatedStyle<ViewStyle>;
  tapHintStyle: AnimatedStyle<ViewStyle>;
  onAddAnother: () => void;
}

export function SuccessContent({
  habitName,
  autoTransition,
  contentStyle,
  tapHintStyle,
  onAddAnother,
}: SuccessContentProps) {
  return (
    <Animated.View
      style={[contentStyle, { alignItems: 'center', width: '100%' }]}
    >
      {/* Headline */}
      <Text
        style={{
          color: COLORS.stone800,
          fontSize: 24,
          fontWeight: '700',
          marginBottom: 8,
          textAlign: 'center',
        }}
      >
        {COPY.successHeadline}
      </Text>

      {/* Subtext */}
      <Text
        style={{
          color: COLORS.stone500,
          fontSize: 13,
          marginBottom: 24,
          textAlign: 'center',
        }}
      >
        {COPY.successSubtext(habitName)}
      </Text>

      {/* Tap to continue hint - only show if auto-transitioning */}
      {autoTransition && (
        <Animated.Text
          style={[
            tapHintStyle,
            {
              color: COLORS.stone500,
              fontSize: 13,
              textAlign: 'center',
            },
          ]}
        >
          Tap anywhere to continue
        </Animated.Text>
      )}

      {/* Add another button - only show if not auto-transitioning */}
      {!autoTransition && (
        <Pressable
          accessibilityHint='Creates another habit'
          accessibilityLabel={COPY.addAnother}
          accessibilityRole='button'
          style={({ pressed }) => ({
            alignItems: 'center',
            backgroundColor: COLORS.stone800,
            borderRadius: BORDER_RADIUS.cta,
            height: TOUCH_TARGETS.ctaHeight,
            justifyContent: 'center',
            opacity: pressed ? 0.9 : 1,
            transform: [{ scale: pressed ? 0.98 : 1 }],
            width: '100%',
          })}
          onPress={onAddAnother}
        >
          <Text
            style={{
              color: '#ffffff',
              fontSize: 15,
              fontWeight: '700',
            }}
          >
            {COPY.addAnother}
          </Text>
        </Pressable>
      )}
    </Animated.View>
  );
}

/**
 * SuccessIcon - Icon container with progress ring and particle burst
 *
 * Displays the success emoji surrounded by visual effects.
 * The progress ring shows countdown to auto-transition.
 */

import { Text, View, ViewStyle } from 'react-native';
import Animated, { AnimatedStyle } from 'react-native-reanimated';

import { PROGRESS_RING, PARTICLE_BURST } from './animations';
import { COLORS } from './constants';
import { ParticleBurst } from './ParticleBurst';
import { ProgressRing } from './ProgressRing';

interface SuccessIconProps {
  emoji: string;
  autoTransition: boolean;
  iconStyle: AnimatedStyle<ViewStyle>;
  ringStyle: AnimatedStyle<ViewStyle>;
  burstStyle: AnimatedStyle<ViewStyle>;
}

export function SuccessIcon({
  emoji,
  autoTransition,
  iconStyle,
  ringStyle,
  burstStyle,
}: SuccessIconProps) {
  return (
    <Animated.View
      style={[
        iconStyle,
        {
          alignItems: 'center',
          height: PROGRESS_RING.size,
          justifyContent: 'center',
          marginBottom: 24,
          width: PROGRESS_RING.size,
        },
      ]}
    >
      {/* Progress Ring - Behind the icon, shows countdown */}
      {autoTransition && (
        <Animated.View
          style={[
            ringStyle,
            {
              height: PROGRESS_RING.size,
              position: 'absolute',
              width: PROGRESS_RING.size,
            },
          ]}
        >
          <ProgressRing
            duration={PROGRESS_RING.duration}
            size={PROGRESS_RING.size}
          />
        </Animated.View>
      )}

      {/* Particle Burst - Positioned behind icon */}
      <Animated.View
        style={[
          burstStyle,
          {
            height: PROGRESS_RING.size,
            position: 'absolute',
            width: PROGRESS_RING.size,
          },
        ]}
      >
        <ParticleBurst
          distance={PARTICLE_BURST.distance}
          duration={PARTICLE_BURST.duration}
        />
      </Animated.View>

      {/* Success Icon Emoji */}
      <View
        style={{
          alignItems: 'center',
          backgroundColor: COLORS.successBackground,
          borderRadius: 48,
          height: 96,
          justifyContent: 'center',
          width: 96,
          zIndex: 10,
        }}
      >
        <Text style={{ fontSize: 48 }}>{emoji}</Text>
      </View>
    </Animated.View>
  );
}

/**
 * SuccessState - Post-creation celebration screen
 *
 * Features:
 * - Pop animation on the success icon
 * - Confetti particles floating upward
 * - Habit name confirmation
 * - Auto-transition to habit list with shared element animation
 * - Tap anywhere to skip and transition immediately
 * - Haptic feedback on mount
 * - "Add another habit" button to reset (if staying on empty state)
 */

import { useEffect, useCallback } from 'react';
import { AccessibilityInfo, Pressable } from 'react-native';
import Animated, { useReducedMotion } from 'react-native-reanimated';

import { useHapticFeedback } from '../../../../hooks/useHapticFeedback';
import { Confetti } from './Confetti';
import { SuccessContent } from './SuccessContent';
import { SuccessIcon } from './SuccessIcon';
import type { SuccessStateProps } from './types';
import { useSuccessStateAnimations } from './useSuccessStateAnimations';

export function SuccessState({
  habitName,
  habitEmoji,
  onAddAnother,
  onTransitionComplete,
  autoTransition = true,
}: SuccessStateProps) {
  const shouldReduceMotion = useReducedMotion();
  const { triggerSuccess } = useHapticFeedback();

  const displayEmoji = habitEmoji || '🌿';

  const {
    iconStyle,
    contentStyle,
    containerStyle,
    tapHintStyle,
    ringStyle,
    burstStyle,
    triggerExitAnimation,
  } = useSuccessStateAnimations({
    autoTransition,
    onTransitionComplete,
    shouldReduceMotion,
  });

  // Tap to skip handler
  const handleTapToSkip = useCallback(() => {
    if (!autoTransition || !onTransitionComplete) return;
    triggerExitAnimation();
  }, [autoTransition, onTransitionComplete, triggerExitAnimation]);

  // Haptic feedback on mount + accessibility announcement
  useEffect(() => {
    triggerSuccess();

    const message = `Success! ${habitName} has been added to your habits. Tap anywhere to continue.`;
    AccessibilityInfo?.announceForAccessibility?.(message);
  }, [habitName, triggerSuccess]);

  return (
    <Pressable
      accessibilityHint='Skip the celebration and view your habit list'
      accessibilityLabel='Tap to continue to your habits'
      accessibilityRole='button'
      style={{ flex: 1 }}
      onPress={handleTapToSkip}
    >
      <Animated.View
        style={[
          containerStyle,
          {
            alignItems: 'center',
            flex: 1,
            justifyContent: 'center',
          },
        ]}
      >
        <Confetti shouldReduceMotion={shouldReduceMotion ?? false} />

        <SuccessIcon
          autoTransition={autoTransition}
          burstStyle={burstStyle}
          emoji={displayEmoji}
          iconStyle={iconStyle}
          ringStyle={ringStyle}
        />

        <SuccessContent
          autoTransition={autoTransition}
          contentStyle={contentStyle}
          habitName={habitName}
          tapHintStyle={tapHintStyle}
          onAddAnother={onAddAnother}
        />
      </Animated.View>
    </Pressable>
  );
}

/**
 * SuggestionChips - Tappable habit suggestion pills
 *
 * Features:
 * - Pyramid layout (3-2-1 formation)
 * - Selection state with emerald highlight
 * - Staggered entrance animation (50ms between each chip)
 */

import { useCallback, useEffect, useRef } from 'react';
import { View } from 'react-native';

import { useTimeBasedChipAnalytics } from './analytics';
import { CHIP_STAGGER } from './animations';
import { Chip } from './Chip';
import type { SuggestionChip, SuggestionChipsProps } from './types';
import { getTimeBasedChips } from './utils';

export function SuggestionChips({
  selectedIndex,
  onSelect,
}: SuggestionChipsProps) {
  const chips = getTimeBasedChips();
  const analytics = useTimeBasedChipAnalytics();
  const displayTimestampRef = useRef<number>(0);
  const previousSelectedChipRef = useRef<{
    chip: SuggestionChip;
    index: number;
  } | null>(null);

  useEffect(() => {
    displayTimestampRef.current = Date.now();
    analytics.trackChipsDisplayed(chips);
  }, [chips, analytics]);

  const handleChipSelect = useCallback(
    (index: number, chip: SuggestionChip) => {
      if (previousSelectedChipRef.current && selectedIndex !== null) {
        analytics.trackChipDeselected(
          previousSelectedChipRef.current.chip,
          previousSelectedChipRef.current.index
        );
      }

      analytics.trackChipSelected(chip, index);
      previousSelectedChipRef.current = { chip, index };
      onSelect(index, chip);
    },
    [analytics, onSelect, selectedIndex]
  );

  const row1 = chips.slice(0, 3);
  const row2 = chips.slice(3, 5);
  const row3 = chips.slice(5, 6);

  const rowStyle = {
    flexDirection: 'row' as const,
    gap: 6,
    justifyContent: 'center' as const,
  };

  return (
    <View style={{ alignItems: 'center', gap: 6, width: '100%' }}>
      <View style={rowStyle}>
        {row1.map((chip, i) => (
          <Chip
            key={chip.label}
            chip={chip}
            index={i}
            isSelected={selectedIndex === i}
            staggerDelay={i * CHIP_STAGGER.delay}
            onPress={() => handleChipSelect(i, chip)}
          />
        ))}
      </View>

      <View style={rowStyle}>
        {row2.map((chip, i) => {
          const index = i + 3;
          return (
            <Chip
              key={chip.label}
              chip={chip}
              index={index}
              isSelected={selectedIndex === index}
              staggerDelay={index * CHIP_STAGGER.delay}
              onPress={() => handleChipSelect(index, chip)}
            />
          );
        })}
      </View>

      <View style={{ ...rowStyle, flexWrap: 'wrap', gap: 8 }}>
        {row3.map((chip, i) => {
          const index = i + 5;
          return (
            <Chip
              key={chip.label}
              chip={chip}
              index={index}
              isSelected={selectedIndex === index}
              staggerDelay={index * CHIP_STAGGER.delay}
              onPress={() => handleChipSelect(index, chip)}
            />
          );
        })}
      </View>
    </View>
  );
}

import { useCallback, useRef, useState } from 'react';
import { useTimeBasedChipAnalytics } from './analytics';
import type { SuggestionChip } from './types';
import { getTimeBasedChips } from './utils';

export function useChipSelection() {
  const analytics = useTimeBasedChipAnalytics();
  const displayTimestampRef = useRef<number>(Date.now());
  const selectedChipDataRef = useRef<SuggestionChip | null>(null);

  const [inputValue, setInputValue] = useState('');
  const [selectedChipIndex, setSelectedChipIndex] = useState<number | null>(
    null
  );
  const [selectedEmoji, setSelectedEmoji] = useState<string | null>(null);

  const handleChipSelect = useCallback(
    (index: number, chip: SuggestionChip) => {
      if (selectedChipIndex === index) {
        setSelectedChipIndex(null);
        setSelectedEmoji(null);
        setInputValue('');
        selectedChipDataRef.current = null;
      } else {
        setSelectedChipIndex(index);
        setSelectedEmoji(chip.emoji);
        setInputValue(chip.fullName);
        selectedChipDataRef.current = chip;
      }
    },
    [selectedChipIndex]
  );

  const handleInputChange = useCallback(
    (text: string) => {
      setInputValue(text);
      if (selectedChipIndex !== null) {
        setSelectedChipIndex(null);
        setSelectedEmoji(null);
        selectedChipDataRef.current = null;

        if (text.trim().length > 0) {
          const chips = getTimeBasedChips();
          analytics.trackManualInputAfterChipView(text, chips);
        }
      }
    },
    [selectedChipIndex, analytics]
  );

  const resetSelection = useCallback(() => {
    setInputValue('');
    setSelectedChipIndex(null);
    setSelectedEmoji(null);
    selectedChipDataRef.current = null;
  }, []);

  const trackChipConversion = useCallback(
    (chipIndex: number) => {
      if (selectedChipDataRef.current) {
        analytics.trackChipConvertedToHabit(
          selectedChipDataRef.current,
          chipIndex,
          displayTimestampRef.current
        );
      }
    },
    [analytics]
  );

  return {
    handleChipSelect,
    handleInputChange,
    inputValue,
    resetSelection,
    selectedChipIndex,
    selectedEmoji,
    setInputValue,
    trackChipConversion,
  };
}

/**
 * useConfettiParticleAnimation - Animation hook for confetti particles
 *
 * Manages the floating, spinning, and fading animation for confetti.
 */

import { useEffect } from 'react';
import {
  useSharedValue,
  useAnimatedStyle,
  withDelay,
  withTiming,
  Easing,
} from 'react-native-reanimated';

import { CONFETTI_CONFIG } from './animations';

interface UseConfettiParticleAnimationParams {
  delay: number;
  shouldReduceMotion: boolean;
}

export function useConfettiParticleAnimation({
  delay,
  shouldReduceMotion,
}: UseConfettiParticleAnimationParams) {
  const translateY = useSharedValue(0);
  const translateX = useSharedValue(0);
  const opacity = useSharedValue(shouldReduceMotion ? 0 : 1);
  const scale = useSharedValue(1);
  const rotation = useSharedValue(0);

  useEffect(() => {
    if (shouldReduceMotion) {
      opacity.value = 0;
      return;
    }

    const drift = Math.round((Math.random() - 0.5) * 100);
    const startX = Math.round((Math.random() - 0.5) * 200);

    translateX.value = startX;
    translateY.value = 50;

    translateY.value = withDelay(
      delay,
      withTiming(-300, {
        duration: CONFETTI_CONFIG.duration,
        easing: Easing.out(Easing.quad),
      })
    );
    translateX.value = withDelay(
      delay,
      withTiming(startX + drift, { duration: CONFETTI_CONFIG.duration })
    );
    opacity.value = withDelay(
      delay,
      withTiming(0, {
        duration: CONFETTI_CONFIG.duration,
        easing: Easing.in(Easing.ease),
      })
    );
    rotation.value = withDelay(
      delay,
      withTiming(Math.round(Math.random() * 360), {
        duration: CONFETTI_CONFIG.duration,
      })
    );
    scale.value = withDelay(
      delay + 200,
      withTiming(0.5, { duration: CONFETTI_CONFIG.duration - 200 })
    );
  }, [
    delay,
    opacity,
    rotation,
    scale,
    shouldReduceMotion,
    translateX,
    translateY,
  ]);

  const particleStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [
      { translateX: translateX.value },
      { translateY: translateY.value },
      { rotate: `${Math.round(rotation.value)}deg` },
      { scale: scale.value },
    ],
  }));

  return { particleStyle };
}

import { useCallback, useState } from 'react';
import { Keyboard, TextInput } from 'react-native';
import { useHapticFeedback } from '../../../../hooks/useHapticFeedback';
import { useChipSelection } from './useChipSelection';

interface UseHabitCreationFlowParams {
  onQuickCreateHabit: (habitName: string) => Promise<void>;
  inputRef: React.RefObject<TextInput>;
}

export function useHabitCreationFlow({
  onQuickCreateHabit,
  inputRef,
}: UseHabitCreationFlowParams) {
  const { triggerSuccess } = useHapticFeedback();
  const chipSelection = useChipSelection();

  const [isCreating, setIsCreating] = useState(false);
  const [successHabitName, setSuccessHabitName] = useState<string | null>(null);
  const [successEmoji, setSuccessEmoji] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const handleCreateHabit = useCallback(async () => {
    if (!chipSelection.inputValue.trim() || isCreating) return;

    Keyboard.dismiss();
    setIsCreating(true);
    setErrorMessage(null);

    try {
      await onQuickCreateHabit(chipSelection.inputValue.trim());
      triggerSuccess();
      setSuccessHabitName(chipSelection.inputValue.trim());
      setSuccessEmoji(chipSelection.selectedEmoji);

      if (chipSelection.selectedChipIndex !== null) {
        chipSelection.trackChipConversion(chipSelection.selectedChipIndex);
      }
    } catch (error) {
      setIsCreating(false);
      setErrorMessage(
        error instanceof Error
          ? error.message
          : 'Failed to create habit. Please try again.'
      );
    }
  }, [chipSelection, isCreating, onQuickCreateHabit, triggerSuccess]);

  const handleSubmitEditing = useCallback(() => {
    if (chipSelection.inputValue.trim() && !isCreating) {
      handleCreateHabit();
    }
  }, [chipSelection.inputValue, isCreating, handleCreateHabit]);

  const handleClearInput = useCallback(() => {
    chipSelection.resetSelection();
    inputRef.current?.focus();
  }, [chipSelection, inputRef]);

  const handleAddAnother = useCallback(() => {
    setSuccessHabitName(null);
    setSuccessEmoji(null);
    setIsCreating(false);
    chipSelection.resetSelection();
    setTimeout(() => inputRef.current?.focus(), 100);
  }, [chipSelection, inputRef]);

  const handleDismissError = useCallback(() => {
    setErrorMessage(null);
  }, []);

  return {
    errorMessage,
    handleChipSelect: chipSelection.handleChipSelect,
    handleAddAnother,
    handleClearInput,
    handleCreateHabit,
    inputValue: chipSelection.inputValue,
    handleDismissError,
    isCreating,
    handleInputChange: chipSelection.handleInputChange,
    selectedChipIndex: chipSelection.selectedChipIndex,
    handleSubmitEditing,
    successEmoji,
    successHabitName,
  };
}

import {
  useAnimatedStyle,
  useReducedMotion,
  withTiming,
  Easing,
} from 'react-native-reanimated';
import { KEYBOARD_LAYOUT } from './animations';

interface UseKeyboardLayoutAnimationsParams {
  isKeyboardVisible: boolean;
  bottomInset: number;
}

export function useKeyboardLayoutAnimations({
  isKeyboardVisible,
  bottomInset,
}: UseKeyboardLayoutAnimationsParams) {
  const shouldReduceMotion = useReducedMotion();

  const timingConfig = {
    duration: shouldReduceMotion ? 0 : KEYBOARD_LAYOUT.transitionDuration,
    easing: Easing.out(Easing.ease),
  };

  const containerAnimatedStyle = useAnimatedStyle(() => ({
    justifyContent: isKeyboardVisible ? 'flex-start' : 'center',
    paddingBottom: withTiming(
      isKeyboardVisible ? 0 : bottomInset + 20,
      timingConfig
    ),
    paddingTop: withTiming(
      isKeyboardVisible ? KEYBOARD_LAYOUT.topPadding : 0,
      timingConfig
    ),
  }));

  const heroAnimatedStyle = useAnimatedStyle(() => ({
    transform: [
      {
        scale: withTiming(
          isKeyboardVisible ? KEYBOARD_LAYOUT.compactHeroSize / 80 : 1,
          timingConfig
        ),
      },
    ],
  }));

  const headlineAnimatedStyle = useAnimatedStyle(() => ({
    fontSize: withTiming(
      isKeyboardVisible ? KEYBOARD_LAYOUT.compactHeadlineFontSize : 24,
      timingConfig
    ),
    marginBottom: withTiming(isKeyboardVisible ? 16 : 32, timingConfig),
    marginTop: withTiming(isKeyboardVisible ? 16 : 32, timingConfig),
  }));

  const chipsAnimatedStyle = useAnimatedStyle(() => ({
    marginBottom: withTiming(isKeyboardVisible ? 0 : 32, timingConfig),
    maxHeight: withTiming(isKeyboardVisible ? 0 : 200, timingConfig),
    opacity: withTiming(isKeyboardVisible ? 0 : 1, timingConfig),
    overflow: 'hidden' as const,
  }));

  const secondaryLinksAnimatedStyle = useAnimatedStyle(() => ({
    maxHeight: withTiming(isKeyboardVisible ? 0 : 100, timingConfig),
    opacity: withTiming(isKeyboardVisible ? 0 : 1, timingConfig),
    overflow: 'hidden' as const,
  }));

  return {
    chipsAnimatedStyle,
    containerAnimatedStyle,
    headlineAnimatedStyle,
    heroAnimatedStyle,
    secondaryLinksAnimatedStyle,
  };
}

/**
 * useSuccessExitAnimation - Exit animation for SuccessState
 *
 * Handles the shared element transition when exiting success state.
 */

import { useCallback, useRef } from 'react';
import {
  SharedValue,
  useSharedValue,
  useAnimatedStyle,
  withDelay,
  withTiming,
  withSpring,
  runOnJS,
  Easing,
} from 'react-native-reanimated';

import { EXIT_TRANSITION, EXIT_SPRING_CONFIG } from './animations';
import { useAutoTransitionTimer } from './useAutoTransitionTimer';

interface UseSuccessExitAnimationParams {
  shouldReduceMotion: boolean | null;
  autoTransition: boolean;
  onTransitionComplete?: () => void;
  iconScale: SharedValue<number>;
  contentOpacity: SharedValue<number>;
}

export function useSuccessExitAnimation({
  shouldReduceMotion,
  autoTransition,
  onTransitionComplete,
  iconScale,
  contentOpacity,
}: UseSuccessExitAnimationParams) {
  const isExiting = useRef(false);
  const autoTransitionTimeout = useRef<NodeJS.Timeout | null>(null);

  const iconTranslateY = useSharedValue(0);
  const iconExitScale = useSharedValue(1);
  const containerOpacity = useSharedValue(1);
  const ringOpacity = useSharedValue(1);
  const burstOpacity = useSharedValue(1);

  const triggerExitAnimation = useCallback(() => {
    if (isExiting.current) return;
    isExiting.current = true;

    if (autoTransitionTimeout.current) {
      clearTimeout(autoTransitionTimeout.current);
      autoTransitionTimeout.current = null;
    }

    if (shouldReduceMotion) {
      onTransitionComplete?.();
      return;
    }

    ringOpacity.value = withTiming(0, {
      duration: EXIT_TRANSITION.content.duration,
      easing: Easing.out(Easing.ease),
    });
    burstOpacity.value = withTiming(0, {
      duration: EXIT_TRANSITION.content.duration,
      easing: Easing.out(Easing.ease),
    });
    iconTranslateY.value = withSpring(
      EXIT_TRANSITION.icon.translateY,
      EXIT_SPRING_CONFIG
    );
    iconExitScale.value = withTiming(EXIT_TRANSITION.icon.scale, {
      duration: EXIT_TRANSITION.icon.duration,
      easing: Easing.out(Easing.cubic),
    });
    contentOpacity.value = withTiming(0, {
      duration: EXIT_TRANSITION.content.duration,
      easing: Easing.out(Easing.ease),
    });
    containerOpacity.value = withDelay(
      EXIT_TRANSITION.onCompleteDelay,
      withTiming(0, { duration: 200 }, (finished) => {
        if (finished && onTransitionComplete) {
          runOnJS(onTransitionComplete)();
        }
      })
    );
  }, [
    shouldReduceMotion,
    onTransitionComplete,
    iconTranslateY,
    iconExitScale,
    contentOpacity,
    containerOpacity,
    ringOpacity,
    burstOpacity,
  ]);

  useAutoTransitionTimer({
    autoTransition,
    containerOpacity,
    iconExitScale,
    iconTranslateY,
    onTransitionComplete,
    triggerExitAnimation,
  });

  const iconStyle = useAnimatedStyle(() => ({
    transform: [
      { scale: iconScale.value * iconExitScale.value },
      { translateY: iconTranslateY.value },
    ],
  }));
  const containerStyle = useAnimatedStyle(() => ({
    opacity: containerOpacity.value,
  }));
  const ringStyle = useAnimatedStyle(() => ({ opacity: ringOpacity.value }));
  const burstStyle = useAnimatedStyle(() => ({ opacity: burstOpacity.value }));

  return {
    burstStyle,
    containerStyle,
    iconStyle,
    ringStyle,
    triggerExitAnimation,
  };
}

/**
 * useTapHintAnimation - Pulsing animation for "Tap anywhere to continue"
 *
 * Creates a subtle pulse effect to draw attention to the hint text.
 */

import { useEffect } from 'react';
import {
  useSharedValue,
  useAnimatedStyle,
  withDelay,
  withSequence,
  withTiming,
  withRepeat,
  cancelAnimation,
  Easing,
} from 'react-native-reanimated';

import { TAP_HINT_PULSE } from './animations';

interface UseTapHintAnimationParams {
  shouldReduceMotion: boolean | null;
  autoTransition: boolean;
}

export function useTapHintAnimation({
  shouldReduceMotion,
  autoTransition,
}: UseTapHintAnimationParams) {
  const tapHintOpacity = useSharedValue(0);
  const tapHintScale = useSharedValue(TAP_HINT_PULSE.minScale);

  useEffect(() => {
    if (!autoTransition) return;

    if (shouldReduceMotion) {
      tapHintOpacity.value = withDelay(
        800,
        withTiming(TAP_HINT_PULSE.maxOpacity, { duration: 300 })
      );
      tapHintScale.value = TAP_HINT_PULSE.minScale;
      return;
    }

    tapHintOpacity.value = withDelay(
      800,
      withSequence(
        withTiming(TAP_HINT_PULSE.maxOpacity, {
          duration: 300,
          easing: Easing.out(Easing.ease),
        }),
        withRepeat(
          withSequence(
            withTiming(TAP_HINT_PULSE.minOpacity, {
              duration: TAP_HINT_PULSE.duration / 2,
              easing: Easing.inOut(Easing.ease),
            }),
            withTiming(TAP_HINT_PULSE.maxOpacity, {
              duration: TAP_HINT_PULSE.duration / 2,
              easing: Easing.inOut(Easing.ease),
            })
          ),
          -1,
          false
        )
      )
    );

    tapHintScale.value = withDelay(
      1100,
      withRepeat(
        withSequence(
          withTiming(TAP_HINT_PULSE.maxScale, {
            duration: TAP_HINT_PULSE.duration / 2,
            easing: Easing.inOut(Easing.ease),
          }),
          withTiming(TAP_HINT_PULSE.minScale, {
            duration: TAP_HINT_PULSE.duration / 2,
            easing: Easing.inOut(Easing.ease),
          })
        ),
        -1,
        false
      )
    );

    return () => {
      cancelAnimation(tapHintOpacity);
      cancelAnimation(tapHintScale);
    };
  }, [autoTransition, shouldReduceMotion, tapHintOpacity, tapHintScale]);

  const tapHintStyle = useAnimatedStyle(() => ({
    opacity: tapHintOpacity.value,
    transform: [{ scale: tapHintScale.value }],
  }));

  return { tapHintStyle };
}

import { View } from 'react-native';
import { DailyMomentumMeter } from '../../../../components/DailyMomentumMeter';
import { useTemplateTooltip } from '../../hooks/useTemplateTooltip';
import { useTemplateBadge } from '../../hooks/useTemplateBadge';
import type { HabitsHeaderProps } from './types';
import { useHeaderAnimations } from './useHeaderAnimations';
import { useHeaderHandlers } from './useHeaderHandlers';
import { AddHabitButton } from './AddHabitButton';
import { IconButtonGroup } from './IconButtonGroup';

export function HabitsHeader({
  completedToday = 0,
  forceShow = false,
  openCreateHabitScreen,
  openSettings,
  openSortSheet,
  openTemplatesScreen,
  reduceMotion = false,
  showCompletionSummary = true,
  totalHabits = 0,
}: HabitsHeaderProps) {
  const { dismissTooltip, showTooltip } = useTemplateTooltip();
  const { showBadge, dismissBadge } = useTemplateBadge({ totalHabits });

  const animations = useHeaderAnimations();
  const handlers = useHeaderHandlers({
    addButtonScale: animations.addButtonScale,
    dismissBadge,
    openCreateHabitScreen,
    openSettings,
    openSortSheet,
    openTemplatesScreen,
    settingsButtonScale: animations.settingsButtonScale,
    sortButtonScale: animations.sortButtonScale,
    templatesButtonScale: animations.templatesButtonScale,
  });

  // Calculate completion percentage for accessibility
  const percentage =
    totalHabits > 0 ? Math.round((completedToday / totalHabits) * 100) : 0;

  // Smart Empty State - hide header completely when user has no habits
  if (totalHabits === 0 && !forceShow) {
    return null;
  }

  return (
    <View className='gap-2'>
      <View className='flex-row items-center justify-between'>
        <AddHabitButton
          animatedStyle={animations.addButtonAnimatedStyle}
          onPress={handlers.handleAddHabitPress}
          onPressIn={handlers.handleAddHabitPressIn}
          onPressOut={handlers.handleAddHabitPressOut}
        />
        <IconButtonGroup
          settingsAnimatedStyle={animations.settingsButtonAnimatedStyle}
          showBadge={showBadge}
          showTooltip={showTooltip}
          sortAnimatedStyle={animations.sortButtonAnimatedStyle}
          templatesAnimatedStyle={animations.templatesButtonAnimatedStyle}
          onDismissTooltip={dismissTooltip}
          onSettingsPress={handlers.handleSettingsPress}
          onSettingsPressIn={handlers.handleSettingsPressIn}
          onSettingsPressOut={handlers.handleSettingsPressOut}
          onSortPress={handlers.handleSortPress}
          onSortPressIn={handlers.handleSortPressIn}
          onSortPressOut={handlers.handleSortPressOut}
          onTemplatesPress={handlers.handleTemplatesPress}
          onTemplatesPressIn={handlers.handleTemplatesPressIn}
          onTemplatesPressOut={handlers.handleTemplatesPressOut}
        />
      </View>

      {showCompletionSummary && (
        <View
          accessibilityLabel={`Today ${completedToday} of ${totalHabits} complete, ${percentage} percent`}
          accessibilityRole='text'
        >
          <DailyMomentumMeter
            completedToday={completedToday}
            reduceMotion={reduceMotion}
            size='standard'
            totalHabits={totalHabits}
          />
        </View>
      )}
    </View>
  );
}

