import { useEffect } from 'react';
import { Gesture } from 'react-native-gesture-handler';
import {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withTiming,
  runOnJS,
  Easing,
} from 'react-native-reanimated';

import { useHapticFeedback } from '../../../../hooks/useHapticFeedback';
import type { HabitSortMode } from '../../types';
import {
  DISMISS_THRESHOLD,
  SCREEN_HEIGHT,
  SHEET_SPRING_CONFIG,
  VELOCITY_THRESHOLD,
} from './constants';

interface UseSortBottomSheetOptions {
  visible: boolean;
  reduceMotion: boolean;
  onClose: () => void;
  onSelectSortMode: (mode: HabitSortMode) => void;
}

export function useSortBottomSheet({
  visible,
  reduceMotion,
  onClose,
  onSelectSortMode,
}: UseSortBottomSheetOptions) {
  const { triggerSelection, triggerLightImpact } = useHapticFeedback({});

  const translateY = useSharedValue(SCREEN_HEIGHT);
  const backdropOpacity = useSharedValue(0);

  useEffect(() => {
    if (visible) {
      backdropOpacity.value = reduceMotion
        ? 0.4
        : withTiming(0.4, { duration: 300, easing: Easing.out(Easing.cubic) });
      translateY.value = reduceMotion ? 0 : withSpring(0, SHEET_SPRING_CONFIG);
    } else {
      backdropOpacity.value = reduceMotion
        ? 0
        : withTiming(0, { duration: 250, easing: Easing.in(Easing.cubic) });
      translateY.value = reduceMotion
        ? SCREEN_HEIGHT
        : withSpring(SCREEN_HEIGHT, SHEET_SPRING_CONFIG);
    }
  }, [visible, reduceMotion, backdropOpacity, translateY]);

  const panGesture = Gesture.Pan()
    .onUpdate((event) => {
      if (event.translationY > 0) {
        translateY.value = event.translationY;
      }
    })
    .onEnd((event) => {
      const velocityY = Math.round(event.velocityY);
      if (
        event.translationY > DISMISS_THRESHOLD ||
        velocityY > VELOCITY_THRESHOLD
      ) {
        translateY.value = withSpring(SCREEN_HEIGHT, SHEET_SPRING_CONFIG);
        runOnJS(triggerLightImpact)();
        runOnJS(onClose)();
      } else {
        translateY.value = withSpring(0, SHEET_SPRING_CONFIG);
      }
    });

  const backdropStyle = useAnimatedStyle(() => ({
    opacity: backdropOpacity.value,
  }));

  const sheetStyle = useAnimatedStyle(() => ({
    transform: [{ translateY: translateY.value }],
  }));

  const handleSelectSort = (mode: HabitSortMode) => {
    triggerSelection();
    onSelectSortMode(mode);
    onClose();
  };

  const handleDismiss = () => {
    triggerLightImpact();
    onClose();
  };

  return {
    backdropStyle,
    handleDismiss,
    handleSelectSort,
    panGesture,
    sheetStyle,
  };
}

import { ChevronRight, LayoutList } from 'lucide-react-native';
