import { useCallback, useState } from 'react';
import { useMutation, useQuery } from 'convex/react';
import { api } from '../../../../convex/_generated/api';
import type { Id } from '../../../../convex/_generated/dataModel';
import type { Habit, HabitSettings, HabitSortMode } from '../types';
import { useHabitsWeekDates } from './useHabitsWeekDates';
import { useHabitsTracking } from './useHabitsTracking';
import { useHabitsSorting } from './useHabitsSorting';
import { useHabitsArchive } from './useHabitsArchive';
import { useRewardToast } from './useRewardToast';
import type { HabitsListState } from './types';

const FREE_HABIT_LIMIT = 3;

export function useHabitsListState(): HabitsListState {
  const [showHabitStrengthPercentage, setShowHabitStrengthPercentage] =
    useState(true);

  const toggleHabitMutation = useMutation(api.habits.toggleHabit);
  const reorderHabits = useMutation(api.habits.reorderHabits);

  const habitsQuery = useQuery(api.habits.list);
  const habitsFromQuery = habitsQuery ?? [];
  const isHabitsLoading = habitsQuery === undefined;

  const settingsQuery = useQuery(api.settings.get);
  const settings = (settingsQuery ?? undefined) as HabitSettings | undefined;
  const celebrationsEnabled = settings?.showMotivationalMessages ?? true;
  const dayShape = settings?.dayShape ?? 'square';
  const habitSortMode: HabitSortMode = settings?.habitSortMode ?? 'manual';
  const habitCompletionIcon = settings?.habitCompletionIcon ?? 'chain';
  const reduceMotionPreference = settings?.reduceMotion ?? false;
  const isPremiumUser = settings?.hasPremium ?? false;
  const showWeekCompletionBar = settings?.showWeekCompletionBar ?? true;

  const weekDatesState = useHabitsWeekDates();
  const { today, extendedDateStrings } = weekDatesState;
  const { getStreak, getHabitStatus } = useHabitsTracking(
    extendedDateStrings,
    today
  );

  const habits = useHabitsSorting({
    getStreak,
    habitsFromQuery,
    habitSortMode,
  });

  const archiveState = useHabitsArchive(habits);
  const rewardState = useRewardToast(celebrationsEnabled, getStreak);

  const habitSlotsUsed = isPremiumUser
    ? habits.length
    : Math.min(habits.length, FREE_HABIT_LIMIT);
  const hasReachedHabitLimit =
    !isPremiumUser && habits.length >= FREE_HABIT_LIMIT;

  const openCreateHabitScreen = useCallback(() => {
    // Handled by parent component
  }, []);

  const handleDragEnd = useCallback(
    async ({ data }: { data: Habit[] }) => {
      if (habitSortMode !== 'manual') return;
      try {
        const habitIds = data.map((h) => h._id);
        await reorderHabits({ habitIds });
      } catch (error) {
        console.error('Failed to reorder habits:', error);
      }
    },
    [habitSortMode, reorderHabits]
  );

  const handleHabitPress = useCallback((_habit: Habit) => {
    // Handled by parent component
  }, []);

  const toggleHabit = useCallback(
    async (args: { habitId: Id<'habits'>; date: string }) => {
      await toggleHabitMutation(args);
    },
    [toggleHabitMutation]
  );

  return {
    canNavigateForward: weekDatesState.canNavigateForward,
    celebrationsEnabled,
    dayShape,
    freeHabitLimit: FREE_HABIT_LIMIT,
    contentPadding: { paddingHorizontal: 24, paddingBottom: 96, paddingTop: 0 },
    habitCompletionIcon,
    habits,
    habitSortMode,
    hasReachedHabitLimit,
    isHabitsLoading,
    showHabitStrengthPercentage,
    showWeekCompletionBar,
    weekDates: weekDatesState.weekDates,
    weekDateStrings: weekDatesState.weekDateStrings,
    ...archiveState,
    ...rewardState,
    getHabitStatus,
    getStreak,
    habitSlotsUsed,
    handleDragEnd,
    handleHabitPress,
    handleNextWeek: weekDatesState.handleNextWeek,
    handlePreviousWeek: weekDatesState.handlePreviousWeek,
    isPremiumUser,
    openCreateHabitScreen,
    reduceMotionPreference,
    toggleHabit,
  };
}

import { useCallback } from 'react';
import type { Id } from '../../../../convex/_generated/dataModel';
import type { Habit, HabitSettings, HabitSettingsUpdate, ShareCardData } from '../types';

interface ModalsSetters {
  setIsCreateHabitOpen: (v: boolean) => void;
  setHabitToEdit: (h: Habit | null) => void;
  setShowShareCard: (v: boolean) => void;
  setShareCardData: (d: ShareCardData | null) => void;
  setSelectedHabit: (h: Habit | null) => void;
  setHabitDetailInitialTab: (t: 'progress' | 'motivation' | 'manage') => void;
  setIsHabitDetailOpen: (v: boolean) => void;
  setIsHabitCalendarOpen: (v: boolean) => void;
  setHabitToPause: (h: Habit | null) => void;
  setShowPauseModal: (v: boolean) => void;
  setShowEditScreen: (v: boolean) => void;
  setShowQuickActions: (v: boolean) => void;
  setQuickActionsHabit: (h: Habit | null) => void;
  setShowVisualizationExercise: (v: boolean) => void;
  setShowActivationModal: (v: boolean) => void;
  setActivationModalHabit: (h: Habit | null) => void;
}

interface ModalsHandlersDeps {
  habits: Habit[];
  settings: HabitSettings | undefined;
  clearMilestone: () => void;
  updateSettings: (s: HabitSettings) => Promise<void>;
  removeHabit: (args: { habitId: Id<'habits'> }) => Promise<void>;
  pauseHabit: (args: { habitId: Id<'habits'> }) => Promise<void>;
  habitToPause: Habit | null;
}

export function useHabitsModalsHandlers(
  setters: ModalsSetters,
  deps: ModalsHandlersDeps
) {
  const { habits, settings, clearMilestone, updateSettings, removeHabit, pauseHabit, habitToPause } = deps;

  const closeCreateHabit = useCallback(() => {
    setters.setIsCreateHabitOpen(false);
    setters.setHabitToEdit(null);
  }, []);

  const closeShareCard = useCallback(() => {
    setters.setShowShareCard(false);
    setters.setShareCardData(null);
    clearMilestone();
  }, [clearMilestone]);

  const openHabitDetail = useCallback(
    (habit: Habit, initialTab: 'progress' | 'motivation' | 'manage' = 'progress') => {
      setters.setSelectedHabit(habit);
      setters.setHabitDetailInitialTab(initialTab);
      setters.setIsHabitDetailOpen(true);
    },
    []
  );

  const openHabitCalendar = useCallback((habit: Habit) => {
    setters.setSelectedHabit(habit);
    setters.setIsHabitCalendarOpen(true);
  }, []);

  const openPauseModal = useCallback(
    (habitId: Id<'habits'>) => {
      const habit = habits.find((h) => h._id === habitId);
      if (habit) {
        setters.setHabitToPause(habit);
        setters.setShowPauseModal(true);
      }
    },
    [habits]
  );

  const openEditHabit = useCallback((habit: Habit | null) => {
    setters.setHabitToEdit(habit);
    if (habit) {
      setters.setShowEditScreen(true);
    }
  }, []);

  const closeEditScreen = useCallback(() => {
    setters.setShowEditScreen(false);
    setters.setHabitToEdit(null);
  }, []);

  const openCreateHabitScreen = useCallback(() => {
    setters.setIsCreateHabitOpen(true);
    setters.setHabitToEdit(null);
  }, []);

  const onSettingsChange = useCallback(
    async (updates: Partial<HabitSettingsUpdate>) => {
      if (!settings) return;
      await updateSettings({ ...settings, ...updates });
    },
    [settings, updateSettings]
  );

  const onDeleteHabit = useCallback(
    async (habitId: Id<'habits'>) => {
      await removeHabit({ habitId });
      setters.setIsHabitDetailOpen(false);
      setters.setSelectedHabit(null);
    },
    [removeHabit]
  );

  const confirmPause = useCallback(async () => {
    if (!habitToPause) return;
    await pauseHabit({ habitId: habitToPause._id });
    setters.setShowPauseModal(false);
    setters.setHabitToPause(null);
    setters.setIsHabitDetailOpen(false);
  }, [habitToPause, pauseHabit]);

  // Quick Actions
  const openQuickActions = useCallback((habit: Habit) => {
    setters.setQuickActionsHabit(habit);
    setters.setShowQuickActions(true);
  }, []);

  const closeQuickActions = useCallback(() => {
    setters.setShowQuickActions(false);
    setters.setQuickActionsHabit(null);
  }, []);

  // Visualization Exercise
  const openVisualizationExercise = useCallback((habit: Habit) => {
    setters.setSelectedHabit(habit);
    setters.setShowVisualizationExercise(true);
  }, []);

  const closeVisualizationExercise = useCallback(() => {
    setters.setShowVisualizationExercise(false);
  }, []);

  // Activation Modal
  const openActivationModal = useCallback((habit: Habit) => {
    setters.setActivationModalHabit(habit);
    setters.setShowActivationModal(true);
  }, []);

  const openActivationModalById = useCallback(
    (habitId: string) => {
      const habit = habits.find((h) => h._id === habitId);
      if (habit) {
        setters.setActivationModalHabit(habit);
        setters.setShowActivationModal(true);
      }
    },
    [habits]
  );

  const closeActivationModal = useCallback(() => {
    setters.setShowActivationModal(false);
    setters.setActivationModalHabit(null);
  }, []);

  const onShareMilestone = useCallback((data: ShareCardData) => {
    setters.setShareCardData(data);
    setters.setShowShareCard(true);
  }, []);

  return {
    closeCreateHabit,
    closeShareCard,
    openHabitDetail,
    openHabitCalendar,
    openPauseModal,
    openEditHabit,
    closeEditScreen,
    openCreateHabitScreen,
    onSettingsChange,
    onDeleteHabit,
    confirmPause,
    openQuickActions,
    closeQuickActions,
    openVisualizationExercise,
    closeVisualizationExercise,
    openActivationModal,
    openActivationModalById,
    closeActivationModal,
    onShareMilestone,
  };
}

import { useCallback, useState } from 'react';
import { useQuery } from 'convex/react';
import { api } from '../../../../convex/_generated/api';
import type { Id } from '../../../../convex/_generated/dataModel';
import type { Habit, HabitSettings, ShareCardData } from '../types';
import { useHabitMutations } from './useHabitMutations';
import { useHabitMilestones } from './useHabitMilestones';
import { useHabitsTracking } from './useHabitsTracking';
import { useHabitStateSync } from './useHabitStateSync';
import { useHabitsModalsHandlers } from './useHabitsModalsHandlers';
import type { HabitsModalsState } from './types';

interface UseHabitsModalsStateProps {
  habits: Habit[];
  showHabitStrengthPercentage: boolean;
}

export function useHabitsModalsState({
  habits,
  showHabitStrengthPercentage,
}: UseHabitsModalsStateProps): HabitsModalsState {
  // Modal visibility states
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isCreateHabitOpen, setIsCreateHabitOpen] = useState(false);
  const [isHabitCalendarOpen, setIsHabitCalendarOpen] = useState(false);
  const [isHabitDetailOpen, setIsHabitDetailOpen] = useState(false);
  const [showShareCard, setShowShareCard] = useState(false);
  const [showPauseModal, setShowPauseModal] = useState(false);
  const [showEditScreen, setShowEditScreen] = useState(false);
  const [showHapticTest, setShowHapticTest] = useState(false);
  const [showTemplatesScreen, setShowTemplatesScreen] = useState(false);
  const [showQuickActions, setShowQuickActions] = useState(false);
  const [showVisualizationExercise, setShowVisualizationExercise] =
    useState(false);
  const [showActivationModal, setShowActivationModal] = useState(false);

  // Habit states for modals
  const [selectedHabit, setSelectedHabit] = useState<Habit | null>(null);
  const [habitToPause, setHabitToPause] = useState<Habit | null>(null);
  const [habitToEdit, setHabitToEdit] = useState<Habit | null>(null);
  const [quickActionsHabit, setQuickActionsHabit] = useState<Habit | null>(
    null
  );
  const [activationModalHabit, setActivationModalHabit] =
    useState<Habit | null>(null);

  // Other states
  const [habitDetailInitialTab, setHabitDetailInitialTab] = useState<
    'progress' | 'motivation' | 'manage'
  >('progress');
  const [shareCardData, setShareCardData] = useState<ShareCardData | null>(
    null
  );

  // Hooks
  const { pauseHabit, removeHabit, updateSettings, toggleHabit, archiveHabit } =
    useHabitMutations();
  const { milestone, clearMilestone } = useHabitMilestones(habits, false);

  const settingsQuery = useQuery(api.settings.get);
  const settings = (settingsQuery ?? undefined) as HabitSettings | undefined;
  const celebrationsEnabled = settings?.showMotivationalMessages ?? true;
  const reduceMotionPreference = settings?.reduceMotion ?? false;

  // Tracking
  const extendedDateStrings = Array.from({ length: 365 }, (_, i) => {
    const date = new Date();
    date.setDate(date.getDate() - i);
    return date.toISOString().split('T')[0];
  });
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const { tracking, getStreak } = useHabitsTracking(extendedDateStrings, today);

  // Sync habit snapshots with source of truth
  useHabitStateSync(habits, selectedHabit, setSelectedHabit, 'selectedHabit');
  useHabitStateSync(habits, habitToEdit, setHabitToEdit);
  useHabitStateSync(habits, habitToPause, setHabitToPause);
  useHabitStateSync(habits, quickActionsHabit, setQuickActionsHabit);
  useHabitStateSync(habits, activationModalHabit, setActivationModalHabit);

  // Handlers from extracted hook
  const handlers = useHabitsModalsHandlers(
    {
      setIsCreateHabitOpen,
      setHabitToEdit,
      setShowShareCard,
      setShareCardData,
      setSelectedHabit,
      setHabitDetailInitialTab,
      setIsHabitDetailOpen,
      setIsHabitCalendarOpen,
      setHabitToPause,
      setShowPauseModal,
      setShowEditScreen,
      setShowQuickActions,
      setQuickActionsHabit,
      setShowVisualizationExercise,
      setShowActivationModal,
      setActivationModalHabit,
    },
    {
      habits,
      settings,
      clearMilestone,
      updateSettings,
      removeHabit,
      pauseHabit,
      habitToPause,
    }
  );

  const handleArchive = useCallback(
    async (habitId: Id<'habits'>) => {
      await archiveHabit({ habitId });
    },
    [archiveHabit]
  );

  const onChangeCelebrationsEnabled = useCallback(
    async (value: boolean) => {
      await handlers.onSettingsChange({ showMotivationalMessages: value });
    },
    [handlers]
  );

  const handleToggleHabit = useCallback(
    async (args: { habitId: Id<'habits'>; date: string }) => {
      await toggleHabit(args);
    },
    [toggleHabit]
  );

  return {
    // State
    celebrationsEnabled,
    habits,
    settings,
    showSettings: isSettingsOpen,
    showCreateHabit: isCreateHabitOpen,
    showEditScreen,
    showHabitCalendar: isHabitCalendarOpen,
    showHabitDetail: isHabitDetailOpen,
    habitDetailInitialTab,
    showHapticTest,
    showShareCard,
    showPauseModal,
    showTemplatesScreen,
    showQuickActions,
    showVisualizationExercise,
    showActivationModal,
    activationModalHabit,
    habitToEdit,
    habitToPause,
    selectedHabit,
    quickActionsHabit,
    shareCardData,
    milestone,
    tracking,
    showHabitStrengthPercentage,
    reduceMotionPreference,

    // Handlers
    closeSettings: () => setIsSettingsOpen(false),
    openSettings: () => setIsSettingsOpen(true),
    openCreateHabitScreen: handlers.openCreateHabitScreen,
    onChangeCelebrationsEnabled,
    setShowHabitStrengthPercentage: () => {},
    closeCreateHabit: handlers.closeCreateHabit,
    closeEditScreen: handlers.closeEditScreen,
    closeHabitCalendar: () => setIsHabitCalendarOpen(false),
    closeHabitDetail: () => setIsHabitDetailOpen(false),
    closeShareCard: handlers.closeShareCard,
    closePauseModal: () => {
      setShowPauseModal(false);
      setHabitToPause(null);
    },
    openHapticTest: () => {
      setIsSettingsOpen(false);
      setShowHapticTest(true);
    },
    closeHapticTest: () => setShowHapticTest(false),
    openTemplatesScreen: () => setShowTemplatesScreen(true),
    closeTemplatesScreen: () => setShowTemplatesScreen(false),
    openHabitDetail: handlers.openHabitDetail,
    openHabitCalendar: handlers.openHabitCalendar,
    openPauseModal: handlers.openPauseModal,
    openEditHabit: handlers.openEditHabit,
    openQuickActions: handlers.openQuickActions,
    closeQuickActions: handlers.closeQuickActions,
    openVisualizationExercise: handlers.openVisualizationExercise,
    closeVisualizationExercise: handlers.closeVisualizationExercise,
    openActivationModal: handlers.openActivationModal,
    openActivationModalById: handlers.openActivationModalById,
    closeActivationModal: handlers.closeActivationModal,
    onSettingsChange: handlers.onSettingsChange,
    onDeleteHabit: handlers.onDeleteHabit,
    onShareMilestone: handlers.onShareMilestone,
    clearMilestone,
    confirmPause: handlers.confirmPause,
    toggleHabit: handleToggleHabit,
    getStreak,
    handleArchive,
  };
}

import { format } from 'date-fns';
import { useCallback, useMemo } from 'react';
import { useQuery } from 'convex/react';

import { api } from '../../../../convex/_generated/api';
import { computeCurrentStreakFromDates } from '../../../utils/streak';
import type { HabitTrackingEntry, HabitStatus } from '../types';

export function useHabitsTracking(extendedDateStrings: string[], today: Date) {
  const tracking =
    useQuery(api.habits.getTracking, { dates: extendedDateStrings }) ?? [];

  const completedDatesByHabit = useMemo(() => {
    const map = new Map<string, Set<string>>();
    for (const entry of tracking) {
      if (!entry.completed) continue;
      if (!map.has(entry.habitId)) {
        map.set(entry.habitId, new Set<string>());
      }
      map.get(entry.habitId)!.add(entry.date);
    }
    return map;
  }, [tracking]);

  const getStreak = useCallback(
    (habitId: string) => {
      const completedDates = completedDatesByHabit.get(habitId);
      if (!completedDates) return 0;
      return computeCurrentStreakFromDates(completedDates, today);
    },
    [completedDatesByHabit, today]
  );

  const getHabitStatus = useCallback(
    (habitId: string, dateString: string): HabitStatus => {
      const entry = tracking.find(
        (item) => item.habitId === habitId && item.date === dateString
      );

      if (entry?.completed) {
        return 'done';
      }

      const [year, month, day] = dateString.split('-').map(Number);
      const date = new Date(year, month - 1, day);
      date.setHours(0, 0, 0, 0);

      if (date < today) {
        return 'missed';
      }
      return 'planned';
    },
    [today, tracking]
  );

  return { tracking: tracking as HabitTrackingEntry[], getStreak, getHabitStatus };
}

import { addDays, eachDayOfInterval, format, startOfDay, subMonths } from 'date-fns';
import { useCallback, useMemo, useState } from 'react';

export function useHabitsWeekDates() {
  const today = useMemo(() => startOfDay(new Date()), []);
  const [weekAnchor, setWeekAnchor] = useState(today);

  const weekDates = useMemo(
    () => Array.from({ length: 5 }, (_, index) => addDays(weekAnchor, index - 4)),
    [weekAnchor]
  );

  const weekDateStrings = useMemo(
    () => weekDates.map((date) => format(date, 'yyyy-MM-dd')),
    [weekDates]
  );

  const extendedDateRange = useMemo(() => {
    const endDate = today;
    const startDate = subMonths(endDate, 12);
    return eachDayOfInterval({ start: startDate, end: endDate });
  }, [today]);

  const extendedDateStrings = useMemo(
    () => extendedDateRange.map((date) => format(date, 'yyyy-MM-dd')),
    [extendedDateRange]
  );

  const canNavigateForward = useMemo(
    () => weekAnchor.getTime() < today.getTime(),
    [today, weekAnchor]
  );

  const handlePreviousWeek = useCallback(() => {
    setWeekAnchor((prev) => addDays(prev, -5));
  }, []);

  const handleNextWeek = useCallback(() => {
    setWeekAnchor((prev) => addDays(prev, 5));
  }, []);

  return {
    today,
    weekDates,
    weekDateStrings,
    extendedDateStrings,
    canNavigateForward,
    handleNextWeek,
    handlePreviousWeek,
  };
}

