/**
 * AnalyticsScreen - Main analytics dashboard screen
 * Shows habit statistics, charts, and insights
 */
import React from 'react';
import { ScrollView, RefreshControl, Modal } from 'react-native';
import { colors } from '../../theme/colors';
import PremiumAnalyticsPaywall from '../../components/PremiumAnalyticsPaywall';
import { useAnalyticsScreen } from './AnalyticsScreen.hooks';
import { styles } from './AnalyticsScreen.styles';
import {
  AnalyticsHeader,
  EmptyState,
  OverviewStats,
  ChartSections,
  InsightsSections,
  ExportButton,
  ExportMenu,
} from './components';

export default function AnalyticsScreen() {
  const {
    refreshing,
    showPaywall,
    showExportMenu,
    isPremiumUser,
    isLoading,
    overviewStats,
    strengthDistribution,
    trendData,
    complianceData,
    weeklyInsights,
    onRefresh,
    handleHabitPress,
    handleExportPress,
    handleExport,
    handleStartTrial,
    setShowPaywall,
    setShowExportMenu,
  } = useAnalyticsScreen();

  // Show paywall modal if not premium user
  if (!isPremiumUser && showPaywall) {
    return (
      <Modal visible animationType='slide' presentationStyle='fullScreen'>
        <PremiumAnalyticsPaywall
          onClose={() => setShowPaywall(false)}
          onStartTrial={handleStartTrial}
        />
      </Modal>
    );
  }

  const hasNoHabits = !isLoading && overviewStats?.totalHabits === 0;

  return (
    <ScrollView
      contentContainerStyle={styles.contentContainer}
      refreshControl={
        <RefreshControl
          colors={[colors.primary[500]]}
          refreshing={refreshing}
          tintColor={colors.primary[500]}
          onRefresh={onRefresh}
        />
      }
      style={styles.container}
    >
      <AnalyticsHeader />

      {hasNoHabits && <EmptyState />}

      <OverviewStats
        isLoading={isLoading}
        stats={overviewStats}
        onHabitPress={handleHabitPress}
      />

      <ChartSections
        complianceData={complianceData}
        strengthDistribution={strengthDistribution}
        trendData={trendData}
      />

      <InsightsSections
        rankedHabits={overviewStats?.rankedHabits || []}
        weeklyInsights={weeklyInsights}
        onHabitPress={handleHabitPress}
      />

      <ExportButton onPress={handleExportPress} />

      <ExportMenu
        visible={showExportMenu}
        onClose={() => setShowExportMenu(false)}
        onExport={handleExport}
      />
    </ScrollView>
  );
}

/**
 * ChartSections - Analytics chart components (Strength, Trend, Heatmap)
