              <LinearGradient
                colors={AVATAR_GRADIENT}
                end={{ x: 1, y: 1 }}
                start={{ x: 0, y: 0 }}
                style={{
                  alignItems: 'center',
                  height: '100%',
                  justifyContent: 'center',
                  width: '100%',
                }}
              >
                <Text className='text-[30px] leading-9'>🦸</Text>
              </LinearGradient>
            </View>
            <View className='flex-col'>
              <View className='flex-row items-center gap-2'>
