/**
 * HeroSection Component
 * Icon, Name, Description, and Streak Badge
 */

import React, { useEffect } from 'react';
import { View, Text } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withTiming,
  Easing,
} from 'react-native-reanimated';
import type { HeroSectionProps } from '../HabitDetailScreen.types';

// Get streak badge text based on streak length (T1.2)
const getStreakBadgeText = (streak: number): string => {
  if (streak >= 30) return `🌟 ${streak} day streak!`;
  if (streak >= 14) return `🔥 ${streak} day streak!`;
  return `⚡ ${streak} day streak!`;
};

export function HeroSection({
  currentStreak,
  habit,
  isCompletedToday,
  reduceMotion = false,
}: HeroSectionProps) {
  // Icon bounce animation on load (T1.1)
  const iconScale = useSharedValue(reduceMotion ? 1 : 0.8);
  const iconTranslateY = useSharedValue(reduceMotion ? 0 : -10);

  // Streak badge animation on load (T1.2)
  const showStreakBadge = currentStreak >= 7;
  const badgeScale = useSharedValue(reduceMotion && showStreakBadge ? 1 : 0);
  const badgeOpacity = useSharedValue(reduceMotion && showStreakBadge ? 1 : 0);

  useEffect(() => {
    if (reduceMotion) {
      iconScale.value = 1;
      iconTranslateY.value = 0;
      if (showStreakBadge) {
        badgeScale.value = 1;
        badgeOpacity.value = 1;
      }
      return;
    }

    iconScale.value = withSpring(1, { damping: 8, mass: 1, stiffness: 150 });
    iconTranslateY.value = withSpring(0, {
      damping: 8,
      mass: 1,
      stiffness: 150,
    });

    if (showStreakBadge) {
      setTimeout(() => {
        badgeOpacity.value = withTiming(1, {
          duration: 200,
          easing: Easing.out(Easing.ease),
        });
        badgeScale.value = withSpring(1, {
          damping: 10,
          mass: 1,
          stiffness: 200,
        });
      }, 400);
    }
  }, [showStreakBadge, reduceMotion]);

  const iconAnimatedStyle = useAnimatedStyle(() => ({
    transform: [
      { scale: iconScale.value },
      { translateY: iconTranslateY.value },
    ],
  }));

  const badgeAnimatedStyle = useAnimatedStyle(() => ({
    opacity: badgeOpacity.value,
    transform: [{ scale: badgeScale.value }],
  }));

  return (
    <View className='items-center pb-4'>
      {habit.icon && (
        <Animated.View
          className='mb-3 h-20 w-20 items-center justify-center rounded-2xl shadow-lg'
          style={[
            { backgroundColor: habit.iconColor || '#fef3c7' },
            iconAnimatedStyle,
          ]}
        >
          <Text className='text-4xl'>{habit.icon}</Text>
        </Animated.View>
      )}

      <Text className='text-xl font-bold text-stone-900'>{habit.name}</Text>

      {showStreakBadge && (
        <Animated.View
          accessibilityLabel={`${currentStreak} day streak`}
          className='mt-2 rounded-full bg-gradient-to-r from-orange-100 to-amber-100 px-3 py-1'
          style={badgeAnimatedStyle}
        >
          <Text className='text-xs font-semibold text-orange-600'>
            {getStreakBadgeText(currentStreak)}
          </Text>
        </Animated.View>
      )}

      {habit.notes ? (
        <Text className='mt-1 px-6 text-center text-sm text-stone-500'>
          {habit.notes}
        </Text>
      ) : null}
    </View>
  );
}

/**
 * useCalendarHandlers
 * Calendar toggle and undo/redo handlers for habit detail screen
 */

import { useCallback } from 'react';
import { Alert } from 'react-native';
import { useMutation } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import * as Haptics from 'expo-haptics';
import type { Id } from '../../../convex/_generated/dataModel';
import type { Habit } from './HabitDetailScreen.types';

interface UseCalendarHandlersProps {
  habit: Habit | null;
  isTogglingCalendar: boolean;
  onArchive?: (habitId: Id<'habits'>) => void;
  onClose: () => void;
  onDelete?: (habitId: Id<'habits'>) => void;
  setIsTogglingCalendar: (toggling: boolean) => void;
  setPendingArchive: (pending: boolean) => void;
  setPendingDelete: (pending: boolean) => void;
}

export const useCalendarHandlers = ({
  habit,
  isTogglingCalendar,
  onArchive,
  onClose,
  onDelete,
  setIsTogglingCalendar,
  setPendingArchive,
  setPendingDelete,
}: UseCalendarHandlersProps) => {
  const toggleHabitMutation = useMutation(api.habits.toggleHabit);

  const handleCalendarDayPress = useCallback(
    (date: string, wasCompleted: boolean): void => {
      if (isTogglingCalendar || !habit?._id) return;

      const inputDate = new Date(date);
      const todayDate = new Date();
      inputDate.setHours(0, 0, 0, 0);
      todayDate.setHours(0, 0, 0, 0);
      if (inputDate > todayDate) return;

      setIsTogglingCalendar(true);
      toggleHabitMutation({ date, habitId: habit._id })
        .catch((error: unknown) => {
          console.error('Failed to toggle habit:', error);
          Alert.alert('Error', 'Failed to update habit. Please try again.');
        })
        .finally(() => setIsTogglingCalendar(false));
    },
    [isTogglingCalendar, habit?._id, toggleHabitMutation, setIsTogglingCalendar]
  );

  const handleSwipeDelete = useCallback(() => {
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning);
    setPendingDelete(true);
  }, [setPendingDelete]);

  const handleSwipeArchive = useCallback(() => {
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning);
    setPendingArchive(true);
  }, [setPendingArchive]);

  const handleConfirmDelete = useCallback(() => {
    setPendingDelete(false);
    if (habit) {
      onDelete?.(habit._id);
      onClose();
    }
  }, [habit, onDelete, onClose, setPendingDelete]);

  const handleConfirmArchive = useCallback(() => {
    setPendingArchive(false);
    if (habit) {
      onArchive?.(habit._id);
      onClose();
    }
  }, [habit, onArchive, onClose, setPendingArchive]);

  const handleUndoDelete = useCallback(
    () => setPendingDelete(false),
    [setPendingDelete]
  );
  const handleUndoArchive = useCallback(
    () => setPendingArchive(false),
    [setPendingArchive]
  );

  return {
    handleCalendarDayPress,
    handleConfirmArchive,
    handleConfirmDelete,
    handleSwipeArchive,
    handleSwipeDelete,
    handleUndoArchive,
    handleUndoDelete,
  };
};

/** useHabitDetailScreenComputed - Computed/derived values for the habit detail screen */

import { useMemo } from 'react';
import type { WeekDayData } from './HabitDetailScreen.types';

interface UseHabitDetailScreenComputedProps {
  completedDates: Set<string>;
  isCompletedToday: boolean;
  today: string;
}

export const useHabitDetailScreenComputed = ({
  completedDates,
  isCompletedToday,
  today,
}: UseHabitDetailScreenComputedProps) => {
  const lastSevenDays = useMemo(
    () =>
      Array.from({ length: 7 }, (_, i) => {
        const date = new Date();
        date.setDate(date.getDate() - (6 - i));
        const dateKey = date.toISOString().split('T')[0];
        return dateKey === today
          ? isCompletedToday
          : completedDates.has(dateKey);
      }),
    [today, isCompletedToday, completedDates]
  );

  const lastThirtyDays = useMemo(
    () =>
      Array.from({ length: 30 }, (_, i) => {
        const date = new Date();
        date.setDate(date.getDate() - (29 - i));
        const dateKey = date.toISOString().split('T')[0];
        return {
          completed:
            dateKey === today ? isCompletedToday : completedDates.has(dateKey),
          date: dateKey,
        };
      }),
    [today, isCompletedToday, completedDates]
  );

  const successRate = useMemo(
    () => (lastThirtyDays.filter((d) => d.completed).length / 30) * 100,
    [lastThirtyDays]
  );

  // Week data for WeeklySummaryStrip (Monday to Sunday)
  const weekData = useMemo<WeekDayData[]>(() => {
    const todayDate = new Date();
    const dayOfWeek = todayDate.getDay(); // 0 = Sunday, 1 = Monday, etc.
    // Convert to Monday-based (0 = Monday, 6 = Sunday)
    const mondayOffset = dayOfWeek === 0 ? 6 : dayOfWeek - 1;
    const monday = new Date(todayDate);
    monday.setDate(todayDate.getDate() - mondayOffset);
    monday.setHours(0, 0, 0, 0);

    return Array.from({ length: 7 }, (_, index) => {
      const date = new Date(monday);
      date.setDate(monday.getDate() + index);
      const dateKey = date.toISOString().split('T')[0];
      const isTodayDate = dateKey === today;

      return {
        completed: isTodayDate ? isCompletedToday : completedDates.has(dateKey),
        date: dateKey,
        isToday: isTodayDate,
      };
    });
  }, [today, isCompletedToday, completedDates]);

  // Last week's completion count for trend comparison
  const lastWeekCompleted = useMemo(() => {
    const todayDate = new Date();
    const dayOfWeek = todayDate.getDay();
    const mondayOffset = dayOfWeek === 0 ? 6 : dayOfWeek - 1;

    const lastMonday = new Date(todayDate);
    lastMonday.setDate(todayDate.getDate() - mondayOffset - 7);
    lastMonday.setHours(0, 0, 0, 0);

    let count = 0;
    for (let i = 0; i < 7; i++) {
      const date = new Date(lastMonday);
      date.setDate(lastMonday.getDate() + i);
      const dateKey = date.toISOString().split('T')[0];
      if (completedDates.has(dateKey)) {
        count++;
      }
    }
    return count;
  }, [completedDates]);

  return {
    lastSevenDays,
    lastThirtyDays,
    lastWeekCompleted,
    successRate,
    weekData,
  };
};

/**
 * useHabitDetailScreenState - State management for the habit detail screen
 */

import { useMemo, useState } from 'react';
import { useQuery } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import type { Id, Doc } from '../../../convex/_generated/dataModel';
import type { HabitTrackingEntry } from '../../features/habits/types';

interface UseHabitDetailScreenStateProps {
  habitCreatedAt: number | undefined;
  habitId: Id<'habits'> | undefined;
  habitStrength: number;
  tracking: HabitTrackingEntry[];
  visible: boolean;
}

export const useHabitDetailScreenState = ({
  habitCreatedAt,
  habitId,
  habitStrength,
  tracking,
  visible,
}: UseHabitDetailScreenStateProps) => {
  // Notes modal states
  const [isNotesEditorOpen, setIsNotesEditorOpen] = useState(false);
  const [isNotesListOpen, setIsNotesListOpen] = useState(false);
  const [editingNoteId, setEditingNoteId] = useState<Id<'notes'> | null>(null);

  // Delete/Archive undo toast states (T3.5: Swipe-to-delete)
  const [pendingDelete, setPendingDelete] = useState(false);
  const [pendingArchive, setPendingArchive] = useState(false);

  // Calendar toggling state
  const [isTogglingCalendar, setIsTogglingCalendar] = useState(false);

  // Fetch habit notes
  const habitNotes =
    useQuery(api.notes.search, visible && habitId ? { habitId } : 'skip') ?? [];

  // Today's date
  const today = useMemo(() => new Date().toISOString().split('T')[0], []);

  // Completed dates set
  const completedDates = useMemo(() => {
    if (!habitId) {
      return new Set<string>();
    }
    return new Set(
      tracking
        .filter((entry) => entry.habitId === habitId && entry.completed)
        .map((entry) => entry.date)
    );
  }, [habitId, tracking]);

  const isCompletedToday = completedDates.has(today);

  // Days tracking calculation
  const daysTracking = useMemo(() => {
    return habitCreatedAt
      ? Math.max(
          0,
          Math.floor((Date.now() - habitCreatedAt) / (1000 * 60 * 60 * 24))
        )
      : 0;
  }, [habitCreatedAt]);

  const totalCompletions = useMemo(() => completedDates.size, [completedDates]);

  const strengthPercent = useMemo(
    () => Math.max(0, Math.min(100, habitStrength * 100)),
    [habitStrength]
  );

  // Get the note being edited
  const editingNote = editingNoteId
    ? habitNotes.find((n) => n._id === editingNoteId)
    : null;

  return {
    completedDates,
    daysTracking,
    editingNote,
    editingNoteId,
    habitNotes,
    isCompletedToday,
    isNotesEditorOpen,
    isNotesListOpen,
    isTogglingCalendar,
    pendingArchive,
    pendingDelete,
    setEditingNoteId,
    setIsNotesEditorOpen,
    setIsNotesListOpen,
    setIsTogglingCalendar,
    setPendingArchive,
    setPendingDelete,
    strengthPercent,
    today,
    totalCompletions,
  };
};

