  habitId,
  habitName,
  selectedEmoji,
  selectedColor,
  remindersEnabled,
  reminderTime,
  onSuccess,
}: UseSaveHandlerProps) {
  const updateHabit = useMutation(api.habits.update);

  const handleSave = useCallback(async () => {
    if (!habitId || !habitName.trim()) return;

    const trimmedName = habitName.trim();
    const fullName = selectedEmoji ? `${selectedEmoji} ${trimmedName}` : trimmedName;
    const reminderTimeString = formatReminderTime(reminderTime);

    let enableReminders = remindersEnabled;

    if (remindersEnabled) {
      const hasPermission = await ensureNotificationPermissions();
      enableReminders = hasPermission;

      if (hasPermission) {
        const scheduled = await scheduleHabitReminder({
          body: 'Time to check in on your habit progress!',
          habitId: String(habitId),
          reminderTime,
          skipPermissionCheck: true,
          title: fullName,
        });
        enableReminders = scheduled;
      }

      if (!enableReminders) {
        await cancelHabitReminder(String(habitId));
        Alert.alert(
          'Notifications Disabled',
          'Enable notifications in your device settings to receive habit reminders.'
        );
      }
    } else {
      await cancelHabitReminder(String(habitId));
    }

    await updateHabit({
      habitId,
      icon: selectedEmoji ?? undefined,
      iconColor: selectedColor,
      name: fullName,
      remindersEnabled: enableReminders,
      reminderSound: enableReminders ? 'default' : undefined,
      reminderTime: enableReminders ? reminderTimeString : undefined,
    });

    onSuccess();
  }, [habitId, habitName, selectedEmoji, selectedColor, remindersEnabled, reminderTime, updateHabit, onSuccess]);

  return { handleSave };
}

/**
 * State management for TemplatesScreen
 */

import { useEffect, useRef, useState } from 'react';
import { FlatList, ScrollView } from 'react-native';
import type { Doc, Id } from '../../../convex/_generated/dataModel';
import type { Category, SortOption } from '../templates/constants';
import type { BrowseTab, ViewMode } from './TemplatesScreen.types';

interface UseTemplatesScreenStateOptions {
  categories: { id: string }[] | undefined;
}

export function useTemplatesScreenState({
  categories,
}: UseTemplatesScreenStateOptions) {
  const flatListRef = useRef<FlatList<Doc<'templates'>>>(null);
  const scrollViewRef = useRef<ScrollView>(null);

  const [viewMode, setViewMode] = useState<ViewMode>('browse');
  const [browseTab, setBrowseTab] = useState<BrowseTab>('categories');
  const [selectedCategory, setSelectedCategory] = useState<Category>('all');
  const [expandedCategories, setExpandedCategories] = useState<Set<string>>(
    new Set()
  );
  const [hasInitializedExpanded, setHasInitializedExpanded] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [sortOption, setSortOption] = useState<SortOption>('popular');
  const [researchOnly, setResearchOnly] = useState(false);
  const [previewTemplate, setPreviewTemplate] =
    useState<Doc<'templates'> | null>(null);
  const [showFullsizePreview, setShowFullsizePreview] = useState(false);
  const [showCustomizeModal, setShowCustomizeModal] = useState(false);
  const [importedTemplateIds, setImportedTemplateIds] = useState<Set<string>>(
    new Set()
  );
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [importingTemplateId, setImportingTemplateId] =
    useState<Id<'templates'> | null>(null);
  const [showSortOptions, setShowSortOptions] = useState(false);
  const [isSeeding, setIsSeeding] = useState(false);

  useEffect(() => {
    if (categories && !hasInitializedExpanded) {
      const nonAll = categories.filter((c) => c.id !== 'all');
      const init = new Set<string>();
      for (const [i, c] of nonAll.entries()) {
        if ((i + 1) % 3 === 0) init.add(c.id);
      }
      setExpandedCategories(init);
      setHasInitializedExpanded(true);
    }
  }, [categories, hasInitializedExpanded]);

  const isSearching = searchQuery.trim().length > 0;
  const effectiveViewMode = isSearching ? 'search' : viewMode;
  const hasActiveFilters =
    selectedCategory !== 'all' || Boolean(searchQuery.trim()) || researchOnly;

  return {
    browseTab,
    effectiveViewMode,
    expandedCategories,
    flatListRef,
    hasActiveFilters,
    importedTemplateIds,
    importingTemplateId,
    isSearching,
    isSeeding,
    previewTemplate,
    researchOnly,
    scrollViewRef,
    searchQuery,
    selectedCategory,
    setBrowseTab,
    setExpandedCategories,
    setImportedTemplateIds,
    setImportingTemplateId,
    setIsSeeding,
    setPreviewTemplate,
    setResearchOnly,
    setSearchQuery,
    setSelectedCategory,
    setShowCustomizeModal,
    setShowFullsizePreview,
    setShowSortOptions,
    setShowToast,
    setSortOption,
    setToastMessage,
    setViewMode,
    showCustomizeModal,
    showFullsizePreview,
    showSortOptions,
    showToast,
    sortOption,
    toastMessage,
    viewMode,
  };
}

