  });

  const getCategoryLabel = (categoryId: string) =>
    data.categories?.find((c) => c.id === categoryId)?.label || categoryId;

  const handleTabPress = (tab: BrowseTab) => {
    state.setBrowseTab(tab);
    tabIndicator.setTabPosition(tab === 'categories' ? 0 : 1);
  };

  return {
    animations,
    data,
    filteredTemplates,
    getCategoryLabel,
    handlers,
    handleTabPress,
    scienceCountsByCategory,
    state,
    tabIndicator,
    templatesByCategory,
  };
}

/**
 * Screen entrance animation hooks for TemplatesScreen
 */

import { useEffect } from 'react';
import { useAnimatedStyle, useSharedValue } from 'react-native-reanimated';

interface UseEntranceAnimationsOptions {
  reducedMotion: boolean;
}

export function useEntranceAnimations({
  reducedMotion,
}: UseEntranceAnimationsOptions) {
  const headerTranslateY = useSharedValue(-20);
  const headerOpacity = useSharedValue(0);
  const searchOpacity = useSharedValue(0);
  const searchTranslateY = useSharedValue(15);
  const tabBarOpacity = useSharedValue(0);
  const tabBarTranslateY = useSharedValue(15);
  const contentOpacity = useSharedValue(0);
  const contentTranslateY = useSharedValue(20);

  useEffect(() => {
    // Content is instant - modal slide IS the animation (like native iOS sheets)
    headerTranslateY.value = 0;
    headerOpacity.value = 1;
    searchTranslateY.value = 0;
    searchOpacity.value = 1;
    tabBarTranslateY.value = 0;
    tabBarOpacity.value = 1;
    contentTranslateY.value = 0;
    contentOpacity.value = 1;
  }, [reducedMotion]);

  const headerAnimatedStyle = useAnimatedStyle(() => ({
    opacity: headerOpacity.value,
    transform: [{ translateY: headerTranslateY.value }],
  }));

  const searchAnimatedStyle = useAnimatedStyle(() => ({
    opacity: searchOpacity.value,
    transform: [{ translateY: searchTranslateY.value }],
  }));

  const tabBarAnimatedStyle = useAnimatedStyle(() => ({
    opacity: tabBarOpacity.value,
    transform: [{ translateY: tabBarTranslateY.value }],
  }));

  const contentAnimatedStyle = useAnimatedStyle(() => ({
    opacity: contentOpacity.value,
    transform: [{ translateY: contentTranslateY.value }],
  }));

  return {
    contentAnimatedStyle,
    headerAnimatedStyle,
    searchAnimatedStyle,
    tabBarAnimatedStyle,
  };
}

/**
 * Scroll shadow management for template lists
 * Shows gradient shadows at top/bottom when content is scrollable
 */

import { useCallback, useRef, useState, useEffect } from 'react';
import type {
  NativeSyntheticEvent,
  NativeScrollEvent,
  LayoutChangeEvent,
} from 'react-native';
import type { ScrollMetrics } from './TemplatesScreen.types';

interface UseScrollShadowsOptions {
  resetDeps?: unknown[];
}

export function useScrollShadows(options: UseScrollShadowsOptions = {}) {
  const { resetDeps = [] } = options;

  const [showTopShadow, setShowTopShadow] = useState(false);
  const [showBottomShadow, setShowBottomShadow] = useState(false);

  const scrollOffset = useRef(0);
  const scrollMetrics = useRef<ScrollMetrics>({
    contentHeight: 0,
    layoutHeight: 0,
  });

  const updateShadows = useCallback(() => {
    const { layoutHeight, contentHeight } = scrollMetrics.current;
    const offsetY = scrollOffset.current;
    const hasScrollableContent = contentHeight > layoutHeight + 1;

    setShowTopShadow(hasScrollableContent && offsetY > 4);
    setShowBottomShadow(
      hasScrollableContent && contentHeight - (offsetY + layoutHeight) > 4
    );
  }, []);

  const handleScroll = useCallback(
    (event: NativeSyntheticEvent<NativeScrollEvent>) => {
      const { contentOffset, layoutMeasurement, contentSize } =
        event.nativeEvent;
      scrollOffset.current = contentOffset.y;
      scrollMetrics.current = {
        contentHeight: contentSize.height,
        layoutHeight: layoutMeasurement.height,
      };
      updateShadows();
    },
    [updateShadows]
  );

  const handleContentSizeChange = useCallback(
    (_width: number, height: number) => {
      scrollMetrics.current = {
        ...scrollMetrics.current,
        contentHeight: height,
      };
      updateShadows();
    },
    [updateShadows]
  );

  const handleLayout = useCallback(
    (event: LayoutChangeEvent) => {
      scrollMetrics.current = {
        ...scrollMetrics.current,
        layoutHeight: event.nativeEvent.layout.height,
      };
      updateShadows();
    },
    [updateShadows]
  );

  // Reset shadows when dependencies change
  useEffect(() => {
    scrollOffset.current = 0;
    scrollMetrics.current = { ...scrollMetrics.current, contentHeight: 0 };
    setShowTopShadow(false);
    setShowBottomShadow(false);
  }, resetDeps);

  return {
    handleContentSizeChange,
    handleLayout,
    handleScroll,
    showBottomShadow,
    showTopShadow,
  };
}

