            className='items-center rounded-3xl bg-stone-800 py-[18px]'
            onPress={() => setMode('signup')}
          >
            <Text className='text-[15px] font-semibold tracking-[3px] text-white'>
              GET STARTED
            </Text>
          </TouchableOpacity>

          <TouchableOpacity
            className='items-center rounded-3xl border border-stone-200 py-[18px]'
            onPress={() => setMode('signin')}
          >
            <Text className='text-[15px] font-semibold tracking-[3px] text-stone-800'>
              SIGN IN
            </Text>
          </TouchableOpacity>
        </View>
      </View>
    </View>
  );
}

import { useEffect } from 'react';
import { View, Text } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withRepeat,
  withTiming,
  Easing,
} from 'react-native-reanimated';

/**
 * Props for the AnimatedLogo component
 */
interface AnimatedLogoProps {
  /** Size of the logo in pixels (width and height) */
  size?: number;
}

/**
 * AnimatedLogo - Breathing logo animation for auth screens
 *
 * Features:
 * - Breathing animation (scale 1.0 → 1.05 → 1.0)
 * - 3-second infinite animation loop with ease-in-out timing
 * - Slate-700 background with shadow
 * - Checkmark icon centered
 * - Full accessibility support
 *
 * @example
 * <AnimatedLogo size={80} />
 */
export function AnimatedLogo({ size = 80 }: AnimatedLogoProps) {
  const scale = useSharedValue(1);

  useEffect(() => {
    // Start the breathing animation (3s duration, infinite loop)
    scale.value = withRepeat(
      withTiming(1.05, {
        duration: 1500,
        easing: Easing.inOut(Easing.ease),
      }),
      -1, // Infinite repeats
      true // Reverse animation (yoyo effect)
    );
  }, []);

  const animatedStyle = useAnimatedStyle(() => {
    return {
      transform: [{ scale: scale.value }],
    };
  });

  return (
    <View
      className="mb-4"
      accessible={true}
      accessibilityLabel="Habit Tracker Logo"
      accessibilityRole="image"
    >
      <Animated.View
        className="items-center justify-center rounded-3xl shadow-lg"
        style={[
          animatedStyle,
          {
            width: size,
            height: size,
            borderRadius: 24,
            backgroundColor: '#44403c', // stone-700
            shadowColor: '#000',
            shadowOffset: { width: 0, height: 4 },
            shadowOpacity: 0.3,
            shadowRadius: 8,
            elevation: 8,
          },
        ]}
      >
        <Text className="text-5xl">✓</Text>
      </Animated.View>
    </View>
  );
}

/**
 * ForgotPasswordModal Component
 *
 * A modal that allows users to reset their password via email.
 * Integrates with Clerk's password reset API.
 */

import { useCallback } from 'react';
import { Text, View } from 'react-native';
import Modal from '../../../../components/Modal';
import { PasswordResetForm } from './PasswordResetForm';
import { PasswordResetSuccess } from './PasswordResetSuccess';
import { useForgotPassword } from './useForgotPassword';
import type { ForgotPasswordModalProps } from './types';

export function ForgotPasswordModal({
  visible,
  onClose,
}: ForgotPasswordModalProps) {
  const {
    email,
    error,
    isLoading,
    success,
    setEmail,
    clearError,
    handleResetPassword,
    resetState,
  } = useForgotPassword();

  const handleClose = useCallback(() => {
    resetState();
    onClose();
  }, [resetState, onClose]);

  const handleEmailChange = useCallback(
    (text: string) => {
      setEmail(text);
      clearError();
    },
    [setEmail, clearError]
  );

  return (
    <Modal
      disableBackdropClose={isLoading}
      disableGestureClose={isLoading}
      variant='centerAlert'
      visible={visible}
      onClose={handleClose}
    >
      <View className='gap-4'>
        {/* Header */}
        <View className='gap-1'>
          <Text className='text-2xl font-extrabold tracking-tight text-stone-900'>
            Reset Password
          </Text>
          <Text className='text-sm text-stone-500'>
            {success
              ? 'Check your email for reset instructions'
              : "Enter your email address and we'll send you a link to reset your password"}
          </Text>
        </View>

        {/* Content */}
        {success ? (
          <PasswordResetSuccess onClose={handleClose} />
        ) : (
          <PasswordResetForm
            email={email}
            error={error}
            isLoading={isLoading}
            onCancel={handleClose}
            onEmailChange={handleEmailChange}
            onSubmit={handleResetPassword}
          />
        )}
      </View>
    </Modal>
  );
}

export default ForgotPasswordModal;

import {
  ActivityIndicator,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from 'react-native';
import type { PasswordResetFormProps } from './types';

export function PasswordResetForm({
  email,
  error,
  isLoading,
  onEmailChange,
  onSubmit,
  onCancel,
}: PasswordResetFormProps) {
  return (
    <View className='gap-4'>
      {/* Email Input */}
      <View className='gap-2'>
        <Text className='text-[10px] font-medium tracking-[3px] text-stone-500'>
          EMAIL ADDRESS
        </Text>
        <View className='relative'>
          <TextInput
            accessible
            autoFocus
            accessibilityHint='Enter your email to receive password reset instructions'
            accessibilityLabel='Email address input'
            autoCapitalize='none'
            autoComplete='email'
            className={`rounded-3xl border ${
              error ? 'border-red-600' : 'border-stone-200'
            } bg-white px-5 py-3.5 text-base font-medium text-stone-900`}
            editable={!isLoading}
            keyboardType='email-address'
            placeholder='Enter your email address'
            placeholderTextColor='#a8a29e'
            returnKeyType='send'
            value={email}
            onChangeText={onEmailChange}
            onSubmitEditing={onSubmit}
          />
          {/* Email icon prefix */}
          <View className='-transtone-y-1/2 absolute left-4 top-1/2'>
            <Text className='text-lg'>📧</Text>
          </View>
          <View className='pl-10' />
        </View>
        {/* Error message */}
        {error && (
          <Text
            accessibilityLiveRegion='polite'
            accessibilityRole='alert'
            className='text-xs font-medium text-red-600'
          >
            {error}
          </Text>
        )}
      </View>

      {/* Action Buttons */}
      <View className='gap-2'>
        {/* Submit Button */}
        <TouchableOpacity
          accessibilityHint='Sends password reset instructions to your email'
          accessibilityLabel='Send reset email'
          accessibilityRole='button'
          accessibilityState={{
            busy: isLoading,
            disabled: isLoading || !email.trim(),
          }}
          className={`items-center rounded-3xl border border-stone-900 bg-stone-900 py-4 ${
            isLoading || !email.trim() ? 'opacity-40' : ''
          }`}
          disabled={isLoading || !email.trim()}
