import { useEffect } from 'react';
import {
  useAnimatedStyle,
  useSharedValue,
  withDelay,
  withSequence,
  withSpring,
  withTiming,
} from 'react-native-reanimated';

export function useSuccessOverlayAnimations(
  visible: boolean,
  onAnimationComplete?: () => void
) {
  const overlayOpacity = useSharedValue(0);
  const checkmarkScale = useSharedValue(0);
  const checkmarkOpacity = useSharedValue(0);
  const ringScale = useSharedValue(0);
  const ringOpacity = useSharedValue(0);
  const textOpacity = useSharedValue(0);
  const textTranslateY = useSharedValue(20);

  useEffect(() => {
    if (visible) {
      overlayOpacity.value = withTiming(1, { duration: 300 });

      ringScale.value = withDelay(
        100,
        withSequence(
          withSpring(1.2, { damping: 8, stiffness: 100 }),
          withTiming(1.5, { duration: 400 })
        )
      );
      ringOpacity.value = withDelay(
        100,
        withSequence(
          withTiming(0.5, { duration: 200 }),
          withTiming(0, { duration: 400 })
        )
      );

      checkmarkScale.value = withDelay(
        200,
        withSpring(1, { damping: 10, stiffness: 150 })
      );
      checkmarkOpacity.value = withDelay(200, withTiming(1, { duration: 200 }));

      textOpacity.value = withDelay(400, withTiming(1, { duration: 300 }));
      textTranslateY.value = withDelay(
        400,
        withSpring(0, { damping: 12, stiffness: 100 })
      );

      if (onAnimationComplete) {
        const timer = setTimeout(() => {
          onAnimationComplete();
        }, 1500);
        return () => clearTimeout(timer);
      }
    } else {
      overlayOpacity.value = 0;
      checkmarkScale.value = 0;
      checkmarkOpacity.value = 0;
      ringScale.value = 0;
      ringOpacity.value = 0;
      textOpacity.value = 0;
      textTranslateY.value = 20;
    }
  }, [visible, onAnimationComplete]);

  const overlayStyle = useAnimatedStyle(() => ({
    opacity: overlayOpacity.value,
  }));

  const checkmarkStyle = useAnimatedStyle(() => ({
    transform: [{ scale: checkmarkScale.value }],
    opacity: checkmarkOpacity.value,
  }));

  const ringStyle = useAnimatedStyle(() => ({
    transform: [{ scale: ringScale.value }],
    opacity: ringOpacity.value,
  }));

  const textStyle = useAnimatedStyle(() => ({
    opacity: textOpacity.value,
    transform: [{ translateY: textTranslateY.value }],
  }));

  return { overlayStyle, checkmarkStyle, ringStyle, textStyle };
}

import { useState } from 'react';
import { Text, View } from 'react-native';
import { FormInput } from '../FormInput';
import { SubmitButton } from '../SubmitButton';

interface VerificationViewProps {
  emailAddress: string;
  isLoading: boolean;
  onVerify: (code: string) => Promise<void>;
}

export function VerificationView({
  emailAddress,
  isLoading,
  onVerify,
}: VerificationViewProps) {
  const [code, setCode] = useState('');

  return (
    <View className='flex-1 bg-white'>
      <View className='pt-15 flex-1 px-6'>
        <Text className='mb-2 text-[32px] font-extrabold tracking-tight text-slate-900'>
          Verify Email
        </Text>
        <Text className='mb-10 text-base text-slate-500'>
          We've sent a verification code to {emailAddress}
        </Text>

        <View className='gap-6'>
          <FormInput
            keyboardType='number-pad'
            label='VERIFICATION CODE'
            maxLength={6}
            placeholder='Enter 6-digit code'
            value={code}
            onChangeText={setCode}
          />

          <SubmitButton
            disabled={code.length !== 6}
            isLoading={isLoading}
            label='VERIFY EMAIL'
            loadingLabel='VERIFYING...'
            onPress={() => onVerify(code)}
          />
        </View>
      </View>
    </View>
  );
}

import { useSignUp } from '@clerk/clerk-expo';
import { useState } from 'react';
import { Alert } from 'react-native';

export function useSignUpFlow() {
  const { isLoaded, signUp, setActive } = useSignUp();
  const [emailAddress, setEmailAddress] = useState('');
  const [password, setPassword] = useState('');
  const [pendingVerification, setPendingVerification] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const handleSignUp = async () => {
    if (!isLoaded) return;

    setIsLoading(true);
    try {
      await signUp.create({ emailAddress, password });
      await signUp.prepareEmailAddressVerification({ strategy: 'email_code' });
      setPendingVerification(true);
    } catch (error: any) {
      console.error(JSON.stringify(error, null, 2));
      Alert.alert('Error', error.errors?.[0]?.message || 'Failed to sign up');
    } finally {
      setIsLoading(false);
    }
  };

  const handleVerification = async (code: string) => {
    if (!isLoaded) return;

    setIsLoading(true);
    try {
      const attempt = await signUp.attemptEmailAddressVerification({ code });

      if (attempt.status === 'complete') {
        await setActive({ session: attempt.createdSessionId });
      } else {
        console.error(JSON.stringify(attempt, null, 2));
        Alert.alert('Error', 'Verification incomplete. Please try again.');
      }
    } catch (error: any) {
      console.error(JSON.stringify(error, null, 2));
      Alert.alert(
        'Error',
        error.errors?.[0]?.message || 'Failed to verify email'
      );
    } finally {
      setIsLoading(false);
    }
  };

  return {
    emailAddress,
    handleSignUp,
    handleVerification,
    isLoading,
    password,
    pendingVerification,
    setEmailAddress,
    setPassword,
  };
}

