import { useEffect, useMemo, useState } from 'react';
import { View, Text, Pressable, ScrollView } from 'react-native';
import { addDays, format } from 'date-fns';
import { BarChart3, Settings } from 'lucide-react-native';
import { DateSelector } from '../../components/DateSelector';
import CharacterScreen from '../CharacterScreen';
import CharacterIcon from '../../components/CharacterIcon';
import Animated, {
  FadeInDown,
  FadeOutUp,
  Layout,
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withTiming,
} from 'react-native-reanimated';

type LocalHabit = {
  color: string;
  completedDates: string[];
  emoji: string;
  id: string;
  name: string;
  strength: number;
};

const generateWeekDateStrings = () => {
  const today = new Date();
  const weekDates = Array.from({ length: 7 }, (_, i) =>
    addDays(today, i - today.getDay())
  );
  return weekDates.map((d) => format(d, 'yyyy-MM-dd'));
};

const WeekDateToggle = ({
  date,
  habitId,
  isCompleted,
  isFuture,
  onToggle,
}: {
  date: string;
  habitId: string;
  isCompleted: boolean;
  isFuture: boolean;
  onToggle: (habitId: string, date: string) => void;
}) => {
  const scale = useSharedValue(1);
  const scaleStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
  }));

  const backgroundClass = isFuture
    ? 'bg-stone-100 opacity-50'
    : isCompleted
      ? 'bg-green-500'
      : 'bg-stone-200';

  const handlePress = () => {
    if (!isFuture) {
      onToggle(habitId, date);
    }
  };

  return (
    <Pressable
      accessibilityRole='button'
      className={`h-9 w-9 items-center justify-center rounded-full ${backgroundClass}`}
      disabled={isFuture}
      onPress={handlePress}
      onPressIn={() => {
        scale.value = withSpring(0.9);
      }}
      onPressOut={() => {
        scale.value = withSpring(1);
      }}
    >
      <Animated.View style={scaleStyle}>
        {isCompleted ? <Text className='text-white'>✓</Text> : null}
      </Animated.View>
    </Pressable>
  );
};

const ExampleHabitCard = ({
  habit,
  onDelete,
  onToggle,
  weekDates,
}: {
  habit: LocalHabit;
  weekDates: string[];
  onDelete: (habitId: string) => void;
  onToggle: (habitId: string, date: string) => void;
}) => {
  const isCompletedFor = (date: string) => habit.completedDates.includes(date);

  const streak = useMemo(() => {
    const sorted = [...habit.completedDates].sort().reverse();
    let s = 0;
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    for (const iso of sorted) {
      const check = new Date(iso);
      check.setHours(0, 0, 0, 0);
      const expected = new Date(today);
      expected.setDate(today.getDate() - s);
      if (check.getTime() === expected.getTime()) s += 1;
      else break;
    }
    return s;
  }, [habit.completedDates]);

  const completionCount = weekDates.filter((date) =>
    isCompletedFor(date)
  ).length;

  // Animated progress bar width
  const containerWidth = useSharedValue(0);
  const progressWidth = useSharedValue(0);
  useEffect(() => {
    const target = containerWidth.value * (completionCount / 7);
    progressWidth.value = withTiming(target, { duration: 500 });
  }, [completionCount, containerWidth, progressWidth]);
  const progressStyle = useAnimatedStyle(() => ({
    width: progressWidth.value,
  }));

  // Card appear/disappear animation
  const cardLayout = Layout.springify();

  return (
    <Animated.View
      className='rounded-3xl border border-stone-200 bg-white p-5 shadow-sm'
      entering={FadeInDown.duration(200)}
      exiting={FadeOutUp.duration(150)}
      layout={cardLayout}
    >
      <View className='mb-4 flex-row items-start justify-between'>
        <View className='flex-row items-center gap-3'>
          <Text className='text-3xl'>{habit.emoji}</Text>
          <View>
            <Text className='text-[17px] font-semibold text-stone-900'>
              {habit.name}
            </Text>
            {streak > 0 && (
              <View className='mt-1 flex-row items-center gap-1'>
                <Text className='text-[11px] font-semibold uppercase tracking-wide text-orange-500'>
                  {streak} Day Streak
                </Text>
              </View>
            )}
          </View>
        </View>
        <Text className='text-sm text-stone-500'>{completionCount}/7</Text>
      </View>

      <View className='flex-row justify-between gap-2'>
        {weekDates.map((date) => {
          const isFuture = new Date(date) > new Date();
          const isDone = isCompletedFor(date);
          return (
            <WeekDateToggle
              key={date}
              date={date}
              habitId={habit.id}
              isCompleted={isDone}
              isFuture={isFuture}
              onToggle={onToggle}
            />
          );
        })}
      </View>

      {/* Habit Strength */}
      <View className='mt-3 flex-row items-center justify-between'>
        <View className='flex-row items-center gap-2'>
          <Text className='text-sm text-stone-500'>Strength</Text>
          <View className='h-2 w-20 overflow-hidden rounded-full bg-stone-200'>
            <View
              className='h-full rounded-full'
              style={{
                backgroundColor: habit.strength >= 60 ? '#22C55E' : habit.strength >= 40 ? '#F59E0B' : '#EF4444',
                width: `${habit.strength}%`,
              }}
            />
          </View>
        </View>
        <Text
          className='text-base font-bold'
          style={{
            color: habit.strength >= 60 ? '#22C55E' : habit.strength >= 40 ? '#F59E0B' : '#EF4444',
          }}
        >
          {habit.strength}%
        </Text>
      </View>

      <View
        className='mt-4 h-1.5 w-full overflow-hidden rounded-full bg-stone-100'
        onLayout={(e) => {
          const w = e.nativeEvent.layout.width;
          containerWidth.value = w;
          progressWidth.value = withTiming(w * (completionCount / 7), {
            duration: 500,
          });
        }}
      >
        <Animated.View
          className='rounded-full'
          style={[
            { backgroundColor: habit.color, height: '100%' },
            progressStyle,
          ]}
        />
      </View>

      <View className='mt-3 flex-row justify-end'>
        <Pressable
          accessibilityRole='button'
          onPress={() => onDelete(habit.id)}
        >
          <Text className='text-red-600'>Delete</Text>
        </Pressable>
      </View>
    </Animated.View>
  );
};

