import { ModalFooter } from './ModalFooter';
import { TemplatePreview } from './TemplatePreview';
import { NameInput } from './NameInput';
import { ColorPicker } from './ColorPicker';
import { ReminderTimePicker } from './ReminderTimePicker';
import { TemplateInfo } from './TemplateInfo';
import { useTemplatePreview } from './useTemplatePreview';
import { styles } from './styles';
import type { TemplatePreviewModalProps } from './types';

export default function TemplatePreviewModal({
  importingTemplateId,
  onClose,
  onImport,
  template,
  visible,
}: TemplatePreviewModalProps) {
  const {
    customName,
    setCustomName,
    customColor,
    showTimePicker,
    setShowTimePicker,
    reminderTime,
    handleImport,
    handleClose,
    handleColorSelect,
    handleTimeChange,
  } = useTemplatePreview({ onClose, onImport, template });

  if (!template) return null;

  const isImporting = importingTemplateId === template._id;

  return (
    <Modal
      disableBackdropClose={isImporting}
      variant='fullScreen'
      visible={visible}
      onClose={handleClose}
    >
      <View style={styles.container}>
        <ModalHeader disabled={isImporting} onClose={handleClose} />

        <ScrollView
          bounces
          contentContainerStyle={styles.scrollContent}
          keyboardShouldPersistTaps='handled'
          showsVerticalScrollIndicator={false}
          style={styles.content}
        >
          <TemplatePreview
            customColor={customColor}
            description={template.description}
            icon={template.icon}
          />
          <NameInput
            customName={customName}
            disabled={isImporting}
            onChangeName={setCustomName}
          />
          <ColorPicker
            customColor={customColor}
            disabled={isImporting}
            onSelectColor={handleColorSelect}
          />
          <ReminderTimePicker
            disabled={isImporting}
            reminderTime={reminderTime}
            showTimePicker={showTimePicker}
            onTimeChange={handleTimeChange}
            onTogglePicker={setShowTimePicker}
          />
          <TemplateInfo
            category={template.category}
            frequency={template.frequency}
          />
        </ScrollView>

        <ModalFooter
          customColor={customColor}
          disabled={!customName.trim() || isImporting}
          isImporting={isImporting}
          onImport={handleImport}
        />
      </View>
    </Modal>
  );
}

/**
 * Hook for TemplatePreviewModal business logic
 */

import { useState, useEffect, useCallback } from 'react';
import * as Haptics from 'expo-haptics';
import type { Doc, Id } from '../../../../convex/_generated/dataModel';
import { DEFAULT_ICON_COLOR, safeColor } from './constants';
import type { TemplateCustomizations } from './types';

interface UseTemplatePreviewProps {
  template: Doc<'templates'> | null;
  onClose: () => void;
  onImport: (
    templateId: Id<'templates'>,
    customizations?: TemplateCustomizations
  ) => void;
}

export function useTemplatePreview({
  template,
  onClose,
  onImport,
}: UseTemplatePreviewProps) {
  const [customName, setCustomName] = useState('');
  const [customColor, setCustomColor] = useState(DEFAULT_ICON_COLOR);
  const [showTimePicker, setShowTimePicker] = useState(false);
  const [reminderTime, setReminderTime] = useState(new Date());

  // Reset customization when template changes
  useEffect(() => {
    if (template) {
      setCustomName(template.name);
      setCustomColor(safeColor(template.iconColor));
      setReminderTime(new Date());
    }
  }, [template]);

  const handleImport = useCallback(() => {
    if (!template) return;

    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);

    const customizations: TemplateCustomizations = {};

    if (customName !== template.name) {
      customizations.name = customName;
    }
    if (customColor !== template.iconColor) {
      customizations.iconColor = customColor;
    }
    customizations.reminderTime = reminderTime.toISOString();

    onImport(template._id, customizations);
  }, [template, customName, customColor, reminderTime, onImport]);

  const handleClose = useCallback(() => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    onClose();
  }, [onClose]);

  const handleColorSelect = useCallback((color: string) => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    setCustomColor(color);
  }, []);

  const handleTimeChange = useCallback((time: Date) => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    setReminderTime(time);
  }, []);

  return {
    customColor,
    customName,
    handleClose,
    handleColorSelect,
    handleImport,
    handleTimeChange,
    reminderTime,
    setCustomName,
    setShowTimePicker,
    showTimePicker,
  };
}

