    /** Track emoji selection from smart suggestions */
    trackEmojiSuggestionUsed: (data: {
      keyword: string | null;
      emojiSelected: string;
      fromSuggestions: boolean;
      wasSmartSuggestion: boolean;
    }) => {
      trackEvent({ type: 'emoji_suggestion_used', ...data });
