/**
 * Date Utilities for Client-Side Calculations
 * Provides consistent date handling that matches backend (convex/streakUtils.ts)
 */

/**
 * Calculate the difference in days between two dates
 * Uses UTC to avoid timezone/DST issues completely
 * Uses Math.round to handle any remaining fractional day differences
 *
 * @param date1 - First date (or date string in YYYY-MM-DD format)
 * @param date2 - Second date (or date string in YYYY-MM-DD format)
 * @returns Number of days difference (positive if date1 > date2)
 */
export function differenceInDays(
  date1: Date | string,
  date2: Date | string
): number {
  // Parse to UTC dates to avoid all timezone/DST issues
  const d1 = parseToUTCMidnight(date1);
  const d2 = parseToUTCMidnight(date2);

  const diffMs = d1.getTime() - d2.getTime();
  // Use Math.round to handle any potential sub-day differences
  // that might occur despite UTC normalization
  return Math.round(diffMs / (1000 * 60 * 60 * 24));
}

/**
 * Parse a date to UTC midnight, avoiding timezone issues
 */
function parseToUTCMidnight(date: Date | string): Date {
  if (typeof date === 'string') {
    // For YYYY-MM-DD strings, parse directly as UTC
    const match = date.match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (match) {
      return new Date(Date.UTC(+match[1], +match[2] - 1, +match[3], 0, 0, 0, 0));
    }
    // Fallback: parse and convert to UTC
    date = new Date(date);
  }

  // Convert Date object to UTC midnight
  return new Date(
    Date.UTC(date.getFullYear(), date.getMonth(), date.getDate(), 0, 0, 0, 0)
  );
}

/**
 * Get today's date string in YYYY-MM-DD format
 * Uses local timezone
 */
export function getTodayString(): string {
  const today = new Date();
  return formatDateString(today);
}

/**
 * Format a date to YYYY-MM-DD string
 * Handles both Date objects and existing strings
 */
export function formatDateString(date: Date | string): string {
  if (typeof date === 'string') {
    // If already a string, validate and return
    if (/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      return date;
    }
    // Try to parse and format
    const parsed = new Date(date);
    if (isNaN(parsed.getTime())) {
      throw new Error(`Invalid date string: ${date}`);
    }
    date = parsed;
  }

  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

/**
 * Check if a date string represents today
 */
export function isToday(dateString: string): boolean {
  return dateString === getTodayString();
}

/**
 * Check if a date string represents yesterday
 */
export function isYesterday(dateString: string): boolean {
  const yesterday = new Date();
  yesterday.setDate(yesterday.getDate() - 1);
  return dateString === formatDateString(yesterday);
}

/**
 * Export data using iOS Share Sheet or Android sharing
 */

import { Share, Platform } from 'react-native';
import * as FileSystem from 'expo-file-system/legacy';
import * as Sharing from 'expo-sharing';
import { convertToCSV, convertToJSON } from './converters';
import type { ExportData, ToastResult } from './types';

/**
 * Export data using iOS Share Sheet or Android sharing
 */
export async function exportData(
  data: ExportData,
  format: 'csv' | 'json'
): Promise<void> {
  try {
    let content: string;
    let filename: string;
    let mimeType: string;

    if (format === 'csv') {
      content = convertToCSV(data);
      filename = `habits_export_${Date.now()}.csv`;
      mimeType = 'text/csv';
    } else {
      content = convertToJSON(data);
      filename = `habits_export_${Date.now()}.json`;
      mimeType = 'application/json';
    }

    // Create temporary file
    const fileUri = FileSystem.documentDirectory + filename;
    await FileSystem.writeAsStringAsync(fileUri, content, {
      encoding: FileSystem.EncodingType.UTF8,
    });

    // Check if sharing is available
    const isAvailable = await Sharing.isAvailableAsync();

    if (isAvailable) {
      await Sharing.shareAsync(fileUri, {
        dialogTitle: 'Export Habit Data',
        mimeType,
        UTI:
          format === 'csv'
            ? 'public.comma-separated-values-text'
            : 'public.json',
      });
    } else if (Platform.OS === 'ios') {
      await Share.share({ title: 'Export Habit Data', url: fileUri });
    } else {
      await Share.share({ message: content, title: 'Export Habit Data' });
    }

    // Clean up temporary file after a delay
    setTimeout(() => {
      FileSystem.deleteAsync(fileUri, { idempotent: true }).catch(() => {
        // Ignore cleanup errors
      });
    }, 5000);
  } catch (error) {
    if (error instanceof Error) {
      if (
        error.message.includes('User canceled') ||
        error.message.includes('cancelled')
      ) {
        return;
      }
      throw error;
    }
  }
}

/**
 * Show success toast after export
 */
export function showExportSuccess(format: 'csv' | 'json'): ToastResult {
  return {
    duration: 3000,
    message: `Data exported successfully as ${format.toUpperCase()}`,
    type: 'success',
  };
}

/**
 * Show error toast on export failure
 */
export function showExportError(error: Error): ToastResult {
  return {
    duration: 4000,
    message: `Export failed: ${error.message}`,
    type: 'error',
  };
}

import * as Notifications from 'expo-notifications';

import { NOTIFICATION_TYPE_AFFIRMATION_DELIVERY } from '../constants';

import type {
  AffirmationFrequency,
  ScheduledAffirmationDelivery,
} from './types';

/**
 * Get all scheduled affirmation delivery notifications
 * Useful for debugging or displaying scheduled notifications to the user
 */
export async function getScheduledAffirmationDeliveries(): Promise<
  ScheduledAffirmationDelivery[]
> {
  try {
    const scheduledNotifications =
      await Notifications.getAllScheduledNotificationsAsync();

    return scheduledNotifications
      .filter(
        (notification) =>
          notification.content?.data?.type ===
          NOTIFICATION_TYPE_AFFIRMATION_DELIVERY
      )
      .map((notification) => {
        const data = notification.content.data as {
          affirmationId?: string;
          habitId?: string;
          frequency?: AffirmationFrequency;
          daysOfWeek?: number[];
        };

        // Extract scheduled time from trigger
        let scheduledTime: Date | null = null;
        const trigger = notification.trigger as {
          date?: Date;
          hour?: number;
          minute?: number;
        } | null;

        if (trigger?.date) {
          scheduledTime = new Date(trigger.date);
        } else if (
          trigger?.hour !== undefined &&
          trigger?.minute !== undefined
        ) {
          // For DAILY triggers, construct a Date for today at that time
          const now = new Date();
          scheduledTime = new Date(now);
          scheduledTime.setHours(trigger.hour, trigger.minute, 0, 0);
          // If time has passed today, it's for tomorrow
          if (scheduledTime.getTime() <= now.getTime()) {
            scheduledTime.setDate(scheduledTime.getDate() + 1);
          }
        }

        return {
          affirmationId: data.affirmationId ?? '',
          daysOfWeek: data.daysOfWeek,
          frequency: data.frequency ?? 'daily',
          habitId: data.habitId ?? '',
          notificationId: notification.identifier,
          scheduledTime,
        };
      });
  } catch (error) {
    console.error('getScheduledAffirmationDeliveries failed', error);
    return [];
  }
}

import { configureAffirmationChannel } from '../channels';
import { ensureNotificationPermissions } from '../permissions';
import { parseTimeString } from '../timeUtils';

import { cancelAffirmationDelivery } from './cancel';
import {
  scheduleDailyNotification,
  scheduleWeeklyNotification,
} from './schedulingHelpers';
import type { ScheduleAffirmationDeliveryParams } from './types';

/** Schedule affirmation delivery. Returns notification ID on success, null on failure. */
export async function scheduleAffirmationDelivery({
  affirmationId,
  habitId,
  affirmationText,
  scheduledTime,
  frequency,
  daysOfWeek,
  skipPermissionCheck = false,
}: ScheduleAffirmationDeliveryParams): Promise<string | null> {
  try {
    // Validate time format
    const timeMatch = scheduledTime.match(/^([01]?[0-9]|2[0-3]):([0-5][0-9])$/);
    if (!timeMatch) {
      console.warn(
        'scheduleAffirmationDelivery: invalid time format',
        scheduledTime
      );
      return null;
    }

    if (skipPermissionCheck) {
      await configureAffirmationChannel();
    } else {
      const hasPermission = await ensureNotificationPermissions();
      if (!hasPermission) {
        return null;
      }
      await configureAffirmationChannel();
    }

    // Cancel any existing notification for this affirmation
    await cancelAffirmationDelivery(affirmationId);

    const { hours, minutes } = parseTimeString(scheduledTime);
    const truncatedText =
      affirmationText.length > 100
        ? affirmationText.slice(0, 97) + '...'
        : affirmationText;

    let notificationId: string;

    if (frequency === 'daily') {
      notificationId = await scheduleDailyNotification(
        affirmationId,
        habitId,
        truncatedText,
        hours,
        minutes
      );
    } else {
      if (!daysOfWeek || daysOfWeek.length === 0) {
        console.warn(
          'scheduleAffirmationDelivery: weekly frequency requires daysOfWeek'
        );
        return null;
      }

      notificationId = await scheduleWeeklyNotification(
        affirmationId,
        habitId,
        truncatedText,
        hours,
        minutes,
        daysOfWeek
      );
    }

    // eslint-disable-next-line no-console
    console.info('scheduleAffirmationDelivery success', {
      affirmationId,
      frequency,
      notificationId,
      scheduledTime,
    });

    return notificationId;
  } catch (error) {
    console.error('scheduleAffirmationDelivery failed', {
      affirmationId,
      error,
    });
    return null;
  }
}

import * as Notifications from 'expo-notifications';
import { Platform } from 'react-native';

import { configureLetterUnlockChannel } from '../channels';
import {
  ANDROID_LETTER_CHANNEL_ID,
  NOTIFICATION_TYPE_LETTER_UNLOCK,
} from '../constants';
import { ensureNotificationPermissions } from '../permissions';
import type { ScheduleLetterUnlockParams } from '../types';

import { cancelLetterUnlockNotification } from './cancel';

/**
 * Schedule a notification for when a letter unlocks
 *
 * Uses a DATE trigger for one-time notification at exact unlock time.
 * Notification data includes type='letterUnlock' to differentiate from habit reminders.
 *
 * @returns Notification identifier string on success, null on failure
 */
export async function scheduleLetterUnlockNotification({
  letterId,
  habitId,
  letterTitle = 'Letter to Self',
  unlockAt,
  skipPermissionCheck = false,
}: ScheduleLetterUnlockParams): Promise<string | null> {
  try {
    // Don't schedule if unlock time is in the past
    if (unlockAt <= Date.now()) {
      console.warn(
        'scheduleLetterUnlockNotification: unlock time is in the past',
        { letterId, unlockAt }
      );
      return null;
    }

    if (skipPermissionCheck) {
      await configureLetterUnlockChannel();
    } else {
      const hasPermission = await ensureNotificationPermissions();

      if (!hasPermission) {
        return null;
      }

      await configureLetterUnlockChannel();
    }

    // Cancel any existing notification for this letter
    await cancelLetterUnlockNotification(letterId);

    const notificationId = await Notifications.scheduleNotificationAsync({
      content: {
        body: 'Your letter to yourself is ready to read!',
        data: {
          habitId,
          letterId,
          type: NOTIFICATION_TYPE_LETTER_UNLOCK,
        },
        sound: 'default',
        title: `📬 ${letterTitle}`,
      },
      trigger: {
        ...(Platform.OS === 'android'
          ? { channelId: ANDROID_LETTER_CHANNEL_ID }
          : {}),
        date: new Date(unlockAt),
        type: Notifications.SchedulableTriggerInputTypes.DATE,
      },
    });

    // eslint-disable-next-line no-console
    console.info('scheduleLetterUnlockNotification success', {
      letterId,
      notificationId,
      unlockAt: new Date(unlockAt).toISOString(),
    });

    return notificationId;
  } catch (error) {
    console.error('scheduleLetterUnlockNotification failed', {
      error,
      letterId,
    });
    return null;
  }
}

import { format, parseISO } from 'date-fns';

/**
 * Compute a streak by starting at the most recent completed day (<= today)
 * and counting backwards through consecutive completed days.
 * Ensures a single isolated completion counts as a 1-day streak.
 */
export const computeCurrentStreakFromDates = (
  completedDates: Set<string>,
  today: Date
): number => {
  if (!completedDates || completedDates.size === 0) {
    return 0;
  }

  const todayString = format(new Date(today), 'yyyy-MM-dd');

  // Find the most recent completed date that is not in the future
  const latestCompleted = Array.from(completedDates)
    .filter((date) => date <= todayString)
    .sort()
    .pop();

  if (!latestCompleted) {
    return 0;
  }

  let streak = 0;
  const currentDate = parseISO(latestCompleted);

  // Count consecutive days backward from the latest completion
  // Stop when a gap is found
  // Safety guard to avoid unexpected infinite loops
  const maxLookbackDays = 400; // > 1 year
  for (let i = 0; i < maxLookbackDays; i++) {
    const dateString = format(currentDate, 'yyyy-MM-dd');
    if (completedDates.has(dateString)) {
      streak += 1;
      currentDate.setDate(currentDate.getDate() - 1);
      continue;
    }
    break;
  }

  return streak;
};

/**
 * Monthly Trend Calculations
 *
 * Computes month-over-month completion trends for habit tracking.
 */

import type { HabitTrackingEntry } from '../../features/habits/types';
import { formatDateString } from '../dateUtils';
import type { MonthOverMonthTrend } from './types';

/**
 * Calculate month-over-month completion trend
 *
 * Compares the current month (1st to today) with the previous month (full month).
 * Used for monthly trend indicators in the progress section.
 *
 * @param tracking - Array of habit tracking entries
 * @param referenceDate - Optional reference date (defaults to today)
 * @returns Month-over-month trend comparison data
 */
export function calculateMonthOverMonthTrend(
  tracking: HabitTrackingEntry[],
  referenceDate?: Date
): MonthOverMonthTrend {
  // Clone the date to avoid mutating the caller's object
  const today = new Date(referenceDate ?? new Date());
  today.setHours(23, 59, 59, 999);

  // This month: 1st to today
  const thisMonthStart = new Date(today.getFullYear(), today.getMonth(), 1);

  // Last month: Full previous month
  const lastMonthStart = new Date(today.getFullYear(), today.getMonth() - 1, 1);
  const lastMonthEnd = new Date(today.getFullYear(), today.getMonth(), 0); // Day 0 = last day of previous month
  lastMonthEnd.setHours(23, 59, 59, 999);

  // Create a set of completed dates for quick lookup
  const completedDates = new Set(
    tracking.filter((t) => t.completed).map((t) => t.date)
  );

  // Count this month's completions
  let thisMonthCompleted = 0;
  let thisMonthTotal = 0;
  const thisMonthCurrent = new Date(thisMonthStart);

  while (thisMonthCurrent <= today) {
    thisMonthTotal++;
    const dateStr = formatDateString(thisMonthCurrent);
    if (completedDates.has(dateStr)) {
      thisMonthCompleted++;
    }
    thisMonthCurrent.setDate(thisMonthCurrent.getDate() + 1);
  }

  // Count last month's completions
  let lastMonthCompleted = 0;
  let lastMonthTotal = 0;
  const lastMonthCurrent = new Date(lastMonthStart);

  while (lastMonthCurrent <= lastMonthEnd) {
    lastMonthTotal++;
    const dateStr = formatDateString(lastMonthCurrent);
    if (completedDates.has(dateStr)) {
      lastMonthCompleted++;
    }
    lastMonthCurrent.setDate(lastMonthCurrent.getDate() + 1);
  }

  // Calculate rates
  const thisMonthRate =
    thisMonthTotal > 0
      ? Math.round((thisMonthCompleted / thisMonthTotal) * 100)
      : 0;

  const lastMonthRate =
    lastMonthTotal > 0
      ? Math.round((lastMonthCompleted / lastMonthTotal) * 100)
      : 0;

  return {
    countChange: thisMonthCompleted - lastMonthCompleted,
    lastMonthCompleted,
    lastMonthRate,
    lastMonthTotal,
    rateChange: thisMonthRate - lastMonthRate,
    thisMonthCompleted,
    thisMonthRate,
    thisMonthTotal,
  };
}

/**
 * Calculate the monthly change value for display in Stats Grid
 *
 * Returns the difference in completion count between this month and last month,
 * adjusted for the number of days elapsed. This provides a fair comparison
 * even early in the month.
 *
 * For StatsGrid, we show the raw count change (e.g., "+3" meaning 3 more completions
 * at this point in the month compared to the same point last month).
 *
 * @param tracking - Array of habit tracking entries
 * @param referenceDate - Optional reference date (defaults to today)
 * @returns Monthly change value (positive = improvement, negative = decline)
 */
export function calculateMonthlyChangeForStatsGrid(
  tracking: HabitTrackingEntry[],
  referenceDate?: Date
): number {
  const trend = calculateMonthOverMonthTrend(tracking, referenceDate);

  // For a fair comparison, compare completion counts at the same point in the month
  // We use rate change since days elapsed may differ
  return trend.rateChange;
}

/**
 * Weekly Trend Calculations
 *
 * Computes week-over-week completion trends for habit tracking.
 */

import type { HabitTrackingEntry } from '../../features/habits/types';
import { formatDateString } from '../dateUtils';
import { getWeekStart } from './dateHelpers';
import type { WeekOverWeekTrend } from './types';

/**
 * Calculate week-over-week completion trend
 *
 * Compares the current week (Monday to today) with the previous week (Monday to Sunday).
 * Used for weekly trend indicators in the progress section.
 *
 * @param tracking - Array of habit tracking entries
 * @param referenceDate - Optional reference date (defaults to today)
 * @returns Week-over-week trend comparison data
 */
export function calculateWeekOverWeekTrend(
  tracking: HabitTrackingEntry[],
  referenceDate?: Date
): WeekOverWeekTrend {
  // Clone the date to avoid mutating the caller's object
  const today = new Date(referenceDate ?? new Date());
  today.setHours(23, 59, 59, 999);

  // This week: Monday to today
  const thisWeekStart = getWeekStart(today);

  // Last week: Previous Monday to Sunday
  const lastWeekEnd = new Date(thisWeekStart);
  lastWeekEnd.setDate(lastWeekEnd.getDate() - 1);
  lastWeekEnd.setHours(23, 59, 59, 999);
  const lastWeekStart = getWeekStart(lastWeekEnd);

  // Create a set of completed dates for quick lookup
  const completedDates = new Set(
    tracking.filter((t) => t.completed).map((t) => t.date)
  );

  // Count this week's completions (Monday to today)
  let thisWeekCompleted = 0;
  let thisWeekTotal = 0;
  const thisWeekCurrent = new Date(thisWeekStart);

  while (thisWeekCurrent <= today) {
    thisWeekTotal++;
    const dateStr = formatDateString(thisWeekCurrent);
    if (completedDates.has(dateStr)) {
      thisWeekCompleted++;
    }
    thisWeekCurrent.setDate(thisWeekCurrent.getDate() + 1);
  }

  // Count last week's completions (full 7 days)
  let lastWeekCompleted = 0;
  const lastWeekCurrent = new Date(lastWeekStart);

  while (lastWeekCurrent <= lastWeekEnd) {
    const dateStr = formatDateString(lastWeekCurrent);
    if (completedDates.has(dateStr)) {
      lastWeekCompleted++;
    }
    lastWeekCurrent.setDate(lastWeekCurrent.getDate() + 1);
  }

  const lastWeekTotal = 7; // Always 7 days for last week

  // Calculate rates
  const thisWeekRate =
    thisWeekTotal > 0
      ? Math.round((thisWeekCompleted / thisWeekTotal) * 100)
      : 0;

  const lastWeekRate =
    lastWeekTotal > 0
      ? Math.round((lastWeekCompleted / lastWeekTotal) * 100)
      : 0;

  return {
    countChange: thisWeekCompleted - lastWeekCompleted,
    lastWeekCompleted,
    lastWeekRate,
    lastWeekTotal,
    rateChange: thisWeekRate - lastWeekRate,
    thisWeekCompleted,
    thisWeekRate,
    thisWeekTotal,
  };
}

